INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/scientific-slides', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'scientific-slides', 0, 0, 75, '2026-02-20T04:13:19.580Z', '2026-02-20T05:05:13.010Z', '3f1b1fd3c18dc6cb8b195144cf54c7e31cdf181199ed6db9f223f7c3c364407c', '{"id":"majiayu000/claude-skill-registry/scientific-slides","name":"scientific-slides","description":{"zh":"科学幻灯片创建技能提供结构、内容开发、视觉设计和演讲准备的综合指导","ja":"科学スライド作成スキルは構造、コンテンツ開発、視覚設計、プレゼンテーションの準備についての包括的なガイダンスを提供します","ko":"과학 프레젠테이션 제작 기술은 구조, 콘텐츠 개발, 시각적 디자인 및 발표 준비에 대한 종합적인 가이드를 제공합니다","es":"Este skill ofrece orientación para crear presentaciones científicas efectivas, desde la estructura hasta el diseño visual","fr":"Ce skill propose des conseils pour créer des présentations scientifiques efficaces, de la structure au design visuel","de":"Dieses Skill bietet Anleitung für die Erstellung effektiver wissenschaftlicher Präsentationen, von der Struktur bis zum visuellen Design","pt":"Slides científicos são fundamentais para comunicar pesquisas e compartilhar descobertas. Este guia oferece dicas para criar apresentações eficazes","ru":"Научные слайды являются важнейшим инструментом для передачи исследований и обмена открытиями. Это руководство предоставляет советы по созданию эффективных презентаций","ar":"الشرائح العلمية هي أداة أساسية للتواصل البحوث ومشاركة الاكتشافات. هذا الدليل يقدم نصائح لإنشاء عروض تقديمية فعالة","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"科学幻灯片创建技能","ja":"科学スライド作成スキル","ko":"과학 프레젠테이션 제작 기술","es":"Diapositivas científicas efectivas","fr":"Présentations scientifiques efficaces","de":"Effektive wissenschaftliche Präsentationen","pt":"Slides Científicos: Dicas para Apresentações de Sucesso","ru":"Научные слайды: сов