INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/scientific-slides', 'scientific-slides', 'majiayu000', 'claude-skill-registry', 'community', 'scientific-slides majiayu000 claude-skill-registry community 科学幻灯片创建技能提供结构、内容开发、视觉设计和演讲准备的综合指导 科学スライド作成スキルは構造、コンテンツ開発、視覚設計、プレゼンテーションの準備についての包括的なガイダンスを提供します 과학 프레젠테이션 제작 기술은 구조, 콘텐츠 개발, 시각적 디자인 및 발표 준비에 대한 종합적인 가이드를 제공합니다 Este skill ofrece orientación para crear presentaciones científicas efectivas, desde la estructura hasta el diseño visual Ce skill propose des conseils pour créer des présentations scientifiques efficaces, de la structure au design visuel Dieses Skill bietet Anleitung für die Erstellung effektiver wissenschaftlicher Präsentationen, von der Struktur bis zum visuellen Design Slides científicos são fundamentais para comunicar pesquisas e compartilhar descobertas. Este guia oferece dicas para criar apresentações eficazes Научные слайды являются важнейшим инструментом для передачи исследований и обмена открытиями. Это руководство предоставляет советы по созданию эффективных презентаций الشرائح العلمية هي أداة أساسية للتواصل البحوث ومشاركة الاكتشافات. هذا الدليل يقدم نصائح لإنشاء عروض تقديمية فعالة The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 科学幻灯片 研究沟通 专业演讲 视觉设计 口头报告 学术沟通 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/nanobanana-skill', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'nanobanana-skill', 0, 0, 75, '2026-02-20T04:13:19.581Z', '2026-02-20T05:12:47.594Z', '8c0ddb19ec9eee3e3598ff47e11004687d6644e61c7367da8cd37b567148dd3c', '{"id":"majiayu000/claude-skill-registry/nanobanana-skill","name":"nanobanana-skill","description":{"zh":"nanobanana-skill是一种基于Google Gemini API的图像生成工具，支持图像生成和编辑","ja":"nanobanana-skillはGoogle Gemini APIを使用した画像生成ツールで、画像生成と編集をサポート","ko":"nanobanana-skill는 Google Gemini API를 사용한 이미지 생성 도구로 이미지 생성 및 편집을 지원","es":"La habilidad nanobanana permite generar o editar imágenes mediante la API de Google Gemini. Requiere Python 3 y paquetes dependientes.","fr":"La compétence nanobanana permet de générer ou de modifier des images à l''aide de l''API Google Gemini. Elle nécessite Python 3 et des packages dépendants.","de":"Die Fähigkeit nanobanana ermöglicht die Generierung oder Bearbeitung von Bildern mithilfe der Google Gemini-API. Sie erfordert Python 3 und abhängige Pakete.","pt":"O nanobanana-skill é uma ferramenta para gerar ou editar imagens usando a API do Google Gemini. Requer configuração e instalação de pacotes Python","ru":"Нанобанана-skill - это инструмент для генерации или редактирования изображений с помощью API Google Gemini. Требует настройки и установки пакетов Python","ar":"nanobanana-skill هو أداة لتوليد أو تعديل الصور باستخدام API جوجل جيمي. يتطلب إعداد وتثبيت حزم بايثون","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"nanobanana-skill: 基于Google Gemini API的图像生成","ja":"nanobanana-skill: Google Gemini APIを使用した画像生成","ko":"nanobanana-skill: Google Gemini API를 사용한 이미지 생성","es":"Generación de Imágenes con Nanobanana","fr":"Génération d''Images avec Nanobanana","de":"Bildgenerierung mit Nanobanana","pt":"Geração de Imagens Nanobanana com Claude Code","ru":"Нанобанана: генерация изображений с помощью Claude Code","ar":"توليد الصورنانوبنانا مع Claude Code","en":"nanobanana-skill"},"description":{"zh":"nanobanana-skill是一种基于Google Gemini API的图像生成工具，支持图像生成和编辑","ja":"nanobanana-skillはGoogle Gemini APIを使用した画像生成ツールで、画像生成と編集をサポート","ko":"nanobanana-skill는 Google Gemini API를 사용한 이미지 생성 도구로 이미지 생성 및 편집을 지원","es":"La habilidad nanobanana permite generar o editar imágenes mediante la API de Google Gemini. Requiere Python 3 y paquetes dependientes.","fr":"La compétence nanobanana permet de générer ou de modifier des images à l''aide de l''API Google Gemini. Elle nécessite Python 3 et des packages dépendants.","de":"Die Fähigkeit nanobanana ermöglicht die Generierung oder Bearbeitung von Bildern mithilfe der Google Gemini-API. Sie erfordert Python 3 und abhängige Pakete.","pt":"O nanobanana-skill é uma ferramenta para gerar ou editar imagens usando a API do Google Gemini. Requer configuração e instalação de pacotes Python","ru":"Нанобанана-skill - это инструмент для генерации или редактирования изображений с помощью API Google Gemini. Требует настройки и установки пакетов Python","ar":"nanobanana-skill هو أداة لتوليد أو تعديل الصور باستخدام API جوجل جيمي. يتطلب إعداد وتثبيت حزم بايثون","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["基于Google Gemini API的图像生成","支持图像编辑","使用Python3和依赖包","通过环境变量配置GEMINI_API_KEY","支持通过pip安装依赖包"],"ja":["Google Gemini APIを使用した画像生成","画像編集をサポート","Python3と依存パッケージを使用","環境変数でGEMINI_API_KEYを設定","pipを使用して依存パッケージをインストール"],"ko":["Google Gemini API를 사용한 이미지 생성","이미지 편집 지원","Python3와 종속 패키지 사용","환경 변수로 GEMINI_API_KEY 설정","pip를 사용하여 종속 패키지 설치"],"es":["Generación de imágenes con la API de Google Gemini","Edición de imágenes con la herramienta nanobanana","Requiere Python 3 y paquetes dependientes","Configuración del entorno mediante variables de entorno","Instalación de paquetes dependientes mediante pip"],"fr":["Génération d''images avec l''API Google Gemini","Modification d''images avec l''outil nanobanana","Nécessite Python 3 et des packages dépendants","Configuration de l''environnement via des variables d''environnement","Installation de packages dépendants via pip"],"de":["Bildgenerierung mit der Google Gemini-API","Bildbearbeitung mit dem Tool nanobanana","Erfordert Python 3 und abhängige Pakete","Konfiguration der Umgebung über Umgebungsvariablen","Installation von abhängigen Paketen über pip"],"pt":["Geração de imagens personalizadas","Integração com API do Google Gemini","Requer configuração de chave de API","Instalação de pacotes Python necessários","Compatibilidade com Python 3"],"ru":["Генерация индивидуальных изображений","Интеграция с API Google Gemini","Требует настройки ключа API","Установка необходимых пакетов Python","Совместимость с Python 3"],"ar":["توليد صور مخصصة","التكامل مع API جوجل جيمي","يتطلب إعداد مفتاح API","تثبيت حزم بايثون الضرورية","التوافق مع بايثون 3"]},"keywords":{"zh":["nanobanana-skill","Google Gemini API","图像生成","图像编辑","Python3","环境变量","GEMINI_API_KEY","pip","依赖包"],"ja":["nanobanana-skill","Google Gemini API","画像生成","画像編集","Python3","環境変数","GEMINI_API_KEY","pip","依存パッケージ"],"ko":["nanobanana-skill","Google Gemini API","이미지 생성","이미지 편집","Python3","환경 변수","GEMINI_API_KEY","pip","종속 패키지"],"es":["generación de imágenes","edición de imágenes","API de Google Gemini","nanobanana","Python 3","paquetes dependientes","variables de entorno","pip"],"fr":["génération d''images","modification d''images","API Google Gemini","nanobanana","Python 3","packages dépendants","variables d''environnement","pip"],"de":["Bildgenerierung","Bildbearbeitung","Google Gemini-API","nanobanana","Python 3","abhängige Pakete","Umgebungsvariablen","pip"],"pt":["nanobanana-skill","geração de imagens","API Google Gemini","Python 3","desenvolvimento de código","ferramentas de programação"],"ru":["nanobanana-skill","генерация изображений","API Google Gemini","Python 3","разработка кода","инструменты программирования"],"ar":["nanobanana-skill","توليد الصور","API جوجل جيمي","بايثون 3","تطوير الكود","أدوات البرمجة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"nanobanana-skill","description":"Generate or edit images using Google Gemini API via nanobanana. Use when the user asks to create, generate, edit images with nanobanana, or mentions image generation/editing tasks.","bodyPreview":"# Nanobanana Image Generation Skill\n\nGenerate or edit images using Google Gemini API through the nanobanana tool.\n\n## Requirements\n\n1. **GEMINI_API_KEY**: Must be configured in `~/.nanobanana.env` or `export GEMINI_API_KEY=<your-api-key>`\n2. **Python3 with depedent packages installed**: google-genai, Pillow, python-dotenv. They could be installed via `python3 -m pip install -r ~/.codex/skills/nanobanana-skill/requirements.txt` if not installed yet.\n3. **Executable**: `~/.codex/skills/nanobanana-","body":"# Nanobanana Image Generation Skill\n\nGenerate or edit images using Google Gemini API through the nanobanana tool.\n\n## Requirements\n\n1. **GEMINI_API_KEY**: Must be configured in `~/.nanobanana.env` or `export GEMINI_API_KEY=<your-api-key>`\n2. **Python3 with depedent packages installed**: google-genai, Pillow, python-dotenv. They could be installed via `python3 -m pip install -r ~/.codex/skills/nanobanana-skill/requirements.txt` if not installed yet.\n3. **Executable**: `~/.codex/skills/nanobanana-skill/nanobanana.py`\n\nExample `.nanobanana.env`:\n\n```bash\nGEMINI_API_KEY=sk-dummy\n```\n\n## Instructions\n\n### For image generation\n\n1. Ask the user for:\n   - What they want to create (the prompt)\n   - Desired aspect ratio/size (optional, defaults to 9:16 portrait)\n   - Output filename (optional, auto-generates UUID if not specified)\n   - Model preference (optional, defaults to gemini-3-pro-image-preview)\n   - Resolution (optional, defaults to 1K)\n\n2. Run the nanobanana script with appropriate parameters:\n\n   ```bash\n   python3 ~/.codex/skills/nanobanana-skill/nanobanana.py --prompt \"description of image\" --output \"filename.png\"\n   ```\n\n3. Show the user the saved image path when complete\n\n### For image editing\n\n1. Ask the user for:\n   - Input image file(s) to edit\n   - What changes they want (the prompt)\n   - Output filename (optional)\n\n2. Run with input images:\n\n   ```bash\n   python3 ~/.codex/skills/nanobanana-skill/nanobanana.py --prompt \"editing instructions\" --input image1.png image2.png --output \"edited.png\"\n   ```\n\n## Available Options\n\n### Aspect Ratios (--size)\n\n- `1024x1024` (1:1) - Square\n- `832x1248` (2:3) - Portrait\n- `1248x832` (3:2) - Landscape\n- `864x1184` (3:4) - Portrait\n- `1184x864` (4:3) - Landscape\n- `896x1152` (4:5) - Portrait\n- `1152x896` (5:4) - Landscape\n- `768x1344` (9:16) - Portrait (default)\n- `1344x768` (16:9) - Landscape\n- `1536x672` (21:9) - Ultra-wide\n\n### Models (--model)\n\n- `gemini-3-pro-image-preview` (default) - Higher quality\n- `gemini-2.5-flash-image` - Faster generation\n\n### Resolution (--resolution)\n\n- `1K` (default)\n- `2K`\n- `4K`\n\n### Optional Flags\n\n- `--enable-google-search` Enable Google Search tool for the model (default: disabled)\n- `--include-thoughts` Include model thinking in output (default: disabled)\n\n## Examples\n\n### Generate a simple image\n\n```bash\npython3 ~/.codex/skills/nanobanana-skill/nanobanana.py --prompt \"A serene mountain landscape at sunset with a lake\"\n```\n\n### Generate with specific size and output\n\n```bash\npython3 ~/.codex/skills/nanobanana-skill/nanobanana.py \\\n  --prompt \"Modern minimalist logo for a tech startup\" \\\n  --size 1024x1024 \\\n  --output \"logo.png\"\n```\n\n### Generate landscape image with high resolution\n\n```bash\npython3 ~/.codex/skills/nanobanana-skill/nanobanana.py \\\n  --prompt \"Futuristic cityscape with flying cars\" \\\n  --size 1344x768 \\\n  --resolution 2K \\\n  --output \"cityscape.png\"\n```\n\n### Edit existing images\n\n```bash\npython3 ~/.codex/skills/nanobanana-skill/nanobanana.py \\\n  --prompt \"Add a rainbow in the sky\" \\\n  --input photo.png \\\n  --output \"photo-with-rainbow.png\"\n```\n\n### Use faster model\n\n```bash\npython3 ~/.codex/skills/nanobanana-skill/nanobanana.py \\\n  --prompt \"Quick sketch of a cat\" \\\n  --model gemini-2.5-flash-image \\\n  --output \"cat-sketch.png\"\n```\n\n## Error Handling\n\nIf the script fails:\n\n- Check that `GEMINI_API_KEY` is exported or set in ~/.nanobanana.env\n- Verify input image files exist and are readable\n- Ensure the output directory is writable\n- If no image is generated, try making the prompt more specific about wanting an image\n\n## Best Practices\n\n1. Be descriptive in prompts - include style, mood, colors, composition\n2. For logos/graphics, use square aspect ratio (1024x1024)\n3. For social media posts, use 9:16 for stories or 1:1 for posts\n4. For wallpapers, use 16:9 or 21:9\n5. Start with 1K resolution for testing, upgrade to 2K/4K for final output\n6. Use gemini-3-pro-image-preview for best quality, gemini-2.5-flash-image for speed\n"},"lastSynced":"2026-02-20T05:12:47.594Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual Content Agents needing advanced image generation and editing capabilities through Google Gemini API","zh":"非常适合需要通过Google Gemini API进行高级图像生成和编辑功能的视觉内容代理","ja":"Google Gemini APIを介して高度な画像生成および編集機能を必要とするビジュアルコンテンツエージェントに最適","ko":"Google Gemini API를 통해 고급 이미지 생성 및 편집 기능을 필요로 하는 시각적 콘텐츠 에이전트에 적합","es":"Perfecto para agentes de contenido visual que necesitan capacidades avanzadas de generación y edición de imágenes a través de la API de Google Gemini","fr":"Parfait pour les agents de contenu visuel ayant besoin de capacités avancées de génération et de modification d''images via l''API Google Gemini","de":"Perfekt für visuelle Inhaltsagenten, die erweiterte Bildgenerierungs- und -bearbeitungsfunktionen über die Google Gemini-API benötigen","pt":"Perfeito para Agentes de Conteúdo Visual que necessitam de capacidades avançadas de geração e edição de imagens por meio da API Google Gemini","ru":"Идеально для Визуальных Контент Агентов, требующих расширенных возможностей генерации и редактирования изображений через API Google Gemini","ar":"مثالي لعميل المحتوى المرئي الذي يحتاج إلى إمكانيات متقدمة لإنشاء وتحرير الصور من خلال واجهة برمجة تطبيقات جوجل جيميني"},"recommendation":{"en":"Empowers agents to generate and edit images using Google Gemini API, leveraging libraries like google-genai and Pillow, with support for environment variables via python-dotenv, and executable scripts","zh":"赋予代理生成和编辑图像的能力，使用Google Gemini API，利用像google-genai和Pillow这样的库，并通过python-dotenv支持环境变量，以及可执行脚本","ja":"エージェントがGoogle Gemini APIを使用して画像を生成および編集できるようにし、google-genaiやPillowなどのライブラリを利用し、python-dotenvを介して環境変数をサポートし、実行可能なスクリプト","ko":"에이전트가 Google Gemini API를 사용하여 이미지 생성 및 편집을 가능하게 하고, google-genai 및 Pillow와 같은 라이브러리를 활용하고, python-dotenv를 통해 환경 변수를 지원하며, 실행 가능한 스크립트","es":"Habilita a los agentes a generar y editar imágenes utilizando la API de Google Gemini, aprovechando bibliotecas como google-genai y Pillow, con soporte para variables de entorno a través de python-dotenv y scripts ejecutables","fr":"Permet aux agents de générer et de modifier des images en utilisant l''API Google Gemini, en exploitant des bibliothèques telles que google-genai et Pillow, avec une prise en charge des variables d''environnement via python-dotenv et des scripts exécutables","de":"Ermächtigt Agenten, Bilder mit der Google Gemini-API zu generieren und zu bearbeiten, indem Bibliotheken wie google-genai und Pillow genutzt werden, mit Unterstützung für Umgebungsvariablen über python-dotenv und ausführbare Skripte","pt":"Habilita os agentes a gerar e editar imagens usando a API Google Gemini, aproveitando bibliotecas como google-genai e Pillow, com suporte a variáveis de ambiente via python-dotenv e scripts executáveis","ru":"Наделяет агентов возможностью генерировать и редактировать изображения с помощью API Google Gemini, используя библиотеки như google-genai и Pillow, с поддержкой переменных среды через python-dotenv и исполняемые скрипты","ar":"تمكن الوكلاء من إنشاء وتحرير الصور باستخدام واجهة برمجة تطبيقات جوجل جيميني، مستفيداً من المكتبات مثل جوجل-جيناي وبيلود، مع دعم متغيرات البيئة عبر بايثون-دوتينف وبرامج نصية قابلة للتنفيذ"},"useCases":{"en":["Generating images with specific styles and prompts","Editing existing images using advanced AI techniques","Automating image creation for web applications"],"zh":["使用特定样式和提示生成图像","使用高级AI技术编辑现有图像","自动化Web应用程序的图像创建"],"ja":["特定のスタイルとプロンプトを使用して画像を生成する","高度なAI技術を使用して既存の画像を編集する","Webアプリケーションの画像作成を自動化する"],"ko":["특정 스타일 및 프롬프트를 사용하여 이미지 생성","고급 AI 기술을 사용하여 기존 이미지 편집","웹 애플리케이션의 이미지 생성 자동화"],"es":["Generar imágenes con estilos y consignas específicas","Editar imágenes existentes utilizando técnicas de inteligencia artificial avanzadas","Automatizar la creación de imágenes para aplicaciones web"],"fr":["Générer des images avec des styles et des invites spécifiques","Modifier des images existantes en utilisant des techniques d''intelligence artificielle avancées","Automatiser la création d''images pour les applications web"],"de":["Bilder mit spezifischen Stilen und Anweisungen generieren","Vorhandene Bilder mithilfe erweiterter künstlicher Intelligenztechniken bearbeiten","BildErstellung für Webanwendungen automatisieren"],"pt":["Geração de imagens com estilos e prompts específicos","Edição de imagens existentes usando técnicas de IA avançadas","Automação da criação de imagens para aplicações web"],"ru":["Генерация изображений с конкретными сти