INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/nanobanana-skill', 'nanobanana-skill', 'majiayu000', 'claude-skill-registry', 'community', 'nanobanana-skill majiayu000 claude-skill-registry community nanobanana-skill是一种基于Google Gemini API的图像生成工具，支持图像生成和编辑 nanobanana-skillはGoogle Gemini APIを使用した画像生成ツールで、画像生成と編集をサポート nanobanana-skill는 Google Gemini API를 사용한 이미지 생성 도구로 이미지 생성 및 편집을 지원 La habilidad nanobanana permite generar o editar imágenes mediante la API de Google Gemini. Requiere Python 3 y paquetes dependientes. La compétence nanobanana permet de générer ou de modifier des images à l''aide de l''API Google Gemini. Elle nécessite Python 3 et des packages dépendants. Die Fähigkeit nanobanana ermöglicht die Generierung oder Bearbeitung von Bildern mithilfe der Google Gemini-API. Sie erfordert Python 3 und abhängige Pakete. O nanobanana-skill é uma ferramenta para gerar ou editar imagens usando a API do Google Gemini. Requer configuração e instalação de pacotes Python Нанобанана-skill - это инструмент для генерации или редактирования изображений с помощью API Google Gemini. Требует настройки и установки пакетов Python nanobanana-skill هو أداة لتوليد أو تعديل الصور باستخدام API جوجل جيمي. يتطلب إعداد وتثبيت حزم بايثون The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app nanobanana-skill Google Gemini API 图像生成 图像编辑 Python3 环境变量 GEMINI_API_KEY pip 依赖包 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/serialization', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'serialization', 0, 0, 75, '2026-02-20T04:13:19.580Z', '2026-03-02T09:49:43.993Z', '0f1f254521079e26f086132d639c959b4ac7be6ad2ec8fe64be61724d9021779', '{"id":"majiayu000/claude-skill-registry/serialization","name":"serialization","description":{"zh":"选择合适的序列化格式，提高.NET应用性能。Protobuf和MessagePack等基于模式的格式通常优于Newtonsoft.Json等反射式格式","ja":".NETアプリケーションのパフォーマンスを向上させるために、適切なシリアル化形式を選択する。ProtobufやMessagePackなどのスキーマベースの形式は、Newtonsoft.Jsonなどのリフレクションベースの形式よりも優れている","ko":".NET 응용 프로그램의 성능을 향상시키는 적합한 직렬화 형식을 선택합니다. Protobuf와 MessagePack 등의 스키마 기반 형식은 Newtonsoft.Json 등의 리플렉션 기반 형식보다 뛰어납니다","es":"La serialización es crucial para aplicaciones .NET. Prefiere formatos basados en esquemas como Protobuf y MessagePack","fr":"La sérialisation est essentielle pour les applications .NET. Préférez les formats basés sur des schémas tels que Protobuf et MessagePack","de":"Die Serialisierung ist entscheidend für .NET-Anwendungen. bevorzugen Sie schemabasierte Formate wie Protobuf und MessagePack","pt":"A serialização é um processo crucial em aplicações .NET. Prefira formatos baseados em esquema como Protobuf e MessagePack para melhor desempenho.","ru":"Сериализация является важным процессом в приложениях .NET. Предпочитайте форматы на основе схем, такие как Protobuf и MessagePack, для лучшей производительности.","ar":"الترميز هو عملية حاسمة في تطبيقات .NET. افضل الصيغ القائمة على مخطط مثل Protobuf و MessagePack لتحقيق أداء أفضل.","en":"Choose the right serialization format for .NET applications. Prefer schema-based formats (Protobuf, MessagePack) over reflection-based (Newtonsoft.Json). Use System.Text.Json with AOT source generators for JSON scenarios."},"seo":{"title":{"zh":"AI智能代理：.NET序列化格式选择","ja":