INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/serialization', 'serialization', 'majiayu000', 'claude-skill-registry', 'community', 'serialization majiayu000 claude-skill-registry community 选择合适的序列化格式，提高.NET应用性能。Protobuf和MessagePack等基于模式的格式通常优于Newtonsoft.Json等反射式格式 .NETアプリケーションのパフォーマンスを向上させるために、適切なシリアル化形式を選択する。ProtobufやMessagePackなどのスキーマベースの形式は、Newtonsoft.Jsonなどのリフレクションベースの形式よりも優れている .NET 응용 프로그램의 성능을 향상시키는 적합한 직렬화 형식을 선택합니다. Protobuf와 MessagePack 등의 스키마 기반 형식은 Newtonsoft.Json 등의 리플렉션 기반 형식보다 뛰어납니다 La serialización es crucial para aplicaciones .NET. Prefiere formatos basados en esquemas como Protobuf y MessagePack La sérialisation est essentielle pour les applications .NET. Préférez les formats basés sur des schémas tels que Protobuf et MessagePack Die Serialisierung ist entscheidend für .NET-Anwendungen. bevorzugen Sie schemabasierte Formate wie Protobuf und MessagePack A serialização é um processo crucial em aplicações .NET. Prefira formatos baseados em esquema como Protobuf e MessagePack para melhor desempenho. Сериализация является важным процессом в приложениях .NET. Предпочитайте форматы на основе схем, такие как Protobuf и MessagePack, для лучшей производительности. الترميز هو عملية حاسمة في تطبيقات .NET. افضل الصيغ القائمة على مخطط مثل Protobuf و MessagePack لتحقيق أداء أفضل. Choose the right serialization format for .NET applications. Prefer schema-based formats (Protobuf, MessagePack) over reflection-based (Newtonsoft.Json). Use System.Text.Json with AOT source generators for JSON scenarios. 如何选择合适的序列化格式 什么是序列化 Protobuf与Newtonsoft.Json的比较 System.Text.Json安装 JSON序列化的优化 提高.NET应用性能的方法 AI智能代理工具 AI智能代理的应用 Choose the right serialization format for .NET applications. Prefer schema-based formats (Protobuf, MessagePack) over reflection-based (Newtonsoft.Json). Use System.Text.Json with AOT source generators for JSON scenarios.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-skills/github-actions', 'official', 'callstackincubator', 'agent-skills', 'callstackincubator/agent-skills', 'github-actions', 969, 57, 75, '2026-03-06T00:34:35Z', '2026-03-06T04:49:53.326Z', 'd6e8269aadc3653e5ae2fc422c612d542f77cc38a1b14d275ccd5bcc0102c32a', '{"id":"callstackincubator/agent-skills/github-actions","name":"github-actions","description":{"en":"The github-actions skill provides reusable workflow patterns for building React Native apps on iOS simulators and Android emulators in the cloud. It benefits developers setting up CI build pipelines.","es":"Patrones de flujo de trabajo de GitHub Actions para construir aplicaciones de React Native para simuladores de iOS y emuladores de Android en la nube","fr":"Modèles de workflow GitHub Actions pour construire des applications React Native pour les simulateurs iOS et les émulateurs Android dans le cloud","de":"Wiederverwendbare GitHub Actions-Muster zum Erstellen von React Native-Apps für iOS-Simulatoren und Android-Emulatoren in der Cloud","pt":"Padrões de workflow de GitHub Actions para builds de React Native em simuladores iOS e emuladores Android na nuvem","ru":"Шаблоны рабочих процессов GitHub Actions для сборки React Native приложений в облаке","ar":"أنماط سير عمل إجراءات GitHub لإنشاء تطبيقات React Native في السحابة"},"owner":"callstackincubator","repo":"agent-skills","repoPath":"callstackincubator/agent-skills","stars":969,"forks":57,"updatedAt":"2026-03-06T00:34:35Z","topics":[],"skillMd":{"name":"github-actions","description":"GitHub Actions workflow patterns for React Native iOS simulator and Android emulator cloud builds with downloadable artifacts. Use when setting up CI build pipelines or downloading GitHub Actions artifacts via gh CLI and GitHub API.","tags":"github-actions, github, ci, react-native, ios, android, simulator, emulator, artifacts, gh-cli","bodyPreview":"# GitHub Actions Build Artifacts\n\n## Overview\n\nReusable GitHub Actions patterns to build React Native apps for iOS simulators and Android emulators in the cloud, then publish artifacts retrievable via `gh` CLI or GitHub API.\n\n## When to Apply\n\nUse this skill when:\n- Creating CI workflows that build React Native simulator/emulator artifacts.\n- Uploading iOS simulator and Android emulator installables from PRs or manual dispatch runs.\n- Replacing local-only mobile builds with downloadable CI artif","body":"# GitHub Actions Build Artifacts\n\n## Overview\n\nReusable GitHub Actions patterns to build React Native apps for iOS simulators and Android emulators in the cloud, then publish artifacts retrievable via `gh` CLI or GitHub API.\n\n## When to Apply\n\nUse this skill when:\n- Creating CI workflows that build React Native simulator/emulator artifacts.\n- Uploading iOS simulator and Android emulator installables from PRs or manual dispatch runs.\n- Replacing local-only mobile builds with downloadable CI artifacts.\n- Needing stable artifact IDs/names for scripted retrieval with `gh` or REST API.\n\n## Quick Reference\n\n1. Add composite actions from [gha-ios-composite-action.md][gha-ios-composite-action] and [gha-android-composite-action.md][gha-android-composite-action].\n2. Wire them into `.github/workflows/mobile-build.yml` from [gha-workflow-and-downloads.md][gha-workflow-and-downloads].\n3. Upload with `actions/upload-artifact@v4` and capture `artifact-id` output.\n4. Download with `gh run download` or `GET /repos/{owner}/{repo}/actions/artifacts/{artifact_id}/{archive_format}`.\n\n## References\n\n| File | Description |\n|------|-------------|\n| [gha-ios-composite-action.md][gha-ios-composite-action] | Composite `action.yml` for iOS simulator `.app.tar.gz` builds and artifact upload |\n| [gha-android-composite-action.md][gha-android-composite-action] | Composite `action.yml` for Android emulator `.apk` builds and artifact upload |\n| [gha-workflow-and-downloads.md][gha-workflow-and-downloads] | End-to-end workflow wiring plus `gh` and REST download commands |\n\n## Problem -> Skill Mapping\n\n| Problem | Start With |\n|---------|------------|\n| Need CI iOS simulator `.app.tar.gz` artifact | [gha-ios-composite-action.md][gha-ios-composite-action] |\n| Need CI Android emulator `.apk` artifact | [gha-android-composite-action.md][gha-android-composite-action] |\n| Need one workflow to trigger both platform jobs | [gha-workflow-and-downloads.md][gha-workflow-and-downloads] |\n| Need scripted artifact download | [gha-workflow-and-downloads.md][gha-workflow-and-downloads] |\n\n## Source Inspiration\n\n- [callstackincubator/ios/action.yml](https://github.com/callstackincubator/ios/blob/main/action.yml)\n- [callstackincubator/android/action.yml](https://github.com/callstackincubator/android/blob/main/action.yml)\n\n[gha-ios-composite-action]: references/gha-ios-composite-action.md\n[gha-android-composite-action]: references/gha-android-composite-action.md\n[gha-workflow-and-downloads]: references/gha-workflow-and-downloads.md\n"},"category":"official","lastSynced":"2026-03-06T04:49:53.326Z","seo":{"title":{"en":"github-actions: Setup Guide for React Native CI Builds | ...","es":"Guía de configuración de GitHub Actions para CI de React ...","fr":"Guide de configuration de GitHub Actions pour le CI de Re...","de":"Konfigurationsleitfaden für GitHub Actions bei React Nati...","pt":"Guia de Configuração de GitHub Actions para Builds de Rea...","ru":"Настройка GitHub Actions для сборки React Native приложений","ar":"دليل إعداد إجراءات GitHub لإنشاء تطبيقات React Native"},"description":{"en":"Streamline your React Native app development with github-actions. Learn how to create CI workflows and download artifacts via gh CLI or GitHub API.","es":"Aprende a configurar GitHub Actions para crear artefactos de construcción de React Native para iOS y Android","fr":"Découvrez comment configurer GitHub Actions pour créer des artefacts de construction de React Native pour iOS et Android","de":"Erfahren Sie, wie Sie GitHub Actions für die Erstellung von React Native-Build-Artefakten für iOS und Android konfigurieren","pt":"Aprenda a configurar workflows de GitHub Actions para builds de React Native em simuladores iOS e emuladores Android na nuvem","ru":"Узнайте, как настроить рабочие процессы GitHub Actions для сборки React Native приложений в облаке","ar":"تعلم كيفية إعداد سير عمل إجراءات GitHub لإنشاء تطبيقات React Native في السحابة"},"definition":{"en":"github-actions is a set of reusable workflow patterns for building and publishing React Native app artifacts in the cloud.","es":"GitHub Actions es una herramienta de integración continua que permite crear artefactos de construcción de React Native para iOS y Android","fr":"GitHub Actions est un outil d''intégration continue qui permet de créer des artefacts de construction de React Native pour iOS et Android","de":"GitHub Actions ist ein Tool für die kontinuierliche Integration, mit dem Sie Build-Artefakte für React Native-Apps für iOS und Android erstellen können","pt":"GitHub Actions é uma ferramenta de automação de workflows que permite criar builds de React Native em simuladores iOS e emuladores Android","ru":"GitHub Actions - это инструмент автоматизации рабочих процессов, который позволяет создавать сборки React Native приложений в облаке","ar":"إجراءات GitHub هي أداة تلقيمية لسير العمل التي تسمح بإنشاء نسخ تطبيق React Native في المحاكي"},"features":{"en":["Builds React Native apps for iOS simulators and Android emulators in the cloud","Publishes artifacts retrievable via gh CLI or GitHub API","Supports creating CI workflows for simulator and emulator builds","Uploads iOS simulator and Android emulator installables from PRs or manual dispatch runs","Replaces local-only mobile builds with downloadable CI artifacts"],"es":["Creación de artefactos de construcción de React Native para iOS y Android","Uso de GitHub Actions para crear flujos de trabajo de CI","Publicación de artefactos en la nube para su descarga","Uso de la CLI de GitHub para descargar artefactos","Integración con la API de GitHub para recuperar artefactos","Compatibilidad con simuladores de iOS y emuladores de Android"],"fr":["Création d''artefacts de construction de React Native pour iOS et Android","Utilisation de GitHub Actions pour créer des flux de travail de CI","Publication d''artefacts dans le cloud pour téléchargement","Utilisation de la CLI GitHub pour télécharger des artefacts","Intégration avec l''API GitHub pour récupérer des artefacts","Compatibilité avec les simulateurs iOS et les émulateurs Android"],"de":["Erstellung von Build-Artefakten für React Native-Apps für iOS und Android","Verwendung von GitHub Actions zum Erstellen von CI-Workflows","Veröffentlichung von Artefakten in der Cloud zum Download","Verwendung der GitHub-CLI zum Herunterladen von Artefakten","Integration mit der GitHub-API zum Abrufen von Artefakten","Kompatibilität mit iOS-Simulatoren und Android-Emulatoren"],"pt":["Suporte a builds de React Native em simuladores iOS","Suporte a builds de React Native em emuladores Android","Publicação de artefatos via gh CLI","Publicação de artefatos via GitHub API","Integração com pipelines de CI","Downloads de artefatos via gh CLI"],"ru":["Поддержка сборки React Native приложений в симуляторах iOS","Поддержка сборки React Native приложений в эмуляторах Android","Публикация артефактов через gh CLI","Публикация артефактов через GitHub API","Интеграция с конвейерами CI","Загрузка артефактов через gh CLI"],"ar":["دعم إنشاء نسخ تطبيق React Native في محاكي iOS","دعم إنشاء نسخ تطبيق React Native في محاكي Android","نشر الملفات المكونة عبر واجهة سطر الأوامر gh","نشر الملفات المكونة عبر واجهة برمجة تطبيقات GitHub","التكامل مع أنابيب CI","تنزيل الملفات المكونة عبر واجهة سطر الأوامر gh"]},"keywords":{"en":["github-actions setup guide","github-actions react native","how to use github-actions for CI builds","github-actions vs circleci","github-actions alternative to jenkins","github-actions install","github-actions tutorial","github-actions workflow patterns","github-actions and react native"],"es":["GitHub Actions","React Native","CI","artefactos de construcción","iOS","Android","simuladores","emuladores","herramientas de integración continua"],"fr":["GitHub Actions","React Native","CI","artefacts de construction","iOS","Android","simulateurs","émulateurs","outils d''intégration continue"],"de":["GitHub Actions","React Native","CI","Build-Artefakte","iOS","Android","Simulatoren","Emulatoren","Tools für kontinuierliche Integration"],"pt":["github actions","react native","simulador ios","emulador android","pipeline de ci","arteatos github","gh cli","github api"],"ru":["github actions","react native","симулятор ios","эмулятор android","конвейер ci","артефакты github","gh cli","github api"],"ar":["إجراءات github","ري액ت نيتيف","محاكي ios","محاكي android","أنبوب ci","ملفات مكونة github","واجهة سطر الأوامر gh","واجهة برمجة تطبيقات github"]}},"agentAnalysis":{"suitability":{"en":"Ideal for CI/CD Automation Agents tasked with mobile app build pipeline orchestration.","zh":"适合用于CI/CD自动化代理，负责移动应用构建流水线编排。","ja":"CI/CD自動化エージェントに適しており、モバイルアプリのビルドパイプラインのオーケストレーションを担当します。","ko":"CI/CD 자동화 에이전트에 적합하며 모바일 앱 빌드 파이프라인 오케스트레이션을 담당합니다.","es":"Ideal para agentes de automatización de CI/CD encargados de la orquestación de la canalización de compilación de aplicaciones móviles.","fr":"Idéal pour les agents d''automatisation CI/CD chargés de l''orchestration de la canalisation de construction d''applications mobiles.","de":"Ideal für CI/CD-Automatisierungsagenten, die mit der Orchestrierung der Build-Pipeline für mobile Apps betraut sind.","pt":"Ideal para agentes de automação de CI/CD encarregados da orquestração de pipelines de compilação de aplicativos móveis.","ru":"Идеально подходит для агентов автоматизации CI/CD, задачей которых является оркестровка конвейеров сборки мобильных приложений.","ar":"مثالي لعميل آلي للتحكم التلقائي في CI/CD المكلف بorchestration خط أنابيب بناء التطبيقات المتنقلة."},"recommendation":{"en":"Enables agents to configure and execute React Native iOS simulator and Android emulator cloud builds through GitHub Actions workflows. It provides artifact generation and management capabilities via gh CLI and GitHub API integration for downloadable installables.","zh":"使代理能够通过GitHub Actions工作流配置和执行React Native iOS模拟器和Android模拟器云构建。它通过gh CLI和GitHub API集成提供构件生成和管理功能，以下载可安装文件。","ja":"エージェントがGitHub Actionsワークフローを介してReact NativeのiOSシミュレータとAndroidエミュレータのクラウドビルドを構成して実行できるようにします。gh CLIとGitHub APIの統合を介してダウンロード可能なインストーラブルを提供するアーティファクト生成および管理機能を提供します。","ko":"에이전트가 GitHub Actions 워크플ロー 통해 React Native의 iOS 시뮬레이터와 안드로이드 에뮬레이터의 클라우드 빌드를 구성하고 실행할 수 있도록 합니다. gh CLI와 GitHub API의 통합을 통해 다운로드 가능한 설치 파일을 제공하는 아티팩트 생성 및 관리 기능을 제공합니다.","es":"Permite a los agentes configurar y ejecutar la construcción de simuladores iOS de React Native y emuladores de Android en la nube a través de flujos de trabajo de GitHub Actions. Proporciona capacidades de generación y administración de artefactos a través de la integración de gh CLI y GitHub API para instalables descargables.","fr":"Permet aux agents de configurer et d''exécuter la construction de simulateurs iOS React Native et d''émulateurs Android dans le cloud via les flux de travail GitHub Actions. Il fournit des capacités de génération et de gestion d''artefacts via l''intégration de gh CLI et de l''API GitHub pour des installables téléchargeables.","de":"Ermöglicht es Agenten, React Native iOS-Simulator- und Android-Emulator-Cloud-Builds über GitHub Actions-Workflows zu konfigurieren und auszuführen. Es bietet Fähigkeiten zur Artefaktgenerierung und -verwaltung über die Integration von gh CLI und GitHub API für herunterladbare Installationsprogramme.","pt":"Permite que os agentes configurem e executem build de simulador iOS do React Native e build de emulador Android na nuvem por meio de fluxos de trabalho do GitHub Actions. Ele fornece capacidades de geração e gerenciamento de artefatos por meio da integração do gh CLI e da API do GitHub para instalações baixáveis.","ru":"Позволяет агентам настраивать и выполнять сборку симулятора iOS React Native и сборку эмулятора Android в облаке через рабочие процессы GitHub Actions. Он обеспечивает возможности генерации и управления артефактами через интеграцию с gh CLI и GitHub API для загружаемых установщиков.","ar":"يمكن للوكلاء تكوين تشغيل بناء محاكي iOS React Native وبناء محاكي Android السحابي من خلال تدفقات العمل GitHub Actions. يتيح القدرات على توليد إدارة المكونات الإضافية من خلال دمج واجهة سطر الأوامر gh وواجهة برمجة تطبيقات GitHub للبرامج القابلة للتنزيل."},"useCases":{"en":["Automating React Native CI build pipelines","Publishing iOS simulator artifacts from PR runs","Generating Android emulator installables via manual dispatch","Retrieving build artifacts through GitHub API integration"],"zh":["自动化React Native CI构建流水线","从PR运行发布iOS模拟器构件","通过手动调度生成Android模拟器安装文件","通过GitHub API集成检索构建构件"],"ja":["React Native CIビルドパイプラインの自動化","PR実行からiOSシミュレータアーティファクトを公開","手動ディスパッチを介してAndroidエミュレータインストーラブルを生成","GitHub API統合を介してビルドアーティファクトを取得"],"ko":["React Native CI 빌드 파이프라인 자동화","PR 실행에서 iOS 시뮬레이터 아티팩트를 공개","수동 디스패치를 통해 안드로이드 에뮬레이터 설치 파일을 생성","GitHub API 통합을 통해 빌드 아티팩트를 가져오기"],"es":["Automatización de canalizaciones de construcción de CI de React Native","Publicación de artefactos del simulador de iOS desde ejecuciones de PR","Generación de instalables de emulador de Android a través de envío manual","Recuperación de artefactos de construcción a través de la integración de la API de GitHub"],"fr":["Automatisation des canalizations de construction de CI React Native","Publication d''artefacts de simulateur iOS à partir d''exécutions de PR","Génération d''installables d''émulateur Android via envoi manuel","Récupération d''artefacts de construction via l''intégration de l''API GitHub"],"de":["Automatisierung von React Native CI-Build-Pipelines","Veröffentlichung von iOS-Simulator-Artefakten aus PR-Läufen","Generierung von Android-Emulator-Installationsprogrammen über manuelle Sendung","Abruf von Build-Artefakten über die GitHub API-Integration"],"pt":["Automatizar pipelines de compilação de CI do React Native","Publicar artefatos do simulador iOS de execuções de PR","Gerar instalações do emulador Android por meio de despacho manual","Recuperar artefatos de compilação por meio da integração da API do GitHub"],"ru":["Автоматизировать конвейеры сборки CI React Native","Публиковать артефакты симулятора iOS из запусков PR","Генерировать установщики эмулятора Android через ручной диспетчер","Извлекать артефакты сборки через интеграцию с GitHub API"],"ar":["التحكم التلقائي في خطوط أنابيب بناء CI لل React Native","نشر مكونات إضافية لمحاكي iOS من تشغيل PR","توليد برامج إضافية لمحاكي Android عبر الإرسال اليدوي","استرجاع مكونات بناء من خلال دمج واجهة برمجة تطبيقات GitHub"]},"limitations":{"en":["Specifically for React Native mobile applications","Requires GitHub Actions workflow configuration","Focuses on simulator/emulator builds only"],"zh":["专门用于React Native移动应用","需要GitHub Actions工作流配置","仅关注模拟器/模拟器构建"],"ja":["React Nativeモバイルアプリケーション専用","GitHub Actionsワークフローの構成が必要","シミュレータ/エミュレータビルドのみに焦点を当てている"],"ko":["React Native 모바일 애플리케이션 전용","GitHub Actions 워크플로우 구성이 필요","시뮬레이터/에뮬레이터 빌드만을 중점으로 하는"],"es":["Específicamente para aplicaciones móviles de React Native","Requiere configuración de flujos de trabajo de GitHub Actions","Se centra únicamente en construcciones de simulador/emulador"],"fr":["Spécifiquement pour les applications mobiles React Native","Nécessite une configuration de flux de travail GitHub Actions","Se concentre uniquement sur les constructions de simulateur/émulateur"],"de":["Speziell für React Native Mobile-Anwendungen","Benötigt eine Konfiguration von GitHub Actions-Workflows","Konzentriert sich ausschließlich auf Simulator/Emulator-Builds"],"pt":["Especificamente para aplicativos móveis do React Native","Exige configuração de fluxo de trabalho do GitHub Actions","Se concentra apenas em compilações de simulador/emulador"],"ru":["В частности, для мобильных приложений React Native","Требует настройки рабочего процесса GitHub Actions","Фокусируется только на сборках симулятора/эмулятора"],"ar":["特别 لبرامج الهواتف المحمولة React Native","يتطلب تكوين تدفق عمل GitHub Actions","يركز فقط على بناء المحاكي / المحاكي"]},"version":4},"contentHash":"d6e8269aadc3653e5ae2fc422c612d542f77cc38a1b14d275ccd5bcc0102c32a","repoEtag":"W/\"cde3f79b6c913438993afe18fdb53c1f5dcf7c814f31b8ef5104f2d45f6ca3dc\"","qualityScore":75}');
