INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callstackincubator/agent-skills/github-actions', 'github-actions', 'callstackincubator', 'agent-skills', 'official', 'github-actions callstackincubator agent-skills official The github-actions skill provides reusable workflow patterns for building React Native apps on iOS simulators and Android emulators in the cloud. It benefits developers setting up CI build pipelines. Patrones de flujo de trabajo de GitHub Actions para construir aplicaciones de React Native para simuladores de iOS y emuladores de Android en la nube Modèles de workflow GitHub Actions pour construire des applications React Native pour les simulateurs iOS et les émulateurs Android dans le cloud Wiederverwendbare GitHub Actions-Muster zum Erstellen von React Native-Apps für iOS-Simulatoren und Android-Emulatoren in der Cloud Padrões de workflow de GitHub Actions para builds de React Native em simuladores iOS e emuladores Android na nuvem Шаблоны рабочих процессов GitHub Actions для сборки React Native приложений в облаке أنماط سير عمل إجراءات GitHub لإنشاء تطبيقات React Native في السحابة github-actions setup guide github-actions react native how to use github-actions for CI builds github-actions vs circleci github-actions alternative to jenkins github-actions install github-actions tutorial github-actions workflow patterns github-actions and react native Builds React Native apps for iOS simulators and Android emulators in the cloud Publishes artifacts retrievable via gh CLI or GitHub API Supports creating CI workflows for simulator and emulator builds Uploads iOS simulator and Android emulator installables from PRs or manual dispatch runs Replaces local-only mobile builds with downloadable CI artifacts github-actions is a set of reusable workflow patterns for building and publishing React Native app artifacts in the cloud.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/webapp-testing', 'official', 'anthropics', 'skills', 'anthropics/skills', 'webapp-testing', 85097, 8974, 74, '2026-03-06T03:11:21Z', '2026-03-06T03:25:46.308Z', '51b7349e77ec63b7744a6f63647e7566a0b4d2e301121cc10e8c2113af6556a2', '{"id":"anthropics/skills/webapp-testing","name":"webapp-testing","description":{"en":"The webapp-testing skill enables developers to test local web applications using Playwright, supporting frontend functionality verification and UI behavior debugging. It benefits developers working on web applications.","zh":"webapp-testing是一个AI代理技能工具包，使用Playwright进行本地Web应用测试。提供原生Python脚本编写，支持前端功能验证、UI行为调试和浏览器日志捕获。包含服务器生命周期管理助手脚本。","ja":"webapp-testingは、Playwrightを使用したローカルWebアプリケーションのテストを行うAIエージェントスキルツールキットです。ネイティブPythonスクリプト作成、フロントエンド機能検証、UI動作デバッグ、ブラウザログキャプチャをサポート。サーバーライフサイクル管理ヘルパースクリプトを含みます。","ko":"webapp-testing은 Playwright를 사용한 로컬 웹 애플리케이션 테스트를 위한 AI 에이전트 스킬 툴킷입니다. 네이티브 Python 스크립트 작성, 프론트엔드 기능 검증, UI 동작 디버깅, 브라우저 로그 캡처를 지원. 서버 라이프사이클 관리 헬퍼 스크립트를 포함합니다.","es":"El conjunto de herramientas de pruebas de aplicaciones web utiliza Playwright para interactuar con aplicaciones web locales, permitiendo la verificación de funcionalidad frontend y la depuración de comportamiento de UI","fr":"L''ensemble d''outils de test d''applications web utilise Playwright pour interagir avec des applications web locales, permettant la vérification de la fonctionnalité frontend et le débogage du comportement de l''UI","de":"Der Satz von Webanwendungstest-Tools verwendet Playwright, um mit lokalen Webanwendungen zu interagieren, und ermöglicht die Überprüfung der Frontend-Funktionalität und die Fehlersuche bei UI-Verhalten"},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"webapp-testing","description":"Toolkit for interacting with and testing local web applications using Playwright. Supports verifying frontend functionality, debugging UI behavior, capturing browser screenshots, and viewing browser logs.","bodyPreview":"# Web Application Testing\n\nTo test local web applications, write native Python Playwright scripts.\n\n**Helper Scripts Available**:\n- `scripts/with_server.py` - Manages server lifecycle (supports multiple servers)\n\n**Always run scripts with `--help` first** to see usage. DO NOT read the source until you try running the script first and find that a customized solution is abslutely necessary. These scripts can be very large and thus pollute your context window. They exist to be called directly as bl","body":"# Web Application Testing\n\nTo test local web applications, write native Python Playwright scripts.\n\n**Helper Scripts Available**:\n- `scripts/with_server.py` - Manages server lifecycle (supports multiple servers)\n\n**Always run scripts with `--help` first** to see usage. DO NOT read the source until you try running the script first and find that a customized solution is abslutely necessary. These scripts can be very large and thus pollute your context window. They exist to be called directly as black-box scripts rather than ingested into your context window.\n\n## Decision Tree: Choosing Your Approach\n\n```\nUser task → Is it static HTML?\n    ├─ Yes → Read HTML file directly to identify selectors\n    │         ├─ Success → Write Playwright script using selectors\n    │         └─ Fails/Incomplete → Treat as dynamic (below)\n    │\n    └─ No (dynamic webapp) → Is the server already running?\n        ├─ No → Run: python scripts/with_server.py --help\n        │        Then use the helper + write simplified Playwright script\n        │\n        └─ Yes → Reconnaissance-then-action:\n            1. Navigate and wait for networkidle\n            2. Take screenshot or inspect DOM\n            3. Identify selectors from rendered state\n            4. Execute actions with discovered selectors\n```\n\n## Example: Using with_server.py\n\nTo start a server, run `--help` first, then use the helper:\n\n**Single server:**\n```bash\npython scripts/with_server.py --server \"npm run dev\" --port 5173 -- python your_automation.py\n```\n\n**Multiple servers (e.g., backend + frontend):**\n```bash\npython scripts/with_server.py \\\n  --server \"cd backend && python server.py\" --port 3000 \\\n  --server \"cd frontend && npm run dev\" --port 5173 \\\n  -- python your_automation.py\n```\n\nTo create an automation script, include only Playwright logic (servers are managed automatically):\n```python\nfrom playwright.sync_api import sync_playwright\n\nwith sync_playwright() as p:\n    browser = p.chromium.launch(headless=True) # Always launch chromium in headless mode\n    page = browser.new_page()\n    page.goto(''http://localhost:5173'') # Server already running and ready\n    page.wait_for_load_state(''networkidle'') # CRITICAL: Wait for JS to execute\n    # ... your automation logic\n    browser.close()\n```\n\n## Reconnaissance-Then-Action Pattern\n\n1. **Inspect rendered DOM**:\n   ```python\n   page.screenshot(path=''/tmp/inspect.png'', full_page=True)\n   content = page.content()\n   page.locator(''button'').all()\n   ```\n\n2. **Identify selectors** from inspection results\n\n3. **Execute actions** using discovered selectors\n\n## Common Pitfall\n\n❌ **Don''t** inspect the DOM before waiting for `networkidle` on dynamic apps\n✅ **Do** wait for `page.wait_for_load_state(''networkidle'')` before inspection\n\n## Best Practices\n\n- **Use bundled scripts as black boxes** - To accomplish a task, consider whether one of the scripts available in `scripts/` can help. These scripts handle common, complex workflows reliably without cluttering the context window. Use `--help` to see usage, then invoke directly. \n- Use `sync_playwright()` for synchronous scripts\n- Always close the browser when done\n- Use descriptive selectors: `text=`, `role=`, CSS selectors, or IDs\n- Add appropriate waits: `page.wait_for_selector()` or `page.wait_for_timeout()`\n\n## Reference Files\n\n- **examples/** - Examples showing common patterns:\n  - `element_discovery.py` - Discovering buttons, links, and inputs on a page\n  - `static_html_automation.py` - Using file:// URLs for local HTML\n  - `console_logging.py` - Capturing console logs during automation"},"category":"official","lastSynced":"2026-03-06T03:25:46.308Z","seo":{"title":{"en":"webapp-testing: Playwright Setup Guide | AI Agent Skill","zh":"webapp-testing AI代理设置指南：使用Playwright测试本地Web应用","ja":"webapp-testing AIエージェントのベストプラクティス：Playwrightを使ったローカルWebアプ...","ko":"webapp-testing AI 에이전트 설정 가이드: Playwright로 로컬 웹 앱 테스트","es":"Guía de configuración para pruebas de aplicaciones web co...","fr":"Guide de configuration pour les tests d''applications web ...","de":"Einrichtungsleitfaden für Webanwendungstests mit Playwright"},"description":{"en":"Unlock efficient web application testing with webapp-testing. Learn how to leverage Playwright for seamless frontend verification and debugging. Get started ...","zh":"使用Playwright AI代理技能测试本地Web应用。支持前端功能验证、UI调试、浏览器截图和日志查看。包含服务器生命周期管理脚本，专为开发者设计。","ja":"Playwright AIエージェントスキルを使用したローカルWebアプリケーションのテスト。フロントエンド機能検証、UIデバッグ、ブラウザスクリーンショット、ログ表示をサポート。サーバーライフサイクル管理スクリプトを含む。","ko":"Playwright AI 에이전트 스킬을 사용한 로컬 웹 애플리케이션 테스트. 프론트엔드 기능 검증, UI 디버깅, 브라우저 스크린샷 및 로그 보기를 지원. 서버 라이프사이클 관리 스크립트 포함.","es":"Aprende a probar aplicaciones web locales con Playwright y scripts de Python, incluyendo verificación de funcionalidad frontend y depuración de comportamient...","fr":"Découvrez comment tester des applications web locales avec Playwright et des scripts Python, y compris la vérification de la fonctionnalité frontend et le dé...","de":"Erfahren Sie, wie Sie lokale Webanwendungen mit Playwright und Python-Skripten testen, einschließlich Überprüfung der Frontend-Funktionalität und Fehlersuche..."},"definition":{"en":"webapp-testing is a toolkit for interacting with and testing local web applications using Playwright, supporting features like browser screenshot capture and log viewing.","zh":"webapp-testing是一个基于Playwright的AI代理测试工具包，专门用于本地Web应用程序的交互和测试。它提供前端功能验证、UI调试、浏览器截图和日志查看功能，包含服务器生命周期管理脚本，支持多服务器环境。","ja":"webapp-testingは、PlaywrightベースのAIエージェントテストツールキットで、ローカルWebアプリケーションの対話とテストに特化しています。フロントエンド機能検証、UIデバッグ、ブラウザスクリーンショット、ログ表示機能を提供し、サーバーライフサイクル管理スクリプトを含み複数サーバー環境をサポートします。","ko":"webapp-testing은 Playwright 기반의 AI 에이전트 테스트 툴킷으로, 로컬 웹 애플리케이션 상호작용 및 테스트에 특화되어 있습니다. 프론트엔드 기능 검증, UI 디버깅, 브라우저 스크린샷, 로그 보기 기능을 제공하며 서버 라이프사이클 관리 스크립트를 포함해 다중 서버 환경을 지원합니다.","es":"Herramienta de pruebas de aplicaciones web que utiliza Playwright para interactuar con aplicaciones web locales y verificar su funcionalidad","fr":"Outil de test d''applications web qui utilise Playwright pour interagir avec des applications web locales et vérifier leur fonctionnalité","de":"Tool für Webanwendungstests, das Playwright verwendet, um mit lokalen Webanwendungen zu interagieren und ihre Funktionalität zu überprüfen"},"features":{"en":["Verifies frontend functionality using native Python Playwright scripts","Supports debugging UI behavior with browser logs and screenshots","Utilizes helper scripts like scripts/with_server.py for server lifecycle management","Enables capturing browser screenshots for visual verification","Allows viewing browser logs for debugging purposes","Supports multiple servers with scripts/with_server.py"],"zh":["使用原生Python编写Playwright测试脚本","支持前端功能验证和UI行为调试","浏览器截图和日志查看功能","包含服务器生命周期管理脚本(scripts/with_server.py)","支持多服务器环境测试","提供--help命令行帮助功能"],"ja":["ネイティブPythonでのPlaywrightテストスクリプト作成","フロントエンド機能検証とUI動作デバッグのサポート","ブラウザスクリーンショットとログ表示機能","サーバーライフサイクル管理スクリプト(scripts/with_server.py)を含む","複数サーバー環境テストのサポート","--helpコマンドラインヘルプ機能の提供"],"ko":["네이티브 Python Playwright 테스트 스크립트 작성","프론트엔드 기능 검증 및 UI 동작 디버깅 지원","브라우저 스크린샷 및 로그 보기 기능","서버 라이프사이클 관리 스크립트(scripts/with_server.py) 포함","다중 서버 환경 테스트 지원","--help 명령줄 도움말 기능 제공"],"es":["Interacción con aplicaciones web locales mediante Playwright","Verificación de funcionalidad frontend","Depuración de comportamiento de UI","Captura de pantallas de navegador","Visualización de registros de navegador"],"fr":["Interaction avec des applications web locales via Playwright","Vérification de la fonctionnalité frontend","Débogage du comportement de l''UI","Capture d''écrans de navigateur","Visualisation des journaux de navigateur"],"de":["Interaktion mit lokalen Webanwendungen über Playwright","Überprüfung der Frontend-Funktionalität","Fehlersuche bei UI-Verhalten","Aufnahme von Browser-Screenshots","Anzeige von Browser-Logs"]},"keywords":{"en":["how to use webapp-testing","webapp-testing setup guide","Playwright web application testing","webapp-testing alternative","webapp-testing vs Selenium","webapp-testing install","what is webapp-testing","webapp-testing tutorial","webapp-testing Playwright scripts"],"zh":["Playwright测试脚本","本地Web应用测试","AI代理工具","前端功能验证","UI调试工具","浏览器截图","服务器生命周期管理","Python测试自动化"],"ja":["Playwrightテストスクリプト","ローカルWebアプリケーションテスト","AIエージェントツール","フロントエンド機能検証","UIデバッグツール","ブラウザスクリーンショット","サーバーライフサイクル管理","Pythonテスト自動化"],"ko":["Playwright 테스트 스크립트","로컬 웹 애플리케이션 테스트","AI 에이전트 도구","프론트엔드 기능 검증","UI 디버깅 도구","브라우저 스크린샷","서버 라이프사이클 관리","Python 테스트 자동화"],"es":["pruebas de aplicaciones web","Playwright","Python","verificación de funcionalidad frontend","depuración de UI","herramientas de pruebas de aplicaciones web","tests de aplicaciones web","desarrollo de aplicaciones web","Agente de pruebas de aplicaciones web"],"fr":["tests d''applications web","Playwright","Python","vérification de la fonctionnalité frontend","débogage de l''UI","outils de test d''applications web","développement d''applications web","Agent de tests d''applications web","Outil de tests d''applications web"],"de":["Webanwendungstests","Playwright","Python","Überprüfung der Frontend-Funktionalität","Fehlersuche bei UI-Verhalten","Webanwendungstest-Tools","Webanwendungs-Entwicklung","Webanwendungstest-Agent","Ihre Webanwendung testen"]}},"agentAnalysis":{"suitability":{"en":"Perfect for QA Automation Agents needing browser-based testing capabilities for local web applications.","zh":"非常适合需要为本地Web应用程序提供基于浏览器的测试功能的QA自动化Agent。","ja":"ローカルWebアプリケーションに対するブラウザベースのテスト機能を必要とするQA自動化エージェントに最適です。","ko":"로컬 웹 애플리케이션에 대한 브라우저 기반 테스트 기능이 필요한 QA 자동화 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Automatización de QA que necesitan capacidades de pruebas basadas en navegador para aplicaciones web locales.","fr":"Parfait pour les Agents d''Automatisation QA ayant besoin de capacités de test basées sur le navigateur pour des applications web locales.","de":"Perfekt für QA-Automatisierungs-Agents, die browserbasierte Testfähigkeiten für lokale Webanwendungen benötigen.","pt":"Perfeito para Agentes de Automação de QA que necessitam de capacidades de teste baseadas em navegador para aplicações web locais.","ru":"Идеально подходит для агентов автоматизации тестирования (QA), которым требуются возможности тестирования на основе браузера для локальных веб-приложений.","ar":"مثالي لوكلات أتمتة ضمان الجودة التي تحتاج إلى قدرات اختبار قائمة على المتصفح للتطبيقات المحلية."},"recommendation":{"en":"Enables automated frontend testing and debugging using Playwright scripts, including UI behavior verification, browser screenshot capture, and log viewing. Supports multiple server lifecycle management through Python helper scripts.","zh":"支持使用Playwright脚本进行自动化前端测试和调试，包括UI行为验证、浏览器截图捕获和日志查看。通过Python helper脚本支持多服务器生命周期管理。","ja":"Playwrightスクリプトを使用した自動化フロントエンドテストとデバッグを可能にします。これには、UI動作の検証、ブラウザのスクリーンショットキャプチャ、ログの表示が含まれます。Pythonヘルパースクリプトを通じて複数のサーバーライフサイクル管理をサポートします。","ko":"Playwright 스크립트를 사용하여 UI 동작 검증, 브라우저 스크린샷 캡처, 로그 보기를 포함한 자동화된 프론트엔드 테스트 및 디버깅을 가능하게 합니다. Python 헬퍼 스크립트를 통해 다중 서버 라이프사이클 관리를 지원합니다.","es":"Permite pruebas y depuración automatizadas del frontend utilizando scripts de Playwright, incluyendo verificación del comportamiento de la UI, captura de capturas de pantalla del navegador y visualización de registros. Admite la gestión del ciclo de vida de múltiples servidores a través de scripts auxiliares de Python.","fr":"Permet des tests et un débogage automatisés du frontend en utilisant des scripts Playwright, incluant la vérification du comportement de l''UI, la capture de captures d''écran du navigateur et la consultation des journaux. Prend en charge la gestion du cycle de vie de multiples serveurs via des scripts d''assistance Python.","de":"Ermöglicht automatisiertes Frontend-Testing und Debugging mit Playwright-Skripten, einschließlich UI-Verhaltensverifikation, Erfassung von Browser-Screenshots und Protokollanzeige. Unterstützt die Lebenszyklusverwaltung mehrerer Server durch Python-Hilfsskripte.","pt":"Permite testes e depuração automatizados de frontend usando scripts Playwright, incluindo verificação de comportamento da UI, captura de screenshots do navegador e visualização de logs. Suporta o gerenciamento de múltiplos ciclos de vida de servidor através de scripts auxiliares em Python.","ru":"Позволяет проводить автоматизированное фронтенд-тестирование и отладку с использованием скриптов Playwright, включая проверку поведения пользовательского интерфейса, захват снимков экрана браузера и просмотр журналов. Поддерживает управление несколькими жизненными циклами серверов с помощью вспомогательных скриптов Python.","ar":"يتيح إجراء اختبارات وتصحيح أخطاء واجهة المستخدم الأمامية الآلية باستخدام نصوص Playwright، بما في ذلك التحقق من سلوك واجهة المستخدم، والتقاط لقطات شاشة المتصفح، وعرض السجلات. يدعم إدارة دورة حياة خوادم متعددة من خلال نصوص مساعدة بلغة Python."},"useCases":{"en":["Verifying frontend functionality of local web apps","Debugging UI behavior and capturing screenshots","Managing multiple server lifecycles during testing","Viewing browser console logs for error analysis"],"zh":["验证本地Web应用程序的前端功能","调试UI行为并捕获屏幕截图","在测试期间管理多个服务器生命周期","查看浏览器控制台日志以进行错误分析"],"ja":["ローカルWebアプリケーションのフロントエンド機能の検証","UI動作のデバッグとスクリーンショットのキャプチャ","テスト中の複数サーバーライフサイクルの管理","エラー分析のためのブラウザコンソールログの表示"],"ko":["로컬 웹 앱의 프론트엔드 기능 검증","UI 동작 디버깅 및 스크린샷 캡처","테스트 중 다중 서버 라이프사이클 관리","오류 분석을 위한 브라우저 콘솔 로그 확인"],"es":["Verificación de la funcionalidad del frontend de aplicaciones web locales","Depuración del comportamiento de la UI y captura de capturas de pantalla","Gestión de múltiples ciclos de vida del servidor durante las pruebas","Visualización de los registros de la consola del navegador para el análisis de errores"],"fr":["Vérification de la fonctionnalité frontend des applications web locales","Débogage du comportement de l''UI et capture de captures d''écran","Gestion de multiples cycles de vie de serveur pendant les tests","Consultation des journaux de la console du navigateur pour l''analyse des erreurs"],"de":["Verifizierung der Frontend-Funktionalität lokaler Web-Apps","Debugging des UI-Verhaltens und Erfassen von Screenshots","Verwaltung mehrerer Server-Lebenszyklen während des Testens","Anzeigen der Browser-Konsolenprotokolle für die Fehleranalyse"],"pt":["Verificação da funcionalidade de frontend de aplicações web locais","Depuração de comportamento da UI e captura de screenshots","Gerenciamento de múltiplos ciclos de vida de servidor durante os testes","Visualização de logs do console do navegador para análise de erros"],"ru":["Проверка функциональности фронтенда локальных веб-приложений","Отладка поведения пользовательского интерфейса и захват снимков экрана","Управление несколькими жизненными циклами серверов во время тестирования","Просмотр журналов консоли браузера для анализа ошибок"],"ar":["التحقق من وظائف واجهة المستخدم الأمامية للتطبيقات المحلية","تصحيح سلوك واجهة المستخدم والتقاط لقطات الشاشة","إدارة دورات حياة خوادم متعددة أثناء الاختبار","عرض سجلات وحدة تحكم المتصفح لتحليل الأخطاء"]},"limitations":{"en":["Requires local web application access","Python Playwright dependency","Server lifecycle management limited to supported configurations","Scripts must be run with --help first to avoid context pollution"],"zh":["需要本地Web应用程序访问权限","依赖Python Playwright","服务器生命周期管理仅限于支持的配置","脚本必须首先使用--help运行以避免上下文污染"],"ja":["ローカルWebアプリケーションへのアクセスが必要","Python Playwrightへの依存","サーバーライフサイクル管理はサポート対象の構成に限定される","コンテキストの汚染を避けるために、スクリプトは最初に--helpを付けて実行する必要がある"],"ko":["로컬 웹 애플리케이션 접근 권한 필요","Python Playwright 종속성","서버 라이프사이클 관리가 지원되는 구성으로 제한됨","컨텍스트 오염을 피하기 위해 스크립트는 먼저 --help로 실행해야 함"],"es":["Requiere acceso a la aplicación web local","Dependencia de Python Playwright","La gestión del ciclo de vida del servidor limitada a configuraciones compatibles","Los scripts deben ejecutarse primero con --help para evitar la contaminación del contexto"],"fr":["Nécessite un accès à l''application web locale","Dépendance à Python Playwright","Gestion du cycle de vie du serveur limitée aux configurations prises en charge","Les scripts doivent d''abord être exécutés avec --help pour éviter la pollution du contexte"],"de":["Erfordert Zugriff auf die lokale Webanwendung","Abhängigkeit von Python Playwright","Server-Lebenszyklusverwaltung auf unterstützte Konfigurationen beschränkt","Skripte müssen zuerst mit --help ausgeführt werden, um Kontextverschmutzung zu vermeiden"],"pt":["Requer acesso à aplicação web local","Dependência do Playwright para Python","O gerenciamento do ciclo de vida do servidor está limitado às configurações suportadas","Os scripts devem ser executados primeiro com --help para evitar poluição de contexto"],"ru":["Требуется доступ к локальному веб-приложению","Зависимость от Python Playwright","Управление жизненным циклом сервера ограничено поддерживаемыми конфигурациями","Скрипты сначала должны быть запущены с --help, чтобы избежать загрязнения контекста"],"ar":["يتطلب الوصول إلى التطبيق المحلي","الاعتماد على Python Playwright","إدارة دورة حياة الخادم محدودة بالتكوينات المدعومة","يجب تشغيل النصوص أولاً باستخدام --help لتجنب تلويث السياق"]},"version":4},"contentHash":"51b7349e77ec63b7744a6f63647e7566a0b4d2e301121cc10e8c2113af6556a2","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":74}');
