INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/webapp-testing', 'webapp-testing', 'anthropics', 'skills', 'official', 'webapp-testing anthropics skills official agent-skills The webapp-testing skill enables developers to test local web applications using Playwright, supporting frontend functionality verification and UI behavior debugging. It benefits developers working on web applications. webapp-testing是一个AI代理技能工具包，使用Playwright进行本地Web应用测试。提供原生Python脚本编写，支持前端功能验证、UI行为调试和浏览器日志捕获。包含服务器生命周期管理助手脚本。 webapp-testingは、Playwrightを使用したローカルWebアプリケーションのテストを行うAIエージェントスキルツールキットです。ネイティブPythonスクリプト作成、フロントエンド機能検証、UI動作デバッグ、ブラウザログキャプチャをサポート。サーバーライフサイクル管理ヘルパースクリプトを含みます。 webapp-testing은 Playwright를 사용한 로컬 웹 애플리케이션 테스트를 위한 AI 에이전트 스킬 툴킷입니다. 네이티브 Python 스크립트 작성, 프론트엔드 기능 검증, UI 동작 디버깅, 브라우저 로그 캡처를 지원. 서버 라이프사이클 관리 헬퍼 스크립트를 포함합니다. El conjunto de herramientas de pruebas de aplicaciones web utiliza Playwright para interactuar con aplicaciones web locales, permitiendo la verificación de funcionalidad frontend y la depuración de comportamiento de UI L''ensemble d''outils de test d''applications web utilise Playwright pour interagir avec des applications web locales, permettant la vérification de la fonctionnalité frontend et le débogage du comportement de l''UI Der Satz von Webanwendungstest-Tools verwendet Playwright, um mit lokalen Webanwendungen zu interagieren, und ermöglicht die Überprüfung der Frontend-Funktionalität und die Fehlersuche bei UI-Verhalten how to use webapp-testing webapp-testing setup guide Playwright web application testing webapp-testing alternative webapp-testing vs Selenium webapp-testing install what is webapp-testing webapp-testing tutorial webapp-testing Playwright scripts Playwright测试脚本 本地Web应用测试 AI代理工具 前端功能验证 UI调试工具 浏览器截图 服务器生命周期管理 Python测试自动化 Verifies frontend functionality using native Python Playwright scripts Supports debugging UI behavior with browser logs and screenshots Utilizes helper scripts like scripts/with_server.py for server lifecycle management Enables capturing browser screenshots for visual verification Allows viewing browser logs for debugging purposes Supports multiple servers with scripts/with_server.py webapp-testing is a toolkit for interacting with and testing local web applications using Playwright, supporting features like browser screenshot capture and log viewing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/using-superpowers', 'official', 'obra', 'superpowers', 'obra/superpowers', 'using-superpowers', 71924, 5546, 74, '2026-03-06T03:26:30Z', '2026-03-06T03:37:04.330Z', '07d73726944e38fac59b9c90d876e0f714e395308b357973ae77b1321fc75067', '{"id":"obra/superpowers/using-superpowers","name":"using-superpowers","description":{"en":"The using-superpowers skill establishes a mandatory protocol for AI agents to invoke applicable skills before generating any response. It provides developers with strict technical requirements for accessing and implementing skills through Claude Code''s Skill tool interface.","zh":"超能力技能是用于提高工作效率的必备工具。通过使用Skill工具，可以轻松访问和使用技能","ja":"超能力スキルは、AIエージェントを使用して作業効率を向上させるための重要なツールです。スキルツールを使用して、スキルにアクセスし、使用できます","ko":"슈퍼파워 스킬은 작업 효율성을 높이는 데 필요한 도구입니다. 스킬 도구를 사용하여 쉽게 스킬에 접근하고 사용할 수 있습니다","es":"Skill técnica que obliga la invocación de herramientas Skill en Claude Code antes de cualquier respuesta, incluyendo preguntas de clarificación. Implementa requisitos estrictos de uso de habilidades cuando existe un 1% de aplicabilidad.","fr":"Compétence technique qui impose l''invocation d''outils Skill dans Claude Code avant toute réponse, y compris les questions de clarification. Implémente des exigences strictes d''utilisation des compétences.","de":"Technische Skill, die die Verwendung von Skill-Tools in Claude Code vor jeder Antwort erzwingt, einschließlich Klärungsfragen. Implementiert strenge Nutzungsanforderungen bei 1%iger Anwendbarkeit.","pt":"A skill using-superpowers estabelece o protocolo obrigatório para invocar ferramentas Skill no Claude Code antes de qualquer resposta. Implementa uma regra estrita de 1% de aplicabilidade que não é negociável e deve ser seguida diretamente.","ru":"Навык using-superpowers устанавливает обязательный протокол для вызова инструментов Skill в Claude Code перед любым ответом. Реализует строгое правило 1% применимости, которое не подлежит обсуждению и должно соблюдаться напрямую.","ar":"تحدد مهارة using-superpowers البروتوكول الإلزامي لاستدعاء أدوات Skill في Claude Code قبل أي رد. تنفذ قاعدة صارمة بنسبة 1٪ للتطبيق غير القابلة للتفاوض ويجب اتباعها مباشرة."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"using-superpowers","description":"Use when starting any conversation - establishes how to find and use skills, requiring Skill tool invocation before ANY response including clarifying questions","bodyPreview":"<EXTREMELY-IMPORTANT>\nIf you think there is even a 1% chance a skill might apply to what you are doing, you ABSOLUTELY MUST invoke the skill.\n\nIF A SKILL APPLIES TO YOUR TASK, YOU DO NOT HAVE A CHOICE. YOU MUST USE IT.\n\nThis is not negotiable. This is not optional. You cannot rationalize your way out of this.\n</EXTREMELY-IMPORTANT>\n\n## How to Access Skills\n\n**In Claude Code:** Use the `Skill` tool. When you invoke a skill, its content is loaded and presented to you—follow it directly. Never use","body":"<EXTREMELY-IMPORTANT>\nIf you think there is even a 1% chance a skill might apply to what you are doing, you ABSOLUTELY MUST invoke the skill.\n\nIF A SKILL APPLIES TO YOUR TASK, YOU DO NOT HAVE A CHOICE. YOU MUST USE IT.\n\nThis is not negotiable. This is not optional. You cannot rationalize your way out of this.\n</EXTREMELY-IMPORTANT>\n\n## How to Access Skills\n\n**In Claude Code:** Use the `Skill` tool. When you invoke a skill, its content is loaded and presented to you—follow it directly. Never use the Read tool on skill files.\n\n**In other environments:** Check your platform''s documentation for how skills are loaded.\n\n# Using Skills\n\n## The Rule\n\n**Invoke relevant or requested skills BEFORE any response or action.** Even a 1% chance a skill might apply means that you should invoke the skill to check. If an invoked skill turns out to be wrong for the situation, you don''t need to use it.\n\n```dot\ndigraph skill_flow {\n    \"User message received\" [shape=doublecircle];\n    \"About to EnterPlanMode?\" [shape=doublecircle];\n    \"Already brainstormed?\" [shape=diamond];\n    \"Invoke brainstorming skill\" [shape=box];\n    \"Might any skill apply?\" [shape=diamond];\n    \"Invoke Skill tool\" [shape=box];\n    \"Announce: ''Using [skill] to [purpose]''\" [shape=box];\n    \"Has checklist?\" [shape=diamond];\n    \"Create TodoWrite todo per item\" [shape=box];\n    \"Follow skill exactly\" [shape=box];\n    \"Respond (including clarifications)\" [shape=doublecircle];\n\n    \"About to EnterPlanMode?\" -> \"Already brainstormed?\";\n    \"Already brainstormed?\" -> \"Invoke brainstorming skill\" [label=\"no\"];\n    \"Already brainstormed?\" -> \"Might any skill apply?\" [label=\"yes\"];\n    \"Invoke brainstorming skill\" -> \"Might any skill apply?\";\n\n    \"User message received\" -> \"Might any skill apply?\";\n    \"Might any skill apply?\" -> \"Invoke Skill tool\" [label=\"yes, even 1%\"];\n    \"Might any skill apply?\" -> \"Respond (including clarifications)\" [label=\"definitely not\"];\n    \"Invoke Skill tool\" -> \"Announce: ''Using [skill] to [purpose]''\";\n    \"Announce: ''Using [skill] to [purpose]''\" -> \"Has checklist?\";\n    \"Has checklist?\" -> \"Create TodoWrite todo per item\" [label=\"yes\"];\n    \"Has checklist?\" -> \"Follow skill exactly\" [label=\"no\"];\n    \"Create TodoWrite todo per item\" -> \"Follow skill exactly\";\n}\n```\n\n## Red Flags\n\nThese thoughts mean STOP—you''re rationalizing:\n\n| Thought | Reality |\n|---------|---------|\n| \"This is just a simple question\" | Questions are tasks. Check for skills. |\n| \"I need more context first\" | Skill check comes BEFORE clarifying questions. |\n| \"Let me explore the codebase first\" | Skills tell you HOW to explore. Check first. |\n| \"I can check git/files quickly\" | Files lack conversation context. Check for skills. |\n| \"Let me gather information first\" | Skills tell you HOW to gather information. |\n| \"This doesn''t need a formal skill\" | If a skill exists, use it. |\n| \"I remember this skill\" | Skills evolve. Read current version. |\n| \"This doesn''t count as a task\" | Action = task. Check for skills. |\n| \"The skill is overkill\" | Simple things become complex. Use it. |\n| \"I''ll just do this one thing first\" | Check BEFORE doing anything. |\n| \"This feels productive\" | Undisciplined action wastes time. Skills prevent this. |\n| \"I know what that means\" | Knowing the concept ≠ using the skill. Invoke it. |\n\n## Skill Priority\n\nWhen multiple skills could apply, use this order:\n\n1. **Process skills first** (brainstorming, debugging) - these determine HOW to approach the task\n2. **Implementation skills second** (frontend-design, mcp-builder) - these guide execution\n\n\"Let''s build X\" → brainstorming first, then implementation skills.\n\"Fix this bug\" → debugging first, then domain-specific skills.\n\n## Skill Types\n\n**Rigid** (TDD, debugging): Follow exactly. Don''t adapt away discipline.\n\n**Flexible** (patterns): Adapt principles to context.\n\nThe skill itself tells you which.\n\n## User Instructions\n\nInstructions say WHAT, not HOW. \"Add X\" or \"Fix Y\" doesn''t mean skip workflows.\n"},"category":"official","lastSynced":"2026-03-06T03:37:04.330Z","seo":{"title":{"en":"using-superpowers: Mandatory Skill Invocation Protocol | ...","zh":"使用超能力技能设置指南","ja":"超能力スキルを使用するためのベストプラクティス","ko":"슈퍼파워 스킬 사용 설정 가이드","es":"Guía de Configuración de using-superpowers para Agentes d...","fr":"Guide de Configuration de using-superpowers pour Agents IA","de":"Einrichtungsanleitung für using-superpowers mit KI-Agenten","pt":"using-superpowers: Guia de Implementação para Skills de IA","ru":"using-superpowers: Руководство по внедрению ИИ Агентов","ar":"using-superpowers: دليل الإعداد لمهارات أدوات الذكاء الاص..."},"description":{"en":"Master the non-negotiable Skill tool invocation protocol for Claude Code. This AI agent skill mandates absolute compliance when applicable skills are detecte...","zh":"了解如何使用超能力技能来提高工作效率，包括如何访问和使用技能工具","ja":"AIエージェントの超能力スキルを使用する方法について説明します。スキルツールの使い方や設定方法を学びましょう","ko":"슈퍼파워 스킬을 사용하여 작업 효율성을 높이는 방법에 대해 알아보세요. 스킬 도구 접근 및 사용 방법을 포함합니다","es":"Aprende a implementar using-superpowers para invocación obligatoria de habilidades en Claude Code. Incluye requisitos técnicos estrictos de uso de herramient...","fr":"Apprenez à implémenter using-superpowers pour l''invocation obligatoire de compétences dans Claude Code. Inclut les exigences techniques strictes d''utilisatio...","de":"Erfahren Sie, wie Sie using-superpowers für obligatorische Skill-Invokation in Claude Code implementieren. Enthält strenge technische Anforderungen für die T...","pt":"Implemente a skill using-superpowers para obrigar invocações de ferramentas em Claude Code. Aprenda a regra mandatória de 1% de aplicabilidade e como carrega...","ru":"Реализуйте навык using-superpowers для принудительного вызова инструментов в Claude Code. Узнайте о обязательном правиле 1% применимости и правильной загрузк...","ar":"تنفيذ مهارة using-superpowers لإلزام استدعاء الأدوات في Claude Code. تعلم قاعدة الـ 1٪ الإلزامية للتطبيق وكيفية تحميل المهارات بشكل صحيح."},"definition":{"en":"using-superpowers is an AI agent skill that mandates compulsory Skill tool invocation in Claude Code when any applicable skill is detected. It establishes non-negotiable technical protocols requiring skill loading and direct implementation before generating responses, including clarifying questions.","zh":"超能力技能是指使用Skill工具来访问和使用技能的能力","ja":"超能力スキルとは、スキルツールを使用してスキルにアクセスし、使用する能力のことです","ko":"슈퍼파워 스킬이란 스킬 도구를 사용하여 스킬에 접근하고 사용하는 능력을 의미합니다","es":"using-superpowers es una habilidad técnica para agentes de IA que exige la invocación obligatoria de herramientas Skill en Claude Code antes de procesar cualquier respuesta, estableciendo requisitos estrictos de uso cuando existe mínima aplicabilidad.","fr":"using-superpowers est une compétence technique pour agents IA qui exige l''invocation obligatoire d''outils Skill dans Claude Code avant tout traitement de réponse, avec des exigences d''utilisation strictes.","de":"using-superpowers ist eine technische Fähigkeit für KI-Agenten, die die obligatorische Verwendung von Skill-Tools in Claude Code vor jeder Antwortverarbeitung erfordert, mit strengen Nutzungsanforderungen.","pt":"Using-superpowers é uma skill técnica para Claude Code que impõe a invocação mandatória de ferramentas Skill quando existe qualquer chance de aplicabilidade. Ela carrega conteúdo específico que deve ser seguido diretamente sem racionalizações.","ru":"Using-superpowers — это технический навык для Claude Code, который обеспечивает обязательный вызов инструментов Skill при любой возможности применения. Он загружает конкретный контент, которому необходимо следовать напрямую без рационализаций.","ar":"Using-superpowers هي مهارة تقنية لـ Claude Code تفرض الاستدعاء الإلزامي لأدوات Skill عند وجود أي فرصة للتطبيق. تقوم بتحميل محتوى محدد يجب اتباعه مباشرة دون أي تبريرات."},"features":{"en":["Enforces mandatory Skill tool invocation in Claude Code when skills apply","Requires skill loading and direct implementation before any response generation","Applies even for clarifying questions when skills are potentially relevant","Uses absolute compliance language with non-negotiable technical requirements","Provides specific Skill tool access protocols for Claude Code implementation"],"zh":["使用Skill工具来访问和使用技能","支持多种技能的加载和呈现","提供直接的技能使用指南"],"ja":["スキルツールを使用してスキルにアクセスし、使用する","複数のスキルのロードと表示をサポート","直接のスキル使用ガイドを提供"],"ko":["스킬 도구를 사용하여 스킬에 접근하고 사용한다","여러 스킬의 로드와 표시를 지원한다","직접적인 스킬 사용 가이드를 제공한다"],"es":["Invocación obligatoria de herramientas Skill en Claude Code","Requisito de uso con 1% de aplicabilidad de habilidad","Procesamiento previo a cualquier respuesta incluyendo preguntas","Carga directa de contenido de habilidades invocadas","Implementación no negociable y no opcional","Seguimiento estricto de instrucciones de habilidades cargadas"],"fr":["Invocation obligatoire d''outils Skill dans Claude Code","Exigence d''utilisation avec 1% d''applicabilité de compétence","Traitement préalable à toute réponse incluant questions","Chargement direct du contenu des compétences invoquées","Implémentation non négociable et non optionnelle","Suivi strict des instructions des compétences chargées"],"de":["Obligatorische Verwendung von Skill-Tools in Claude Code","Nutzungspflicht bei 1%iger Skill-Anwendbarkeit","Verarbeitung vor jeder Antwort einschließlich Fragen","Direktes Laden von invokiertem Skill-Inhalt","Nicht verhandelbare und nicht optionale Implementierung","Strikte Befolgung von geladenen Skill-Anweisungen"],"pt":["Regra mandatória de 1% de aplicabilidade de skills","Invocações obrigatórias de ferramentas Skill no Claude Code","Carregamento direto de conteúdo de skill para execução","Protocolo não negociável para qualquer resposta do agente","Proibição de racionalizações para evitar invocações","Integração estrita com o ecossistema de tools do Claude"],"ru":["Обязательное правило 1% применимости навыков","Обязательные вызовы инструментов Skill в Claude Code","Прямая загрузка контента навыка для выполнения","Непереговорный протокол для любого ответа агента","Запрет рационализаций для избежания вызовов","Строгая интеграция с экосистемой tools Claude"],"ar":["قاعدة إلزامية بنسبة 1٪ لتطبيق المهارات","استدعاءات إلزامية لأدوات Skill في Claude Code","تحميل مباشر لمحتوى المهارة للتنفيذ","بروتوكول غير قابل للتفاوض لأي رد من الوكيل","حظر المبررات لتجنب الاستدعاءات","تكامل صارم مع نظام أدوات Claude"]},"keywords":{"en":["using-superpowers mandatory skill invocation","how to use Skill tool in Claude Code","what is using-superpowers AI agent skill","using-superpowers vs other skill protocols","using-superpowers setup guide for developers","Claude Code Skill tool implementation","AI agent skill compliance requirements","using-superpowers technical documentation"],"zh":["超能力技能","AI工具","Skill工具","工作效率","如何使用超能力技能","超能力技能设置指南"],"ja":["超能力スキル","AIエージェント","スキルツール","作業効率","超能力スキルの使い方","超能力スキル設定ガイド"],"ko":["슈퍼파워 스킬","AI 에이전트","스킬 도구","작업 효율성","슈퍼파워 스킬 사용 방법","슈퍼파워 스킬 설정 가이드"],"es":["using-superpowers skill","invocación herramientas Skill Claude","agentes IA habilidades técnicas","implementación Claude Code","requisitos obligatorios habilidades IA","tool invocation AI agents","configuración using-superpowers","desarrollo agentes inteligentes"],"fr":["using-superpowers compétence","invocation outils Skill Claude","agents IA compétences techniques","implémentation Claude Code","exigences obligatoires compétences IA","tool invocation agents IA","configuration using-superpowers","développement agents intelligents"],"de":["using-superpowers skill","skill tools invocation claude","ki agenten technische fähigkeiten","implementierung claude code","obligatorische anforderungen ki skills","tool invocation ki agenten","einrichtung using-superpowers","entwicklung intelligente agenten"],"pt":["claude code skill tool","invocação obrigatória skills IA","regra 1% aplicabilidade Claude","implementação using-superpowers","ferramentas agentes AI Claude","protocolo não negociável skills","developer tools Claude Code","carregamento conteúdo skills"],"ru":["claude code skill tool","обязательный вызов навыков ИИ","правило 1% применимости Claude","внедрение using-superpowers","инструменты ИИ агентов Claude","непереговорный протокол навыков","developer tools Claude Code","загрузка контента навыков"],"ar":["claude code skill tool","استدعاء إلزامي لمهارات الذكاء الاصطناعي","قاعدة 1٪ تطبيق Claude","تنفيذ using-superpowers","أدوات وكلاء الذكاء الاصطناعي Claude","بروتوكول غير قابل للتفاوض للمهارات","developer tools Claude Code","تحميل محتوى المهارات"]}},"agentAnalysis":{"suitability":{"en":"Essential for all AI Agents requiring mandatory skill discovery and invocation compliance.","zh":"适用于所有需要强制技能发现和调用合规性的 AI Agent。","ja":"強制スキル発見と呼び出しコンプライアンスを必要とするすべてのAIエージェントに不可欠。","ko":"강제 스킬 발견 및 호출 규정 준수를 필요로 하는 모든 AI 에이전트에 필수적입니다.","es":"Esencial para todos los agentes de IA que requieren descubrimiento obligatorio de habilidades y cumplimiento de invocación.","fr":"Essentiel pour tous les agents d''IA nécessitant une découverte obligatoire des compétences et une conformité d''invocation.","de":"Essenziell für alle KI-Agenten, die eine obligatorische Skill-Entdeckung und Aufrufkonformität erfordern.","pt":"Essencial para todos os Agentes de IA que exigem descoberta obrigatória de habilidades e conformidade de invocação.","ru":"Необходимо для всех ИИ-агентов, требующих обязательного обнаружения навыков и соблюдения правил их вызова.","ar":"أساسي لجميع وكلاء الذكاء الاصطناعي الذين يتطلبون اكتشاف المهارات الإلزامية والامتثال للاستدعاء."},"recommendation":{"en":"Enforces strict skill-first protocol requiring immediate Skill tool invocation when any applicable skill is detected, eliminating agent discretion and ensuring compliance with ecosystem standards. Directly integrates with Claude Code''s Skill tool infrastructure for seamless skill loading and execution.","zh":"强制执行严格的技能优先协议，要求在检测到任何适用技能时立即调用 Skill 工具，消除代理人自主权，并确保遵守生态系统标准。直接集成 Claude Code 的 Skill 工具基础设施以实现无缝的技能加载和执行。","ja":"厳格なスキルファーストプロトコルを適用し、適応可能なスキルが検出された場合には、すぐに Skill ツールの呼び出しが必要であり、エージェントの裁量を排除し、エコシステムの標準に準拠する。Claude Code の Skill ツールインフラストラクチャと直接統合してスキルの読み込みと実行をシームレスに行う。","ko":"严格한 스킬 우선 프로토콜을 강제하여 적용 가능한 스킬이 감지될 때마다 즉시 Skill 툴을 호출하여 에이전트의 재량을 제거하고 생태계 표준을 준수하도록 합니다. Claude Code의 Skill 툴 인프라스트럭처와 직접 통합하여 스킬 로딩 및 실행을 무중단으로 수행합니다.","es":"Impone un protocolo estricto de habilidades primero que requiere la invocación inmediata de la herramienta Skill cuando se detecta cualquier habilidad aplicable, eliminando la discreción del agente y garantizando el cumplimiento de los estándares del ecosistema. Se integra directamente con la infraestructura de herramientas Skill de Claude Code para una carga y ejecución perfecta de habilidades.","fr":"Applique un protocole strict de compétences d''abord, exigeant une invocation immédiate de l''outil Skill dès qu''une compétence applicable est détectée, éliminant la discrétion de l''agent et assurant la conformité aux normes de l''écosystème. S''intègre directement à l''infrastructure d''outils Skill de Claude Code pour un chargement et une exécution fluides des compétences.","de":"Erzwingt ein striktes Skill-first-Protokoll, das die sofortige Aufrufung des Skill-Tools erfordert, sobald ein anwendbarer Skill erkannt wird, eliminiert den Ermessensspielraum des Agenten und stellt die Einhaltung der Ökosystemstandards sicher. Integriert sich direkt in die Skill-Tool-Infrastruktur von Claude Code für nahtloses Laden und Ausführen von Skills.","pt":"Impõe um protocolo rigoroso de prioridade de habilidades, exigindo a invocação imediata da ferramenta Skill quando qualquer habilidade aplicável é detectada, eliminando a discricionariedade do agente e garantindo conformidade com os padrões do ecossistema. Integra-se diretamente com a infraestrutura de ferramentas Skill do Claude Code para carregamento e execução perfeita de habilidades.","ru":"Вводит строгий протокол приоритета навыков, требующий немедленного вызова инструмента Skill при обнаружении любого применимого навыка, устраняя усмотрение агента и обеспечивая соответствие стандартам экосистемы. Прямо интегрируется с инфраструктурой инструментов Skill Claude Code для беспрепятственной загрузки и выполнения навыков.","ar":"يفرض بروتوكولًا صارمًا يعطي الأولوية للمهارات، ويتطلب الاستدعاء الفوري لأداة Skill عند اكتشاف أي مهارة قابلة للتطبيق، مما يلغي تقدير الوكيل ويضمن الامتثال لمعايير النظام البيئي. يتكامل مباشرة مع بنية أدوات Skill في Claude Code للتحميل والتنفيذ السلس للمهارات."},"useCases":{"en":["Enforcing skill invocation protocols","Preventing agent rationalization of skill avoidance","Automating skill discovery workflows","Standardizing agent response initialization"],"zh":["执行技能调用协议","防止代理人理性化技能避免","自动化技能发现工作流","标准化代理人响应初始化"],"ja":["スキル呼び出しプロトコルの適用","エージェントによるスキル回避の理性化を防止","スキル発見ワークフローの自動化","エージェント応答の初期化の標準化"],"ko":["스킬 호출 프로토콜 적용","에이전트의 스킬 회피 理性化 방지","스킬 발견 워크플로 자동화","에이전트 응답 초기화 표준화"],"es":["Aplicación de protocolos de invocación de habilidades","Prevención de la racionalización del agente para evitar habilidades","Automatización de flujos de trabajo de descubrimiento de habilidades","Estandarización de la inicialización de respuestas del agente"],"fr":["Application des protocoles d''invocation des compétences","Prévention de la rationalisation de l''évitement des compétences par l''agent","Automatisation des flux de travail de découverte des compétences","Standardisation de l''initialisation des réponses de l''agent"],"de":["Durchsetzung von Skill-Aufrufprotokollen","Verhinderung von Rationalisierungen des Agenten zur Vermeidung von Skills","Automatisierung von Skill-Entdeckungs-Workflows","Standardisierung der Initialisierung von Agentenantworten"],"pt":["Imposição de protocolos de invocação de habilidades","Prevenção da racionalização do agente para evitar habilidades","Automação de fluxos de trabalho de descoberta de habilidades","Padronização da inicialização de resposta do agente"],"ru":["Обеспечение соблюдения протоколов вызова навыков","Предотвращение рационализации агентом избегания навыков","Автоматизация рабочих процессов обнаружения навыков","Стандартизация инициализации ответов агента"],"ar":["فرض بروتوكولات استدعاء المهارات","منع تبرير الوكيل لتجنب المهارات","أتمتة سير عمل اكتشاف المهارات","توحيد معيارية تهيئة استجابة الوكيل"]},"limitations":{"en":["Claude Code ecosystem specific","Requires immediate tool invocation before any response","No agent discretion permitted for applicable skills"],"zh":["仅限 Claude Code 生态系统","需要在任何响应之前立即调用工具","不允许代理人自主权适用于相关技能"],"ja":["Claude Code エコシステム専用","いかなる応答よりも前にすぐにツールの呼び出しが必要","適用可能なスキルに対してはエージェントの裁量を許可しない"],"ko":["Claude Code 생태계 전용","어떠한 응답보다도 즉시 툴 호출이 필요","적용 가능한 스킬에 대한 에이전트의 재량을 허용하지 않음"],"es":["Específico del ecosistema Claude Code","Requiere invocación inmediata de herramientas antes de cualquier respuesta","No se permite discreción del agente para habilidades aplicables"],"fr":["Spécifique à l''écosystème Claude Code","Nécessite une invocation immédiate des outils avant toute réponse","Aucune discrétion de l''agent n''est autorisée pour les compétences applicables"],"de":["Spezifisch für das Claude Code-Ökosystem","Erfordert sofortigen Tool-Aufruf vor jeder Antwort","Kein Ermessensspielraum des Agenten für anwendbare Skills erlaubt"],"pt":["Específico do ecossistema Claude Code","Requer invocação imediata da ferramenta antes de qualquer resposta","Nenhuma discricionariedade do agente permitida para habilidades aplicáveis"],"ru":["Специфично для экосистемы Claude Code","Требует немедленного вызова инструмента перед любым ответом","Не допускается усмотрение агента для применимых навыков"],"ar":["مخصص لنظام Claude Code البيئي","يتطلب استدعاء الأداة فورًا قبل أي رد","لا يُسمح بأي تقدير للوكيل للمهارات القابلة للتطبيق"]},"version":4},"contentHash":"07d73726944e38fac59b9c90d876e0f714e395308b357973ae77b1321fc75067","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":74}');
