INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/using-superpowers', 'using-superpowers', 'obra', 'superpowers', 'official', 'using-superpowers obra superpowers official The using-superpowers skill establishes a mandatory protocol for AI agents to invoke applicable skills before generating any response. It provides developers with strict technical requirements for accessing and implementing skills through Claude Code''s Skill tool interface. 超能力技能是用于提高工作效率的必备工具。通过使用Skill工具，可以轻松访问和使用技能 超能力スキルは、AIエージェントを使用して作業効率を向上させるための重要なツールです。スキルツールを使用して、スキルにアクセスし、使用できます 슈퍼파워 스킬은 작업 효율성을 높이는 데 필요한 도구입니다. 스킬 도구를 사용하여 쉽게 스킬에 접근하고 사용할 수 있습니다 Skill técnica que obliga la invocación de herramientas Skill en Claude Code antes de cualquier respuesta, incluyendo preguntas de clarificación. Implementa requisitos estrictos de uso de habilidades cuando existe un 1% de aplicabilidad. Compétence technique qui impose l''invocation d''outils Skill dans Claude Code avant toute réponse, y compris les questions de clarification. Implémente des exigences strictes d''utilisation des compétences. Technische Skill, die die Verwendung von Skill-Tools in Claude Code vor jeder Antwort erzwingt, einschließlich Klärungsfragen. Implementiert strenge Nutzungsanforderungen bei 1%iger Anwendbarkeit. A skill using-superpowers estabelece o protocolo obrigatório para invocar ferramentas Skill no Claude Code antes de qualquer resposta. Implementa uma regra estrita de 1% de aplicabilidade que não é negociável e deve ser seguida diretamente. Навык using-superpowers устанавливает обязательный протокол для вызова инструментов Skill в Claude Code перед любым ответом. Реализует строгое правило 1% применимости, которое не подлежит обсуждению и должно соблюдаться напрямую. تحدد مهارة using-superpowers البروتوكول الإلزامي لاستدعاء أدوات Skill في Claude Code قبل أي رد. تنفذ قاعدة صارمة بنسبة 1٪ للتطبيق غير القابلة للتفاوض ويجب اتباعها مباشرة. using-superpowers mandatory skill invocation how to use Skill tool in Claude Code what is using-superpowers AI agent skill using-superpowers vs other skill protocols using-superpowers setup guide for developers Claude Code Skill tool implementation AI agent skill compliance requirements using-superpowers technical documentation 超能力技能 AI工具 Skill工具 工作效率 如何使用超能力技能 超能力技能设置指南 Enforces mandatory Skill tool invocation in Claude Code when skills apply Requires skill loading and direct implementation before any response generation Applies even for clarifying questions when skills are potentially relevant Uses absolute compliance language with non-negotiable technical requirements Provides specific Skill tool access protocols for Claude Code implementation using-superpowers is an AI agent skill that mandates compulsory Skill tool invocation in Claude Code when any applicable skill is detected. It establishes non-negotiable technical protocols requiring skill loading and direct implementation before generating responses, including clarifying questions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/verification-before-completion', 'official', 'obra', 'superpowers', 'obra/superpowers', 'verification-before-completion', 71924, 5546, 74, '2026-03-06T03:26:30Z', '2026-03-06T03:37:53.802Z', 'ea52d15aabaf72bc6b558efe2c126f161b53961090ddcd712000273bfe8c7b6c', '{"id":"obra/superpowers/verification-before-completion","name":"verification-before-completion","description":{"en":"Verification-before-completion ensures evidence-based claims by requiring fresh verification evidence before making completion claims, benefiting AI agent developers and users","zh":"verification-before-completion 技术要求在提交代码前运行验证命令并确认输出，确保代码的完整性和正确性","ja":"Verification Before Completion は、コードを提交する前に検証コマンドを実行し、出力を確認することで、コードの完全性と正確性を確保する","ko":"verification-before-completion 기능은 코드를 제출하기 전에 검증 명령을 실행하고 출력을 확인하여 코드의 완성성과 안정성을 보장합니다","es":"Un skill técnico para agentes de IA que aplica el principio ''evidencia antes que afirmaciones''. Bloquea declaraciones de finalización hasta que los comandos de verificación se ejecuten y su output sea confirmado, previniendo claims falsos en PRs.","fr":"Une compétence technique pour outils IA qui applique le principe ''preuve avant les affirmations''. Il bloque les déclarations d''achèvement tant que les commandes de vérification ne sont pas exécutées et leur sortie confirmée, empêchant les déclarations fausses dans les PR.","de":"Eine technische Fähigkeit für KI-Agenten, die das Prinzip ''Beweis vor Behauptungen'' durchsetzt. Sie blockiert Fertigstellungsmeldungen, bis Verifikationsbefehle ausgeführt und ihre Ausgabe bestätigt wurde, und verhindert so falsche Statusmeldungen in PRs.","pt":"Skill técnica para agentes de IA que impõe a execução obrigatória de comandos de verificação (ex: testes, linting) antes de qualquer declaração de conclusão. Implementa o princípio ''evidence before assertions'' para evitar claims falsos em pull requests e deployment pipelines.","ru":"Технический навык для ИИ агентов, который обеспечивает обязательное выполнение команд проверки (напр., тесты, линтинг) перед любым заявлением о завершении. Реализует принцип ''evidence before assertions'' для предотвращения ложных claims в pull requests и пайплайнах.","ar":"مهارة تقنية لوكلاء الذكاء الاصطناعي تفرض تنفيذ أوامر التحقق (مثل الاختبارات، linting) قبل أي إعلان بالاكتمال. تنفذ مبدأ ''evidence before assertions'' لمنع الادعاءات الكاذبة في طلبات السحب وخطوط الأنابيب."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"verification-before-completion","description":"Use when about to claim work is complete, fixed, or passing, before committing or creating PRs - requires running verification commands and confirming output before making any success claims; evidence before assertions always","bodyPreview":"# Verification Before Completion\n\n## Overview\n\nClaiming work is complete without verification is dishonesty, not efficiency.\n\n**Core principle:** Evidence before claims, always.\n\n**Violating the letter of this rule is violating the spirit of this rule.**\n\n## The Iron Law\n\n```\nNO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE\n```\n\nIf you haven''t run the verification command in this message, you cannot claim it passes.\n\n## The Gate Function\n\n```\nBEFORE claiming any status or expressing sati","body":"# Verification Before Completion\n\n## Overview\n\nClaiming work is complete without verification is dishonesty, not efficiency.\n\n**Core principle:** Evidence before claims, always.\n\n**Violating the letter of this rule is violating the spirit of this rule.**\n\n## The Iron Law\n\n```\nNO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE\n```\n\nIf you haven''t run the verification command in this message, you cannot claim it passes.\n\n## The Gate Function\n\n```\nBEFORE claiming any status or expressing satisfaction:\n\n1. IDENTIFY: What command proves this claim?\n2. RUN: Execute the FULL command (fresh, complete)\n3. READ: Full output, check exit code, count failures\n4. VERIFY: Does output confirm the claim?\n   - If NO: State actual status with evidence\n   - If YES: State claim WITH evidence\n5. ONLY THEN: Make the claim\n\nSkip any step = lying, not verifying\n```\n\n## Common Failures\n\n| Claim | Requires | Not Sufficient |\n|-------|----------|----------------|\n| Tests pass | Test command output: 0 failures | Previous run, \"should pass\" |\n| Linter clean | Linter output: 0 errors | Partial check, extrapolation |\n| Build succeeds | Build command: exit 0 | Linter passing, logs look good |\n| Bug fixed | Test original symptom: passes | Code changed, assumed fixed |\n| Regression test works | Red-green cycle verified | Test passes once |\n| Agent completed | VCS diff shows changes | Agent reports \"success\" |\n| Requirements met | Line-by-line checklist | Tests passing |\n\n## Red Flags - STOP\n\n- Using \"should\", \"probably\", \"seems to\"\n- Expressing satisfaction before verification (\"Great!\", \"Perfect!\", \"Done!\", etc.)\n- About to commit/push/PR without verification\n- Trusting agent success reports\n- Relying on partial verification\n- Thinking \"just this once\"\n- Tired and wanting work over\n- **ANY wording implying success without having run verification**\n\n## Rationalization Prevention\n\n| Excuse | Reality |\n|--------|---------|\n| \"Should work now\" | RUN the verification |\n| \"I''m confident\" | Confidence ≠ evidence |\n| \"Just this once\" | No exceptions |\n| \"Linter passed\" | Linter ≠ compiler |\n| \"Agent said success\" | Verify independently |\n| \"I''m tired\" | Exhaustion ≠ excuse |\n| \"Partial check is enough\" | Partial proves nothing |\n| \"Different words so rule doesn''t apply\" | Spirit over letter |\n\n## Key Patterns\n\n**Tests:**\n```\n✅ [Run test command] [See: 34/34 pass] \"All tests pass\"\n❌ \"Should pass now\" / \"Looks correct\"\n```\n\n**Regression tests (TDD Red-Green):**\n```\n✅ Write → Run (pass) → Revert fix → Run (MUST FAIL) → Restore → Run (pass)\n❌ \"I''ve written a regression test\" (without red-green verification)\n```\n\n**Build:**\n```\n✅ [Run build] [See: exit 0] \"Build passes\"\n❌ \"Linter passed\" (linter doesn''t check compilation)\n```\n\n**Requirements:**\n```\n✅ Re-read plan → Create checklist → Verify each → Report gaps or completion\n❌ \"Tests pass, phase complete\"\n```\n\n**Agent delegation:**\n```\n✅ Agent reports success → Check VCS diff → Verify changes → Report actual state\n❌ Trust agent report\n```\n\n## Why This Matters\n\nFrom 24 failure memories:\n- your human partner said \"I don''t believe you\" - trust broken\n- Undefined functions shipped - would crash\n- Missing requirements shipped - incomplete features\n- Time wasted on false completion → redirect → rework\n- Violates: \"Honesty is a core value. If you lie, you''ll be replaced.\"\n\n## When To Apply\n\n**ALWAYS before:**\n- ANY variation of success/completion claims\n- ANY expression of satisfaction\n- ANY positive statement about work state\n- Committing, PR creation, task completion\n- Moving to next task\n- Delegating to agents\n\n**Rule applies to:**\n- Exact phrases\n- Paraphrases and synonyms\n- Implications of success\n- ANY communication suggesting completion/correctness\n\n## The Bottom Line\n\n**No shortcuts for verification.**\n\nRun the command. Read the output. THEN claim the result.\n\nThis is non-negotiable.\n"},"category":"official","lastSynced":"2026-03-06T03:37:53.802Z","seo":{"title":{"en":"Verification-Before-Completion: Setup Guide for AI Agents","zh":"verification-before-completion 设置指南：确保代码完整性","ja":"Verification Before Completion のベストプラクティス：AIエージェントを使用したコード検証","ko":"verification-before-completion 구현 가이드: 코드 완성성 검증","es":"Guía de configuración: verification-before-completion par...","fr":"Guide de configuration : verification-before-completion p...","de":"Setup Guide: verification-before-completion für KI-Agenten","pt":"verification-before-completion: Guia de Implementação par...","ru":"verification-before-completion: Руководство по внедрению ...","ar":"verification-before-completion: دليل التنفيذ لوكلاء الذكا..."},"description":{"en":"Learn how to implement verification-before-completion in your AI agent workflow. Get started with our expert guide and ensure evidence-based claims","zh":"了解 verification-before-completion 技术，确保您的代码在提交前经过彻底的验证和测试","ja":"Verification Before Completion を使用して、コードの完全性を確保し、AIエージェントの検証機能を最大限に活用する","ko":"verification-before-completion 기능을 사용하여 코드의 완성성을 검증하고 안정성을 높여보세요","es":"Implementa el skill ''verification-before-completion'' para agentes de IA. Exige evidencia de comandos de verificación antes de afirmar que el trabajo está com...","fr":"Implémentez le skill ''verification-before-completion'' pour outils IA. Exigez une preuve via des commandes de vérification avant de déclarer un travail termin...","de":"Implementieren Sie den ''verification-before-completion''-Skill für KI-Agenten. Erzwingen Sie den Nachweis durch Verifikationsbefehle, bevor Arbeit als fertig ...","pt":"Skill para agentes de IA que exige verificação via comandos CLI antes de declarar conclusão. Garante evidência antes de afirmações, prevenindo claims falsos ...","ru":"Навык для ИИ агентов, требующий проверки через CLI команды перед объявлением завершения. Гарантирует доказательства перед утверждениями, предотвращая ложные ...","ar":"مهارة لوكلاء الذكاء الاصطناعي تتطلب التحقق عبر أوامر CLI قبل الإعلان عن الاكتمال. تضمن الأدلة قبل الادعاءات، preventing false claims في طلبات السحب والعمليات."},"definition":{"en":"Verification-before-completion is a core principle that mandates running verification commands and confirming output before claiming work is complete or passing","zh":"verification-before-completion 是一种技术，要求在提交代码前运行验证命令并确认输出，以确保代码的完整性","ja":"Verification Before Completion は、コードの完全性を確保するために、コードを提交する前に検証コマンドを実行し、出力を確認する技術","ko":"verification-before-completion은 코드의 완성성을 보장하기 위해 코드를 제출하기 전에 검증 명령을 실행하고 출력을 확인하는 기술입니다","es":"''verification-before-completion'' es un skill para agentes de IA que actúa como una compuerta de verificación. Impide que se afirme que el trabajo está completo o que un PR pasa las pruebas hasta que se ejecuten y confirmen los comandos de verificación específicos.","fr":"''verification-before-completion'' est une compétence pour outils IA qui agit comme une barrière de vérification. Elle empêche de déclarer un travail terminé ou qu''une PR passe les tests tant que les commandes de vérification spécifiques ne sont pas exécutées et confirmées.","de":"''verification-before-completion'' ist eine Fähigkeit für KI-Agenten, die als Verifikationsschleuse fungiert. Sie verhindert, dass Arbeit als fertig oder ein PR als testbestanden deklariert wird, bis spezifische Verifikationsbefehle ausgeführt und ihre Ausgabe bestätigt wurde.","pt":"Skill de agente de IA que aplica verificação programática via CLI antes de declarar trabalho como completo. Exige evidência de comandos como testes ou linting, prevenindo claims não verificados em commits e PRs.","ru":"Навык ИИ агента, применяющий программную проверку через CLI перед объявлением работы завершенной. Требует доказательств от команд like тесты или линтинг, предотвращая непроверенные claims в коммитах и PR.","ar":"مهارة وكيل الذكاء الاصطناعي التي تطبق التحقق البرمجي عبر CLI قبل الإعلان عن اكتمال العمل. تتطلب أدلة من أوامر like الاختبارات أو linting، preventing unverified claims في العمليات والطلبات."},"features":{"en":["Requires running verification commands before claiming completion","Mandates confirmation of output before making success claims","Enforces the Iron Law of no completion claims without fresh verification evidence","Supports gate function for expressing satisfaction only after verification","Ensures evidence-based assertions always"],"zh":["运行验证命令","确认输出结果","确保代码完整性","提高代码质量","减少错误率"],"ja":["検証コマンドの実行","出力の確認","コードの完全性の確保","コード品質の向上","エラー率の削減"],"ko":["검증 명령 실행","출력 확인","코드 완성성 보장","코드 품질 향상","오류율 감소"],"es":["Impone el ''Iron Law'': bloquea claims de finalización sin evidencia de verificación reciente.","Función de compuerta (Gate Function): verifica el estado antes de expresar satisfacción o commit.","Requiere la ejecución de comandos de verificación específicos para el contexto.","Exige la confirmación del output de los comandos antes de cualquier afirmación.","Previene declaraciones falsas en Pull Requests (PRs) y commits.","Aplica el principio central de ''evidencia antes que afirmaciones, siempre''."],"fr":["Impose la ''Loi de Fer'' : bloque les déclarations d''achèvement sans preuve de vérification récente.","Fonction de barrière (Gate Function) : vérifie le statut avant d''exprimer la satisfaction ou de committer.","Exige l''exécution de commandes de vérification spécifiques au contexte.","Demande la confirmation de la sortie des commandes avant toute affirmation.","Empêche les déclarations fausses dans les Pull Requests (PRs) et les commits.","Applique le principe central de ''preuve avant les affirmations, toujours''."],"de":["Erzwingt das ''Eiserne Gesetz'': Blockiert Fertigstellungsmeldungen ohne Nachweis einer aktuellen Verifikation.","Schleusenfunktion (Gate Function): Überprüft den Status, bevor Zufriedenheit ausgedrückt oder committet wird.","Erfordert die Ausführung kontextspezifischer Verifikationsbefehle.","Verlangt die Bestätigung der Befehlsausgabe vor jeder Statusbehauptung.","Verhindert falsche Aussagen in Pull Requests (PRs) und Commits.","Wendet das Kernprinzip ''Beweis vor Behauptungen, immer'' an."],"pt":["Execução obrigatória de comandos de verificação CLI antes de claims","Princípio ''evidence before assertions'' para integridade técnica","Prevenção de claims falsos em pull requests e deployment","Integração com pipelines de testes e linting","Gate function para bloquear declarações não validadas"],"ru":["Обязательное выполнение CLI команд проверки перед claims","Принцип ''evidence before assertions'' для технической целостности","Предотвращение ложных claims в pull requests и деплое","Интеграция с пайплайнами тестов и линтинга","Gate function для блокировки непроверенных заявлений"],"ar":["التنفيذ الإلزامي لأوامر التحقق CLI قبل الادعاءات","مبدأ ''evidence before assertions'' للنزاهة التقنية","منع الادعاءات الكاذبة في طلبات السحب والنشر","التكامل مع خطوط أنابيب الاختبارات والفحص","وظيفة البوابة لحظر التصريحات غير الموثقة"]},"keywords":{"en":["how to use verification-before-completion","verification-before-completion setup guide","what is verification-before-completion","verification-before-completion alternative","verification-before-completion vs testing","verification-before-completion install","verification-before-completion best practices"],"zh":["verification-before-completion","代码验证","代码完整性","AI工具","代码质量","错误率","代码提交"],"ja":["Verification Before Completion","コード検証","コード完全性","AIエージェント","コード品質","エラー率","コード提交"],"ko":["verification-before-completion","코드 검증","코드 완성성","AI 도구","코드 품질","오류율","코드 제출"],"es":["agentes de IA verification before completion","skill verification antes de commit","evidencia antes de afirmaciones PR","comandos verificación agentes IA","gate function pull requests","iron law declaraciones completado","prevenir claims falsos PR","automatizar verificacion trabajo completo"],"fr":["outils IA verification before completion","compétence vérification avant commit","preuve avant affirmations PR","commandes vérification outils IA","fonction barrière pull requests","loi de fer déclarations terminé","éviter déclarations fausses PR","automatiser vérification travail complet"],"de":["KI-Agenten verification before completion","Skill Verifikation vor Commit","Beweis vor Behauptungen PR","Verifikationsbefehle KI-Agenten","Gate Function Pull Requests","Eisernes Gesetz Fertigstellungsmeldungen","falsche Statusmeldungen PR verhindern","Verifikation Arbeit komplett automatisieren"],"pt":["agentes de IA verification","CLI commands agentes IA","testes antes de commit","pull request verification","evidence before assertions","automated testing agent","false claims prevention","deployment pipeline checks"],"ru":["ИИ агенты проверка","CLI команды ИИ агенты","тесты перед коммитом","pull request verification","evidence before assertions","automated testing agent","false claims prevention","deployment pipeline checks"],"ar":["وكلاء الذكاء الاصطناعي التحقق","أوامر CLI وكلاء الذكاء الاصطناعي","اختبارات قبل العمليات","تحقق طلب السحب","evidence before assertions","وكيل الاختبار الآلي","منع الادعاءات الكاذبة","فحوصات خط أنابيب النشر"]}},"agentAnalysis":{"suitability":{"en":"Essential for Code Review and QA Agents requiring evidence-based completion validation.","zh":"对于需要基于证据完成验证的代码审查和QA代理至关重要。","ja":"証拠に基づく完了検証を必要とするコードレビューおよびQAエージェントに不可欠です。","ko":"증거 기반 완료 검증이 필요한 코드 리뷰 및 QA 에이전트에 필수적입니다.","es":"Esencial para Agentes de Revisión de Código y Control de Calidad que requieren validación de finalización basada en evidencia.","fr":"Essentiel pour les Agents de Revue de Code et d''Assurance Qualité nécessitant une validation de finalisation basée sur des preuves.","de":"Unverzichtbar für Code-Review- und QA-Agenten, die eine evidenzbasierte Abschlussvalidierung erfordern.","pt":"Essencial para Agentes de Revisão de Código e QA que exigem validação de conclusão baseada em evidências.","ru":"Необходим для Агентов проверки кода и QA, требующих подтверждения завершения на основе доказательств.","ar":"أساسي لوكلاء مراجعة التعليمات البرمجية وضمان الجودة الذين يتطلبون التحقق من الإكمال بناءً على الأدلة."},"recommendation":{"en":"Enforces rigorous verification protocols before claiming completion status, requiring fresh command execution and output confirmation to prevent premature success assertions. It provides a gate function against dishonesty by mandating evidence before claims.","zh":"在声明完成状态前强制执行严格的验证协议，需要执行新命令并进行输出确认以防止过早的成功断言。它通过要求在声明前提供证据来提供防止不诚实行为的门控功能。","ja":"完了ステータスの主張前に厳格な検証プロトコルを実施し、時期尚早な成功断言を防ぐために新しいコマンド実行と出力確認を要求します。主張前に証拠を必須とすることで、不誠実さに対するゲート機能を提供します。","ko":"완료 상태를 선언하기 전에 엄격한 검증 프로토콜을 시행하여 조기 성공 주장을 방지하기 위해 새로운 명령어 실행 및 출력 확인을 요구합니다. 주장 전에 증거를 요구함으로써 부정직함에 대한 게이트 기능을 제공합니다.","es":"Impone protocolos de verificación rigurosos antes de declarar el estado de finalización, requiriendo la ejecución de comandos nuevos y la confirmación de la salida para evitar afirmaciones prematuras de éxito. Proporciona una función de barrera contra la deshonestidad al exigir evidencia antes de las afirmaciones.","fr":"Impose des protocoles de vérification rigoureux avant de déclarer un statut de finalisation, nécessitant une exécution de commande fraîche et une confirmation de sortie pour éviter des assertions de succès prématurées. Il fournit une fonction de garde-fou contre la malhonnêteté en exigeant des preuves avant toute affirmation.","de":"Erzwingt strenge Verifizierungsprotokolle, bevor der Abschlussstatus beansprucht wird, und erfordert die Ausführung neuer Befehle und die Bestätigung der Ausgabe, um vorzeitige Erfolgsmeldungen zu verhindern. Es bietet eine Sperrfunktion gegen Unehrlichkeit, indem es Beweise vor Behauptungen verlangt.","pt":"Impõe protocolos de verificação rigorosos antes de declarar o status de conclusão, exigindo a execução de comandos recentes e a confirmação da saída para evitar afirmações prematuras de sucesso. Ele fornece uma função de controle contra desonestidade, exigindo evidências antes de alegações.","ru":"Обеспечивает соблюдение строгих протоколов проверки перед объявлением статуса завершения, требуя выполнения новых команд и подтверждения вывода, чтобы предотвратить преждевременные заявления об успехе. Он обеспечивает функцию защиты от недобросовестности, требуя доказательств перед заявлениями.","ar":"يفرض بروتوكولات تحقق صارمة قبل المطالبة بحالة الإكمال، مما يتطلب تنفيذ أوامر حديثة وتأكيد المخرجات لمنع الادعاءات المبكرة بالنجاح. يوظف وظيفة بوابة ضد عدم الأمانة من خلال اشتراط تقديم الأدلة قبل المطالبات."},"useCases":{"en":["Running verification commands before PR creation","Confirming test suite output before deployment","Validating fix completion before status reporting","Executing fresh verification in current context before claims"],"zh":["PR创建前运行验证命令","部署前确认测试套件输出","状态报告前验证修复完成情况","声明前在当前上下文中执行新验证"],"ja":["PR作成前の検証コマンド実行","デプロイ前のテストスイート出力確認","ステータス報告前の修正完了検証","主張前の現行コンテキストでの新規検証実行"],"ko":["PR 생성 전 검증 명령어 실행","배포 전 테스트 스위트 출력 확인","상태 보고 전 수정 완료 검증","주장 전 현재 컨텍스트에서 새 검증 실행"],"es":["Ejecutar comandos de verificación antes de la creación de una PR","Confirmar la salida del conjunto de pruebas antes del despliegue","Validar la finalización de una corrección antes de informar el estado","Ejecutar una verificación nueva en el contexto actual antes de las afirmaciones"],"fr":["Exécuter des commandes de vérification avant la création d''une PR","Confirmer la sortie de la suite de tests avant le déploiement","Valider la finalisation d''une correction avant le reporting de statut","Exécuter une vérification fraîche dans le contexte actuel avant les affirmations"],"de":["Ausführen von Verifizierungsbefehlen vor der PR-Erstellung","Bestätigen der Testsuite-Ausgabe vor dem Deployment","Validieren der Abschluss einer Korrektur vor der Statusmeldung","Ausführen einer neuen Verifizierung im aktuellen Kontext vor Behauptungen"],"pt":["Execução de comandos de verificação antes da criação de PR","Confirmação da saída do conjunto de testes antes da implantação","Validação da conclusão da correção antes do relatório de status","Execução de verificação recente no contexto atual antes de alegações"],"ru":["Запуск команд проверки перед созданием PR","Подтверждение вывода тестового набора перед развертыванием","Проверка завершения исправления перед отчетом о статусе","Выполнение новой проверки в текущем контексте перед заявлениями"],"ar":["تشغيل أوامر التحقق قبل إنشاء طلب السحب (PR)","تأكيد مخرجات مجموعة الاختبار قبل النشر","التحقق من اكتمال الإصلاح قبل الإبلاغ عن الحالة","تنفيذ تحقق حديث في السياق الحالي قبل المطالبات"]},"limitations":{"en":["Requires access to command execution environment","Needs output analysis capabilities","Depends on available verification commands in context"],"zh":["需要访问命令执行环境","需要输出分析能力","依赖于上下文中可用的验证命令"],"ja":["コマンド実行環境へのアクセスが必要","出力分析機能が必要","コンテキスト内で利用可能な検証コマンドに依存"],"ko":["명령어 실행 환경에 대한 액세스 필요","출력 분석 기능 필요","컨텍스트에서 사용 가능한 검증 명령어에 의존"],"es":["Requiere acceso al entorno de ejecución de comandos","Necesita capacidades de análisis de salida","Depende de los comandos de verificación disponibles en el contexto"],"fr":["Nécessite un accès à l''environnement d''exécution de commandes","Requiert des capacités d''analyse de sortie","Dépend des commandes de vérification disponibles dans le contexte"],"de":["Erfordert Zugriff auf die Befehlsausführungsumgebung","Benötigt Fähigkeiten zur Ausgabeanalyse","Hängt von den im Kontext verfügbaren Verifizierungsbefehlen ab"],"pt":["Requer acesso ao ambiente de execução de comandos","Necessita de capacidades de análise de saída","Depende de comandos de verificação disponíveis no contexto"],"ru":["Требует доступа к среде выполнения команд","Требует возможности анализа вывода","Зависит от доступных команд проверки в контексте"],"ar":["يتطلب الوصول إلى بيئة تنفيذ الأوامر","يحتاج إلى قدرات تحليل المخرجات","يعتمد على أوامر التحقق المتاحة في السياق"]},"version":4},"contentHash":"ea52d15aabaf72bc6b558efe2c126f161b53961090ddcd712000273bfe8c7b6c","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":74}');
