INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/verification-before-completion', 'verification-before-completion', 'obra', 'superpowers', 'official', 'verification-before-completion obra superpowers official Verification-before-completion ensures evidence-based claims by requiring fresh verification evidence before making completion claims, benefiting AI agent developers and users verification-before-completion 技术要求在提交代码前运行验证命令并确认输出，确保代码的完整性和正确性 Verification Before Completion は、コードを提交する前に検証コマンドを実行し、出力を確認することで、コードの完全性と正確性を確保する verification-before-completion 기능은 코드를 제출하기 전에 검증 명령을 실행하고 출력을 확인하여 코드의 완성성과 안정성을 보장합니다 Un skill técnico para agentes de IA que aplica el principio ''evidencia antes que afirmaciones''. Bloquea declaraciones de finalización hasta que los comandos de verificación se ejecuten y su output sea confirmado, previniendo claims falsos en PRs. Une compétence technique pour outils IA qui applique le principe ''preuve avant les affirmations''. Il bloque les déclarations d''achèvement tant que les commandes de vérification ne sont pas exécutées et leur sortie confirmée, empêchant les déclarations fausses dans les PR. Eine technische Fähigkeit für KI-Agenten, die das Prinzip ''Beweis vor Behauptungen'' durchsetzt. Sie blockiert Fertigstellungsmeldungen, bis Verifikationsbefehle ausgeführt und ihre Ausgabe bestätigt wurde, und verhindert so falsche Statusmeldungen in PRs. Skill técnica para agentes de IA que impõe a execução obrigatória de comandos de verificação (ex: testes, linting) antes de qualquer declaração de conclusão. Implementa o princípio ''evidence before assertions'' para evitar claims falsos em pull requests e deployment pipelines. Технический навык для ИИ агентов, который обеспечивает обязательное выполнение команд проверки (напр., тесты, линтинг) перед любым заявлением о завершении. Реализует принцип ''evidence before assertions'' для предотвращения ложных claims в pull requests и пайплайнах. مهارة تقنية لوكلاء الذكاء الاصطناعي تفرض تنفيذ أوامر التحقق (مثل الاختبارات، linting) قبل أي إعلان بالاكتمال. تنفذ مبدأ ''evidence before assertions'' لمنع الادعاءات الكاذبة في طلبات السحب وخطوط الأنابيب. how to use verification-before-completion verification-before-completion setup guide what is verification-before-completion verification-before-completion alternative verification-before-completion vs testing verification-before-completion install verification-before-completion best practices verification-before-completion 代码验证 代码完整性 AI工具 代码质量 错误率 代码提交 Requires running verification commands before claiming completion Mandates confirmation of output before making success claims Enforces the Iron Law of no completion claims without fresh verification evidence Supports gate function for expressing satisfaction only after verification Ensures evidence-based assertions always Verification-before-completion is a core principle that mandates running verification commands and confirming output before claiming work is complete or passing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/database-migrations', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'database-migrations', 61988, 7678, 74, '2026-03-06T03:39:20Z', '2026-03-06T03:59:45.266Z', '01d862480a071015cd9a7efedb4e0ec63568a1e90bbe82d4d135cad03f795309', '{"id":"affaan-m/everything-claude-code/database-migrations","name":"database-migrations","description":{"en":"Database-migrations enables developers to perform safe and reversible database schema changes, supporting zero-downtime deployments across various databases and ORMs, including PostgreSQL, MySQL, Prisma, and TypeORM.","zh":"数据库迁移最佳实践包括PostgreSQL、MySQL和常见ORM的零宕机部署和数据迁移","ja":"データベース移行のベストプラクティスは、PostgreSQL、MySQL、ORMでのゼロダウンタイムデプロイとデータ移行を含みます","ko":"데이터베이스 마이그레이션의 베스트 프랙티스는 PostgreSQL, MySQL, ORM에서 제로 다운타임 배포와 데이터 마이그레이션을 포함합니다","es":"Migraciones de base de datos seguras y reversibles para cambios de esquema y datos con AI Agent, compatible con PostgreSQL, MySQL y ORMs como Prisma y TypeORM","fr":"Migrations de base de données sûres et réversibles pour les changements de schéma et de données avec Agent IA, compatible avec PostgreSQL, MySQL et ORMs comme Prisma et TypeORM","de":"Sichere und rückgängig machbare Datenbankmigrationen für Schema- und Datenänderungen mit KI-Agent, kompatibel mit PostgreSQL, MySQL und ORMs wie Prisma und TypeORM","pt":"Realize migrações de esquema de banco de dados seguras e reversíveis com PostgreSQL, MySQL e ORMs como Prisma e TypeORM","ru":"Выполняйте безопасные и обратимые миграции схемы базы данных с PostgreSQL, MySQL и ORM, такими как Prisma и TypeORM для ИИ Агентов","ar":"إجراء عمليات هجرة آمنة ومتعاكسة لجدول قاعدة البيانات مع PostgreSQL و MySQL و ORMs مثل Prisma و TypeORM"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"database-migrations","description":"Database migration best practices for schema changes, data migrations, rollbacks, and zero-downtime deployments across PostgreSQL, MySQL, and common ORMs (Prisma, Drizzle, Django, TypeORM, golang-migrate).","bodyPreview":"# Database Migration Patterns\n\nSafe, reversible database schema changes for production systems.\n\n## When to Activate\n\n- Creating or altering database tables\n- Adding/removing columns or indexes\n- Running data migrations (backfill, transform)\n- Planning zero-downtime schema changes\n- Setting up migration tooling for a new project\n\n## Core Principles\n\n1. **Every change is a migration** — never alter production databases manually\n2. **Migrations are forward-only in production** — rollbacks use new","body":"# Database Migration Patterns\n\nSafe, reversible database schema changes for production systems.\n\n## When to Activate\n\n- Creating or altering database tables\n- Adding/removing columns or indexes\n- Running data migrations (backfill, transform)\n- Planning zero-downtime schema changes\n- Setting up migration tooling for a new project\n\n## Core Principles\n\n1. **Every change is a migration** — never alter production databases manually\n2. **Migrations are forward-only in production** — rollbacks use new forward migrations\n3. **Schema and data migrations are separate** — never mix DDL and DML in one migration\n4. **Test migrations against production-sized data** — a migration that works on 100 rows may lock on 10M\n5. **Migrations are immutable once deployed** — never edit a migration that has run in production\n\n## Migration Safety Checklist\n\nBefore applying any migration:\n\n- [ ] Migration has both UP and DOWN (or is explicitly marked irreversible)\n- [ ] No full table locks on large tables (use concurrent operations)\n- [ ] New columns have defaults or are nullable (never add NOT NULL without default)\n- [ ] Indexes created concurrently (not inline with CREATE TABLE for existing tables)\n- [ ] Data backfill is a separate migration from schema change\n- [ ] Tested against a copy of production data\n- [ ] Rollback plan documented\n\n## PostgreSQL Patterns\n\n### Adding a Column Safely\n\n```sql\n-- GOOD: Nullable column, no lock\nALTER TABLE users ADD COLUMN avatar_url TEXT;\n\n-- GOOD: Column with default (Postgres 11+ is instant, no rewrite)\nALTER TABLE users ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT true;\n\n-- BAD: NOT NULL without default on existing table (requires full rewrite)\nALTER TABLE users ADD COLUMN role TEXT NOT NULL;\n-- This locks the table and rewrites every row\n```\n\n### Adding an Index Without Downtime\n\n```sql\n-- BAD: Blocks writes on large tables\nCREATE INDEX idx_users_email ON users (email);\n\n-- GOOD: Non-blocking, allows concurrent writes\nCREATE INDEX CONCURRENTLY idx_users_email ON users (email);\n\n-- Note: CONCURRENTLY cannot run inside a transaction block\n-- Most migration tools need special handling for this\n```\n\n### Renaming a Column (Zero-Downtime)\n\nNever rename directly in production. Use the expand-contract pattern:\n\n```sql\n-- Step 1: Add new column (migration 001)\nALTER TABLE users ADD COLUMN display_name TEXT;\n\n-- Step 2: Backfill data (migration 002, data migration)\nUPDATE users SET display_name = username WHERE display_name IS NULL;\n\n-- Step 3: Update application code to read/write both columns\n-- Deploy application changes\n\n-- Step 4: Stop writing to old column, drop it (migration 003)\nALTER TABLE users DROP COLUMN username;\n```\n\n### Removing a Column Safely\n\n```sql\n-- Step 1: Remove all application references to the column\n-- Step 2: Deploy application without the column reference\n-- Step 3: Drop column in next migration\nALTER TABLE orders DROP COLUMN legacy_status;\n\n-- For Django: use SeparateDatabaseAndState to remove from model\n-- without generating DROP COLUMN (then drop in next migration)\n```\n\n### Large Data Migrations\n\n```sql\n-- BAD: Updates all rows in one transaction (locks table)\nUPDATE users SET normalized_email = LOWER(email);\n\n-- GOOD: Batch update with progress\nDO $$\nDECLARE\n  batch_size INT := 10000;\n  rows_updated INT;\nBEGIN\n  LOOP\n    UPDATE users\n    SET normalized_email = LOWER(email)\n    WHERE id IN (\n      SELECT id FROM users\n      WHERE normalized_email IS NULL\n      LIMIT batch_size\n      FOR UPDATE SKIP LOCKED\n    );\n    GET DIAGNOSTICS rows_updated = ROW_COUNT;\n    RAISE NOTICE ''Updated % rows'', rows_updated;\n    EXIT WHEN rows_updated = 0;\n    COMMIT;\n  END LOOP;\nEND $$;\n```\n\n## Prisma (TypeScript/Node.js)\n\n### Workflow\n\n```bash\n# Create migration from schema changes\nnpx prisma migrate dev --name add_user_avatar\n\n# Apply pending migrations in production\nnpx prisma migrate deploy\n\n# Reset database (dev only)\nnpx prisma migrate reset\n\n# Generate client after schema changes\nnpx prisma generate\n```\n\n### Schema Example\n\n```prisma\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  name      String?\n  avatarUrl String?  @map(\"avatar_url\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n  orders    Order[]\n\n  @@map(\"users\")\n  @@index([email])\n}\n```\n\n### Custom SQL Migration\n\nFor operations Prisma cannot express (concurrent indexes, data backfills):\n\n```bash\n# Create empty migration, then edit the SQL manually\nnpx prisma migrate dev --create-only --name add_email_index\n```\n\n```sql\n-- migrations/20240115_add_email_index/migration.sql\n-- Prisma cannot generate CONCURRENTLY, so we write it manually\nCREATE INDEX CONCURRENTLY IF NOT EXISTS idx_users_email ON users (email);\n```\n\n## Drizzle (TypeScript/Node.js)\n\n### Workflow\n\n```bash\n# Generate migration from schema changes\nnpx drizzle-kit generate\n\n# Apply migrations\nnpx drizzle-kit migrate\n\n# Push schema directly (dev only, no migration file)\nnpx drizzle-kit push\n```\n\n### Schema Example\n\n```typescript\nimport { pgTable, text, timestamp, uuid, boolean } from \"drizzle-orm/pg-core\";\n\nexport const users = pgTable(\"users\", {\n  id: uuid(\"id\").primaryKey().defaultRandom(),\n  email: text(\"email\").notNull().unique(),\n  name: text(\"name\"),\n  isActive: boolean(\"is_active\").notNull().default(true),\n  createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n  updatedAt: timestamp(\"updated_at\").notNull().defaultNow(),\n});\n```\n\n## Django (Python)\n\n### Workflow\n\n```bash\n# Generate migration from model changes\npython manage.py makemigrations\n\n# Apply migrations\npython manage.py migrate\n\n# Show migration status\npython manage.py showmigrations\n\n# Generate empty migration for custom SQL\npython manage.py makemigrations --empty app_name -n description\n```\n\n### Data Migration\n\n```python\nfrom django.db import migrations\n\ndef backfill_display_names(apps, schema_editor):\n    User = apps.get_model(\"accounts\", \"User\")\n    batch_size = 5000\n    users = User.objects.filter(display_name=\"\")\n    while users.exists():\n        batch = list(users[:batch_size])\n        for user in batch:\n            user.display_name = user.username\n        User.objects.bulk_update(batch, [\"display_name\"], batch_size=batch_size)\n\ndef reverse_backfill(apps, schema_editor):\n    pass  # Data migration, no reverse needed\n\nclass Migration(migrations.Migration):\n    dependencies = [(\"accounts\", \"0015_add_display_name\")]\n\n    operations = [\n        migrations.RunPython(backfill_display_names, reverse_backfill),\n    ]\n```\n\n### SeparateDatabaseAndState\n\nRemove a column from the Django model without dropping it from the database immediately:\n\n```python\nclass Migration(migrations.Migration):\n    operations = [\n        migrations.SeparateDatabaseAndState(\n            state_operations=[\n                migrations.RemoveField(model_name=\"user\", name=\"legacy_field\"),\n            ],\n            database_operations=[],  # Don''t touch the DB yet\n        ),\n    ]\n```\n\n## golang-migrate (Go)\n\n### Workflow\n\n```bash\n# Create migration pair\nmigrate create -ext sql -dir migrations -seq add_user_avatar\n\n# Apply all pending migrations\nmigrate -path migrations -database \"$DATABASE_URL\" up\n\n# Rollback last migration\nmigrate -path migrations -database \"$DATABASE_URL\" down 1\n\n# Force version (fix dirty state)\nmigrate -path migrations -database \"$DATABASE_URL\" force VERSION\n```\n\n### Migration Files\n\n```sql\n-- migrations/000003_add_user_avatar.up.sql\nALTER TABLE users ADD COLUMN avatar_url TEXT;\nCREATE INDEX CONCURRENTLY idx_users_avatar ON users (avatar_url) WHERE avatar_url IS NOT NULL;\n\n-- migrations/000003_add_user_avatar.down.sql\nDROP INDEX IF EXISTS idx_users_avatar;\nALTER TABLE users DROP COLUMN IF EXISTS avatar_url;\n```\n\n## Zero-Downtime Migration Strategy\n\nFor critical production changes, follow the expand-contract pattern:\n\n```\nPhase 1: EXPAND\n  - Add new column/table (nullable or with default)\n  - Deploy: app writes to BOTH old and new\n  - Backfill existing data\n\nPhase 2: MIGRATE\n  - Deploy: app reads from NEW, writes to BOTH\n  - Verify data consistency\n\nPhase 3: CONTRACT\n  - Deploy: app only uses NEW\n  - Drop old column/table in separate migration\n```\n\n### Timeline Example\n\n```\nDay 1: Migration adds new_status column (nullable)\nDay 1: Deploy app v2 — writes to both status and new_status\nDay 2: Run backfill migration for existing rows\nDay 3: Deploy app v3 — reads from new_status only\nDay 7: Migration drops old status column\n```\n\n## Anti-Patterns\n\n| Anti-Pattern | Why It Fails | Better Approach |\n|-------------|-------------|-----------------|\n| Manual SQL in production | No audit trail, unrepeatable | Always use migration files |\n| Editing deployed migrations | Causes drift between environments | Create new migration instead |\n| NOT NULL without default | Locks table, rewrites all rows | Add nullable, backfill, then add constraint |\n| Inline index on large table | Blocks writes during build | CREATE INDEX CONCURRENTLY |\n| Schema + data in one migration | Hard to rollback, long transactions | Separate migrations |\n| Dropping column before removing code | Application errors on missing column | Remove code first, drop column next deploy |\n"},"category":"official","lastSynced":"2026-03-06T03:59:45.266Z","seo":{"title":{"en":"Database-Migrations: Zero-Downtime Deployment Guide | AI ...","zh":"数据库迁移最佳实践指南","ja":"データベース移行のベストプラクティスガイド","ko":"데이터베이스 마이그레이션 설정 가이드","es":"Guía de configuración de migraciones de base de datos con...","fr":"Guide de migration de base de données avec Agent IA","de":"Einrichtungsleitfaden für Datenbankmigrationen mit KI-Agent","pt":"Guia de Migração de Banco de Dados: Melhores Práticas","ru":"Руководство по миграции баз данных: Лучшие практики для И...","ar":"دليل هجرة قواعد البيانات: أفضل الممارسات لآلات التعلم"},"description":{"en":"Learn how to implement safe and reversible database schema changes with database-migrations. Get started with zero-downtime deployments across PostgreSQL, My...","zh":"了解数据库迁移的最佳实践，包括PostgreSQL、MySQL和常见ORM的零宕机部署","ja":"データベース移行のベストプラクティスを学び、PostgreSQL、MySQL、ORMでのゼロダウンタイムデプロイを実現する","ko":"데이터베이스 마이그레이션의 베스트 프랙티스를 알아보고 PostgreSQL, MySQL, ORM에서 제로 다운타임 배포를 구현하세요","es":"Aprende a implementar migraciones de base de datos seguras y reversibles con AI Agent, compatible con PostgreSQL, MySQL y ORMs como Prisma y TypeORM","fr":"Découvrez comment mettre en œuvre des migrations de base de données sûres et réversibles avec Agent IA, compatible avec PostgreSQL, MySQL et ORMs comme Prism...","de":"Erfahren Sie, wie Sie sichere und rückgängig machbare Datenbankmigrationen mit KI-Agent implementieren, kompatibel mit PostgreSQL, MySQL und ORMs wie Prisma ...","pt":"Aprenda a realizar migrações de esquema de banco de dados seguras e reversíveis com PostgreSQL, MySQL e ORMs populares","ru":"Узнайте, как выполнять безопасные и обратимые миграции схемы базы данных с PostgreSQL, MySQL и популярными ORM для ИИ Агентов","ar":"تعلم كيفية إجراء عمليات هجرة آمنة ومتعاكسة لجدول قاعدة البيانات مع PostgreSQL و MySQL و ORMs الشهيرة"},"definition":{"en":"Database-migrations is a set of best practices for managing schema changes, data migrations, and rollbacks in production systems, ensuring minimal downtime and data integrity.","zh":"数据库迁移是指将数据库从一个版本迁移到另一个版本的过程","ja":"データベース移行とは、データベースをあるバージョンから別のバージョンに移行するプロセスです","ko":"데이터베이스 마이그레이션은 데이터베이스를 한 버전에서 다른 버전으로 이동하는 과정입니다","es":"Migraciones de base de datos son cambios controlados en la estructura o datos de una base de datos","fr":"Les migrations de base de données sont des changements contrôlés dans la structure ou les données d''une base de données","de":"Datenbankmigrationen sind kontrollierte Änderungen an der Struktur oder den Daten einer Datenbank","pt":"Migração de banco de dados é o processo de alterar a estrutura de um banco de dados de forma segura e reversível","ru":"Миграция базы данных - это процесс изменения структуры базы данных безопасным и обратимым образом для ИИ Агентов","ar":"هجرة قاعدة البيانات هي عملية تغيير هيكل قاعدة البيانات بطريقة آمنة ومتعاكسة"},"features":{"en":["Supports schema changes and data migrations for PostgreSQL and MySQL","Integrates with popular ORMs such as Prisma, Drizzle, Django, and TypeORM","Enables zero-downtime deployments using forward-only migrations in production","Allows for rollbacks using new migrations","Provides a framework for planning and executing safe and reversible database changes"],"zh":["支持PostgreSQL、MySQL和常见ORM","零宕机部署和数据迁移","遵循每次改变都是迁移的原则","只在生产环境中进行前向迁移","支持Prisma、Drizzle、Django、TypeORM、golang-migrate"],"ja":["PostgreSQL、MySQL、ORMをサポート","ゼロダウンタイムデプロイとデータ移行","毎回の変更は移行であるという原則に従う","生産環境では前向きにのみ移行する","Prisma、Drizzle、Django、TypeORM、golang-migrateをサポート"],"ko":["PostgreSQL, MySQL, ORM 지원","제로 다운타임 배포와 데이터 마이그레이션","매번 변경은 마이그레이션이라는 원칙을 따름","생산 환경에서는 앞으로만 마이그레이션","Prisma, Drizzle, Django, TypeORM, golang-migrate 지원"],"es":["Soporte para PostgreSQL, MySQL y ORMs como Prisma y TypeORM","Migraciones de esquema y datos seguras y reversibles","Implementación de cambios de esquema sin tiempo de inactividad","Uso de herramientas de migración como Drizzle y Django","Compatibilidad con golang-migrate para migraciones de datos"],"fr":["Prise en charge de PostgreSQL, MySQL et ORMs comme Prisma et TypeORM","Migrations de schéma et de données sûres et réversibles","Mise en œuvre de changements de schéma sans temps d''arrêt","Utilisation d''outils de migration comme Drizzle et Django","Compatibilité avec golang-migrate pour les migrations de données"],"de":["Unterstützung für PostgreSQL, MySQL und ORMs wie Prisma und TypeORM","Sichere und rückgängig machbare Schema- und Datenmigrationen","Implementierung von Schemaänderungen ohne Ausfallzeit","Verwendung von Migrationstools wie Drizzle und Django","Kompatibilität mit golang-migrate für Datenmigrationen"],"pt":["Suporte a PostgreSQL e MySQL","Integração com ORMs populares como Prisma e TypeORM","Migrações de esquema seguras e reversíveis","Suporte a deploy sem tempo de inatividade","Ferramentas de migração para novos projetos"],"ru":["Поддержка PostgreSQL и MySQL","Интеграция с популярными ORM, такими как Prisma и TypeORM для ИИ Агентов","Безопасные и обратимые миграции схемы","Поддержка развертывания без простоя","Инструменты миграции для новых проектов"],"ar":["دعم PostgreSQL و MySQL","التكامل مع ORMs الشهيرة مثل Prisma و TypeORM","عمليات هجرة جدول آمنة ومتعاكسة","دعم التثبيت بدون توقف","أدوات الهجرة للمشاريع الجديدة"]},"keywords":{"en":["database-migrations tutorial","zero-downtime deployment strategies","PostgreSQL migration best practices","MySQL database migration tools","Prisma vs TypeORM for database migrations","how to use database-migrations with Django","database-migrations setup guide","database-migrations alternative solutions","database-migrations and golang-migrate integration"],"zh":["数据库迁移","PostgreSQL迁移","MySQL迁移","ORM迁移","零宕机部署","数据迁移","Prisma","Drizzle","Django","TypeORM","golang-migrate"],"ja":["データベース移行","PostgreSQL移行","MySQL移行","ORM移行","ゼロダウンタイムデプロイ","データ移行","Prisma","Drizzle","Django","TypeORM","golang-migrate"],"ko":["데이터베이스 마이그레이션","PostgreSQL 마이그레이션","MySQL 마이그레이션","ORM 마이그레이션","제로 다운타임 배포","데이터 마이그레이션","Prisma","Drizzle","Django","TypeORM","golang-migrate"],"es":["migraciones de base de datos","AI Agent","PostgreSQL","MySQL","Prisma","TypeORM","Drizzle","Django","golang-migrate","migraciones de esquema"],"fr":["migrations de base de données","Agent IA","PostgreSQL","MySQL","Prisma","TypeORM","Drizzle","Django","golang-migrate","migrations de schéma"],"de":["Datenbankmigrationen","KI-Agent","PostgreSQL","MySQL","Prisma","TypeORM","Drizzle","Django","golang-migrate","Schema-Migrationen"],"pt":["migração de banco de dados","melhores práticas de migração","PostgreSQL","MySQL","Prisma","TypeORM","migração de esquema","deploy sem tempo de inatividade","ferramentas de migração"],"ru":["миграция базы данных","лучшие практики миграции для ИИ Агентов","PostgreSQL","MySQL","Prisma","TypeORM","миграция схемы","развертывание без простоя","инструменты миграции"],"ar":["هجرة قاعدة البيانات","أفضل الممارسات للهجرة","PostgreSQL","MySQL","Prisma","TypeORM","هجرة جدول","التثبيت بدون توقف","أدوات الهجرة"]}},"agentAnalysis":{"suitability":{"en":"Essential for DevOps and Backend Agents managing production database schema changes across PostgreSQL, MySQL, and popular ORMs.","zh":"适用于DevOps和后端代理，管理跨PostgreSQL、MySQL和流行ORM的生产数据库模式更改。","ja":"DevOpsとバックエンドエージェントに不可欠で、PostgreSQL、MySQL、人気のORMを横断するプロダクションデータベーススキーマの変更を管理します。","ko":"DevOps 및 백엔드 에이전트에 필수적이며 PostgreSQL, MySQL 및 인기 있는 ORM을 가로지르는 프로덕션 데이터베이스 스키마 변경을 관리합니다.","es":"Esencial para DevOps y Backend Agents que gestionan cambios en el esquema de base de datos de producción en PostgreSQL, MySQL y ORMs populares.","fr":"Essentiel pour les agents DevOps et Backend qui gèrent les modifications du schéma de base de données de production sur PostgreSQL, MySQL et les ORM populaires.","de":"Wesentlich für DevOps- und Backend-Agents, die Änderungen an der Produktionsdatenbankschemachange in PostgreSQL, MySQL und beliebten ORMs verwalten.","pt":"Essencial para DevOps e Agentes de Backend que gerenciam alterações no esquema de banco de dados de produção em PostgreSQL, MySQL e ORMs populares.","ru":"Необходим для DevOps и агентов Backend, управляющих изменениями схемы базы данных в производстве в PostgreSQL, MySQL и популярных ORMs.","ar":"ضروري لعمليات DevOps ووكلاء Backend الذين يديرون تغييرات مخطط قاعدة البيانات الإنتاج عبر PostgreSQL و MySQL و ORMs الشهيرة."},"recommendation":{"en":"Enables zero-downtime deployments and safe rollbacks through forward-only migration patterns. Provides expert guidance on schema changes, data backfills, and tooling integration for Prisma, Drizzle, Django, TypeORM, and golang-migrate.","zh":"通过仅前进的迁移模式实现零停机部署和安全回滚。为Prisma、Drizzle、Django、TypeORM和golang-migrate提供模式更改、数据回填和工具集成的专家指导。","ja":"前方へのみの移行パターンを通じて、ゼロダウンタイムのデプロイと安全なロールバックを可能にします。Prisma、Drizzle、Django、TypeORM、golang-migrateのスキーマ変更、データバックフィル、ツール統合についての専門家のガイダンスを提供します。","ko":"전진 전용 마이그레이션 패턴을 통해 제로 다운타임 배포 및 안전한 롤백을 가능하게 합니다. Prisma, Drizzle, Django, TypeORM 및 golang-migrate에 대한 스키마 변경, 데이터 백필 및 툴 통합에 대한 전문가 가이드를 제공합니다.","es":"Permite implementaciones sin tiempo de inactividad y reversión segura a través de patrones de migración solo hacia adelante. Proporciona orientación experta sobre cambios de esquema, rellenado de datos y integración de herramientas para Prisma, Drizzle, Django, TypeORM y golang-migrate.","fr":"Permet des déploiements sans temps d''arrêt et des réversions sécurisées grâce à des modèles de migration uniquement vers l''avant. Fournit une orientation experte sur les modifications de schéma, les remplissages de données et l''intégration d''outils pour Prisma, Drizzle, Django, TypeORM et golang-migrate.","de":"Ermöglicht Zero-Downtime-Deployments und sichere Rückgängigmachung durch forward-only-Migrationsmuster. Bietet Expertenrat zu Schemäänderungen, Daten-Nachbefüllung und Tool-Integration für Prisma, Drizzle, Django, TypeORM und golang-migrate.","pt":"Permite implantações sem tempo de inatividade e reversões seguras por meio de padrões de migração somente para frente. Fornece orientação especializada sobre alterações de esquema, backfills de dados e integração de ferramentas para Prisma, Drizzle, Django, TypeORM e golang-migrate.","ru":"Позволяет выполнять развертывания без простоя и безопасные откаты посредством шаблонов миграции только вперед. Предоставляет экспертные рекомендации по изменениям схемы, обратному заполнению данных и интеграции инструментов для Prisma, Drizzle, Django, TypeORM и golang-migrate.","ar":"تمكن من عمليات النشر بدون توقف وعمليات التراجع الآمنة من خلال أنماط الهجرة إلى الأمام فقط. توفر إرشادات خبيرة حول تغييرات المخطط وعمليات ملء البيانات وعملية دمج الأدوات ل Prisma و Drizzle و Django و TypeORM و golang-migrate."},"useCases":{"en":["Executing reversible schema migrations","Planning zero-downtime deployments","Running data backfill operations","Setting up migration tooling for new projects","Generating rollback strategies for failed deployments"],"zh":["执行可逆的模式迁移","规划零停机部署","运行数据回填操作","为新项目设置迁移工具","为失败的部署生成回滚策略"],"ja":["可逆なスキーマ移行を実行する","ゼロダウンタイムのデプロイを計画する","データバックフィル操作を実行する","新しいプロジェクトのための移行ツールを設定する","失敗したデプロイのためのロールバック戦略を生成する"],"ko":["가역적인 스키마 마이그레이션을 실행하는 것","제로 다운타임 배포를 계획하는 것","데이터 백필 작업을 실행하는 것","새 프로젝트를 위한 마이그레이션 툴을 설정하는 것","실패한 배포를 위한 롤백 전략을 생성하는 것"],"es":["Ejecutar migraciones de esquema reversibles","Planificar implementaciones sin tiempo de inactividad","Ejecutar operaciones de rellenado de datos","Configurar herramientas de migración para nuevos proyectos","Generar estrategias de reversión para implementaciones fallidas"],"fr":["Exécuter des migrations de schéma réversibles","Planifier des déploiements sans temps d''arrêt","Exécuter des opérations de remplissage de données","Configurer des outils de migration pour de nouveaux projets","Générer des stratégies de réversion pour les déploiements échoués"],"de":["Ausführen reversibler Schemamigrationen","Planen von Zero-Downtime-Deployments","Ausführen von Daten-Nachbefüllungsoperationen","Einrichten von Migrations-Tooling für neue Projekte","Generieren von Rückgängigkeitsstrategien für fehlgeschlagene Deployments"],"pt":["Executar migrações de esquema reversíveis","Planejar implantações sem tempo de inatividade","Executar operações de backfill de dados","Configurar ferramentas de migração para novos projetos","Gerar estratégias de rollback para implantações com falha"],"ru":["Выполнять обратимые миграции схемы","Планировать развертывания без простоя","Запускать операции по обратному заполнению данных","Настроить инструменты миграции для новых проектов","Генерировать стратегии откатов для неудачных развертываний"],"ar":["تنفيذ هجرات مخطط معكوسة","تخطيط عمليات النشر بدون توقف","تشغيل عمليات ملء البيانات","ضبط أدوات الهجرة لمشاريع جديدة","توليد استراتيجيات التراجع لعمليات النشر الفاشلة"]},"limitations":{"en":["Requires database connection credentials","ORM-specific implementations may vary","Production environments require forward-only migration patterns"],"zh":["需要数据库连接凭据","ORM特定的实现可能会有所不同","生产环境需要前进式迁移模式"],"ja":["データベース接続資格情報が必要","ORM固有の実装は異なる場合がある","プロダクション環境では前方へのみの移行パターンが必要"],"ko":["데이터베이스 연결 자격 증명이 필요함","ORM 특정 구현은 달라질 수 있음","프로덕션 환경에서는 전진 전용 마이그레이션 패턴이 필요함"],"es":["Requiere credenciales de conexión de base de datos","Las implementaciones específicas de ORM pueden variar","Los entornos de producción requieren patrones de migración solo hacia adelante"],"fr":["Nécessite des informations d''identification de connexion de base de données","Les implémentations spécifiques à l''ORM peuvent varier","Les environnements de production nécessitent des modèles de migration uniquement vers l''avant"],"de":["Benötigt Datenbank-Verbindungszugangsdaten","ORM-spezifische Implementierungen können variieren","Produktionsumgebungen erfordern forward-only-Migrationsmuster"],"pt":["Requer credenciais de conexão de banco de dados","Implementações específicas de ORM podem variar","Ambientes de produção requerem padrões de migração somente para frente"],"ru":["Требует учетных данных подключения к базе данных","Реализации, специфичные для ORM, могут различаться","Продукционные среды требуют шаблонов миграции только вперед"],"ar":["يتطلب بيانات اعتماد الاتصال بقاعدة البيانات","يمكن أن تختلف تنفيذات ORM النوعية","تتطلب بيئات الإنتاج أنماط هجرة إلى الأمام فقط"]},"version":4},"contentHash":"01d862480a071015cd9a7efedb4e0ec63568a1e90bbe82d4d135cad03f795309","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":74}');
