INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/database-migrations', 'database-migrations', 'affaan-m', 'everything-claude-code', 'official', 'database-migrations affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity Database-migrations enables developers to perform safe and reversible database schema changes, supporting zero-downtime deployments across various databases and ORMs, including PostgreSQL, MySQL, Prisma, and TypeORM. 数据库迁移最佳实践包括PostgreSQL、MySQL和常见ORM的零宕机部署和数据迁移 データベース移行のベストプラクティスは、PostgreSQL、MySQL、ORMでのゼロダウンタイムデプロイとデータ移行を含みます 데이터베이스 마이그레이션의 베스트 프랙티스는 PostgreSQL, MySQL, ORM에서 제로 다운타임 배포와 데이터 마이그레이션을 포함합니다 Migraciones de base de datos seguras y reversibles para cambios de esquema y datos con AI Agent, compatible con PostgreSQL, MySQL y ORMs como Prisma y TypeORM Migrations de base de données sûres et réversibles pour les changements de schéma et de données avec Agent IA, compatible avec PostgreSQL, MySQL et ORMs comme Prisma et TypeORM Sichere und rückgängig machbare Datenbankmigrationen für Schema- und Datenänderungen mit KI-Agent, kompatibel mit PostgreSQL, MySQL und ORMs wie Prisma und TypeORM Realize migrações de esquema de banco de dados seguras e reversíveis com PostgreSQL, MySQL e ORMs como Prisma e TypeORM Выполняйте безопасные и обратимые миграции схемы базы данных с PostgreSQL, MySQL и ORM, такими как Prisma и TypeORM для ИИ Агентов إجراء عمليات هجرة آمنة ومتعاكسة لجدول قاعدة البيانات مع PostgreSQL و MySQL و ORMs مثل Prisma و TypeORM database-migrations tutorial zero-downtime deployment strategies PostgreSQL migration best practices MySQL database migration tools Prisma vs TypeORM for database migrations how to use database-migrations with Django database-migrations setup guide database-migrations alternative solutions database-migrations and golang-migrate integration 数据库迁移 PostgreSQL迁移 MySQL迁移 ORM迁移 零宕机部署 数据迁移 Prisma Drizzle Django TypeORM golang-migrate Supports schema changes and data migrations for PostgreSQL and MySQL Integrates with popular ORMs such as Prisma, Drizzle, Django, and TypeORM Enables zero-downtime deployments using forward-only migrations in production Allows for rollbacks using new migrations Provides a framework for planning and executing safe and reversible database changes Database-migrations is a set of best practices for managing schema changes, data migrations, and rollbacks in production systems, ensuring minimal downtime and data integrity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/eval-harness', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'eval-harness', 61988, 7678, 74, '2026-03-06T03:39:20Z', '2026-03-06T04:09:26.114Z', '0b1933f5532df4bcc750d8799b7b33037e66c5d41f87d2953065868d08981926', '{"id":"affaan-m/everything-claude-code/eval-harness","name":"eval-harness","description":{"en":"The eval-harness skill provides a formal evaluation framework for Claude Code sessions, implementing eval-driven development principles for AI-assisted workflows. It benefits developers working with AI agents.","zh":"Eval Harness 是一个正式的评估框架，用于 Claude Code 会话，实现评估驱动开发（EDD）原则。它帮助开发者提高 AI 辅助工作流的可靠性和性能","ja":"Eval Harness は、Claude Code セッションのための正式な評価フレームワークです。評価駆動開発（EDD）原則を実装し、AI エージェントの信頼性とパフォーマンスを向上させます","ko":"Eval Harness는 Claude Code 세션을 위한 공식적인 평가 프레임워크로, 평가 주도 개발(EDD) 원칙을 구현하여 AI 에이전트의 신뢰성과 성능을 향상시킵니다","es":"Eval Harness es un marco de evaluación formal para sesiones de Claude Code que implementa principios de desarrollo basado en evaluación. Mejora la productividad y la confiabilidad de los agentes de IA.","fr":"Eval Harness est un cadre d''évaluation formel pour les sessions Claude Code qui met en œuvre les principes de développement basé sur l''évaluation. Améliorez la productivité et la fiabilité des agents de l''IA.","de":"Eval Harness ist ein formaler Bewertungsrahmen für Claude-Code-Sitzungen, der Entwicklung basierend auf Bewertung implementiert. Steigern Sie die Produktivität und Zuverlässigkeit von KI-Agents.","pt":"O eval-harness é um framework de avaliação formal para sessões Claude Code que implementa princípios de eval-driven development (EDD). Permite definir critérios de pass/fail, medir confiabilidade com métricas pass@k e criar suites de teste de regressão para agentes AI.","ru":"eval-harness - это формальная структура оценки для сессий Claude Code, реализующая принципы eval-driven development (EDD). Позволяет определять критерии pass/fail, измерять надежность с метриками pass@k и создавать регрессионные тесты для ИИ Агентов.","ar":"eval-harness هو إطار تقييم رسمي لجلسات Claude Code ينفذ مبادئ eval-driven development (EDD). يتيح تحديد معايير النجاح/الفشل، قياس الموثوقية بمقاييس pass@k وإنشاء مجموعات اختبار الانحدار لأدوات الذكاء الاصطناعي."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"eval-harness","description":"Formal evaluation framework for Claude Code sessions implementing eval-driven development (EDD) principles","bodyPreview":"# Eval Harness Skill\n\nA formal evaluation framework for Claude Code sessions, implementing eval-driven development (EDD) principles.\n\n## When to Activate\n\n- Setting up eval-driven development (EDD) for AI-assisted workflows\n- Defining pass/fail criteria for Claude Code task completion\n- Measuring agent reliability with pass@k metrics\n- Creating regression test suites for prompt or agent changes\n- Benchmarking agent performance across model versions\n\n## Philosophy\n\nEval-Driven Development treats","body":"# Eval Harness Skill\n\nA formal evaluation framework for Claude Code sessions, implementing eval-driven development (EDD) principles.\n\n## When to Activate\n\n- Setting up eval-driven development (EDD) for AI-assisted workflows\n- Defining pass/fail criteria for Claude Code task completion\n- Measuring agent reliability with pass@k metrics\n- Creating regression test suites for prompt or agent changes\n- Benchmarking agent performance across model versions\n\n## Philosophy\n\nEval-Driven Development treats evals as the \"unit tests of AI development\":\n- Define expected behavior BEFORE implementation\n- Run evals continuously during development\n- Track regressions with each change\n- Use pass@k metrics for reliability measurement\n\n## Eval Types\n\n### Capability Evals\nTest if Claude can do something it couldn''t before:\n```markdown\n[CAPABILITY EVAL: feature-name]\nTask: Description of what Claude should accomplish\nSuccess Criteria:\n  - [ ] Criterion 1\n  - [ ] Criterion 2\n  - [ ] Criterion 3\nExpected Output: Description of expected result\n```\n\n### Regression Evals\nEnsure changes don''t break existing functionality:\n```markdown\n[REGRESSION EVAL: feature-name]\nBaseline: SHA or checkpoint name\nTests:\n  - existing-test-1: PASS/FAIL\n  - existing-test-2: PASS/FAIL\n  - existing-test-3: PASS/FAIL\nResult: X/Y passed (previously Y/Y)\n```\n\n## Grader Types\n\n### 1. Code-Based Grader\nDeterministic checks using code:\n```bash\n# Check if file contains expected pattern\ngrep -q \"export function handleAuth\" src/auth.ts && echo \"PASS\" || echo \"FAIL\"\n\n# Check if tests pass\nnpm test -- --testPathPattern=\"auth\" && echo \"PASS\" || echo \"FAIL\"\n\n# Check if build succeeds\nnpm run build && echo \"PASS\" || echo \"FAIL\"\n```\n\n### 2. Model-Based Grader\nUse Claude to evaluate open-ended outputs:\n```markdown\n[MODEL GRADER PROMPT]\nEvaluate the following code change:\n1. Does it solve the stated problem?\n2. Is it well-structured?\n3. Are edge cases handled?\n4. Is error handling appropriate?\n\nScore: 1-5 (1=poor, 5=excellent)\nReasoning: [explanation]\n```\n\n### 3. Human Grader\nFlag for manual review:\n```markdown\n[HUMAN REVIEW REQUIRED]\nChange: Description of what changed\nReason: Why human review is needed\nRisk Level: LOW/MEDIUM/HIGH\n```\n\n## Metrics\n\n### pass@k\n\"At least one success in k attempts\"\n- pass@1: First attempt success rate\n- pass@3: Success within 3 attempts\n- Typical target: pass@3 > 90%\n\n### pass^k\n\"All k trials succeed\"\n- Higher bar for reliability\n- pass^3: 3 consecutive successes\n- Use for critical paths\n\n## Eval Workflow\n\n### 1. Define (Before Coding)\n```markdown\n## EVAL DEFINITION: feature-xyz\n\n### Capability Evals\n1. Can create new user account\n2. Can validate email format\n3. Can hash password securely\n\n### Regression Evals\n1. Existing login still works\n2. Session management unchanged\n3. Logout flow intact\n\n### Success Metrics\n- pass@3 > 90% for capability evals\n- pass^3 = 100% for regression evals\n```\n\n### 2. Implement\nWrite code to pass the defined evals.\n\n### 3. Evaluate\n```bash\n# Run capability evals\n[Run each capability eval, record PASS/FAIL]\n\n# Run regression evals\nnpm test -- --testPathPattern=\"existing\"\n\n# Generate report\n```\n\n### 4. Report\n```markdown\nEVAL REPORT: feature-xyz\n========================\n\nCapability Evals:\n  create-user:     PASS (pass@1)\n  validate-email:  PASS (pass@2)\n  hash-password:   PASS (pass@1)\n  Overall:         3/3 passed\n\nRegression Evals:\n  login-flow:      PASS\n  session-mgmt:    PASS\n  logout-flow:     PASS\n  Overall:         3/3 passed\n\nMetrics:\n  pass@1: 67% (2/3)\n  pass@3: 100% (3/3)\n\nStatus: READY FOR REVIEW\n```\n\n## Integration Patterns\n\n### Pre-Implementation\n```\n/eval define feature-name\n```\nCreates eval definition file at `.claude/evals/feature-name.md`\n\n### During Implementation\n```\n/eval check feature-name\n```\nRuns current evals and reports status\n\n### Post-Implementation\n```\n/eval report feature-name\n```\nGenerates full eval report\n\n## Eval Storage\n\nStore evals in project:\n```\n.claude/\n  evals/\n    feature-xyz.md      # Eval definition\n    feature-xyz.log     # Eval run history\n    baseline.json       # Regression baselines\n```\n\n## Best Practices\n\n1. **Define evals BEFORE coding** - Forces clear thinking about success criteria\n2. **Run evals frequently** - Catch regressions early\n3. **Track pass@k over time** - Monitor reliability trends\n4. **Use code graders when possible** - Deterministic > probabilistic\n5. **Human review for security** - Never fully automate security checks\n6. **Keep evals fast** - Slow evals don''t get run\n7. **Version evals with code** - Evals are first-class artifacts\n\n## Example: Adding Authentication\n\n```markdown\n## EVAL: add-authentication\n\n### Phase 1: Define (10 min)\nCapability Evals:\n- [ ] User can register with email/password\n- [ ] User can login with valid credentials\n- [ ] Invalid credentials rejected with proper error\n- [ ] Sessions persist across page reloads\n- [ ] Logout clears session\n\nRegression Evals:\n- [ ] Public routes still accessible\n- [ ] API responses unchanged\n- [ ] Database schema compatible\n\n### Phase 2: Implement (varies)\n[Write code]\n\n### Phase 3: Evaluate\nRun: /eval check add-authentication\n\n### Phase 4: Report\nEVAL REPORT: add-authentication\n==============================\nCapability: 5/5 passed (pass@3: 100%)\nRegression: 3/3 passed (pass^3: 100%)\nStatus: SHIP IT\n```\n\n## Product Evals (v1.8)\n\nUse product evals when behavior quality cannot be captured by unit tests alone.\n\n### Grader Types\n\n1. Code grader (deterministic assertions)\n2. Rule grader (regex/schema constraints)\n3. Model grader (LLM-as-judge rubric)\n4. Human grader (manual adjudication for ambiguous outputs)\n\n### pass@k Guidance\n\n- `pass@1`: direct reliability\n- `pass@3`: practical reliability under controlled retries\n- `pass^3`: stability test (all 3 runs must pass)\n\nRecommended thresholds:\n- Capability evals: pass@3 >= 0.90\n- Regression evals: pass^3 = 1.00 for release-critical paths\n\n### Eval Anti-Patterns\n\n- Overfitting prompts to known eval examples\n- Measuring only happy-path outputs\n- Ignoring cost and latency drift while chasing pass rates\n- Allowing flaky graders in release gates\n\n### Minimal Eval Artifact Layout\n\n- `.claude/evals/<feature>.md` definition\n- `.claude/evals/<feature>.log` run history\n- `docs/releases/<version>/eval-summary.md` release snapshot\n"},"category":"official","lastSynced":"2026-03-06T04:09:26.114Z","seo":{"title":{"en":"eval-harness: Setup Guide for AI Agents | AI Agent Skill","zh":"Eval Harness Setup Guide - AIエージェント开发框架","ja":"Eval Harness ベストプラクティス - AIエージェントの評価フレームワーク","ko":"Eval Harness 구축 가이드 - AI 에이전트 개발을 위한 평가 프레임워크","es":"Guía de configuración de Eval Harness para desarrolladores","fr":"Guide de mise en place d''Eval Harness pour les développeurs","de":"Einrichtungsleitfaden für Eval Harness für Entwickler","pt":"eval-harness: Guia de Configuração para Eval-Driven Devel...","ru":"eval-harness: Руководство по настройке Eval-Driven Develo...","ar":"eval-harness: دليل إعداد Eval-Driven Development لأدوات ا..."},"description":{"en":"Unlock eval-driven development with eval-harness. Learn how to set up pass/fail criteria and measure agent reliability. Get started now!","zh":"了解 Eval Harness 如何通过评估驱动开发（EDD）原则提高 AI 辅助工作流的可靠性和性能","ja":"Eval Harness を使用して AI エージェントの信頼性とパフォーマンスを向上させる方法を学ぶ","ko":"Eval Harness를 사용하여 AI 에이전트의 신뢰성과 성능을 향상시키는 방법에 대해 알아보세요","es":"Mejora la productividad con Eval Harness, un marco de evaluación formal para sesiones de Claude Code que implementa principios de desarrollo basado en evalua...","fr":"Améliorez la productivité avec Eval Harness, un cadre d''évaluation formel pour les sessions Claude Code qui met en œuvre les principes de développement basé ...","de":"Steigern Sie die Produktivität mit Eval Harness, einem formalen Bewertungsrahmen für Claude-Code-Sitzungen, der Entwicklung basierend auf Bewertung implement...","pt":"Framework formal de avaliação para sessões Claude Code implementando princípios EDD. Configure critérios pass/fail, métricas pass@k e suites de regressão par...","ru":"Формальная структура оценки для сессий Claude Code, реализующая принципы EDD. Настройте критерии pass/fail, метрики pass@k и регрессионные тесты для ИИ Агентов.","ar":"إطار تقييم رسمي لجلسات Claude Code ينفذ مبادئ EDD. قم بإعداد معايير النجاح/الفشل، مقاييس pass@k ومجموعات اختبار الانحدار لتطوير أدوات الذكاء الاصطناعي."},"definition":{"en":"eval-harness is a formal evaluation framework for Claude Code sessions, implementing eval-driven development principles for AI-assisted workflows.","zh":"Eval Harness 是一个 AI 辅助工作流的评估框架，用于实现评估驱动开发（EDD）原则","ja":"Eval Harness は、AI エージェントの評価フレームワークであり、評価駆動開発（EDD）原則を実装するために使用されます","ko":"Eval Harness는 AI 에이전트의 평가 프레임워크로, 평가 주도 개발(EDD) 원칙을 구현하는 데 사용됩니다","es":"Eval Harness es un marco de evaluación formal para desarrolladores que implementa principios de desarrollo basado en evaluación para sesiones de Claude Code","fr":"Eval Harness est un cadre d''évaluation formel pour les développeurs qui met en œuvre les principes de développement basé sur l''évaluation pour les sessions Claude Code","de":"Eval Harness ist ein formaler Bewertungsrahmen für Entwickler, der Entwicklung basierend auf Bewertung für Claude-Code-Sitzungen implementiert","pt":"eval-harness é um framework formal de avaliação para sessões Claude Code que implementa princípios de desenvolvimento orientado por avaliação (EDD). Ele permite definir critérios de pass/fail, medir confiabilidade de agentes com métricas pass@k e criar suites de teste de regressão para mudanças em prompts ou agentes.","ru":"eval-harness - это формальная структура оценки для сессий Claude Code, реализующая принципы разработки на основе оценки (EDD). Она позволяет определять критерии pass/fail, измерять надежность агентов с метриками pass@k и создавать регрессионные тесты для изменений промптов или агентов.","ar":"eval-harness هو إطار تقييم رسمي لجلسات Claude Code ينفذ مبادئ التطوير القائم على التقييم (EDD). يسمح بتحديد معايير النجاح/الفشل، قياس موثوقية الأدوات بمقاييس pass@k وإنشاء اختبارات الانحدار للتغييرات في الأوامر أو الأدوات."},"features":{"en":["Implements eval-driven development (EDD) principles for AI-assisted workflows","Defines pass/fail criteria for Claude Code task completion","Measures agent reliability with pass@k metrics","Creates regression test suites for prompt or agent changes","Benchmarking agent performance across model versions"],"zh":["评估驱动开发（EDD）原则实现","Claude Code 会话的正式评估框架","pass/fail 标准的定义","pass@k 指标的测量","回归测试套件的创建","Benchmarking 代理性能"],"ja":["評価駆動開発（EDD）原則の実装","Claude Code セッションのための正式な評価フレームワーク","pass/fail 基準の定義","pass@k メトリクスの測定","回帰テストスイートの作成","ベンチマーク テストの実行"],"ko":["평가 주도 개발(EDD) 원칙 구현","Claude Code 세션을 위한 공식적인 평가 프레임워크","pass/fail 기준의 정의","pass@k 지표의 측정","회귀 테스트套件의 생성","벤치마킹 에이전트 성능"],"es":["Implementación de principios de desarrollo basado en evaluación (EDD)","Definición de criterios de aprobación/rechazo para la finalización de tareas de Claude Code","Medición de la confiabilidad de los agentes con métricas pass@k","Creación de suites de pruebas de regresión para cambios en los agentes o las sesiones","Benchmarcking del rendimiento de los agentes en diferentes versiones del modelo"],"fr":["Mise en œuvre des principes de développement basé sur l''évaluation (EDD)","Définition des critères de réussite/échec pour la finalisation des tâches Claude Code","Mesure de la fiabilité des agents avec des métriques pass@k","Création de suites de tests de régression pour les modifications des agents ou des sessions","Benchmarcking des performances des agents dans différentes versions du modèle"],"de":["Implementierung von Entwicklung basierend auf Bewertung (EDD)-Prinzipien","Definition von Bestehen/Scheitern-Kriterien für die Fertigstellung von Claude-Code-Aufgaben","Messung der Zuverlässigkeit von Agents mit pass@k-Metriken","Erstellung von Regressions-Test-Suiten für Änderungen an Agents oder Sitzungen","Benchmarcking der Leistung von Agents in verschiedenen Modellversionen"],"pt":["Implementação de princípios eval-driven development (EDD) para workflows com IA","Definição de critérios pass/fail para conclusão de tarefas no Claude Code","Medição de confiabilidade de agentes com métricas pass@k","Criação de suites de teste de regressão para mudanças em prompts ou agentes","Benchmarking de performance entre versões de modelos AI","Integração com ecossistema MCP e ferramentas de desenvolvimento"],"ru":["Реализация принципов eval-driven development (EDD) для рабочих процессов с ИИ","Определение критериев pass/fail для завершения задач в Claude Code","Измерение надежности ИИ Агентов с метриками pass@k","Создание регрессионных тестов для изменений промптов или агентов","Сравнение производительности между версиями AI моделей","Интеграция с экосистемой MCP и инструментами разработки"],"ar":["تنفيذ مبادئ eval-driven development (EDD) لسير العمل باستخدام الذكاء الاصطناعي","تحديد معايير النجاح/الفشل لإكمال المهام في Claude Code","قياس موثوقية أدوات الذكاء الاصطناعي بمقاييس pass@k","إنشاء مجموعات اختبار الانحدار للتغييرات في الأوامر أو الأدوات","مقارنة الأداء بين إصدارات نماذج الذكاء الاصطناعي","التكامل مع نظام MCP وأدوات التطوير"]},"keywords":{"en":["how to use eval-harness","eval-harness setup guide","eval-harness alternative","eval-harness vs mcp","eval-driven development tutorial","ai agent reliability metrics"],"zh":["AI 辅助工作流","评估驱动开发","Claude Code","评估框架","AI エージェント开发","评估驱动开发原则","pass/fail 标准","pass@k 指标"],"ja":["AI エージェント開発","評価駆動開発","Claude Code","評価フレームワーク","AI エージェントの評価","評価駆動開発原則","pass/fail 基準","pass@k メトリクス"],"ko":["AI 에이전트 개발","평가 주도 개발","Claude Code","평가 프레임워크","AI 에이전트의 평가","평가 주도 개발 원칙","pass/fail 기준","pass@k 지표"],"es":["Eval Harness","desarrollo basado en evaluación","agentes de IA","herramientas de desarrollo","Claude Code","productividad","confiabilidad","métricas pass@k","pruebas de regresión"],"fr":["Eval Harness","développement basé sur l''évaluation","agents de l''IA","outils de développement","Claude Code","productivité","fiabilité","métriques pass@k","tests de régression"],"de":["Eval Harness","Entwicklung basierend auf Bewertung","KI-Agents","Entwicklungstools","Claude Code","Produktivität","Zuverlässigkeit","pass@k-Metriken","Regressions-Tests"],"pt":["eval-harness setup claude","eval driven development EDD","pass@k metrics AI agents","claude code evaluation framework","regression test suites prompts","MCP integration developer tools","benchmarking AI model versions","anthropic claude developer workflow"],"ru":["eval-harness настройка ИИ Агентов","eval driven development EDD","pass@k метрики Claude Code","фреймворк оценки ИИ Агентов","регрессионные тесты промптов","MCP интеграция инструменты разработки","сравнение версий AI моделей","anthropic claude рабочий процесс"],"ar":["eval-harness إعداد أدوات الذكاء الاصطناعي","eval driven development EDD","مقاييس pass@k Claude Code","إطار تقييم أدوات الذكاء الاصطناعي","اختبارات الانحدار للأوامر","تكامل MCP أدوات المطور","مقارنة إصدارات نماذج الذكاء الاصطناعي","anthropic claude سير العمل"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Evaluation Framework Agents implementing eval-driven development (EDD) principles for AI-assisted workflows.","zh":"非常适合为实施评估驱动开发（EDD）原则以实现AI辅助工作流程的评估框架代理。","ja":"AI支援ワークフローのための評価駆動開発（EDD）原則を実装する評価フレームワークエージェントに最適です。","ko":"AI 지원 워크플로우를 위한 평가 주도 개발(EDD) 원칙을 구현하는 평가 프레임워크 에이전트에 완벽하게 적합합니다.","es":"Perfecto para agentes del marco de evaluación que implementan principios de desarrollo impulsado por evaluación (EDD) para flujos de trabajo asistidos por IA.","fr":"Parfait pour les agents du cadre d''évaluation qui mettent en œuvre les principes de développement piloté par l''évaluation (EDD) pour les flux de travail assistés par l''IA.","de":"Perfekt für Bewertungsframework-Agents, die EDD-Prinzipien (eval-driven development) für AI-gestützte Workflows umsetzen.","pt":"Perfeito para agentes de Framework de Avaliação que implementam princípios de desenvolvimento orientado por avaliação (EDD) para fluxos de trabalho assistidos por IA.","ru":"Идеально подходит для агентов оценочной структуры (Evaluation Framework Agents), реализующих принципы разработки на основе оценки (EDD) для рабочих процессов с поддержкой ИИ.","ar":"مثالي لوكلاء إطار التقييم الذين ينفذون مبادئ التطوير القائم على التقييم (EDD) لسير العمل المعزز بالذكاء الاصطناعي."},"recommendation":{"en":"Enables formal evaluation framework implementation for Claude Code sessions with pass/fail criteria definition and pass@k reliability metrics. Provides structured regression testing and performance benchmarking capabilities across model versions.","zh":"支持为Claude Code会话实施正式的评估框架，包括定义通过/失败标准和pass@k可靠性指标。提供跨模型版本的结构化回归测试和性能基准测试能力。","ja":"Claude Codeセッションのための正式な評価フレームワークの実装を可能にし、合格/不合格基準の定義とpass@k信頼性メトリクスを提供します。モデルバージョン間での構造化された回帰テストとパフォーマンスベンチマーク機能を提供します。","ko":"Claude Code 세션을 위한 공식 평가 프레임워크 구현을 가능하게 하며, 합격/불합격 기준 정의와 pass@k 신뢰성 메트릭을 제공합니다. 모델 버전 전반에 걸친 구조화된 회귀 테스트 및 성능 벤치마킹 기능을 제공합니다.","es":"Habilita la implementación formal del marco de evaluación para sesiones de Claude Code con definición de criterios de aprobado/reprobado y métricas de confiabilidad pass@k. Proporciona capacidades de prueba de regresión estructurada y benchmarking de rendimiento en varias versiones del modelo.","fr":"Permet la mise en œuvre formelle du cadre d''évaluation pour les sessions Claude Code avec définition des critères d''approbation/échec et des métriques de fiabilité pass@k. Fournit des capacités de test de régression structuré et de benchmarking de performances à travers les versions de modèle.","de":"Ermöglicht die formale Implementierung des Bewertungsframeworks für Claude Code-Sitzungen mit Bestehen/Scheitern-Kriterien-Definition und pass@k-Zuverlässigkeitsmetriken. Bietet strukturierte Regressions-Test- und Leistungs-Benchmarking-Fähigkeiten über Modellversionen hinweg.","pt":"Permite a implementação de um framework de avaliação formal para sessões do Claude Code com definição de critérios de aprovação/reprovação e métricas de confiabilidade pass@k. Fornece capacidades estruturadas de teste de regressão e benchmarking de desempenho entre versões de modelos.","ru":"Позволяет реализовать формальную оценочную структуру для сессий Claude Code с определением критериев прохождения/непрохождения и метрик надежности pass@k. Обеспечивает структурированные возможности регрессионного тестирования и сравнительного анализа производительности между версиями моделей.","ar":"يتيح تنفيذ إطار تقييم رسمي لجلسات Claude Code مع تعريف معايير النجاح/الرسوب ومقاييس موثوقية pass@k. يوفر إمكانيات منظمة لاختبار الانحدار ومعايير أداء عبر إصدارات النماذج."},"useCases":{"en":["Setting up eval-driven development workflows","Measuring agent reliability with pass@k metrics","Creating regression test suites for prompt changes","Benchmarking performance across model versions"],"zh":["设置评估驱动开发工作流程","使用pass@k指标衡量代理可靠性","为提示更改创建回归测试套件","跨模型版本进行性能基准测试"],"ja":["評価駆動開発ワークフローの設定","pass@kメトリクスを使用したエージェントの信頼性測定","プロンプト変更のための回帰テストスイートの作成","モデルバージョン間でのパフォーマンスベンチマーク"],"ko":["평가 주도 개발 워크플로우 설정","pass@k 메트릭을 사용한 에이전트 신뢰성 측정","프롬프트 변경을 위한 회귀 테스트 스위트 생성","모델 버전 간 성능 벤치마킹"],"es":["Configuración de flujos de trabajo de desarrollo impulsado por evaluación","Medición de la confiabilidad del agente con métricas pass@k","Creación de suites de pruebas de regresión para cambios de prompt","Benchmarking de rendimiento en varias versiones del modelo"],"fr":["Configuration de flux de travail de développement piloté par l''évaluation","Mesure de la fiabilité de l''agent avec des métriques pass@k","Création de suites de tests de régression pour les modifications de prompt","Benchmarking des performances à travers les versions de modèle"],"de":["Einrichtung von EDD-Workflows","Messung der Zuverlässigkeit des Agents mit pass@k-Metrik","Erstellung von Regressions-Test-Suiten für Prompt-Änderungen","Leistungs-Benchmarking über Modellversionen hinweg"],"pt":["Configuração de fluxos de trabalho de desenvolvimento orientado por avaliação","Medição da confiabilidade do agente com métricas pass@k","Criação de suites de teste de regressão para alterações de prompt","Benchmarking de desempenho entre versões de modelos"],"ru":["Настройка рабочих процессов разработки на основе оценки","Измерение надежности агента с помощью метрик pass@k","Создание наборов регрессионных тестов для изменений промптов","Сравнительный анализ производительности между версиями моделей"],"ar":["إعداد سير عمل التطوير القائم على التقييم","قياس موثوقية الوكيل بمقاييس pass@k","إنشاء مجموعات اختبار الانحدار لتغييرات الـ prompt","قياس الأداء المقارن عبر إصدارات النماذج"]},"limitations":{"en":["Specifically designed for Claude Code sessions","Requires predefined pass/fail criteria","Focused on EDD principles implementation"],"zh":["专为Claude Code会话设计","需要预定义的通过/失败标准","专注于EDD原则的实施"],"ja":["Claude Codeセッション専用に設計されています","事前定義された合格/不合格基準が必要です","EDD原則の実装に焦点を当てています"],"ko":["Claude Code 세션 전용으로 설계됨","미리 정의된 합격/불합격 기준이 필요함","EDD 원칙 구현에 중점을 둠"],"es":["Diseñado específicamente para sesiones de Claude Code","Requiere criterios predefinidos de aprobado/reprobado","Centrado en la implementación de principios EDD"],"fr":["Conçu spécifiquement pour les sessions Claude Code","Nécessite des critères prédéfinis d''approbation/échec","Axé sur la mise en œuvre des principes EDD"],"de":["Speziell für Claude Code-Sitzungen konzipiert","Benötigt vordefinierte Bestehen/Scheitern-Kriterien","Fokussiert auf die Umsetzung von EDD-Prinzipien"],"pt":["Projetado especificamente para sessões do Claude Code","Requer critérios de aprovação/reprovação predefinidos","Focado na implementação dos princípios do EDD"],"ru":["Специально разработан для сессий Claude Code","Требует предопределенных критериев прохождения/непрохождения","Сфокусирован на реализации принципов EDD"],"ar":["مصمم خصيصًا لجلسات Claude Code","يتطلب معايير نجاح/رسوب محددة مسبقًا","مركز على تنفيذ مبادئ EDD"]},"version":4},"contentHash":"0b1933f5532df4bcc750d8799b7b33037e66c5d41f87d2953065868d08981926","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":74}');
