INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/eval-harness', 'eval-harness', 'affaan-m', 'everything-claude-code', 'official', 'eval-harness affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The eval-harness skill provides a formal evaluation framework for Claude Code sessions, implementing eval-driven development principles for AI-assisted workflows. It benefits developers working with AI agents. Eval Harness 是一个正式的评估框架，用于 Claude Code 会话，实现评估驱动开发（EDD）原则。它帮助开发者提高 AI 辅助工作流的可靠性和性能 Eval Harness は、Claude Code セッションのための正式な評価フレームワークです。評価駆動開発（EDD）原則を実装し、AI エージェントの信頼性とパフォーマンスを向上させます Eval Harness는 Claude Code 세션을 위한 공식적인 평가 프레임워크로, 평가 주도 개발(EDD) 원칙을 구현하여 AI 에이전트의 신뢰성과 성능을 향상시킵니다 Eval Harness es un marco de evaluación formal para sesiones de Claude Code que implementa principios de desarrollo basado en evaluación. Mejora la productividad y la confiabilidad de los agentes de IA. Eval Harness est un cadre d''évaluation formel pour les sessions Claude Code qui met en œuvre les principes de développement basé sur l''évaluation. Améliorez la productivité et la fiabilité des agents de l''IA. Eval Harness ist ein formaler Bewertungsrahmen für Claude-Code-Sitzungen, der Entwicklung basierend auf Bewertung implementiert. Steigern Sie die Produktivität und Zuverlässigkeit von KI-Agents. O eval-harness é um framework de avaliação formal para sessões Claude Code que implementa princípios de eval-driven development (EDD). Permite definir critérios de pass/fail, medir confiabilidade com métricas pass@k e criar suites de teste de regressão para agentes AI. eval-harness - это формальная структура оценки для сессий Claude Code, реализующая принципы eval-driven development (EDD). Позволяет определять критерии pass/fail, измерять надежность с метриками pass@k и создавать регрессионные тесты для ИИ Агентов. eval-harness هو إطار تقييم رسمي لجلسات Claude Code ينفذ مبادئ eval-driven development (EDD). يتيح تحديد معايير النجاح/الفشل، قياس الموثوقية بمقاييس pass@k وإنشاء مجموعات اختبار الانحدار لأدوات الذكاء الاصطناعي. how to use eval-harness eval-harness setup guide eval-harness alternative eval-harness vs mcp eval-driven development tutorial ai agent reliability metrics AI 辅助工作流 评估驱动开发 Claude Code 评估框架 AI エージェント开发 评估驱动开发原则 pass/fail 标准 pass@k 指标 Implements eval-driven development (EDD) principles for AI-assisted workflows Defines pass/fail criteria for Claude Code task completion Measures agent reliability with pass@k metrics Creates regression test suites for prompt or agent changes Benchmarking agent performance across model versions eval-harness is a formal evaluation framework for Claude Code sessions, implementing eval-driven development principles for AI-assisted workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/postgres-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'postgres-patterns', 61988, 7678, 74, '2026-03-06T03:39:20Z', '2026-03-06T04:25:20.538Z', '2b07d5f7de1b68a93c8b25d093be2f0e9bfde11b8f488bd5433f0bac15415074', '{"id":"affaan-m/everything-claude-code/postgres-patterns","name":"postgres-patterns","description":{"en":"An AI Agent skill providing PostgreSQL database patterns for query optimization, schema design, indexing, and security. It serves developers writing SQL queries, migrations, and implementing Row Level Security based on Supabase best practices.","zh":"Postgres 模式提供了数据库优化的最佳实践，包括查询优化、模式设计、索引和安全","ja":"Postgres パターンは、クエリ最適化、スキーマ設計、インデックス、セキュリティのベストプラクティスを提供します","ko":"Postgres 패턴은 데이터베이스 최적화를 위한 최고의 관행을 제공합니다. 쿼리 최적화, 스키마 디자인, 인덱싱, 보안 등","es":"Patrones de Postgres para optimizar consultas, diseñar esquemas y mejorar la seguridad de tu base de datos","fr":"Modèles Postgres pour optimiser les requêtes, concevoir des schémas et améliorer la sécurité de votre base de données","de":"Postgres-Muster für Abfrage-Optimierung, Schemadesign und Sicherheitsverbesserung Ihrer Datenbank","pt":"O Postgres-Patterns fornece diretrizes para otimização de consultas, design de esquemas e segurança de banco de dados","ru":"Шаблоны PostgreSQL предоставляют рекомендации для оптимизации запросов, проектирования схем и безопасности базы данных","ar":"أنماط بوستجريز توفر إرشادات لتحسين الاستفسارات وتصميم مخططات قاعدة البيانات وأمانها"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"postgres-patterns","description":"PostgreSQL database patterns for query optimization, schema design, indexing, and security. Based on Supabase best practices.","bodyPreview":"# PostgreSQL Patterns\n\nQuick reference for PostgreSQL best practices. For detailed guidance, use the `database-reviewer` agent.\n\n## When to Activate\n\n- Writing SQL queries or migrations\n- Designing database schemas\n- Troubleshooting slow queries\n- Implementing Row Level Security\n- Setting up connection pooling\n\n## Quick Reference\n\n### Index Cheat Sheet\n\n| Query Pattern | Index Type | Example |\n|--------------|------------|---------|\n| `WHERE col = value` | B-tree (default) | `CREATE INDEX idx ON","body":"# PostgreSQL Patterns\n\nQuick reference for PostgreSQL best practices. For detailed guidance, use the `database-reviewer` agent.\n\n## When to Activate\n\n- Writing SQL queries or migrations\n- Designing database schemas\n- Troubleshooting slow queries\n- Implementing Row Level Security\n- Setting up connection pooling\n\n## Quick Reference\n\n### Index Cheat Sheet\n\n| Query Pattern | Index Type | Example |\n|--------------|------------|---------|\n| `WHERE col = value` | B-tree (default) | `CREATE INDEX idx ON t (col)` |\n| `WHERE col > value` | B-tree | `CREATE INDEX idx ON t (col)` |\n| `WHERE a = x AND b > y` | Composite | `CREATE INDEX idx ON t (a, b)` |\n| `WHERE jsonb @> ''{}''` | GIN | `CREATE INDEX idx ON t USING gin (col)` |\n| `WHERE tsv @@ query` | GIN | `CREATE INDEX idx ON t USING gin (col)` |\n| Time-series ranges | BRIN | `CREATE INDEX idx ON t USING brin (col)` |\n\n### Data Type Quick Reference\n\n| Use Case | Correct Type | Avoid |\n|----------|-------------|-------|\n| IDs | `bigint` | `int`, random UUID |\n| Strings | `text` | `varchar(255)` |\n| Timestamps | `timestamptz` | `timestamp` |\n| Money | `numeric(10,2)` | `float` |\n| Flags | `boolean` | `varchar`, `int` |\n\n### Common Patterns\n\n**Composite Index Order:**\n```sql\n-- Equality columns first, then range columns\nCREATE INDEX idx ON orders (status, created_at);\n-- Works for: WHERE status = ''pending'' AND created_at > ''2024-01-01''\n```\n\n**Covering Index:**\n```sql\nCREATE INDEX idx ON users (email) INCLUDE (name, created_at);\n-- Avoids table lookup for SELECT email, name, created_at\n```\n\n**Partial Index:**\n```sql\nCREATE INDEX idx ON users (email) WHERE deleted_at IS NULL;\n-- Smaller index, only includes active users\n```\n\n**RLS Policy (Optimized):**\n```sql\nCREATE POLICY policy ON orders\n  USING ((SELECT auth.uid()) = user_id);  -- Wrap in SELECT!\n```\n\n**UPSERT:**\n```sql\nINSERT INTO settings (user_id, key, value)\nVALUES (123, ''theme'', ''dark'')\nON CONFLICT (user_id, key)\nDO UPDATE SET value = EXCLUDED.value;\n```\n\n**Cursor Pagination:**\n```sql\nSELECT * FROM products WHERE id > $last_id ORDER BY id LIMIT 20;\n-- O(1) vs OFFSET which is O(n)\n```\n\n**Queue Processing:**\n```sql\nUPDATE jobs SET status = ''processing''\nWHERE id = (\n  SELECT id FROM jobs WHERE status = ''pending''\n  ORDER BY created_at LIMIT 1\n  FOR UPDATE SKIP LOCKED\n) RETURNING *;\n```\n\n### Anti-Pattern Detection\n\n```sql\n-- Find unindexed foreign keys\nSELECT conrelid::regclass, a.attname\nFROM pg_constraint c\nJOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)\nWHERE c.contype = ''f''\n  AND NOT EXISTS (\n    SELECT 1 FROM pg_index i\n    WHERE i.indrelid = c.conrelid AND a.attnum = ANY(i.indkey)\n  );\n\n-- Find slow queries\nSELECT query, mean_exec_time, calls\nFROM pg_stat_statements\nWHERE mean_exec_time > 100\nORDER BY mean_exec_time DESC;\n\n-- Check table bloat\nSELECT relname, n_dead_tup, last_vacuum\nFROM pg_stat_user_tables\nWHERE n_dead_tup > 1000\nORDER BY n_dead_tup DESC;\n```\n\n### Configuration Template\n\n```sql\n-- Connection limits (adjust for RAM)\nALTER SYSTEM SET max_connections = 100;\nALTER SYSTEM SET work_mem = ''8MB'';\n\n-- Timeouts\nALTER SYSTEM SET idle_in_transaction_session_timeout = ''30s'';\nALTER SYSTEM SET statement_timeout = ''30s'';\n\n-- Monitoring\nCREATE EXTENSION IF NOT EXISTS pg_stat_statements;\n\n-- Security defaults\nREVOKE ALL ON SCHEMA public FROM public;\n\nSELECT pg_reload_conf();\n```\n\n## Related\n\n- Agent: `database-reviewer` - Full database review workflow\n- Skill: `clickhouse-io` - ClickHouse analytics patterns\n- Skill: `backend-patterns` - API and backend patterns\n\n---\n\n*Based on Supabase Agent Skills (credit: Supabase team) (MIT License)*\n"},"category":"official","lastSynced":"2026-03-06T04:25:20.538Z","seo":{"title":{"en":"Postgres-Patterns: Database Optimization & Security Best ...","zh":"Postgres 模式最佳实践指南","ja":"Postgres パターン設定ガイド - AIエージェント","ko":"Postgres 패턴설정 가이드 - 개발자를 위한 최고의 관행","es":"Patrones de Postgres: Guía de Optimización de Consultas","fr":"Modèles Postgres: Guide de Meilleures Pratiques","de":"Postgres-Muster: Leitfaden für Abfrage-Optimierung","pt":"Guia de Configuração do Postgres-Patterns para Otimização...","ru":"Настройка шаблонов PostgreSQL для оптимизации запросов","ar":"دليل إعداد أنماط بوستجريز لتحسين الاستفسارات"},"description":{"en":"Accelerate PostgreSQL development with AI-driven best practices for query optimization, B-tree indexing, schema design, and Row Level Security. Install this ...","zh":"提高Postgres数据库性能，使用优化查询、模式设计、索引和安全的最佳实践","ja":"Postgresデータベースのパフォーマンスを向上させるためのクエリ最適化、スキーマ設計、インデックス、セキュリティのベストプラクティス","ko":"Postgres 데이터베이스 성능 향상을 위한 쿼리 최적화, 스키마 디자인, 인덱싱, 보안의 최고의 관행","es":"Mejora el rendimiento de tu base de datos con patrones de Postgres para optimización de consultas, diseño de esquemas y seguridad","fr":"Améliorez les performances de votre base de données avec des modèles Postgres pour l''optimisation des requêtes, la conception de schémas et la sécurité","de":"Verbessern Sie die Leistung Ihrer Datenbank mit Postgres-Mustern für Abfrage-Optimierung, Schemadesign und Sicherheit","pt":"Aprenda a otimizar consultas SQL, projetar esquemas de banco de dados e implementar segurança de nível de linha com os padrões d