INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/postgres-patterns', 'postgres-patterns', 'affaan-m', 'everything-claude-code', 'official', 'postgres-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity An AI Agent skill providing PostgreSQL database patterns for query optimization, schema design, indexing, and security. It serves developers writing SQL queries, migrations, and implementing Row Level Security based on Supabase best practices. Postgres 模式提供了数据库优化的最佳实践，包括查询优化、模式设计、索引和安全 Postgres パターンは、クエリ最適化、スキーマ設計、インデックス、セキュリティのベストプラクティスを提供します Postgres 패턴은 데이터베이스 최적화를 위한 최고의 관행을 제공합니다. 쿼리 최적화, 스키마 디자인, 인덱싱, 보안 등 Patrones de Postgres para optimizar consultas, diseñar esquemas y mejorar la seguridad de tu base de datos Modèles Postgres pour optimiser les requêtes, concevoir des schémas et améliorer la sécurité de votre base de données Postgres-Muster für Abfrage-Optimierung, Schemadesign und Sicherheitsverbesserung Ihrer Datenbank O Postgres-Patterns fornece diretrizes para otimização de consultas, design de esquemas e segurança de banco de dados Шаблоны PostgreSQL предоставляют рекомендации для оптимизации запросов, проектирования схем и безопасности базы данных أنماط بوستجريز توفر إرشادات لتحسين الاستفسارات وتصميم مخططات قاعدة البيانات وأمانها how to use postgres-patterns postgres-patterns vs database reviewer postgres-patterns install guide postgres-patterns indexing best practices what is postgres-patterns postgres-patterns Row Level Security setup postgres-patterns MCP skill for Claude postgres-patterns B-tree index examples postgres-patterns schema design patterns postgres-patterns Supabase best practices Postgres 模式 数据库优化 查询优化 模式设计 索引 安全 Supabase AI工具 开发者工具 Provides quick reference for PostgreSQL best practices and patterns Includes an index cheat sheet for optimizing query patterns like `WHERE col = value` Guides on implementing Row Level Security (RLS) for enhanced database security Assists with database schema design and writing SQL migrations Recommends B-tree indexes (the default PostgreSQL index type) for specific query patterns Integrates with the `database-reviewer` agent for detailed guidance postgres-patterns is an AI Agent skill for PostgreSQL that provides quick-reference patterns for query optimization, B-tree indexing, schema design, and implementing Row Level Security. It''s designed for developers writing SQL queries or migrations and troubleshooting performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/sred-work-summary', 'official', 'getsentry', 'skills', 'getsentry/skills', 'sred-work-summary', 360, 11, 74, '2026-03-06T00:20:36Z', '2026-03-06T05:19:25.443Z', '2ccbcb74155d8b53e00584aa3eedfb18615e2e21b58d11280a5659f652039534', '{"id":"getsentry/skills/sred-work-summary","name":"sred-work-summary","description":{"en":"The sred-work-summary skill automates the process of grouping relevant links into projects for SRED documentation, benefiting developers and teams who need to track their work. It collects data from Github PRs, Notion docs, and Linear tickets.","zh":"SRED工作总结AIエージェント可以自动收集Github PRs、Notion文档和Linear票据，生成私人Notion文档，简化SRED项目文档过程","ja":"SRED Work Summary AIエージェントは、Github PR、Notionドキュメント、Linearチケットを自動的に収集して、プライベートNotionドキュメントを生成し、SREDプロジェクトの文書化プロセスを簡素化","ko":"SRED 작업 요약 AI 에이전트는 Github PR, Notion 문서 및 Linear 티켓을 자동으로 수집하여 개인 Notion 문서를 생성하여 SRED 프로젝트 문서화 프로세스를 단순화","es":"El agente sred-work-summary recopila enlaces de Github, Notion y Linear para generar un resumen de trabajo de SRED en un documento de Notion. Utiliza MCP y la herramienta CLI de Github para acceder a los datos","fr":"L''outil sred-work-summary collecte des liens Github, Notion et Linear pour générer un résumé de travail SRED dans un document Notion. Il utilise MCP et l''outil CLI de Github pour accéder aux données","de":"Der sred-work-summary-Agent sammelt Links von Github, Notion und Linear, um eine SRED-Arbeitszusammenfassung in einem Notion-Dokument zu erstellen. Er verwendet MCP und die Github-CLI-Tool, um auf die Daten zuzugreifen","pt":"O sred-work-summary é uma ferramenta que reúne links relevantes do Github, Notion e Linear em projetos documentados","ru":"ИИ Агент sred-work-summary - это инструмент, который собирает ссылки из Github, Notion и Linear в проекты для документации","ar":"سرد العمل sred-work-summary هو أداة تجمع الروابط ذات الصلة من Github و Notion و Linear في مشاريع موثقة"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"sred-work-summary","description":"Go back through the previous year of work and create a Notion doc that groups relevant links into projects that can then be documented as SRED projects.","bodyPreview":"# SRED Work Summary\n\nCollect all the Github PRs, Notion docs and Linear tickets a person completed in a given year. Group the links from all of those into projects. Put everything into a private Notion document and return a link to that document.\n\n## Prerequisites\n\nBefore starting make sure that Github, Notion and Linear can be accessed. Notion and Linear should be connected using an MCP. Github can be connected with an MCP, but if you have access to the `gh` CLI tool, you can use that instead.","body":"# SRED Work Summary\n\nCollect all the Github PRs, Notion docs and Linear tickets a person completed in a given year. Group the links from all of those into projects. Put everything into a private Notion document and return a link to that document.\n\n## Prerequisites\n\nBefore starting make sure that Github, Notion and Linear can be accessed. Notion and Linear should be connected using an MCP. Github can be connected with an MCP, but if you have access to the `gh` CLI tool, you can use that instead.\n\nIf any of these can''t be accessed, prompt the user to grant access before proceeding.\n\n## Process\n\n### Step 1\n\n```bash\n# Get the current year\ndate +%Y\n```\n\nThe output of this command is the current year.\nThe current year minus one is the previous year.\n\n### Step 2\n\nCollect all of the required information from the user:\n\n*Github Username*: What is the github username of the user?\n\n*Github Repositories*: Which Github repositories should be searched for PRs?\n\nThe user can either specify a comma separated list, or provide a directory that contains repositories. In the second case use this command in the specified directory:\n\n```bash\n# Find github repos\nfind . -maxdepth 2 -name \".git\" -type d | sed ''s/\\/.git$//'' | sort\n```\n\nEnsure:\n- All the repositories listed are in the `getsentry` Github organization.\n\nThe output of this is hereafter referred to as the \"user repos\".\n\n*Incidents*: Ask if the user wants to include incident documents.\n\nThe answer is either yes or no. If the answer is no, that will exclude certain documents from the search later on.\n\n*Other Users*: Ask if there are any other users who might have created Notion documents.\n\nThis should be a comma separated list of names. Remember this as the \"other users\".\n\n### Step 3\n\nCreate a private Notion document entitled \"SRED Work Summary [current year]\". This document will be referred to as the Work Summary.\n\nIf a document with this name already exists, notify the user to rename the existing document and stop executing.\n\nEnsure:\n- If the Work Summary already exists, stop execution.\n\n### Step 4\n\nThe time window is Feb. 1 of the previous year until Jan. 31 of the current year\nFind all Github PRs created by the given github username in the time window for the user repos.\nIf the user does not want to include incident documents, ignore any Github PRs with `INC-X`, `inc-X` in the title or description.\nUse either the Github MCP or the `gh` command to do this.\n\nFind all the Notion documents the user created in the time window.\nIf the user does not want to include incident documents, ignore any Notion Documents with `INC-XXXX` in the title.\nUse the Notion MCP to do this.\n\nFind all the Linear tickets the user was assigned in the time window.\nIf the user does not want to include incident documents, ignore any Linear tickets with `INC-XXXX` in the title.\nUse the Linear MCP to do this.\n\nEnsure:\n- All the Github PRs were created or merged in the time window and was opened by the user.\n- All the Notion docs were created in the time window and were created by the user.\n- All the Linear tickets were opened or completed in the time window and were assigned to the user when they were completed.\n\n### Step 5\n\nFor each of the Github PRs, Notion documents and Linear tickets found in Step 4, put a link into the private document created in Step 3.\n\nEnsure:\n- There is a link for all the Github PRs in the Work Summary\n- There is a link for all the Notion docs in the Work Summary\n- There is a link for all the Linear tickets in the Work Summary\n- DO NOT truncate the lists of links. DO NOT use shorteners like \"...and 75 more\". Make sure that the full set of all Github PRs, Notion documents and Linear tickets is visible in the document.\n\n### Step 6\n\nUse your own intelligence to group all the Github, Notion and Linear ticket links in the Work Summary document into projects. The format of this document is shown below.\n\n```markdown\n# Projects\n\n## [Project Name]\n*Summary*: [X] PRs, [X] Notion docs, [X] Linear tickets\n\n### Pull Requests [X]\n*[repository name]\n[Links to all the PRs]\n- [link] - [Merge date]\n\n### Notion Docs [X]\n[Links to all the Notion docs]\n- [link] - [Creation date]\n\n### Linear Tickets [X]\n- [link] - [Creation date]\n```\n\nFor Github PRs, use both the title of the PR and the description of the PR for grouping.\nFor Notion documents, use the full document for grouping.\nFor Linear tickets use the title of the ticket and the description of the ticket.\n\nEnsure:\n- All the links in the file are assigned to a project.\n- The file follows the format specified above.\n- DO NOT truncate the lists of links. DO NOT use shorteners like \"...and 75 more\". Make sure that the full set of all Github PRs, Notion documents and Linear tickets is visible in the document.\n\n### Step 7\n\nSearch for notion documents created by the \"other users\". Take any that are relevant to the projects in the Work Summary and add links to those Notion documents into the Work Summary in the appropriate project.\n\n### Step 8\n\nReturn a link to the Work Summary Notion doc to the user.\n\nEnsure:\n- The actual Notion document link is in the final output.\n\n## Resources\n\nThis is an example Working Summary document for the year 2025: https://www.notion.so/sentry/Work-Summary-Feb-2025-Jan-2026-3068b10e4b5d81d3a40cfa6ad3fe1078?source=copy_link\n\n"},"category":"official","lastSynced":"2026-03-06T05:19:25.443Z","seo":{"title":{"en":"sred-work-summary: Automated SRED Project Documentation S...","zh":"SRED 工作总结设置指南 - 使用AIエージェント","ja":"SRED Work Summary セットアップガイド - AIエージェントを使用","ko":"SRED 작업 요약 설정 가이드 - AI 에이전트 사용","es":"Guía de configuración de sred-work-summary: resumen de tr...","fr":"Guide de configuration de sred-work-summary: résumé de tr...","de":"Konfigurationsleitfaden für sred-work-summary: SRED-Arbei...","pt":"Guia de Configuração do sred-work-summary: Organize Proje...","ru":"ИИ Агент sred-work-summary: Руководство по Настройке для ...","ar":"دليل إعداد سرد العمل sred-work-summary: تنظيم المشاريع با..."},"description":{"en":"Discover how to streamline SRED project documentation with sred-work-summary. Learn how to connect Github, Notion, and Linear for seamless project tracking a...","zh":"使用SRED工作总结AIエージェント，自动收集Github PRs、Notion文档和Linear票据，生成私人Notion文档","ja":"SRED Work Summary AIエージェントを使用して、Github PR、Notionドキュメント、Linearチケットを自動的に収集して、プライベートNotionドキュメントを生成","ko":"SRED 작업 요약 AI 에이전트를 사용하여 Github PR, Notion 문서 및 Linear 티켓을 자동으로 수집하여 개인 Notion 문서를 생성","es":"Automatice el resumen de trabajo de SRED con nuestro agente de inteligencia artificial, que recopila enlaces de Github, Notion y Linear en un documento de No...","fr":"Automatisez le résumé de travail SRED avec notre outil d''intelligence artificielle, qui collecte des liens Github, Notion et Linear dans un document Notion","de":"Automatisieren Sie die SRED-Arbeitszusammenfassung mit unserem KI-Tool, das Links von Github, Notion und Linear in ein Notion-Dokument sammelt","pt":"Descubra como o sred-work-summary ajuda a organizar projetos com links relevantes do Github, Notion e Linear em um documento único","ru":"Узнайте, как ИИ Агент sred-work-summary помогает организовывать проекты с помощью ссылок из Github, Notion и Linear в одном документе","ar":"تعرف على كيفية استخدام سرد العمل sred-work-summary لتنظيم المشاريع باستخدام روابط من Github و Notion و Linear في وثيقة واحدة"},"definition":{"en":"sred-work-summary is a skill that automates the creation of a Notion document grouping relevant links into projects for SRED project documentation purposes.","zh":"SRED工作总结是使用AIエージェント自动收集和文档化SRED项目相关链接的过程","ja":"SRED Work Summaryは、AIエージェントを使用してSREDプロジェクトに関連するリンクを自動的に収集して文書化するプロセス","ko":"SRED 작업 요약은 AI 에이전트를 사용하여 SRED 프로젝트 관련 링크를 자동으로 수집하고 문서화하는 프로세스","es":"El sred-work-summary es un agente de inteligencia artificial que genera un resumen de trabajo de SRED, agrupando enlaces de proyectos en un documento de Notion","fr":"Le sred-work-summary est un outil d''intelligence artificielle qui génère un résumé de travail SRED, en regroupant des liens de projets dans un document Notion","de":"Der sred-work-summary ist ein KI-Tool, das eine SRED-Arbeitszusammenfassung erstellt, indem es Projektlinks in ein Notion-Dokument gruppiert","pt":"O sred-work-summary é uma ferramenta de organização de projetos que reúne links do Github, Notion e Linear","ru":"ИИ Агент sred-work-summary - это инструмент для организации проектов, который собирает ссылки из Github, Notion и Linear","ar":"سرد العمل sred-work-summary هو أداة لتنظيم المشاريع التي تجمع الروابط من Github و Notion و Linear"},"features":{"en":["Collects Github PRs, Notion docs, and Linear tickets from the previous year","Groups links into projects for SRED documentation","Connects to Github using the gh CLI tool or an MCP","Integrates with Notion and Linear using an MCP","Returns a link to a private Notion document containing the grouped project links"],"zh":["自动收集Github PRs、Notion文档和Linear票据","生成私人Notion文档","支持Github、Notion和Linear集成","使用MCP连接Notion和Linear","支持gh CLI工具连接Github"],"ja":["Github PR、Notionドキュメント、Linearチケットの自動収集","プライベートNotionドキュメントの生成","Github、Notion、Linearの統合サポート","MCPを使用してNotionとLinearを接続","gh CLIツールを使用してGithubに接続"],"ko":["Github PR, Notion 문서 및 Linear 티켓 자동 수집","개인 Notion 문서 생성","Github, Notion 및 Linear 통합 지원","MCP를 사용하여 Notion과 Linear 연결","gh CLI 툴을 사용하여 Github에 연결"],"es":["Recopilación de enlaces de Github, Notion y Linear","Uso de MCP para conectar Notion y Linear","Acceso a datos mediante la herramienta CLI de Github","Generación de un resumen de trabajo de SRED en un documento de Notion","Compatibilidad con acceso privado a documentos de Notion"],"fr":["Collecte de liens Github, Notion et Linear","Utilisation de MCP pour connecter Notion et Linear","Accès aux données via l''outil CLI de Github","Génération d''un résumé de travail SRED dans un document Notion","Compatibilité avec l''accès privé aux documents Notion"],"de":["Sammeln von Links von Github, Notion und Linear","Verwendung von MCP, um Notion und Linear zu verbinden","Zugriff auf Daten über die Github-CLI-Tool","Erstellung einer SRED-Arbeitszusammenfassung in einem Notion-Dokument","Kompatibilität mit privatem Zugriff auf Notion-Dokumente"],"pt":["Integração com Github para coletar PRs","Conexão com Notion para criar documentos privados","Compatibilidade com Linear para tickets","Uso do CLI tool ''gh'' para acesso ao Github","Criação de um documento Notion com links organizados"],"ru":["Интеграция с Github для сбора PR","Соединение с Notion для создания приватных документов","Совместимость с Linear для тикетов","Использование инструмента командной строки ''gh'' для доступа к Github","Создание документа Notion со ссылками, организованными в проекты"],"ar":["التكامل مع Github لجمع الطلبات الجديدة","الارتباط مع Notion لإنشاء وثائق خاصة","التوافق مع Linear لتذاكر","استخدام أداة سطر الأوامر ''gh'' للوصول إلى Github","إنشاء وثيقة Notion مع روابط منظمة في المشاريع"]},"keywords":{"en":["how to use sred-work-summary","sred-work-summary setup guide","sred-work-summary alternative","sred-work-summary vs manual documentation","automated SRED project documentation","Github Notion Linear integration","what is sred-work-summary","sred-work-summary install","sred-work-summary for developers"],"zh":["SRED工作总结","AIエージェント","Github PR","Notion文档","Linear票据","MCP","gh CLI工具","SRED项目文档化","自动化文档化"],"ja":["SRED Work Summary","AIエージェント","Github PR","Notionドキュメント","Linearチケット","MCP","gh CLIツール","SREDプロジェクト文書化","自動化文書化"],"ko":["SRED 작업 요약","AI 에이전트","Github PR","Notion 문서","Linear 티켓","MCP","gh CLI 툴","SRED 프로젝트 문서화","자동화 문서화"],"es":["sred-work-summary","agente de inteligencia artificial","resumen de trabajo de SRED","Github","Notion","Linear","MCP","CLI de Github","automatización de tareas","productividad"],"fr":["sred-work-summary","outil d''intelligence artificielle","résumé de travail SRED","Github","Notion","Linear","MCP","CLI de Github","automatisation de tâches","productivité"],"de":["sred-work-summary","KI-Tool","SRED-Arbeitszusammenfassung","Github","Notion","Linear","MCP","Github-CLI-Tool","Aufgabenautomatisierung","Produktivität"],"pt":["sred-work-summary","organização de projetos","Notion","Github","Linear","CLI tool gh","documentação de projetos","ferramentas de desenvolvimento"],"ru":["ИИ Агент sred-work-summary","организация проектов","Notion","Github","Linear","инструмент командной строки gh","документация проектов","инструменты разработки"],"ar":["سرد العمل sred-work-summary","تنظيم المشاريع","Notion","Github","Linear","أداة سطر الأوامر gh","توثيق المشاريع","أدوات التطوير"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Productivity Agents needing advanced project documentation and SRED reporting capabilities.","zh":"非常适合需要高级项目文档和SRED报告功能的生产力代理。","ja":"高度なプロジェクト文書化とSREDレポート機能を必要とする生産性エージェントに最適。","ko":"고급 프로젝트 문서화 및 SRED 보고 기능이 필요한 생산성 에이전트에게 적합합니다.","es":"Perfecto para agentes de productividad que necesitan documentación de proyecto avanzada y capacidades de informes SRED.","fr":"Parfait pour les agents de productivité ayant besoin d''une documentation de projet avancée et de capacités de rapport SRED.","de":"Perfekt für Produktivitätsagenten, die eine erweiterte Projektdokumentation und SRED-Berichtsfunktionen benötigen.","pt":"Perfeito para Agentes de Produtividade que necessitam de documentação de projeto avançada e capacidades de relatórios SRED.","ru":"Идеально подходит для-Agentов Продуктивности, которым необходимы расширенная документация проектов и возможности отчетности SRED.","ar":" مثالي لوكلاء الإنتاجية الذين يحتاجون إلى توثيق متقدم للمشروع وقدرات تقارير SRED."},"recommendation":{"en":"Empowers agents to collect and organize Github PRs, Notion docs, and Linear tickets into private Notion documents using MCP connections and the gh CLI tool, streamlining SRED project documentation and providing a comprehensive work summary.","zh":"赋予代理人使用MCP连接和gh CLI工具收集和组织Github PRs、Notion文档和Linear门票到私人Notion文档的能力，简化SRED项目文档化，并提供全面工作总结。","ja":"MCP接続とgh CLIツールを使用して、GithubのPR、Notionのドキュメント、LinearのチケットをプライベートなNotionドキュメントに収集・整理する機能をエージェントに与え、SREDプロジェクトの文書化を簡素化し、包括的な作業サマリーを提供する。","ko":"MCP 연결 및 gh CLI 도구를 사용하여 Github PR, Notion 문서 및 Linear 티켓을 개인 Notion 문서로 수집 및 구성하여 SRED 프로젝트 문서화를 간소화하고 종합적인 작업 요약을 제공하는 에이전트의 능력을 강화합니다.","es":"Habilita a los agentes a recopilar y organizar solicitudes de extracción de Github, documentos de Notion y tickets de Linear en documentos privados de Notion utilizando conexiones MCP y la herramienta CLI gh, lo que simplifica la documentación del proyecto SRED y proporciona un resumen de trabajo integral.","fr":"Permet aux agents de collecter et d''organiser les demandes d''extraction Github, les documents Notion et les tickets Linear dans des documents Notion privés à l''aide de connexions MCP et de l''outil CLI gh, ce qui rationalise la documentation du projet SRED et fournit un résumé de travail complet.","de":"Ermächtigt die Agenten, Github-PRs, Notion-Dokumente und Linear-Tickets in private Notion-Dokumente mithilfe von MCP-Verbindungen und dem gh-CLI-Tool zu sammeln und zu organisieren, was die SRED-Projektdokumentation rationalisiert und eine umfassende Arbeitszusammenfassung liefert.","pt":"Habilita agentes a coletar e organizar PRs do Github, documentos do Notion e tickets do Linear em documentos privados do Notion usando conexões MCP e a ferramenta CLI gh, racionalizando a documentação do projeto SRED e fornecendo um resumo abrangente do trabalho.","ru":"Наделяет агентов возможностью собирать и организовывать PR Github, документы Notion и тикеты Linear в приватные документы Notion, используя соединения MCP и инструмент CLI gh, оптимизируя документацию проекта SRED и предоставляя всесторонний обзор работы.","ar":"تمكّن الوكلاء من جمع وتنظيم طلبات سحب Github، ووثائق Notion، وتذاكر Linear في مستندات Notion الخاصة باستخدام اتصالات MCP وأداة CLI gh، وتبسيط توثيق مشروع SRED وتقديم ملخص شاملة للعمل."},"useCases":{"en":["Automating SRED project documentation","Generating comprehensive work summaries","Organizing Github PRs and Notion docs into projects"],"zh":["自动化SRED项目文档化","生成全面工作总结","将Github PRs和Notion文档组织到项目中"],"ja":["SREDプロジェクトの文書化を自動化する","包括的な作業サマリーを生成する","GithubのPRとNotionのドキュメントをプロジェクトに整理する"],"ko":["SRED 프로젝트 문서화를 자동화하는 것","포괄적인 작업 요약을 생성하는 것","Github PR 및 Notion 문서를 프로젝트에 구성하는 것"],"es":["Automatización de la documentación de proyectos SRED","Generación de resúmenes de trabajo integrales","Organización de solicitudes de extracción de Github y documentos de Notion en proyectos"],"fr":["Automatisation de la documentation de projet SRED","Génération de résumés de travail complets","Organisation des demandes d''extraction Github et des documents Notion dans des projets"],"de":["Automatisierung der SRED-Projektdokumentation","Erstellung umfassender Arbeitszusammenfassungen","Organisation von Github-PRs und Notion-Dokumenten in Projekte"],"pt":["Automatizar a documentação do projeto SRED","Gerar resumos abrangentes do trabalho","Organizar PRs do Github e documentos do Notion em projetos"],"ru":["Автоматизировать документацию проекта SRED","Генерировать всесторонние обзоры работы","Организовывать PR Github и документы Notion в проекты"],"ar":["تحقيق 자동 لتوثيق مشروع SRED","إيجاد ملخصات شاملة للعمل","تنظيم طلبات سحب Github ووثائق Notion في المشاريع"]},"limitations":{"en":["Requires access to Github, Notion, and Linear","Needs MCP connections for Notion and Linear","Optional: gh CLI tool for Github access"],"zh":["需要访问Github、Notion和Linear","需要MCP连接用于Notion和Linear","可选：gh CLI工具用于Github访问"],"ja":["Github、Notion、Linearへのアクセスが必要","NotionとLinearにはMCP接続が必要","オプション：Githubへのアクセスにgh CLIツールを使用"],"ko":["Github, Notion, Linear에 대한 액세스가 필요합니다","Notion 및 Linear에는 MCP 연결이 필요합니다","선택 사항: Github 액세스에 gh CLI 도구를 사용"],"es":["Requiere acceso a Github, Notion y Linear","Necesita conexiones MCP para Notion y Linear","Opcional: herramienta CLI gh para acceso a Github"],"fr":["Nécessite un accès à Github, Notion et Linear","A besoin de connexions MCP pour Notion et Linear","Optionnel : outil CLI gh pour l''accès à Github"],"de":["Benötigt Zugriff auf Github, Notion und Linear","Benötigt MCP-Verbindungen für Notion und Linear","Optional: gh-CLI-Tool für Github-Zugriff"],"pt":["Requer acesso ao Github, Notion e Linear","Necessita conexões MCP para Notion e Linear","Opcional: ferramenta CLI gh para acesso ao Github"],"ru":["Требует доступа к Github, Notion и Linear","Нужно соединения MCP для Notion и Linear","Необязательно: инструмент CLI gh для доступа к Github"],"ar":["يتطلب الوصول الى Github، Notion، و Linear","يحتاج إلى اتصالات MCP من أجل Notion و Linear","إختياري: أداة CLI gh للوصول الى Github"]},"version":4},"contentHash":"2ccbcb74155d8b53e00584aa3eedfb18615e2e21b58d11280a5659f652039534","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":74}');
