INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/sred-work-summary', 'sred-work-summary', 'getsentry', 'skills', 'official', 'sred-work-summary getsentry skills official tag-production The sred-work-summary skill automates the process of grouping relevant links into projects for SRED documentation, benefiting developers and teams who need to track their work. It collects data from Github PRs, Notion docs, and Linear tickets. SRED工作总结AIエージェント可以自动收集Github PRs、Notion文档和Linear票据，生成私人Notion文档，简化SRED项目文档过程 SRED Work Summary AIエージェントは、Github PR、Notionドキュメント、Linearチケットを自動的に収集して、プライベートNotionドキュメントを生成し、SREDプロジェクトの文書化プロセスを簡素化 SRED 작업 요약 AI 에이전트는 Github PR, Notion 문서 및 Linear 티켓을 자동으로 수집하여 개인 Notion 문서를 생성하여 SRED 프로젝트 문서화 프로세스를 단순화 El agente sred-work-summary recopila enlaces de Github, Notion y Linear para generar un resumen de trabajo de SRED en un documento de Notion. Utiliza MCP y la herramienta CLI de Github para acceder a los datos L''outil sred-work-summary collecte des liens Github, Notion et Linear pour générer un résumé de travail SRED dans un document Notion. Il utilise MCP et l''outil CLI de Github pour accéder aux données Der sred-work-summary-Agent sammelt Links von Github, Notion und Linear, um eine SRED-Arbeitszusammenfassung in einem Notion-Dokument zu erstellen. Er verwendet MCP und die Github-CLI-Tool, um auf die Daten zuzugreifen O sred-work-summary é uma ferramenta que reúne links relevantes do Github, Notion e Linear em projetos documentados ИИ Агент sred-work-summary - это инструмент, который собирает ссылки из Github, Notion и Linear в проекты для документации سرد العمل sred-work-summary هو أداة تجمع الروابط ذات الصلة من Github و Notion و Linear في مشاريع موثقة how to use sred-work-summary sred-work-summary setup guide sred-work-summary alternative sred-work-summary vs manual documentation automated SRED project documentation Github Notion Linear integration what is sred-work-summary sred-work-summary install sred-work-summary for developers SRED工作总结 AIエージェント Github PR Notion文档 Linear票据 MCP gh CLI工具 SRED项目文档化 自动化文档化 Collects Github PRs, Notion docs, and Linear tickets from the previous year Groups links into projects for SRED documentation Connects to Github using the gh CLI tool or an MCP Integrates with Notion and Linear using an MCP Returns a link to a private Notion document containing the grouped project links sred-work-summary is a skill that automates the creation of a Notion document grouping relevant links into projects for SRED project documentation purposes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('google-labs-code/stitch-skills/remotion', 'official', 'google-labs-code', 'stitch-skills', 'google-labs-code/stitch-skills', 'remotion', 2204, 256, 74, '2026-03-06T05:29:41Z', '2026-03-06T05:46:51.432Z', '34fde6f0d4ffe9d1f170f311da2ee91691e1c85018653bddf2eb55d50ccaf27f', '{"id":"google-labs-code/stitch-skills/remotion","name":"remotion","description":{"en":"Remotion generates walkthrough videos from Stitch projects with smooth transitions, zooming, and text overlays, benefiting video production specialists.","zh":"Remotion是一种程序化视频生成工具，用于从Stitch项目创建专业的视频，具有平滑的过渡效果、缩放和文本叠加","ja":"Remotionは、Stitchプロジェクトからスムーズなウォークスルー動画を生成するためのプログラム化動画生成ツールです","ko":"Remotion은 Stitch 프로젝트에서 전문적인 워크스루 비디오를 생성하는 프로그래밍 비디오 생성 도구입니다","es":"Remotion es una herramienta para generar videos de walkthrough desde proyectos Stitch con transiciones suaves y zoom","fr":"Remotion est un outil pour créer des vidéos de démonstration à partir de projets Stitch avec des transitions fluides et un zoom","de":"Remotion ist ein Tool, um Walkthrough-Videos aus Stitch-Projekten mit glatten Übergängen und Zoom zu erstellen","pt":"Remotion é uma ferramenta para criar vídeos de apresentação profissionais a partir de projetos Stitch, com transições suaves e zoom.","ru":"Remotion - это инструмент для создания профессиональных видео-презентаций из проектов Stitch, с гладкими переходами и зумом.","ar":"Remotion هي أداة لإنشاء مقاطع فيديو تعليمية احترافية من مشاريع Stitch، مع انتقالات سلسة وتكبير النص."},"owner":"google-labs-code","repo":"stitch-skills","repoPath":"google-labs-code/stitch-skills","stars":2204,"forks":256,"updatedAt":"2026-03-06T05:29:41Z","topics":[],"skillMd":{"name":"remotion","description":"Generate walkthrough videos from Stitch projects using Remotion with smooth transitions, zooming, and text overlays","bodyPreview":"# Stitch to Remotion Walkthrough Videos\n\nYou are a video production specialist focused on creating engaging walkthrough videos from app designs. You combine Stitch''s screen retrieval capabilities with Remotion''s programmatic video generation to produce smooth, professional presentations.\n\n## Overview\n\nThis skill enables you to create walkthrough videos that showcase app screens with professional transitions, zoom effects, and contextual text overlays. The workflow retrieves screens from Stitch p","body":"# Stitch to Remotion Walkthrough Videos\n\nYou are a video production specialist focused on creating engaging walkthrough videos from app designs. You combine Stitch''s screen retrieval capabilities with Remotion''s programmatic video generation to produce smooth, professional presentations.\n\n## Overview\n\nThis skill enables you to create walkthrough videos that showcase app screens with professional transitions, zoom effects, and contextual text overlays. The workflow retrieves screens from Stitch projects and orchestrates them into a Remotion video composition.\n\n## Prerequisites\n\n**Required:**\n- Access to the Stitch MCP Server\n- Access to the Remotion MCP Server (or Remotion CLI)\n- Node.js and npm installed\n- A Stitch project with designed screens\n\n**Recommended:**\n- Familiarity with Remotion''s video capabilities\n- Understanding of React components (Remotion uses React)\n\n## Retrieval and Networking\n\n### Step 1: Discover Available MCP Servers\n\nRun `list_tools` to identify available MCP servers and their prefixes:\n- **Stitch MCP**: Look for `stitch:` or `mcp_stitch:` prefix\n- **Remotion MCP**: Look for `remotion:` or `mcp_remotion:` prefix\n\n### Step 2: Retrieve Stitch Project Information\n\n1. **Project lookup** (if Project ID is not provided):\n   - Call `[stitch_prefix]:list_projects` with `filter: \"view=owned\"`\n   - Identify target project by title (e.g., \"Calculator App\")\n   - Extract Project ID from `name` field (e.g., `projects/13534454087919359824`)\n\n2. **Screen retrieval**:\n   - Call `[stitch_prefix]:list_screens` with the project ID (numeric only)\n   - Review screen titles to identify all screens for the walkthrough\n   - Extract Screen IDs from each screen''s `name` field\n\n3. **Screen metadata fetch**:\n   For each screen:\n   - Call `[stitch_prefix]:get_screen` with `projectId` and `screenId`\n   - Retrieve:\n     - `screenshot.downloadUrl` — Visual asset for the video\n     - `htmlCode.downloadUrl` — Optional: for extracting text/content\n     - `width`, `height` — Screen dimensions for proper scaling\n     - Screen title and description for text overlays\n\n4. **Asset download**:\n   - Use `web_fetch` or `Bash` with `curl` to download screenshots\n   - Save to a staging directory: `assets/screens/{screen-name}.png`\n   - Organize assets in order of the intended walkthrough flow\n\n### Step 3: Set Up Remotion Project\n\n1. **Check for existing Remotion project**:\n   - Look for `remotion.config.ts` or `package.json` with Remotion dependencies\n   - If exists, use the existing project structure\n\n2. **Create new Remotion project** (if needed):\n   ```bash\n   npm create video@latest -- --blank\n   ```\n   - Choose TypeScript template\n   - Set up in a dedicated `video/` directory\n\n3. **Install dependencies**:\n   ```bash\n   cd video\n   npm install @remotion/transitions @remotion/animated-emoji\n   ```\n\n## Video Composition Strategy\n\n### Architecture\n\nCreate a modular Remotion composition with these components:\n\n1. **`ScreenSlide.tsx`** — Individual screen display component\n   - Props: `imageSrc`, `title`, `description`, `width`, `height`\n   - Features: Zoom-in animation, fade transitions\n   - Duration: Configurable (default 3-5 seconds per screen)\n\n2. **`WalkthroughComposition.tsx`** — Main video composition\n   - Sequences multiple `ScreenSlide` components\n   - Handles transitions between screens\n   - Adds text overlays and annotations\n\n3. **`config.ts`** — Video configuration\n   - Frame rate (default: 30 fps)\n   - Video dimensions (match Stitch screen dimensions or scale appropriately)\n   - Total duration calculation\n\n### Transition Effects\n\nUse Remotion''s `@remotion/transitions` for professional effects:\n\n- **Fade**: Smooth cross-fade between screens\n  ```tsx\n  import {fade} from ''@remotion/transitions/fade'';\n  ```\n\n- **Slide**: Directional slide transitions\n  ```tsx\n  import {slide} from ''@remotion/transitions/slide'';\n  ```\n\n- **Zoom**: Zoom in/out effects for emphasis\n  - Use `spring()` animation for smooth zoom\n  - Apply to important UI elements\n\n### Text Overlays\n\nAdd contextual information using Remotion''s text rendering:\n\n1. **Screen titles**: Display at the top or bottom of each frame\n2. **Feature callouts**: Highlight specific UI elements with animated pointers\n3. **Descriptions**: Fade in descriptive text for each screen\n4. **Progress indicator**: Show current screen position in walkthrough\n\n## Execution Steps\n\n### Step 1: Gather Screen Assets\n\n1. Identify target Stitch project\n2. List all screens in the project\n3. Download screenshots for each screen\n4. Organize in order of walkthrough flow\n5. Create a manifest file (`screens.json`):\n\n```json\n{\n  \"projectName\": \"Calculator App\",\n  \"screens\": [\n    {\n      \"id\": \"1\",\n      \"title\": \"Home Screen\",\n      \"description\": \"Main calculator interface with number pad\",\n      \"imagePath\": \"assets/screens/home.png\",\n      \"width\": 1200,\n      \"height\": 800,\n      \"duration\": 4\n    },\n    {\n      \"id\": \"2\",\n      \"title\": \"History View\",\n      \"description\": \"View of previous calculations\",\n      \"imagePath\": \"assets/screens/history.png\",\n      \"width\": 1200,\n      \"height\": 800,\n      \"duration\": 3\n    }\n  ]\n}\n```\n\n### Step 2: Generate Remotion Components\n\nCreate the video components following Remotion best practices:\n\n1. **Create `ScreenSlide.tsx`**:\n   - Use `useCurrentFrame()` and `spring()` for animations\n   - Implement zoom and fade effects\n   - Add text overlays with proper timing\n\n2. **Create `WalkthroughComposition.tsx`**:\n   - Import screen manifest\n   - Sequence screens with `<Sequence>` components\n   - Apply transitions between screens\n   - Calculate proper timing and offsets\n\n3. **Update `remotion.config.ts`**:\n   - Set composition ID\n   - Configure video dimensions\n   - Set frame rate and duration\n\n**Reference Resources:**\n- Use `resources/screen-slide-template.tsx` as starting point\n- Follow `resources/composition-checklist.md` for completeness\n- Review examples in `examples/walkthrough/` directory\n\n### Step 3: Preview and Refine\n\n1. **Start Remotion Studio**:\n   ```bash\n   npm run dev\n   ```\n   - Opens browser-based preview\n   - Allows real-time editing and refinement\n\n2. **Adjust timing**:\n   - Ensure each screen has appropriate display duration\n   - Verify transitions are smooth\n   - Check text overlay timing\n\n3. **Fine-tune animations**:\n   - Adjust spring configurations for zoom effects\n   - Modify easing functions for transitions\n   - Ensure text is readable at all times\n\n### Step 4: Render Video\n\n1. **Render using Remotion CLI**:\n   ```bash\n   npx remotion render WalkthroughComposition output.mp4\n   ```\n\n2. **Alternative: Use Remotion MCP** (if available):\n   - Call `[remotion_prefix]:render` with composition details\n   - Specify output format (MP4, WebM, etc.)\n\n3. **Optimization options**:\n   - Set quality level (`--quality`)\n   - Configure codec (`--codec h264` or `h265`)\n   - Enable parallel rendering (`--concurrency`)\n\n## Advanced Features\n\n### Interactive Hotspots\n\nHighlight clickable elements or important features:\n\n```tsx\nimport {interpolate, useCurrentFrame} from ''remotion'';\n\nconst Hotspot = ({x, y, label}) => {\n  const frame = useCurrentFrame();\n  const scale = spring({\n    frame,\n    fps: 30,\n    config: {damping: 10, stiffness: 100}\n  });\n  \n  return (\n    <div style={{\n      position: ''absolute'',\n      left: x,\n      top: y,\n      transform: `scale(${scale})`\n    }}>\n      <div className=\"pulse-ring\" />\n      <span>{label}</span>\n    </div>\n  );\n};\n```\n\n### Voiceover Integration\n\nAdd narration to the walkthrough:\n\n1. Generate voiceover script from screen descriptions\n2. Use text-to-speech or record audio\n3. Import audio into Remotion with `<Audio>` component\n4. Sync screen timing with voiceover pacing\n\n### Dynamic Text Extraction\n\nExtract text from Stitch HTML code for automatic annotations:\n\n1. Download `htmlCode.downloadUrl` for each screen\n2. Parse HTML to extract key text elements (headings, buttons, labels)\n3. Generate automatic callouts for important UI elements\n4. Add to composition as timed text overlays\n\n## File Structure\n\n```\nproject/\n├── video/                      # Remotion project directory\n│   ├── src/\n│   │   ├── WalkthroughComposition.tsx\n│   │   ├── ScreenSlide.tsx\n│   │   ├── components/\n│   │   │   ├── Hotspot.tsx\n│   │   │   └── TextOverlay.tsx\n│   │   └── Root.tsx\n│   ├── public/\n│   │   └── assets/\n│   │       └── screens/        # Downloaded Stitch screenshots\n│   │           ├── home.png\n│   │           └── history.png\n│   ├── remotion.config.ts\n│   └── package.json\n├── screens.json                # Screen manifest\n└── output.mp4                  # Rendered video\n```\n\n## Integration with Remotion Skills\n\nRemotion maintains its own Agent Skills that define best practices. Review these for advanced techniques:\n\n- **Repository**: https://github.com/remotion-dev/remotion/tree/main/packages/skills\n- **Installation**: `npx skills add remotion-dev/skills`\n\nKey Remotion skills to leverage:\n- Animation timing and easing\n- Composition architecture patterns\n- Performance optimization\n- Audio synchronization\n\n## Common Patterns\n\n### Pattern 1: Simple Slide Show\n\nBasic walkthrough with fade transitions:\n- 3-5 seconds per screen\n- Cross-fade transitions\n- Bottom text overlay with screen title\n- Progress bar at top\n\n### Pattern 2: Feature Highlight\n\nFocus on specific UI elements:\n- Zoom into specific regions\n- Animated circles/arrows pointing to features\n- Slow-motion emphasis on key interactions\n- Side-by-side before/after comparisons\n\n### Pattern 3: User Flow\n\nShow step-by-step user journey:\n- Sequential screen flow with directional slides\n- Numbered steps overlay\n- Highlight user actions (clicks, taps)\n- Connect screens with animated paths\n\n## Troubleshooting\n\n| Issue | Solution |\n|-------|----------|\n| **Blurry screenshots** | Ensure downloaded images are at full resolution; check `screenshot.downloadUrl` quality settings |\n| **Misaligned text** | Verify screen dimensions match composition size; adjust text positioning based on actual screen size |\n| **Choppy animations** | Increase frame rate to 60fps; use proper spring configurations with appropriate damping |\n| **Remotion build fails** | Check Node version compatibility; ensure all dependencies are installed; review Remotion docs |\n| **Timing feels off** | Adjust duration per screen in manifest; preview in Remotion Studio; test with actual users |\n\n## Best Practices\n\n1. **Maintain aspect ratio**: Use actual Stitch screen dimensions or scale proportionally\n2. **Consistent timing**: Keep screen display duration consistent unless emphasizing specific screens\n3. **Readable text**: Ensure sufficient contrast; use appropriate font sizes; avoid cluttered overlays\n4. **Smooth transitions**: Use spring animations for natural motion; avoid jarring cuts\n5. **Preview thoroughly**: Always preview in Remotion Studio before final render\n6. **Optimize assets**: Compress images appropriately; use efficient formats (PNG for UI, JPG for photos)\n\n## Example Usage\n\n**User prompt:**\n```\nLook up the screens in my Stitch project \"Calculator App\" and build a remotion video \nthat shows a walkthrough of the screens.\n```\n\n**Agent workflow:**\n1. List Stitch projects → Find \"Calculator App\" → Extract project ID\n2. List screens in project → Identify all screens (Home, History, Settings)\n3. Download screenshots for each screen → Save to `assets/screens/`\n4. Create `screens.json` manifest with screen metadata\n5. Generate Remotion components (`ScreenSlide.tsx`, `WalkthroughComposition.tsx`)\n6. Preview in Remotion Studio → Refine timing and transitions\n7. Render final video → `calculator-walkthrough.mp4`\n8. Report completion with video preview link\n\n## Tips for Success\n\n- **Start simple**: Begin with basic fade transitions before adding complex animations\n- **Follow Remotion patterns**: Leverage Remotion''s official skills and documentation\n- **Use manifest files**: Keep screen data organized in JSON for easy updates\n- **Preview frequently**: Use Remotion Studio to catch issues early\n- **Consider accessibility**: Add captions; ensure text is readable; use clear visuals\n- **Optimize for platform**: Match video dimensions to target platform (YouTube, social media, etc.)\n\n## References\n\n- **Stitch Documentation**: https://stitch.withgoogle.com/docs/\n- **Remotion Documentation**: https://www.remotion.dev/docs/\n- **Remotion Skills**: https://www.remotion.dev/docs/ai/skills\n- **Remotion MCP**: https://www.remotion.dev/docs/ai/mcp\n- **Remotion Transitions**: https://www.remotion.dev/docs/transitions\n"},"category":"official","lastSynced":"2026-03-06T05:46:51.432Z","seo":{"title":{"en":"Remotion: Setup Guide for AI Agents","zh":"Remotion_SETUP GUIDE：使用Stitch项目生成专业的视频","ja":"Remotionベストプラクティス：Stitchプロジェクトからスムーズなウォークスルー動画を生成","ko":"Remotion_TUTORIAL：Stitch 프로젝트를 사용하여 전문적인 워크스루 비디오 생성","es":"Guía de configuración de Remotion para videos de walkthrough","fr":"Mise en place de Remotion pour les vidéos de démonstration","de":"Remotion Einrichtungsanleitung für Walkthrough-Videos","pt":"Guia de Configuração Remotion para Vídeos de Apresentação","ru":"Настройка Remotion для создания видео-презентаций ИИ Агенты","ar":"دليل إعداد Remotion لإنشاء مقاطع فيديو تعليمية"},"description":{"en":"Unlock professional video production with Remotion. Learn how to generate walkthrough videos with smooth transitions and text overlays from Stitch projects.","zh":"使用Remotion从Stitch项目生成专业的视频，具有平滑的过渡效果、缩放和文本叠加","ja":"Stitchプロジェクトからスムーズなウォークスルー動画を生成するRemotionの使い方","ko":"Stitch 프로젝트에서 전문적인 워크스루 비디오를 생성하는 Remotion의 기능","es":"Aprende a generar videos de walkthrough desde proyectos Stitch con Remotion, incluyendo transiciones suaves y zoom","fr":"Découvrez comment créer des vidéos de démonstration à partir de projets Stitch avec Remotion, avec des transitions fluides et un zoom","de":"Erfahren Sie, wie Sie Walkthrough-Videos aus Stitch-Projekten mit Remotion erstellen, einschließlich glatter Übergänge und Zoom","pt":"Aprenda a criar vídeos de apresentação profissionais com Remotion e Stitch, incluindo transições suaves e zoom","ru":"Создавайте профессиональные видео-презентации с помощью Remotion и Stitch, включая гладкие переходы и зум ИИ Агенты","ar":"تعلم كيفية إنشاء مقاطع فيديو تعليمية احترافية باستخدام Remotion و Stitch، بما في ذلك الانتقالات السلسة وتكبير النص"},"definition":{"en":"Remotion is a programmatic video generation tool that creates professional presentations from app designs with features like zoom effects and contextual text overlays.","zh":"Remotion是一种用于生成视频的AIエージェント工具","ja":"Remotionは、動画を生成するためのAIエージェントツールです","ko":"Remotion은 비디오를 생성하는 AI 도구입니다","es":"Remotion es una herramienta de generación de video programática para crear videos de walkthrough","fr":"Remotion est un outil de génération de vidéo programmatique pour créer des vidéos de démonstration","de":"Remotion ist ein Tool für die programmgesteuerte Videoerstellung, um Walkthrough-Videos zu erstellen","pt":"Remotion é uma tecnologia de geração de vídeo programático que cria vídeos de apresentação a partir de projetos Stitch.","ru":"Remotion - это технология программной генерации видео, создающая видео-презентации из проектов Stitch.","ar":"Remotion هي تقنية جيل فيديو برمجي لإنشاء مقاطع فيديو تعليمية من مشاريع Stitch."},"features":{"en":["Generates walkthrough videos from Stitch projects","Creates smooth transitions between app screens","Supports zoom effects for enhanced visual appeal","Adds contextual text overlays for clarity","Combines Stitch''s screen retrieval capabilities with Remotion''s video generation","Produces professional presentations with programmatic video generation"],"zh":["从Stitch项目生成视频","平滑的过渡效果","缩放和文本叠加","程序化视频生成","支持Stitch屏幕检索"],"ja":["Stitchプロジェクトから動画を生成","スムーズな遷移効果","ズームとテキストオーバーレイ","プログラム化動画生成","Stitch画面取得のサポート"],"ko":["Stitch 프로젝트에서 비디오 생성","스무스한 전환 효과","줌과 텍스트 오버레이","프로그래밍 비디오 생성","Stitch 화면检索 지원"],"es":["Generación de videos de walkthrough desde proyectos Stitch","Transiciones suaves y zoom","Textos superpuestos contextuales","Integración con Stitch para la recuperación de pantallas","Capacidades de generación de video programática"],"fr":["Génération de vidéos de démonstration à partir de projets Stitch","Transitions fluides et zoom","Textes superposés contextuels","Intégration avec Stitch pour la récupération d''écrans","Capacités de génération de vidéo programmatique"],"de":["Erstellung von Walkthrough-Videos aus Stitch-Projekten","Glatte Übergänge und Zoom","Kontextuelle Textüberlagerungen","Integration mit Stitch für die Bildschirmabfrage","Fähigkeiten zur programmgesteuerten Videoerstellung"],"pt":["Geração de vídeos de apresentação profissionais","Transições suaves e zoom","Inclusão de texto e legendas","Integração com projetos Stitch","Capacidade de criar vídeos personalizados"],"ru":["Создание профессиональных видео-презентаций","Гладкие переходы и зум","Включение текста и субтитров","Интеграция с проектами Stitch","Возможность создания индивидуальных видео"],"ar":["إنشاء مقاطع فيديو تعليمية احترافية","انتقالات سلسة وتكبير النص","إضافة النص والترجمة","التكامل مع مشاريع Stitch","القدرة على إنشاء مقاطع فيديو مخصصة"]},"keywords":{"en":["how to use remotion","remotion alternative","remotion setup guide","what is remotion","remotion vs video editing software","remotion install","stitch to remotion workflow","remotion walkthrough videos","remotion video production"],"zh":["Remotion","Stitch","程序化视频生成","AIエージェント","视频生成工具","专业视频创建","平滑过渡效果","缩放和文本叠加"],"ja":["Remotion","Stitch","プログラム化動画生成","AIエージェント","動画生成ツール","プロフェッショナル動画作成","スムーズな遷移効果","ズームとテキストオーバーレイ"],"ko":["Remotion","Stitch","프로그래밍 비디오 생성","AI 도구","비디오 생성 도구","전문적인 비디오 생성","스무스한 전환 효과","줌과 텍스트 오버레이"],"es":["Remotion","videos de walkthrough","Stitch","generación de video programática","transiciones suaves","zoom","textos superpuestos","herramientas de video","AI Agentes","desarrollo de video"],"fr":["Remotion","vidéos de démonstration","Stitch","génération de vidéo programmatique","transitions fluides","zoom","textes superposés","outils de vidéo","Agents IA","développement de vidéo"],"de":["Remotion","Walkthrough-Videos","Stitch","programmgesteuerte Videoerstellung","glatte Übergänge","Zoom","kontextuelle Textüberlagerungen","Video-Tools","KI-Tools","Video-Entwicklung"],"pt":["remotion","vídeos de apresentação","stitch","transições suaves","zoom","geração de vídeo programático","criação de vídeos profissionais","integração com stitch"],"ru":["remotion","видео-презентации","stitch","гладкие переходы","зум","программная генерация видео","создание профессиональных видео","интеграция с stitch","ИИ Агенты"],"ar":["remotion","مقاطع فيديو تعليمية","stitch","انتقالات سلسة","تكبير النص","جيل فيديو برمجي","إنشاء مقاطع فيديو احترافية","التكامل مع stitch","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Video Production Agents specializing in programmatic app walkthroughs and screen-based presentations.","zh":"非常适合专门从事程序化应用演示和基于屏幕的演示的视频制作代理。","ja":"プログラムによるアプリのウォークスルーと画面ベースのプレゼンテーションを専門とするビデオ制作エージェントに最適です。","ko":"프로그램 방식의 앱 워크스루와 화면 기반 프레ゼンテ이션을 전문으로 하는 비디오制作 에이전트에게 적합합니다.","es":"Ideal para agentes de producción de vídeo especializados en tutoriales de aplicaciones programáticos y presentaciones basadas en pantalla.","fr":"Parfait pour les agents de production vidéo spécialisés dans les démonstrations d''applications programmatiques et les présentations basées sur l''écran.","de":"Perfekt für Video Production Agents, die sich auf programmatische App-Walkthroughs und bildschirmbasierte Präsentationen spezialisieren.","pt":"Ideal para Agentes de Produção de Vídeo especializados em walkthroughs programáticos de aplicativos e apresentações baseadas em tela.","ru":"Идеально подходит для Агентов Видеопроизводства, специализирующихся на программных пошаговых руководствах по приложениям и презентациях на основе экрана.","ar":"مثالي لوكلاء إنتاج الفيديو المتخصصين في جولات التطبيقات البرمجية والعروض التقديمية القائمة على الشاشة."},"recommendation":{"en":"Empowers agents to generate professional walkthrough videos with smooth transitions, zoom effects, and text overlays by combining Stitch''s screen retrieval capabilities with Remotion''s programmatic video generation framework.","zh":"通过将Stitch的屏幕检索能力与Remotion的程序化视频生成框架相结合，赋予代理生成具有平滑过渡、缩放效果和文本覆盖的专业化的应用演示视频的能力。","ja":"Stitchの画面取得機能とRemotionのプログラムによるビデオ生成フレームワークを組み合わせて、スムーズな遷移、ズーム効果、テキストオーバーレイを備えたプロフェッショナルなウォークスルー動画を生成するエージェントを可能にします。","ko":"Stitch의 화면 검색 기능과 Remotion의 프로그램 방식의 비디오 생성 프레임워크를 결합하여, 매끄러운 전환, 확대/축소 효과 및 텍스트 오버레이를 갖춘 전문적인 애플리케이션 데모 비디오를 생성하는 에이전트를 가능하게 합니다.","es":"Permite a los agentes generar vídeos de tutoriales profesionales con transiciones suaves, efectos de zoom y superposiciones de texto mediante la combinación de las capacidades de recuperación de pantalla de Stitch con el framework de generación de vídeo programático de Remotion.","fr":"Permet aux agents de générer des vidéos de démonstration professionnelles avec des transitions fluides, des effets de zoom et des incrustations de texte en combinant les capacités de récupération d''écran de Stitch avec le framework de génération vidéo programmatique de Remotion.","de":"Ermöglicht es Agents, professionelle Walkthrough-Videos mit sanften Übergängen, Zoomeffekten und Texteinblendungen zu generieren, indem die Bildschirmabruf-Fähigkeiten von Stitch mit dem programmatischen Videogenerierungs-Framework von Remotion kombiniert werden.","pt":"Capacita os agentes a gerar vídeos de walkthrough profissionais com transições suaves, efeitos de zoom e sobreposições de texto, combinando as capacidades de recuperação de tela do Stitch com a framework de geração de vídeo programático do Remotion.","ru":"Позволяет агентам создавать профессиональные видео-руководства с плавными переходами, эффектами масштабирования и текстовыми наложениями, объединяя возможности извлечения экрана Stitch с фреймворком программного создания видео Remotion.","ar":"يمكن الوكلاء من إنشاء فيديوهات جولات احترافية بانتقالات سلسة، وتأثيرات تكبير/تصوير، وتراكبات نصية من خلال دمج قدرات استرجاع الشاشة من Stitch مع إطار عمل إنشاء الفيديو البرمجي Remotion."},"useCases":{"en":["Generating app demo videos from Stitch projects","Creating smooth zoom transitions between screen elements","Adding contextual text overlays to screen recordings"],"zh":["从Stitch项目生成应用程序演示视频","在屏幕元素之间创建平滑的缩放过渡","向屏幕录制添加上下文文本覆盖"],"ja":["Stitchプロジェクトからアプリデモ動画を生成する","画面要素間でスムーズなズーム遷移を作成する","画面録画にコンテキストテキストオーバーレイを追加する"],"ko":["Stitch 프로젝트에서 애플리케이션 데모 비디오를 생성하는 것","화면 요소 사이에서 매끄러운 확대/축소 전환을 생성하는 것","화면 녹화에 컨텍스트 텍스트 오버레이를 추가하는 것"],"es":["Generación de vídeos de demostración de aplicaciones a partir de proyectos de Stitch","Creación de transiciones de zoom suaves entre elementos de la pantalla","Adición de superposiciones de texto contextuales a las grabaciones de pantalla"],"fr":["Génération de vidéos de démonstration d''applications à partir de projets Stitch","Création de transitions de zoom fluides entre les éléments de l''écran","Ajout d''incrustations de texte contextuelles aux enregistrements d''écran"],"de":["Generieren von App-Demo-Videos aus Stitch-Projekten","Erstellen sanfter Zoom-Übergänge zwischen Bildschirmelementen","Hinzufügen von kontextbezogenen Texteinblendungen zu Bildschirmaufnahmen"],"pt":["Geração de vídeos de demonstração de aplicativos a partir de projetos Stitch","Criação de transições de zoom suaves entre elementos da tela","Adição de sobreposições de texto contextuais a gravações de tela"],"ru":["Создание демонстрационных видео приложений из проектов Stitch","Создание плавных переходов масштабирования между элементами экрана","Добавление контекстных текстовых наложений к записям экрана"],"ar":["إنشاء فيديوهات عرض توضيحي للتطبيقات من مشاريع Stitch","إنشاء انتقالات تكبير/تصوير سلسة بين عناصر الشاشة","إضافة تراكبات نصية سياقية لتسجيلات الشاشة"]},"limitations":{"en":["Requires Stitch project integration","Dependent on Remotion framework for video generation"],"zh":["需要Stitch项目集成","依赖Remotion框架进行视频生成"],"ja":["Stitchプロジェクトの統合が必要","ビデオ生成にRemotionフレームワークに依存"],"ko":["Stitch 프로젝트 통합이 필요","비디오 생성에 Remotion 프레임워크에 의존"],"es":["Requiere integración con proyectos de Stitch","Depende del framework Remotion para la generación de vídeo"],"fr":["Nécessite une intégration avec des projets Stitch","Dépend du framework Remotion pour la génération vidéo"],"de":["Erfordert die Integration von Stitch-Projekten","Abhängig vom Remotion-Framework für die Videogenerierung"],"pt":["Requer integração com projeto Stitch","Dependente do framework Remotion para geração de vídeo"],"ru":["Требует интеграции с проектом Stitch","Зависит от фреймворка Remotion для создания видео"],"ar":["يتطلب تكاملًا مع مشروع Stitch","يعتمد على إطار عمل Remotion لإنشاء الفيديو"]},"version":4},"contentHash":"34fde6f0d4ffe9d1f170f311da2ee91691e1c85018653bddf2eb55d50ccaf27f","repoEtag":"W/\"bb47617e3029a9b4385327f9dc9702c508cf6c4fbacc7fed320cabd4b144bac3\"","qualityScore":74}');
