INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-labs-code/stitch-skills/remotion', 'remotion', 'google-labs-code', 'stitch-skills', 'official', 'remotion google-labs-code stitch-skills official Remotion generates walkthrough videos from Stitch projects with smooth transitions, zooming, and text overlays, benefiting video production specialists. Remotion是一种程序化视频生成工具，用于从Stitch项目创建专业的视频，具有平滑的过渡效果、缩放和文本叠加 Remotionは、Stitchプロジェクトからスムーズなウォークスルー動画を生成するためのプログラム化動画生成ツールです Remotion은 Stitch 프로젝트에서 전문적인 워크스루 비디오를 생성하는 프로그래밍 비디오 생성 도구입니다 Remotion es una herramienta para generar videos de walkthrough desde proyectos Stitch con transiciones suaves y zoom Remotion est un outil pour créer des vidéos de démonstration à partir de projets Stitch avec des transitions fluides et un zoom Remotion ist ein Tool, um Walkthrough-Videos aus Stitch-Projekten mit glatten Übergängen und Zoom zu erstellen Remotion é uma ferramenta para criar vídeos de apresentação profissionais a partir de projetos Stitch, com transições suaves e zoom. Remotion - это инструмент для создания профессиональных видео-презентаций из проектов Stitch, с гладкими переходами и зумом. Remotion هي أداة لإنشاء مقاطع فيديو تعليمية احترافية من مشاريع Stitch، مع انتقالات سلسة وتكبير النص. how to use remotion remotion alternative remotion setup guide what is remotion remotion vs video editing software remotion install stitch to remotion workflow remotion walkthrough videos remotion video production Remotion Stitch 程序化视频生成 AIエージェント 视频生成工具 专业视频创建 平滑过渡效果 缩放和文本叠加 Generates walkthrough videos from Stitch projects Creates smooth transitions between app screens Supports zoom effects for enhanced visual appeal Adds contextual text overlays for clarity Combines Stitch''s screen retrieval capabilities with Remotion''s video generation Produces professional presentations with programmatic video generation Remotion is a programmatic video generation tool that creates professional presentations from app designs with features like zoom effects and contextual text overlays.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('n8n-io/n8n/n8n-conventions', 'official', 'n8n-io', 'n8n', 'n8n-io/n8n', 'n8n-conventions', 177792, 55472, 74, '2026-03-06T06:12:37Z', '2026-03-06T06:21:54.103Z', '6823cc50d12f4ccbb581f5aad8d38bd8feb0b1201b9db70aee38aa2ec082bf68', '{"id":"n8n-io/n8n/n8n-conventions","name":"n8n-conventions","description":{"en":"This skill serves as a quick reference for n8n development patterns and conventions. It provides developers with immediate access to critical TypeScript rules, error handling protocols, and architectural details, streamlining the workflow automation development process.","zh":"n8n-conventions 提供了 n8n 开发的关键规则和最佳实践，包括 TypeScript 和错误处理。帮助您快速提高开发效率","ja":"n8n-conventions は、n8n 開発の重要なルールとベストプラクティスを提供します。TypeScript とエラーハンドリングを含む開発効率を向上させます","ko":"n8n-conventions는 n8n 개발을 위한 중요 규칙 및 모범 사례를 제공합니다. TypeScript 및 오류 처리를 포함하여 개발 효율성을 향상시킵니다","es":"El skill n8n-conventions proporciona una referencia rápida para patrones de n8n, incluyendo reglas críticas para TypeScript y manejo de errores","fr":"Le skill n8n-conventions offre une référence rapide pour les modèles n8n, y compris des règles critiques pour TypeScript et la gestion des erreurs","de":"Der Skill n8n-Konventionen bietet eine schnelle Referenz für n8n-Muster, einschließlich kritischer Regeln für TypeScript und Fehlerbehandlung","pt":"O n8n-conventions é um guia rápido para padrões n8n, incluindo regras críticas para TypeScript e tratamento de erros","ru":"n8n-conventions - это быстрая справка для шаблонов n8n, включая критические правила для TypeScript и обработки ошибок","ar":"n8n-conventions هو مرجع سريع لانماط n8n، بما في ذلك القواعد الحاسمة ل TypeScript ومعالجة الأخطاء"},"owner":"n8n-io","repo":"n8n","repoPath":"n8n-io/n8n","stars":177792,"forks":55472,"updatedAt":"2026-03-06T06:12:37Z","topics":["ai","apis","automation","cli","data-flow","development","integration-framework","integrations","ipaas","low-code","low-code-platform","mcp","mcp-client","mcp-server","n8n","no-code","self-hosted","typescript","workflow","workflow-automation"],"skillMd":{"name":"n8n-conventions","description":"Quick reference for n8n patterns. Full docs /AGENTS.md","bodyPreview":"# n8n Quick Reference\n\n**📚 Full Documentation:**\n- **General:** `/AGENTS.md` - Architecture, commands, workflows\n- **Frontend:** `/packages/frontend/AGENTS.md` - CSS variables, timing\n\nUse this skill when you need quick reminders on critical patterns.\n\n## Critical Rules (Must Follow)\n\n**TypeScript:**\n- Never `any` → use `unknown`\n- Prefer `satisfies` over `as` (except tests)\n- Shared types in `@n8n/api-types`\n\n**Error Handling:**\n```typescript\nimport { UnexpectedError } from ''n8n-workflow'';\nthr","body":"# n8n Quick Reference\n\n**📚 Full Documentation:**\n- **General:** `/AGENTS.md` - Architecture, commands, workflows\n- **Frontend:** `/packages/frontend/AGENTS.md` - CSS variables, timing\n\nUse this skill when you need quick reminders on critical patterns.\n\n## Critical Rules (Must Follow)\n\n**TypeScript:**\n- Never `any` → use `unknown`\n- Prefer `satisfies` over `as` (except tests)\n- Shared types in `@n8n/api-types`\n\n**Error Handling:**\n```typescript\nimport { UnexpectedError } from ''n8n-workflow'';\nthrow new UnexpectedError(''message'', { extra: { context } });\n// DON''T use deprecated ApplicationError\n```\n\n**Frontend:**\n- Vue 3 Composition API (`<script setup lang=\"ts\">`)\n- CSS variables (never hardcode px) - see `/packages/frontend/AGENTS.md`\n- All text via i18n (`$t(''key'')`)\n- `data-testid` for E2E (single value, no spaces)\n\n**Backend:**\n- Controller → Service → Repository\n- Dependency injection via `@n8n/di`\n- Config via `@n8n/config`\n- Zod schemas for validation\n\n**Testing:**\n- Vitest (unit), Playwright (E2E)\n- Mock external dependencies\n- Work from package directory: `pushd packages/cli && pnpm test`\n\n**Database:**\n- SQLite/PostgreSQL only (app DB)\n- Exception: DB nodes (MySQL Node, etc.) can use DB-specific features\n\n**Commands:**\n```bash\npnpm build > build.log 2>&1  # Always redirect\npnpm typecheck               # Before commit\npnpm lint                    # Before commit\n```\n\n## Key Packages\n\n| Package | Purpose |\n|---------|---------|\n| `packages/cli` | Backend API |\n| `packages/frontend/editor-ui` | Vue 3 frontend |\n| `packages/@n8n/api-types` | Shared types |\n| `packages/@n8n/db` | TypeORM entities |\n| `packages/workflow` | Core interfaces |\n\n## Common Patterns\n\n**Pinia Store:**\n```typescript\nimport { STORES } from ''@n8n/stores'';\nexport const useMyStore = defineStore(STORES.MY_STORE, () => {\n  const state = shallowRef([]);\n  return { state };\n});\n```\n\n**Vue Component:**\n```vue\n<script setup lang=\"ts\">\ntype Props = { title: string };\nconst props = defineProps<Props>();\n</script>\n```\n\n**Service:**\n```typescript\nimport { Service } from ''@n8n/di'';\nimport { Config } from ''@n8n/config'';\n\n@Service()\nexport class MyService {\n  constructor(private readonly config: Config) {}\n}\n```\n\n---\n\n📖 **Need more details?** Read `/AGENTS.md` and `/packages/frontend/AGENTS.md`\n"},"category":"official","lastSynced":"2026-03-06T06:21:54.103Z","seo":{"title":{"en":"n8n-conventions: TypeScript & Error Handling Best Practic...","zh":"n8n-conventions 设置指南：TypeScript 和错误处理最佳实践","ja":"n8n-conventions セットアップガイド：TypeScript とエラーハンドリングのベストプラクティス","ko":"n8n-conventions 설정 가이드: TypeScript 및 오류 처리 최적화","es":"Guía de configuración de n8n-conventions para desarrollad...","fr":"Guide de mise en place des conventions n8n pour développeurs","de":"Einrichtungsleitfaden für n8n-Konventionen für Entwickler","pt":"Guia de Configuração n8n-conventions: Melhores Práticas p...","ru":"ИИ Агенты: Руководство по настройке n8n-conventions для р...","ar":"دليل إعداد n8n-conventions: أفضل الممارسات لالمطورين"},"description":{"en":"Master n8n development patterns. This AI Agent skill provides quick reference for critical TypeScript rules like using `satisfies` over `as`, `UnexpectedErro...","zh":"了解 n8n-conventions 的关键规则和最佳实践，包括 TypeScript 和错误处理。快速提高您的 n8n 开发技能","ja":"n8n-conventions の重要なルールとベストプラクティスを学びましょう。TypeScript とエラーハンドリングを含む n8n 開発スキルを短期間で身につけましょう","ko":"n8n-conventions의 중요 규칙 및 모범 사례를 알아보세요. TypeScript 및 오류 처리를 포함한 n8n 개발 기술을 빠르게 향상시키세요","es":"Aprende las mejores prácticas para trabajos con n8n, incluyendo patrones de TypeScript y manejo de errores","fr":"Découvrez les meilleures pratiques pour travailler avec n8n, y compris les modèles TypeScript et la gestion des erreurs","de":"Erfahren Sie die besten Praktiken für die Arbeit mit n8n, einschließlich TypeScript-Mustern und Fehlerbehandlung","pt":"Aprenda as convenções críticas do n8n, incluindo regras de TypeScript e tratamento de erros, para melhorar suas habilidades de desenvolvimento","ru":"Узнайте критические соглашения n8n, включая правила TypeScript и обработку ошибок, чтобы улучшить свои навыки разработки","ar":"تعرف على الاتفاقيات الحاسمة ل n8n، بما في ذلك قواعد TypeScript ومعالجة الأخطاء، لتحسين مهاراتك في التطوير"},"definition":{"en":"n8n-conventions is an AI Agent skill that acts as a quick reference guide for n8n workflow automation platform development. It provides instant access to mandatory TypeScript patterns, error handling standards, and links to full architectural documentation for developers.","zh":"n8n-conventions 是一个提供 n8n 开发关键规则和最佳实践的参考指南","ja":"n8n-conventions は、n8n 開発の重要なルールとベストプラクティスの参考ガイドです","ko":"n8n-conventions는 n8n 개발을 위한 중요 규칙 및 모범 사례를 제공하는 참조 가이드입니다","es":"n8n-conventions es un conjunto de reglas y patrones para trabajar con la plataforma n8n","fr":"n8n-conventions est un ensemble de règles et de modèles pour travailler avec la plateforme n8n","de":"n8n-Konventionen sind eine Sammlung von Regeln und Mustern für die Arbeit mit der n8n-Plattform","pt":"n8n-conventions é um conjunto de regras e padrões para desenvolvedores que trabalham com a plataforma n8n","ru":"n8n-conventions - это набор правил и соглашений для разработчиков, работающих с платформой n8n","ar":"n8n-conventions هو مجموعة من القواعد والاتفاقيات للمطورين الذين يعملون مع منصة n8n"},"features":{"en":["Quick reference for critical n8n TypeScript patterns, prohibiting the `any` type in favor of `unknown`","Guides on preferring the `satisfies` operator over type assertions (`as`) except in test files","References shared types located in the `@n8n/api-types` package for consistent type definitions","Provides error handling code examples using the `UnexpectedError` class from `n8n-workflow`","Directs users to comprehensive documentation files including `/AGENTS.md` for general architecture and `/packages/frontend/AGENTS.md` for frontend-specific conventions"],"zh":["TypeScript 语法规则：使用 unknown 代替 any","错误处理：使用 UnexpectedError","共享类型：使用 @n8n/api-types","优先使用 satisfies 而不是 as","支持自托管和低代码开发"],"ja":["TypeScript 構文ルール：any の代わりに unknown を使用","エラーハンドリング：UnexpectedError を使用","共有タイプ：@n8n/api-types を使用","satisfies を as より優先して使用","セルフホストとローコード開発のサポート"],"ko":["TypeScript 문법 규칙: unknown을 any 대신 사용","오류 처리: UnexpectedError 사용","공유 타입: @n8n/api-types 사용","satisfies를 as보다 우선하여 사용","자체 호스팅 및 로우코드 개발 지원"],"es":["Reglas críticas para TypeScript, como evitar el uso de ''any'' y preferir ''satisfies'' sobre ''as''","Manejo de errores con n8n-workflow","Uso de tipos compartidos en @n8n/api-types","Compatibilidad con la plataforma n8n y sus herramientas de desarrollo","Soporte para la creación de flujos de trabajo y automatización de procesos"],"fr":["Règles critiques pour TypeScript, telles que l''évitement de ''any'' et la préférence pour ''satisfies'' sur ''as''","Gestion des erreurs avec n8n-workflow","Utilisation de types partagés dans @n8n/api-types","Compatibilité avec la plateforme n8n et ses outils de développement","Prise en charge de la création de flux de travail et d''automatisation de processus"],"de":["Kritische Regeln für TypeScript, wie z.B. das Vermeiden von ''any'' und die Bevorzugung von ''satisfies'' gegenüber ''as''","Fehlerbehandlung mit n8n-workflow","Verwendung von gemeinsamen Typen in @n8n/api-types","Kompatibilität mit der n8n-Plattform und ihren Entwicklungstools","Unterstützung für die Erstellung von Workflows und Automatisierung von Prozessen"],"pt":["Regras críticas para TypeScript, incluindo a preferência por `unknown` em vez de `any`","Tratamento de erros com `UnexpectedError` do `n8n-workflow`","Uso de `satisfies` em vez de `as` (exceto em testes)","Tipos compartilhados em `@n8n/api-types`","Arquitetura e comandos para workflows","CSS variables e temporização para frontend"],"ru":["Критические правила для TypeScript, включая предпочтение `unknown` вместо `any`","Обработка ошибок с `UnexpectedError` из `n8n-workflow`","Использование `satisfies` вместо `as` (кроме тестов)","Общие типы в `@n8n/api-types`","Архитектура и команды для workflows","CSS-переменные и тайминги для frontend"],"ar":["القواعد الحاسمة ل TypeScript، بما في ذلك التفضيل لاستخدام `unknown` بدلاً من `any`","معالجة الأخطاء باستخدام `UnexpectedError` من `n8n-workflow`","استخدام `satisfies` بدلاً من `as` (إلا في الاختبارات)","الأنواع المشتركة في `@n8n/api-types`","هندسة واوامر للعملات","متغيرات CSS وتوقيت للواجهة الأمامية"]},"keywords":{"en":["n8n-conventions skill","n8n TypeScript patterns","how to use n8n UnexpectedError","n8n-conventions vs other n8n skills","n8n satisfies operator guide","install n8n-conventions AI agent","n8n @n8n/api-types usage","n8n workflow automation best practices","n8n-conventions setup guide","what is n8n-conventions"],"zh":["n8n-conventions","TypeScript","错误处理","自托管","低代码开发","n8n 开发","AI 工具","AI 开发"],"ja":["n8n-conventions","TypeScript","エラーハンドリング","セルフホスト","ローコード開発","n8n 開発","AI エージェント","AI 開発"],"ko":["n8n-conventions","TypeScript","오류 처리","자체 호스팅","로우코드 개발","n8n 개발","AI 에이전트","AI 개발"],"es":["n8n-conventions","desarrollo de software","TypeScript","manejo de errores","n8n-workflow","automatización de procesos","Herramientas de desarrollo de n8n","integración de APIs","flujo de trabajo"],"fr":["n8n-conventions","développement de logiciels","TypeScript","gestion des erreurs","n8n-workflow","automatisation de processus","Outils de développement de n8n","intégration d''API","flux de travail"],"de":["n8n-Konventionen","Software-Entwicklung","TypeScript","Fehlerbehandlung","n8n-workflow","Automatisierung von Prozessen","Entwicklungstools von n8n","API-Integration","Workflow"],"pt":["n8n conventions","typescript regras","tratamento de erros n8n","desenvolvimento n8n","n8n workflow","n8n frontend","n8n api types","n8n satisfies","n8n unknown"],"ru":["n8n соглашения","typescript правила","обработка ошибок n8n","разработка n8n","n8n workflow","n8n frontend","n8n api типы","n8n satisfies","n8n unknown"],"ar":["اتفاقيات n8n","قواعد TypeScript","معالجة الأخطاء n8n","تطوير n8n","n8n workflow","n8n frontend","أنواع واجهة برمجة التطبيقات n8n","n8n satisfies","n8n unknown"]}},"agentAnalysis":{"suitability":{"en":"Perfect for TypeScript-based AI Agents needing to adhere to strict n8n coding conventions and patterns.","zh":"适用于需要遵守严格n8n编码约定和模式的TypeScript-based AI Agents。","ja":"n8nの厳格なコーディング規約とパターンに従う必要があるTypeScriptベースのAIエージェントに最適です。","ko":"严格한 n8n 코딩 규칙 및 패턴을 준수해야 하는 TypeScript 기반 AI 에이전트에 적합합니다.","es":"Ideal para AI Agents basados en TypeScript que necesitan adherirse a estrictas convenciones y patrones de codificación de n8n.","fr":"Parfait pour les AI Agents basés sur TypeScript ayant besoin de respecter les conventions et modèles de codification stricts de n8n.","de":"Perfekt für TypeScript-basierte AI Agents, die sich an strenge n8n-Codierungskonventionen und -muster halten müssen.","pt":"Perfeito para Agentes de IA baseados em TypeScript que precisam aderir a convenções e padrões de codificação estritos do n8n.","ru":"Идеально подходит для агентов ИИ на основе TypeScript, которым необходимо соблюдать строгие конвенции и модели кодирования n8n.","ar":"مثالي للوكلاء الذكية القائمة على TypeScript التي تحتاج إلى الالتزام بالاتفاقيات وقوالب الترميز الصارمة الخاصة بن8n."},"recommendation":{"en":"Empowers agents to enforce type safety using TypeScript''s ''unknown'' type and ''satisfies'' operator, while also handling errors with ''n8n-workflow'' and ''UnexpectedError'', ensuring seamless integration with n8n workflows and frontend components using CSS variables and timing.","zh":"赋予代理人使用TypeScript的''unknown''类型和''satisfies''运算符来执行类型安全，同时使用''n8n-workflow''和''UnexpectedError''处理错误，确保与n8n工作流和使用CSS变量和计时的前端组件的无缝集成。","ja":"TypeScriptの''unknown''型と''satisfies''演算子を使用して型セーフティを実施し、''n8n-workflow''と''UnexpectedError''でエラーを処理することでエージェントを強化し、n8nワークフローとCSS変数およびタイミングを使用するフロントエンドコンポーネントとのシームレスな統合を保証する。","ko":"타입스크립트의 ''unknown'' 타입과 ''satisfies'' 연산자를 사용하여 타입 안전성을 강제하고 ''n8n-workflow''와 ''UnexpectedError''로 오류를 처리하여 에이전트를 강화하고 n8n 워크플로 및 CSS 변수와 타이밍을 사용하는 프론트엔드 컴포넌트와의 무결점 통합을 보장합니다.","es":"Permite a los agentes aplicar la seguridad de tipos usando el tipo ''unknown'' y el operador ''satisfies'' de TypeScript, mientras también maneja errores con ''n8n-workflow'' y ''UnexpectedError'', asegurando una integración perfecta con los workflows de n8n y los componentes frontend usando variables CSS y timing.","fr":"Permet aux agents d''appliquer la sécurité des types en utilisant le type ''unknown'' et l''opérateur ''satisfies'' de TypeScript, tout en gérant les erreurs avec ''n8n-workflow'' et ''UnexpectedError'', garantissant une intégration transparente avec les workflows n8n et les composants frontend utilisant des variables CSS et le timing.","de":"Ermöglicht Agents, Typsicherheit durch TypeScripts ''unknown''-Typ und ''satisfies''-Operator durchzusetzen, während gleichzeitig Fehler mit ''n8n-workflow'' und ''UnexpectedError'' behandelt werden, was eine nahtlose Integration mit n8n-Workflows und Frontend-Komponenten unter Verwendung von CSS-Variablen und Timing gewährleistet.","pt":"Habilita os agentes a impor a segurança de tipo usando o tipo ''unknown'' do TypeScript e o operador ''satisfies'', além de lidar com erros com ''n8n-workflow'' e ''UnexpectedError'', garantindo uma integração perfeita com fluxos de trabalho do n8n e componentes da interface do usuário usando variáveis CSS e temporização.","ru":"Наделяет агентов возможностью обеспечить безопасность типа с помощью типа ''unknown'' и оператора ''satisfies'' TypeScript, а также обработку ошибок с помощью ''n8n-workflow'' и ''UnexpectedError'', гарантируя бесшовную интеграцию с рабочими процессами n8n и компонентами frontend с использованием переменных CSS и тайминга.","ar":"تمكّن الوكلاء من فرض سلامة النوع باستخدام نوع ''unknown'' من TypeScript وعامل ''satisfies'' ، بالإضافة إلى التعامل مع الأخطاء باستخدام ''n8n-workflow'' و ''UnexpectedError'' ، مما يضمن التكامل السلس مع سير عمل n8n ومكونات الواجهة الأمامية باستخدام متغيرات CSS والتنظيم الزمني."},"useCases":{"en":["Enforcing strict TypeScript typing for n8n workflows","Handling errors with ''n8n-workflow'' and ''UnexpectedError''","Implementing shared types from ''@n8n/api-types'' for consistent API interactions"],"zh":["执行n8n工作流的严格TypeScript类型检查","使用''n8n-workflow''和''UnexpectedError''处理错误","从''@n8n/api-types''实现共享类型以实现一致的API交互"],"ja":["n8nワークフローの厳格なTypeScript型チェックの実施","''n8n-workflow''と''UnexpectedError''でエラーを処理","''@n8n/api-types''から共有型を実装して一貫したAPI相互作用を実現"],"ko":["n8n 워크플로의 엄격한 타입스크립트 유형 확인 실행","''n8n-workflow''와 ''UnexpectedError''로 오류 처리","''@n8n/api-types''에서 공유 유형을 구현하여 일관된 API 상호 작용을 구현"],"es":["Aplicar tipado estricto de TypeScript para workflows de n8n","Manejar errores con ''n8n-workflow'' y ''UnexpectedError''","Implementar tipos compartidos desde ''@n8n/api-types'' para interacciones API consistentes"],"fr":["Appliquer un typage TypeScript strict pour les workflows n8n","Gérer les erreurs avec ''n8n-workflow'' et ''UnexpectedError''","Implémenter des types partagés depuis ''@n8n/api-types'' pour des interactions API cohérentes"],"de":["Durchsetzung strenger TypeScript-Typisierung für n8n-Workflows","Fehlerbehandlung mit ''n8n-workflow'' und ''UnexpectedError''","Implementierung gemeinsamer Typen aus ''@n8n/api-types'' für konsistente API-Interaktionen"],"pt":["Impor tipagem estrita do TypeScript para fluxos de trabalho do n8n","Lidar com erros com ''n8n-workflow'' e ''UnexpectedError''","Implementar tipos compartilhados de ''@n8n/api-types'' para interações de API consistentes"],"ru":["Внедрение строгой типизации TypeScript для рабочих процессов n8n","Обработка ошибок с помощью ''n8n-workflow'' и ''UnexpectedError''","Реализация общих типов из ''@n8n/api-types'' для последовательных взаимодействий с API"],"ar":["إلزام الترميز الصارم من TypeScript لسير عمل n8n","التعامل مع الأخطاء باستخدام ''n8n-workflow'' و ''UnexpectedError''","تنفيذ أنواع مشتركة من ''@n8n/api-types'' لتفاعلات API المتسقة"]},"limitations":{"en":["Requires knowledge of TypeScript and n8n architecture","Limited to n8n-specific workflows and frontend components"],"zh":["需要TypeScript和n8n架构的知识","仅限n8n特定的工作流和前端组件"],"ja":["TypeScriptとn8nアーキテクチャの知識が必要","n8n特有のワークフローとフロントエンドコンポーネントに限定"],"ko":["타입스크립트와 n8n 아키텍처에 대한 지식이 필요","n8n 특정 워크플로 및 프론트엔드 컴포넌트로 제한"],"es":["Requiere conocimiento de TypeScript y la arquitectura de n8n","Limitado a workflows y componentes frontend específicos de n8n"],"fr":["Nécessite une connaissance de TypeScript et de l''architecture n8n","Limité aux workflows spécifiques à n8n et aux composants frontend"],"de":["Erfordert Kenntnisse in TypeScript und der n8n-Architektur","Beschränkt auf n8n-spezifische Workflows und Frontend-Komponenten"],"pt":["Exige conhecimento de TypeScript e arquitetura do n8n","Limitado a fluxos de trabalho e componentes da interface do usuário específicos do n8n"],"ru":["Требует знания TypeScript и архитектуры n8n","Ограничен рабочими процессами и компонентами frontend, специфичными для n8n"],"ar":["يتطلب معرفة باللغة TypeScript وهندسة n8n","محدود بسير عمل ومكونات الواجهة الأمامية الخاصة بن8n"]},"version":4},"contentHash":"6823cc50d1