INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('n8n-io/n8n/n8n-conventions', 'n8n-conventions', 'n8n-io', 'n8n', 'official', 'n8n-conventions n8n-io n8n official ai apis automation cli data-flow development integration-framework integrations ipaas low-code low-code-platform mcp mcp-client mcp-server n8n no-code self-hosted typescript workflow workflow-automation This skill serves as a quick reference for n8n development patterns and conventions. It provides developers with immediate access to critical TypeScript rules, error handling protocols, and architectural details, streamlining the workflow automation development process. n8n-conventions 提供了 n8n 开发的关键规则和最佳实践，包括 TypeScript 和错误处理。帮助您快速提高开发效率 n8n-conventions は、n8n 開発の重要なルールとベストプラクティスを提供します。TypeScript とエラーハンドリングを含む開発効率を向上させます n8n-conventions는 n8n 개발을 위한 중요 규칙 및 모범 사례를 제공합니다. TypeScript 및 오류 처리를 포함하여 개발 효율성을 향상시킵니다 El skill n8n-conventions proporciona una referencia rápida para patrones de n8n, incluyendo reglas críticas para TypeScript y manejo de errores Le skill n8n-conventions offre une référence rapide pour les modèles n8n, y compris des règles critiques pour TypeScript et la gestion des erreurs Der Skill n8n-Konventionen bietet eine schnelle Referenz für n8n-Muster, einschließlich kritischer Regeln für TypeScript und Fehlerbehandlung O n8n-conventions é um guia rápido para padrões n8n, incluindo regras críticas para TypeScript e tratamento de erros n8n-conventions - это быстрая справка для шаблонов n8n, включая критические правила для TypeScript и обработки ошибок n8n-conventions هو مرجع سريع لانماط n8n، بما في ذلك القواعد الحاسمة ل TypeScript ومعالجة الأخطاء n8n-conventions skill n8n TypeScript patterns how to use n8n UnexpectedError n8n-conventions vs other n8n skills n8n satisfies operator guide install n8n-conventions AI agent n8n @n8n/api-types usage n8n workflow automation best practices n8n-conventions setup guide what is n8n-conventions n8n-conventions TypeScript 错误处理 自托管 低代码开发 n8n 开发 AI 工具 AI 开发 Quick reference for critical n8n TypeScript patterns, prohibiting the `any` type in favor of `unknown` Guides on preferring the `satisfies` operator over type assertions (`as`) except in test files References shared types located in the `@n8n/api-types` package for consistent type definitions Provides error handling code examples using the `UnexpectedError` class from `n8n-workflow` Directs users to comprehensive documentation files including `/AGENTS.md` for general architecture and `/packages/frontend/AGENTS.md` for frontend-specific conventions n8n-conventions is an AI Agent skill that acts as a quick reference guide for n8n workflow automation platform development. It provides instant access to mandatory TypeScript patterns, error handling standards, and links to full architectural documentation for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/extract-errors', 'official', 'facebook', 'react', 'facebook/react', 'extract-errors', 243646, 50653, 73, '2026-03-06T05:37:42Z', '2026-03-06T06:10:00.885Z', '70d61d42e5b5806e1eeb0ef2380b2f3d4d87237e848128e7da35929f78813e5f', '{"id":"facebook/react/extract-errors","name":"extract-errors","description":{"en":"The extract-errors skill helps React developers manage error codes by running yarn extract-errors and reporting new errors. It ensures error codes are up to date.","zh":"extract-errors 是一个用于 React 的错误代码提取工具，帮助开发者保持错误代码的更新","ja":"extract-errors は React 用のエラーコード抽出ツールで、エラーコードを最新の状態に保つのに役立ちます","ko":"extract-errors는 React용 오류 코드 추출 도구로 오류 코드를 최신 상태로 유지하는 데 도움이 됩니다","pt":"O extract-errors é uma ferramenta para gerenciar códigos de erro em projetos React, permitindo a execução de yarn extract-errors para relatar novos erros.","ru":"ИИ Агент extract-errors - это инструмент для управления кодами ошибок в проектах React, позволяющий выполнять yarn extract-errors для сообщения о новых ошибках.","ar":"extract-errors هي أداة لإدارة أكواد الأخطاء في مشاريع React، مما يسمح بتشغيل yarn extract-errors لتقرير أخطاء جديدة."},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"extract-errors","description":"Use when adding new error messages to React, or seeing unknown error code warnings.","bodyPreview":"# Extract Error Codes\n\n## Instructions\n\n1. Run `yarn extract-errors`\n2. Report if any new errors need codes assigned\n3. Check if error codes are up to date","body":"# Extract Error Codes\n\n## Instructions\n\n1. Run `yarn extract-errors`\n2. Report if any new errors need codes assigned\n3. Check if error codes are up to date\n"},"category"