INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/extract-errors', 'extract-errors', 'facebook', 'react', 'official', 'extract-errors facebook react official declarative frontend javascript library react ui The extract-errors skill helps React developers manage error codes by running yarn extract-errors and reporting new errors. It ensures error codes are up to date. extract-errors 是一个用于 React 的错误代码提取工具，帮助开发者保持错误代码的更新 extract-errors は React 用のエラーコード抽出ツールで、エラーコードを最新の状態に保つのに役立ちます extract-errors는 React용 오류 코드 추출 도구로 오류 코드를 최신 상태로 유지하는 데 도움이 됩니다 O extract-errors é uma ferramenta para gerenciar códigos de erro em projetos React, permitindo a execução de yarn extract-errors para relatar novos erros. ИИ Агент extract-errors - это инструмент для управления кодами ошибок в проектах React, позволяющий выполнять yarn extract-errors для сообщения о новых ошибках. extract-errors هي أداة لإدارة أكواد الأخطاء في مشاريع React، مما يسمح بتشغيل yarn extract-errors لتقرير أخطاء جديدة. how to use extract-errors extract-errors setup guide error code management in React yarn extract-errors command extract-errors alternative extract-errors vs error handling libraries what is extract-errors extract-errors install React error code best practices extract-errors React 错误代码 错误代码提取 declarative 编程 前端开发 JavaScript 库 AIエージェント React 项目 Runs yarn extract-errors command to extract error codes Reports new errors that need codes assigned Checks if error codes are up to date Supports React applications Utilizes declarative frontend approach Integrates with JavaScript and UI libraries extract-errors is a skill that assists in extracting and managing error codes in React applications using yarn extract-errors command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/fix', 'official', 'facebook', 'react', 'facebook/react', 'fix', 243646, 50653, 73, '2026-03-06T05:37:42Z', '2026-03-06T06:11:55.904Z', 'a2edb0e8fb758efe98df7a4bc2bab1d82e46b1b40a5ad9cd45b60f44730e7c32', '{"id":"facebook/react/fix","name":"fix","description":{"en":"The fix skill helps frontend developers resolve lint errors and formatting issues in JavaScript and React projects, ensuring smooth CI pipelines.","zh":"Fix AI工具用于修复代码格式化和Lint错误，确保代码质量和CI检查通过","ja":"Fix AIエージェントはコード整形とLintエラーの修復に使用され、コード品質とCIチェックの通過を確保する","ko":"Fix AI 에이전트는 코드 형식화와 Lint 오류 수정에 사용되며 코드 품질과 CI 검사 통과를 보장합니다","es":"Fix es una herramienta para solucionar errores de lint y formato en código JavaScript, especialmente útil antes de comprometer cambios","fr":"Fix est un outil pour résoudre les erreurs de lint et de format dans le code JavaScript, particulièrement utile avant de committer des modifications","de":"Fix ist ein Werkzeug zur Behebung von Lint- und Formatierungsfehlern in JavaScript-Code, insbesondere nützlich vor dem Committen von Änderungen","pt":"O Fix é uma ferramenta para corrigir erros de lint e formatação no código, garantindo a qualidade e a consistência","ru":"ИИ Агент Fix - это инструмент для исправления ошибок lint и форматирования кода, обеспечивающий качество и согласованность","ar":"أداة الإصلاح هي أداة لتصحيح أخطاء لينت وتحسين تنسيق الكود، لضمان الجودة والاتساق"},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"fix","description":"Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI.","bodyPreview":"# Fix Lint and Formatting\n\n## Instructions\n\n1. Run `yarn prettier` to fix formatting\n2. Run `yarn linc` to check for remaining lint issues\n3. Report any remaining manual fixes needed\n\n## Common Mistakes\n\n- **Running prettier on wrong files** - `yarn prettier` only formats changed files\n- **Ignoring linc errors** - These will fail CI, fix them before committing","body":"# Fix Lint and Formatting\n\n## Instructions\n\n1. Run `yarn prettier` to fix formatting\n2. Run `yarn linc` to check for remaining lint issues\n3. Report any remaining manual fixes needed\n\n## Common Mistakes\n\n- **Running prettier on wrong files** - `yarn prettier` only formats changed files\n- **Ignoring linc errors** - These will fail CI, fix them before committing\n"},"category":"official","lastSynced":"2026-03-06T06:11:55.904Z","seo":{"title":{"en":"fix: Lint and Formatting Setup Guide | AI Agent Skill","zh":"Fix AI工具：代码格式化和Lint错误修复指南","ja":"Fix AIエージェント：コード整形とLintエラー修復ガイド","ko":"Fix AI 에이전트: 코드 형식화와 Lint 오류 수정 가이드","es":"Guía de configuración de fix para errores de lint y formato","fr":"Guide de configuration de fix pour les erreurs de lint et...","de":"Konfigurationsleitfaden für fix zur Behebung von Lint- un...","pt":"Guia de Configuração do Fix: Corrigindo Erros de Lint e F...","ru":"ИИ Агент Fix: Руководство по Исправлению Ошибок Lint и Фо...","ar":"إعداد أداة الإصلاح: إصلاح أخطاء لينت وتحسين التنسيق"},"description":{"en":"Discover how to fix lint errors and formatting issues with yarn prettier and yarn linc, ensuring CI success - get started now!","zh":"使用Fix AI工具快速修复代码格式化和Lint错误，确保代码通过CI检查","ja":"Fix AIエージェントを使用してコード整形とLintエラーを修復し、CIチェックに合格する","ko":"Fix AI 에이전트를 사용하여 코드 형식화와 Lint 오류를 수정하고 CI 검사에合格하십시오","es":"Aprende a utilizar fix para solucionar errores de lint y formato en tu código JavaScript y asegurarte de que pasa la integración continua","fr":"Découvrez comment utiliser fix pour résoudre les erreurs de lint et de format dans votre code JavaScript et vous assurer qu''il passe l''intégration continue","de":"Erfahren Sie, wie Sie fix verwenden, um Lint- und Formatierungsfehler in Ihrem JavaScript-Code zu beheben und sicherzustellen, dass er die kontinuierliche In...","pt":"Aprenda a usar o Fix para corrigir erros de lint e formatação no seu código, garantindo a aprovação do CI","ru":"Узнайте, как использовать ИИ Агент Fix для исправления ошибок lint и форматирования, чтобы обеспечить прохождение CI","ar":"تعرف على كيفية استخدام أداة الإصلاح لتصحيح أخطاء لينت وتحسين تنسيق الكود، لضمان прохождение الاختبار المتماسك"},"definition":{"en":"fix is a technical skill that resolves lint errors, formatting issues, and ensures code quality in declarative, frontend, and UI projects","zh":"Fix AI工具是一种用于修复代码格式化和Lint错误的工具","ja":"Fix AIエージェントはコード整形とLintエラーの修復を行うツールです","ko":"Fix AI 에이전트는 코드 형식화와 Lint 오류 수정을 수행하는 도구입니다","es":"Fix es una herramienta de línea de comandos que utiliza yarn prettier y yarn linc para corregir errores de formato y lint","fr":"Fix est un outil en ligne de commande qui utilise yarn prettier et yarn linc pour corriger les erreurs de format et de lint","de":"Fix ist ein Kommandozeilenwerkzeug, das yarn prettier und yarn linc verwendet, um Formatierungs- und Lint-Fehler zu beheben","pt":"O Fix é uma ferramenta de correção de erros de lint e formatação para código","ru":"ИИ Агент Fix - это инструмент для исправления ошибок lint и форматирования кода","ar":"أداة الإصلاح هي أداة لتصحيح أخطاء لينت وتحسين تنسيق الكود"},"features":{"en":["Runs yarn prettier to fix formatting issues in changed files","Executes yarn linc to check for remaining lint issues","Reports manual fixes needed for complete code quality assurance","Supports declarative, frontend, and UI development with JavaScript and React","Ensures code passes CI checks for seamless project deployment"],"zh":["运行yarn prettier修复代码格式化","运行yarn linc检查剩余的Lint错误","报告需要手动修复的错误","支持React和JavaScript代码","确保代码通过CI检查"],"ja":["yarn prettierを実行してコード整形を修復","yarn lincを実行して残りのLintエラーをチェック","手動で修復する必要があるエラーを報告","ReactとJavaScriptコードをサポート","コードがCIチェックに合格することを保証"],"ko":["yarn prettier 실행하여 코드 형식화 수정","yarn linc 실행하여 남은 Lint 오류 확인","수동으로 수정해야 하는 오류 보고","React와 JavaScript 코드 지원","코드가 CI 검사에合格하는 것을 보장"],"es":["Utiliza yarn prettier para corregir errores de formato","Utiliza yarn linc para detectar errores de lint","Informa sobre los errores de lint restantes que requieren correcciones manuales","Ayuda a asegurarse de que el código pasa la integración continua","Es especialmente útil antes de comprometer cambios"],"fr":["Utilise yarn prettier pour corriger les erreurs de format","Utilise yarn linc pour détecter les erreurs de lint","Signale les erreurs de lint restantes qui nécessitent des corrections manuelles","Aide à s''assurer que le code passe l''intégration continue","Est particulièrement utile avant de committer des modifications"],"de":["Verwendet yarn prettier, um Formatierungsfehler zu beheben","Verwendet yarn linc, um Lint-Fehler zu erkennen","Berichtet über verbleibende Lint-Fehler, die manuelle Korrekturen erfordern","Hilft dabei, sicherzustellen, dass der Code die kontinuierliche Integration besteht","Ist insbesondere nützlich vor dem Committen von Änderungen"],"pt":["Correção de erros de lint com yarn linc","Formatação de código com yarn prettier","Verificação de erros antes do commit","Integração com React e bibliotecas JavaScript","Suporte a formatação de código em arquivo"],"ru":["Исправление ошибок lint с помощью yarn linc","Форматирование кода с помощью yarn prettier","Проверка ошибок перед коммитом","Интеграция с React и библиотеками JavaScript","Поддержка форматирования кода в файле"],"ar":["تصحيح أخطاء لينت باستخدام yarn linc","تنسيق الكود باستخدام yarn prettier","فحص الأخطاء قبل الالتزام","التكامل مع React و مكتبات JavaScript","دعم تنسيق الكود في الملف"]},"keywords":{"en":["how to use fix","fix setup guide","yarn prettier tutorial","lint error resolution","fix vs eslint","fix install guide","what is fix","fix for react developers","javascript code formatting","ci pipeline optimization"],"zh":["Fix AI工具","代码格式化","Lint错误修复","CI检查","React代码","JavaScript代码","yarn prettier","yarn linc"],"ja":["Fix AIエージェント","コード整形","Lintエラー修復","CIチェック","Reactコード","JavaScriptコード","yarn prettier","yarn linc"],"ko":["Fix AI 에이전트","코드 형식화","Lint 오류 수정","CI 검사","React 코드","JavaScript 코드","yarn prettier","yarn linc"],"es":["herramientas de desarrollo","fix errores de lint","formato de código","yarn prettier","yarn linc","integración continua","desarrollo de software","herramientas de línea de comandos"],"fr":["outils de développement","corriger les erreurs de lint","formatage de code","yarn prettier","yarn linc","intégration continue","développement de logiciels","outils en ligne de commande"],"de":["Entwicklungstools","Beheben von Lint-Fehlern","Code-Formatierung","yarn prettier","yarn linc","Kontinuierliche Integration","Software-Entwicklung","Kommandozeilenwerkzeuge"],"pt":["fix lint","formatação de código","yarn prettier","yarn linc","react","javascript","correção de erros","qualidade de código","integração contínua"],"ru":["исправление ошибок lint","форматирование кода","yarn prettier","yarn linc","react","javascript","коррекция ошибок","качество кода","непрерывная интеграция"],"ar":["إصلاح أخطاء لينت","تنسيق الكود","yarn prettier","yarn linc","react","javascript","تصحيح الأخطاء","جودة الكود","التكامل المستمر"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing automated linting and formatting fixes.","zh":"适合需要自动化 linting 和格式化修复的代码分析代理。","ja":"コード分析エージェントが自動化されたlintingとフォーマット修正を必要とする場合に最適です。","ko":"자동화된 linting 및 형식 지정 수정이 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan revisión y corrección de formato automatizadas.","fr":"Parfait pour les agents d''analyse de code nécessitant une analyse et une correction de formatage automatisées.","de":"Perfekt für Code-Analyse-Agents, die eine automatisierte Überprüfung und Formatierungsberichtigung benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de linting automatizado e correções de formatação.","ru":"Идеально для агентов анализа кода, которым необходим автоматизированный linting и исправление форматирования.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى تنسيق وتحديثات تصحيح آلي."},"recommendation":{"en":"Empowers agents to enforce coding standards and pass CI checks by running `yarn prettier` for formatting and `yarn linc` for linting, ensuring consistent code quality and reducing manual fixes.","zh":"通过运行 `yarn prettier` 进行格式化和运行 `yarn linc` 进行 linting，赋予代理执行编码标准和通过 CI 检查的能力，确保一致的代码质量并减少手动修复。","ja":"コードの整形には `yarn prettier` 、Lintには `yarn linc` を実行することで、エージェントにコーディング規約を適用し、CI チェックに合格する能力を与え、コード品質を一貫して維持し、手動での修正を減らします。","ko":"코드 형식을 지정하는 데 `yarn prettier`를 실행하고 린트를 위해 `yarn linc`를 실행하여 에이전트가 코딩 표준을 적용하고 CI 체크를 통과 할 수 있도록 하여 코드 품질을 일관되게 유지하고 수동 수정을 줄입니다.","es":"Habilita a los agentes a hacer cumplir los estándares de codificación y aprobar las comprobaciones de CI ejecutando `yarn prettier` para el formato y `yarn linc` para la revisión, garantizando una calidad de código coherente y reduciendo las correcciones manuales.","fr":"Permet aux agents de faire respecter les normes de codage et de passer les vérifications de CI en exécutant `yarn prettier` pour le formatage et `yarn linc` pour la vérification, garantissant une qualité de code cohérente et réduisant les corrections manuelles.","de":"Ermächtigt die Agenten, die Kodierungsstandards durchzusetzen und die CI-Prüfungen zu bestehen, indem sie `yarn prettier` für das Formatieren und `yarn linc` für die Überprüfung ausführen, um eine konsistente Codequalität sicherzustellen und manuelle Korrekturen zu reduzieren.","pt":"Habilita os agentes a impor padrões de codificação e passar nas verificações de CI executando `yarn prettier` para formatação e `yarn linc` para linting, garantindo uma qualidade de código consistente e reduzindo os reparos manuais.","ru":"Наделяет агентов возможностью обеспечивать соблюдение стандартов кодирования и прохождения проверок CI путем запуска `yarn prettier` для форматирования и `yarn linc` для linting, обеспечивая последовательное качество кода и уменьшая ручные исправления.","ar":"يمنح الوكلاء القدرة على فرض معايير الترميز والنجاح في عمليات التحقق من CI من خلال تشغيل `yarn prettier` لتنسيق الشفرة و `yarn linc` للكشف عن الأخطاء، مما يضمن جودة الشفرة المتسقة وتقليل الإصلاحات اليدوية."},"useCases":{"en":["Automating code formatting with `yarn prettier`","Debugging lint issues with `yarn linc`","Ensuring CI/CD pipeline compliance"],"zh":["使用 `yarn prettier` 自动化代码格式化","使用 `yarn linc` 调试 lint 问题","确保 CI/CD 流水线合规性"],"ja":["`yarn prettier` を使用したコードの自動整形","`yarn linc` を使用した Lint の問題のデバッグ","CI/CD パイプラインの準拠性の確保"],"ko":["`yarn prettier`를 사용한 코드 자동 형식화","`yarn linc`를 사용한 린트 문제 디버깅","CI/CD 파이프라인 준수 보장"],"es":["Automatización del formato de código con `yarn prettier`","Depuración de problemas de revisión con `yarn linc`","Garantía del cumplimiento de la canalización de CI/CD"],"fr":["Automatisation du formatage de code avec `yarn prettier`","Débogage des problèmes de vérification avec `yarn linc`","Assurance du respect de la canalisation de CI/CD"],"de":["Automatisierung der Codeformatierung mit `yarn prettier`","Fehlerbehebung bei Überprüfungsproblemen mit `yarn linc`","Sicherstellung der Einhaltung der CI/CD-Pipeline"],"pt":["Automatizar a formatação de código com `yarn prettier`","Depurar problemas de lint com `yarn linc`","Garantir conformidade com o pipeline CI/CD"],"ru":["Автоматизировать форматирование кода с помощью `yarn prettier`","Отладить проблемы lint с помощью `yarn linc`","Обеспечить соблюдение конвейера CI/CD"],"ar":["توفير تنسيق الشفرة تلقائيًا باستخدام `yarn prettier`","تصحيح مشاكل الكشف عن الأخطاء باستخدام `yarn linc`","ضمان امتثال трубة CI/CD"]},"limitations":{"en":["Requires yarn package manager","Limited to JavaScript projects"],"zh":["需要 yarn 包管理器","仅限于 JavaScript 项目"],"ja":["yarn パッケージマネージャーが必要","JavaScript プロジェクトのみ"],"ko":["yarn 패키지 관리자 필요","JavaScript 프로젝트만 해당"],"es":["Requiere el administrador de paquetes yarn","Limitado a proyectos de JavaScript"],"fr":["Nécessite le gestionnaire de paquets yarn","Limité aux projets JavaScript"],"de":["Benötigt den Paket-Manager yarn","Begrenzt auf JavaScript-Projekte"],"pt":["Requer gerenciador de pacotes yarn","Limitado a projetos JavaScript"],"ru":["Требуется менеджер пакетов yarn","Ограничен проектами JavaScript"],"ar":["يتطلب مدير حزم yarn","محدود بمشاريع JavaScript"]},"version":4},"contentHash":"a2edb0e8fb758efe98df7a4bc2bab1d82e46b1b40a5ad9cd45b60f44730e7c32","repoEtag":"W/\"7e366b67cb3bf6b132fa9e4b13c8e3f5f4a0c4e37519cb121164846325962090\"","qualityScore":73}');
