INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/fix', 'fix', 'facebook', 'react', 'official', 'fix facebook react official declarative frontend javascript library react ui The fix skill helps frontend developers resolve lint errors and formatting issues in JavaScript and React projects, ensuring smooth CI pipelines. Fix AI工具用于修复代码格式化和Lint错误，确保代码质量和CI检查通过 Fix AIエージェントはコード整形とLintエラーの修復に使用され、コード品質とCIチェックの通過を確保する Fix AI 에이전트는 코드 형식화와 Lint 오류 수정에 사용되며 코드 품질과 CI 검사 통과를 보장합니다 Fix es una herramienta para solucionar errores de lint y formato en código JavaScript, especialmente útil antes de comprometer cambios Fix est un outil pour résoudre les erreurs de lint et de format dans le code JavaScript, particulièrement utile avant de committer des modifications Fix ist ein Werkzeug zur Behebung von Lint- und Formatierungsfehlern in JavaScript-Code, insbesondere nützlich vor dem Committen von Änderungen O Fix é uma ferramenta para corrigir erros de lint e formatação no código, garantindo a qualidade e a consistência ИИ Агент Fix - это инструмент для исправления ошибок lint и форматирования кода, обеспечивающий качество и согласованность أداة الإصلاح هي أداة لتصحيح أخطاء لينت وتحسين تنسيق الكود، لضمان الجودة والاتساق how to use fix fix setup guide yarn prettier tutorial lint error resolution fix vs eslint fix install guide what is fix fix for react developers javascript code formatting ci pipeline optimization Fix AI工具 代码格式化 Lint错误修复 CI检查 React代码 JavaScript代码 yarn prettier yarn linc Runs yarn prettier to fix formatting issues in changed files Executes yarn linc to check for remaining lint issues Reports manual fixes needed for complete code quality assurance Supports declarative, frontend, and UI development with JavaScript and React Ensures code passes CI checks for seamless project deployment fix is a technical skill that resolves lint errors, formatting issues, and ensures code quality in declarative, frontend, and UI projects');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/flow', 'official', 'facebook', 'react', 'facebook/react', 'flow', 243646, 50653, 73, '2026-03-06T05:37:42Z', '2026-03-06T06:14:00.250Z', '4dcef83a65a5b702866f98922af5c56466e81e3e71809cf69c9292e182c2a685', '{"id":"facebook/react/flow","name":"flow","description":{"en":"The Flow skill helps developers run Flow type checking and troubleshoot type errors in React code, supporting various renderers like dom-node and React Native","zh":"Flow 类型检查用于识别 React 代码中的类型错误。它支持多种渲染器，包括 dom-node、dom-browser、native 和 fabric","ja":"Flow タイプチェックは React コードのタイプエラーを識別するために使用され、dom-node、dom-browser、native、fabric などの複数のレンダラーをサポートします - AIエージェント","ko":"Flow 타입 체크는 React 코드의 타입 오류를 식별하는 데 사용되며 dom-node, dom-browser, native, fabric 등의 여러 렌더러를 지원합니다","pt":"O Flow é uma ferramenta de verificação de tipos para React que ajuda a identificar erros de tipo no código","ru":"Flow - это инструмент проверки типов для React, который помогает выявить ошибки типов в коде","ar":"Flow هو أداة للتحقق من الأنواع لمساعدة React على تحديد الأخطاء في الرموز"},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"flow","description":"Use when you need to run Flow type checking, or when seeing Flow type errors in React code.","bodyPreview":"# Flow Type Checking\n\nArguments:\n- $ARGUMENTS: Renderer to check (default: dom-node)\n\n## Renderers\n\n| Renderer | When to Use |\n|----------|-------------|\n| `dom-node` | Default, recommended for most changes |\n| `dom-browser` | Browser-specific DOM code |\n| `native` | React Native |\n| `fabric` | React Native Fabric |\n\n## Instructions\n\n1. Run `yarn flow $ARGUMENTS` (use `dom-node` if no argument)\n2. Report type errors with file locations\n3. For comprehensive checking (slow), use `yarn flow-ci`\n\n##","body":"# Flow Type Checking\n\nArguments:\n- $ARGUMENTS: Renderer to check (default: dom-node)\n\n## Renderers\n\n| Renderer | When to Use |\n|----------|-------------|\n| `dom-node` | Default, recommended for most changes |\n| `dom-browser` | Browser-specific DOM code |\n| `native` | React Native |\n| `fabric` | React Native Fabric |\n\n## Instructions\n\n1. Run `yarn flow $ARGUMENTS` (use `dom-node` if no argument)\n2. Report type errors with file locations\n3. For comprehensive checking (slow), use `yarn flow-ci`\n\n## Common Mistakes\n\n- **Running without a renderer** - Always specify or use default `dom-node`\n- **Ignoring suppressions** - Check if `$FlowFixMe` comments are masking real issues\n- **Missing type imports** - Ensure types are imported from the correct package\n"},"category":"official","lastSynced":"2026-03-06T06:14:00.250Z","seo":{"title":{"en":"Flow: React Type Checking Setup Guide | AI Agent Skill","zh":"Flow 类型检查 Setup Guide","ja":"Flow タイプチェックベストプラクティス - AIエージェント","ko":"Flow 타입 체크 설정 가이드","pt":"Guia de Configuração do Flow para Verificação de Tipos","ru":"Настройка Flow для проверки типов: ИИ Агенты для React","ar":"دليل إعداد Flow للتحقق من الأنواع مع أدوات الذكاء الاصطناعي"},"description":{"en":"Master Flow type checking for React code - learn how to run yarn flow and troubleshoot type errors with our expert guide, tailored for AI agents","zh":"使用 Flow 类型检查来识别 React 代码中的类型错误，并了解如何使用 yarn flow 进行检查","ja":"React コードのタイプエラーを識別するために Flow タイプチェックを使用し、yarn flow を使用する方法を学ぶ - AIエージェント","ko":"Flow 타입 체크를 사용하여 React 코드의 타입 오류를 식별하고 yarn flow를 사용하여 체크하는 방법을 알아보세요","pt":"Aprenda a configurar o Flow para verificar tipos em seu código React e resolva erros de tipo com facilidade","ru":"Узнайте, как настроить Flow для проверки типов в вашем коде React и исправьте ошибки типов с помощью ИИ Агентов","ar":"تعلم كيفية ضبط Flow للتحقق من الأنواع في رمز React الخاص بك واستكشف كيفية إصلاح الأخطاء باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Flow is a type checking system for JavaScript, used to validate React code and ensure consistency across applications","zh":"Flow 类型检查是一种用于识别 React 代码中的类型错误的工具","ja":"Flow タイプチェックは React コードのタイプエラーを識別するために使用されるツールです - AIエージェント","ko":"Flow 타입 체크는 React 코드의 타입 오류를 식별하는 데 사용되는 도구입니다","pt":"O que é Flow? É uma ferramenta de verificação de tipos para React","ru":"Что такое Flow? Это инструмент проверки типов для React","ar":"ما هو Flow؟ إنه أداة للتحقق من الأنواع لمساعدة React"},"features":{"en":["Runs Flow type checking using yarn flow command","Supports multiple renderers, including dom-node, dom-browser, native, and fabric","Provides comprehensive type checking with yarn flow-ci command","Reports type errors with file locations for easy debugging","Integrates with React and React Native for seamless type checking"],"zh":["支持多种渲染器，包括 dom-node、dom-browser、native 和 fabric","使用 yarn flow 进行类型检查","支持 React 代码的类型错误识别","提供详细的类型错误报告","支持 comprehensive checking 模式"],"ja":["複数のレンダラーをサポートする，including dom-node、dom-browser、native、fabric","yarn flow を使用したタイプチェック","React コードのタイプエラー識別をサポート","詳細なタイプエラー報告を提供","comprehensive checking モードをサポート"],"ko":["여러 렌더러를 지원함，including dom-node, dom-browser, native, fabric","yarn flow를 사용한 타입 체크","React 코드의 타입 오류 식별을 지원","상세한 타입 오류 보고서를 제공","comprehensive checking 모드를 지원"],"pt":["Verificação de tipos em tempo de execução","Suporte a renderizadores diferentes (dom-node, dom-browser, native, fabric)","Integração com o React para identificar erros de tipo","Opção de verificação completa com yarn flow-ci","Relatórios de erros com localização de arquivos"],"ru":["Проверка типов в режиме реального времени","Поддержка разных рендереров (dom-node, dom-browser, native, fabric)","Интеграция с React для выявления ошибок типов","Возможность полной проверки с yarn flow-ci","Отчеты об ошибках с указанием местоположения файлов"],"ar":["التحقق من الأنواع في وقت التشغيل","دعم معالجات الت描 khácة (dom-node, dom-browser, native, fabric)","التكامل مع React لتحديد الأخطاء في الأنواع","خيار التحقق الشامل مع yarn flow-ci","تقارير الأخطاء مع موقع الملفات"]},"keywords":{"en":["how to use flow","flow type checking","react flow setup","flow vs typescript","flow install guide","yarn flow command","flow react native","flow dom-node renderer","flow type errors"],"zh":["Flow 类型检查","React 类型错误","yarn flow","dom-node","dom-browser","native","fabric","JavaScript 类型检查","React 开发工具"],"ja":["Flow タイプチェック","React タイプエラー","yarn flow","dom-node","dom-browser","native","fabric","JavaScript タイプチェック","React 開発ツール","AIエージェント"],"ko":["Flow 타입 체크","React 타입 오류","yarn flow","dom-node","dom-browser","native","fabric","JavaScript 타입 체크","React 개발 도구"],"pt":["Flow React","verificação de tipos","erros de tipo","React Native","yarn flow","Flow type checking","Guia de configuração do Flow"],"ru":["Flow React","проверка типов","ошибки типов","React Native","yarn flow","Flow тип проверка","ИИ Агенты для React"],"ar":["Flow React","التحقق من الأنواع","أخطاء الأنواع","React Native","yarn flow","Flow التحقق من النوع","أدوات الذكاء الاصطناعي للتحقق من الأنواع"]}},"agentAnalysis":{"suitability":{"en":"Perfect for React Developer Agents needing advanced Flow type checking capabilities.","zh":"适合需要高级Flow类型检查功能的React开发者代理。","ja":"React Developer Agentsが高度なFlow型チェック機能を必要とする場合に適しています。","ko":"고급 Flow 유형 검사 기능이 필요한 React 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador de React que necesitan capacidades de verificación de tipo avanzadas de Flow.","fr":"Parfait pour les agents de développeur React nécessitant des capacités de vérification de type avancées de Flow.","de":"Perfekt für React-Entwickleragenten, die erweiterte Flow-Typprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes Desenvolvedores React que necessitam de capacidades avançadas de verificação de tipos Flow.","ru":"Идеально подходит для React Developer Agents, которым требуются расширенные возможности проверки типов Flow.","ar":"مثالي لوكلاء مطوري React الذين يحتاجون إلى قدرات متقدمة للتحقق من نوع Flow."},"recommendation":{"en":"Empowers agents to run Flow type checking on React code using yarn flow, supporting multiple renderers like dom-node, dom-browser, native, and fabric, and provides comprehensive type error reporting with file locations.","zh":"使代理能够在React代码上运行Flow类型检查，使用yarn flow，支持多个渲染器，如dom-node、dom-browser、native和fabric，并提供包含文件位置的全面类型错误报告。","ja":"エージェントがReactコードでFlow型チェックを実行できるようにし、yarn flowを使用して複数のレンダラー（dom-node、dom-browser、native、fabricなど）をサポートし、ファイルの場所を含む包括的な型エラー報告を提供します。","ko":"에이전트가 React 코드에서 Flow 유형 검사를 실행할 수 있도록 하며, yarn flow를 사용하여 여러 렌더러(dom-node, dom-browser, native, fabric 등)를 지원하며, 파일 위치를 포함한 포괄적인 유형 오류 보고를 제공합니다.","es":"Habilita a los agentes a ejecutar la verificación de tipo Flow en el código React usando yarn flow, que admite varios renderizadores como dom-node, dom-browser, native y fabric, y proporciona un informe de errores de tipo completo con ubicaciones de archivos.","fr":"Permet aux agents d''exécuter la vérification de type Flow sur le code React à l''aide de yarn flow, en prenant en charge plusieurs renderers tels que dom-node, dom-browser, native et fabric, et fournit un rapport d''erreurs de type complet avec des emplacements de fichiers.","de":"Ermöglicht es Agenten, Flow-Typprüfung auf React-Code mithilfe von yarn flow auszuführen, wobei mehrere Renderer wie dom-node, dom-browser, native und fabric unterstützt werden, und bietet umfassende Typfehlerberichte mit Dateispeicherorten.","pt":"Permite que os agentes executem a verificação de tipos Flow em código React usando yarn flow, suportando múltiplos renderizadores como dom-node, dom-browser, native e fabric, e fornece relatórios abrangentes de erros de tipo com localizações de arquivo.","ru":"Позволяет агентам запускать проверку типов Flow на React-коде с помощью yarn flow, поддерживая несколько рендереров, таких как dom-node, dom-browser, native и fabric, и предоставляет всестороннюю отчетность об ошибках типов с указанием местоположения файлов.","ar":"يمكّن الوكلاء من تشغيل التحقق من نوع Flow على كود React باستخدام yarn flow، مع دعم عدة عارضات مثل dom-node و dom-browser و native و fabric، ويوفر تقارير شاملة لأخطاء النوع مع مواقع الملفات."},"useCases":{"en":["Running Flow type checking on React code","Debugging type errors in React applications","Validating React Native code using Flow type checking"],"zh":["在React代码上运行Flow类型检查","在React应用程序中调试类型错误","使用Flow类型检查验证React Native代码"],"ja":["ReactコードでFlow型チェックを実行する","Reactアプリケーションで型エラーをデバッグする","Flow型チェックを使用してReact Nativeコードを検証する"],"ko":["React 코드에서 Flow 유형 검사를 실행하는 것","React 응용 프로그램에서 유형 오류를 디버깅하는 것","Flow 유형 검사를 사용하여 React Native 코드를 확인하는 것"],"es":["Ejecutar la verificación de tipo Flow en el código React","Depurar errores de tipo en aplicaciones React","Validar el código React Native mediante la verificación de tipo Flow"],"fr":["Exécuter la vérification de type Flow sur le code React","Déboguer les erreurs de type dans les applications React","Valider le code React Native à l''aide de la vérification de type Flow"],"de":["Ausführen der Flow-Typprüfung auf React-Code","Debuggen von Typfehlern in React-Anwendungen","Validieren des React-Native-Codes mithilfe der Flow-Typprüfung"],"pt":["Executar a verificação de tipos Flow em código React","Depurar erros de tipo em aplicações React","Validar código React Native usando a verificação de tipos Flow"],"ru":["Запуск проверки типов Flow на React-коде","Отладка ошибок типов в React-приложениях","Проверка кода React Native с использованием проверки типов Flow"],"ar":["تشغيل التحقق من نوع Flow على كود React","تصحيح أخطاء النوع في تطبيقات React","التحقق من صحة كود React Native باستخدام التحقق من نوع Flow"]},"limitations":{"en":["Requires yarn installation","Limited to React and React Native projects","Slow comprehensive checking with yarn flow-ci"],"zh":["需要yarn安装","仅限React和React Native项目","使用yarn flow-ci进行全面检查速度慢"],"ja":["yarnのインストールが必要","ReactとReact Nativeプロジェクトのみに限定","yarn flow-ciを使用した包括的なチェックは遅い"],"ko":["yarn 설치가 필요함","React 및 React Native 프로젝트만 해당함","yarn flow-ci를 사용한 포괄적인 검사 속도가 느림"],"es":["Requiere la instalación de yarn","Limitado a proyectos React y React Native","Verificación completa lenta con yarn flow-ci"],"fr":["Nécessite l''installation de yarn","Limité aux projets React et React Native","Vérification complète lente avec yarn flow-ci"],"de":["Benötigt die Installation von yarn","Begrenzt auf React- und React-Native-Projekte","Langsames umfassendes Prüfen mit yarn flow-ci"],"pt":["Requer instalação do yarn","Limitado a projetos React e React Native","Verificação abrangente lenta com yarn flow-ci"],"ru":["Требует установки yarn","Ограничено проектами React и React Native","Медленная комплексная проверка с yarn flow-ci"],"ar":["يتطلب تثبيت yarn","مقتصر على مشاريع React و React Native","فحص شامل بطيء باستخدام yarn flow-ci"]},"version":4},"contentHash":"4dcef83a65a5b702866f98922af5c56466e81e3e71809cf69c9292e182c2a685","repoEtag":"W/\"7e366b67cb3bf6b132fa9e4b13c8e3f5f4a0c4e37519cb121164846325962090\"","qualityScore":73}');
