INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/flow', 'flow', 'facebook', 'react', 'official', 'flow facebook react official declarative frontend javascript library react ui The Flow skill helps developers run Flow type checking and troubleshoot type errors in React code, supporting various renderers like dom-node and React Native Flow 类型检查用于识别 React 代码中的类型错误。它支持多种渲染器，包括 dom-node、dom-browser、native 和 fabric Flow タイプチェックは React コードのタイプエラーを識別するために使用され、dom-node、dom-browser、native、fabric などの複数のレンダラーをサポートします - AIエージェント Flow 타입 체크는 React 코드의 타입 오류를 식별하는 데 사용되며 dom-node, dom-browser, native, fabric 등의 여러 렌더러를 지원합니다 O Flow é uma ferramenta de verificação de tipos para React que ajuda a identificar erros de tipo no código Flow - это инструмент проверки типов для React, который помогает выявить ошибки типов в коде Flow هو أداة للتحقق من الأنواع لمساعدة React على تحديد الأخطاء في الرموز how to use flow flow type checking react flow setup flow vs typescript flow install guide yarn flow command flow react native flow dom-node renderer flow type errors Flow 类型检查 React 类型错误 yarn flow dom-node dom-browser native fabric JavaScript 类型检查 React 开发工具 Runs Flow type checking using yarn flow command Supports multiple renderers, including dom-node, dom-browser, native, and fabric Provides comprehensive type checking with yarn flow-ci command Reports type errors with file locations for easy debugging Integrates with React and React Native for seamless type checking Flow is a type checking system for JavaScript, used to validate React code and ensure consistency across applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/verify', 'official', 'facebook', 'react', 'facebook/react', 'verify', 243646, 50653, 73, '2026-03-06T05:37:42Z', '2026-03-06T06:16:07.808Z', '070d8a87c34b661d98c7b8d72b4443706c4f78386647b115476d34121e70d0be', '{"id":"facebook/react/verify","name":"verify","description":{"en":"The verify skill validates changes before committing, checking React contribution requirements through a series of tests and checks, benefiting frontend developers.","zh":"Verify Skill 用于验证 React 代码的格式、语法和功能，确保代码符合贡献要求","ja":"Verify Skill は React コードのフォーマット、文法、機能を検証し、コードが貢献要件を満たしていることを確認します","ko":"Verify Skill은 React 코드의 형식, 문법 및 기능을 검증하여 코드가 기여 요구사항을 충족하는지 확인합니다","es":"Verifica cambios en tu proyecto React con yarn prettier, yarn linc y pruebas en paralelo","fr":"Vérifiez les modifications de votre projet React avec yarn prettier, yarn linc et des tests en parallèle","de":"Überprüfen Sie Änderungen in Ihrem React-Projekt mit yarn prettier, yarn linc und parallelen Tests","pt":"O Verify é uma ferramenta que valida alterações no código React antes de commitar, utilizando tecnologias como Prettier, Linc e Flow","ru":"ИИ Агент Verify - это инструмент, который проверяет изменения в коде React перед коммитом, используя технологии như Prettier, Linc и Flow","ar":"Verify هو أداة تقوم بالتحقق من التغييرات في رمز React قبل الالتزام، باستخدام تقنيات مثل Prettier و Linc و Flow"},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"verify","description":"Use when you want to validate changes before committing, or when you need to check all React contribution requirements.","bodyPreview":"# Verification\n\nRun all verification steps.\n\nArguments:\n- $ARGUMENTS: Test pattern for the test step\n\n## Instructions\n\nRun these first in sequence:\n1. Run `yarn prettier` - format code (stop if fails)\n2. Run `yarn linc` - lint changed files (stop if fails)\n\nThen run these with subagents in parallel:\n1. Use `/flow` to type check (stop if fails)\n2. Use `/test` to test changes in source (stop if fails)\n3. Use `/test www` to test changes in www (stop if fails)\n\nIf all pass, show success summary. On","body":"# Verification\n\nRun all verification steps.\n\nArguments:\n- $ARGUMENTS: Test pattern for the test step\n\n## Instructions\n\nRun these first in sequence:\n1. Run `yarn prettier` - format code (stop if fails)\n2. Run `yarn linc` - lint changed files (stop if fails)\n\nThen run these with subagents in parallel:\n1. Use `/flow` to type check (stop if fails)\n2. Use `/test` to test changes in source (stop if fails)\n3. Use `/test www` to test changes in www (stop if fails)\n\nIf all pass, show success summary. On failure, stop immediately and report the issue with suggested fixes.\n"},"category":"official","lastSynced":"2026-03-06T06:16:07.808Z","seo":{"title":{"en":"Verify: Validation Setup Guide for AI Agents","zh":"Verify Setup Guide: React 代码验证和检查","ja":"Verify ベストプラクティス: React コード検証とチェック","ko":"Verify 설정 가이드: React 코드 검증 및 확인","es":"Guía de configuración de verificación de cambios con React","fr":"Configurer les meilleures pratiques de vérification pour ...","de":"Einrichten der Überprüfung von Änderungen mit React","pt":"Guia de Configuração do Verify: Validando Alterações no R...","ru":"ИИ Агент Verify: Руководство по Настройке для React","ar":"دليل إعداد Verify: التحقق من التغييرات في React"},"description":{"en":"Streamline your React development workflow with the verify skill, ensuring compliance with contribution requirements - learn how to set it up now","zh":"使用 Verify Skill 运行 React 代码格式化、lint 检查、类型检查和测试，确保代码质量和稳定性","ja":"Verify Skill を使用して React コードのフォーマット、lint チェック、型チェック、テストを実行し、コード品質と安定性を確保する","ko":"Verify Skill을 사용하여 React 코드의 형식화, lint 검사, 유형 검사 및 테스트를 실행하여 코드 품질과 안정성을 보장합니다","es":"Aprende a validar cambios en tu proyecto React antes de comprometerlos con nuestra guía de verificación","fr":"Découvrez comment vérifier vos modifications React avant de les valider avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Änderungen in Ihrem React-Projekt überprüfen, bevor Sie sie committen, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a utilizar o Verify para validar alterações no código React antes de commitar, garantindo a qualidade e a conformidade","ru":"Узнайте, как использовать ИИ Агент Verify для проверки изменений в коде React перед коммитом, чтобы обеспечить качество и соответствие требованиям","ar":"تعلم كيفية استخدام Verify للتحقق من التغييرات في رمز React قبل الالتزام، لضمان الجودة والامتثال"},"definition":{"en":"Verify is a skill that runs all verification steps, including code formatting, linting, and type checking, to ensure code quality and compliance.","zh":"Verify 是一个用于验证 React 代码的 AI 工具，检查代码格式、语法和功能","ja":"Verify は React コードを検証する AI エージェントであり、コードのフォーマット、文法、機能をチェックします","ko":"Verify는 React 코드를 검증하는 AI 도구로서 코드의 형식, 문법 및 기능을 확인합니다","es":"La verificación es un proceso que valida los cambios en un proyecto React antes de comprometerlos","fr":"La vérification est un processus qui valide les modifications d''un projet React avant de les valider","de":"Die Überprüfung ist ein Prozess, der Änderungen in einem React-Projekt überprüft, bevor sie committet werden","pt":"O Verify é uma ferramenta de verificação que garante a qualidade e a conformidade do código React","ru":"ИИ Агент Verify - это инструмент проверки, который обеспечивает качество и соответствие кода React","ar":"Verify هو أداة تحقق تضمن جودة وامتثال رمز React"},"features":{"en":["Runs yarn prettier for code formatting","Executes yarn linc for linting changed files","Uses /flow for type checking","Runs /test for testing changes in source","Runs /test www for testing changes in www","Shows success summary upon passing all checks"],"zh":["运行 yarn prettier 格式化代码","执行 yarn linc 检查代码语法","使用 /flow 进行类型检查","使用 /test 和 /test www 进行功能测试","支持并行执行多个测试任务","提供详细的测试报告和摘要"],"ja":["yarn prettier を実行してコードをフォーマット","yarn linc を実行してコードの文法をチェック","/flow を使用して型チェックを実行","/test と /test www を使用して機能テストを実行","複数のテストタスクを並行して実行","詳細なテストレポートとサマリーを提供"],"ko":["yarn prettier를 실행하여 코드를 형식화","yarn linc를 실행하여 코드의 문법을 확인","/flow를 사용하여 유형 검사를 수행","/test와 /test www를 사용하여 기능 테스트를 수행","여러 테스트 작업을 병렬로 실행","상세한 테스트 보고서와 요약 제공"],"es":["Ejecuta yarn prettier para formatear el código","Ejecuta yarn linc para analizar los archivos cambiados","Ejecuta pruebas en paralelo con /flow y /test","Soporte para tipo de comprobación con /flow","Soporte para pruebas de cambios en la fuente y en www","Resumen de éxito si todas las pruebas pasan"],"fr":["Exécutez yarn prettier pour formater le code","Exécutez yarn linc pour analyser les fichiers modifiés","Exécutez des tests en parallèle avec /flow et /test","Prise en charge de la vérification de type avec /flow","Prise en charge des tests de modifications dans la source et sur www","Résumé de réussite si tous les tests passent"],"de":["Führen Sie yarn prettier aus, um den Code zu formatieren","Führen Sie yarn linc aus, um die geänderten Dateien zu analysieren","Führen Sie parallele Tests mit /flow und /test aus","Unterstützung für Typüberprüfung mit /flow","Unterstützung für Änderungstests in Quelle und www","Erfolgszusammenfassung, wenn alle Tests bestanden sind"],"pt":["Executa o Prettier para formatar o código","Executa o Linc para verificar a conformidade do código","Utiliza o Flow para realizar checagem de tipo","Executa testes em paralelo com subagentes","Verifica alterações no código React antes de commitar"],"ru":["Выполняет Prettier для форматирования кода","Выполняет Linc для проверки соответствия кода","Использует Flow для проверки типа","Выполняет тесты параллельно с субагентами","Проверяет изменения в коде React перед коммитом"],"ar":["ينفذ Prettier لتنسيق الرمز","ينفذ Linc للتحقق من مطابقة الرمز","يستخدم Flow للتحقق من النوع","ينفذ الاختبارات بشكل متوازي مع الوكلاء الفرعيين","يُحقق التغييرات في رمز React قبل الالتزام"]},"keywords":{"en":["how to use verify","verify setup guide","react contribution requirements","verify vs eslint","verify install","what is verify","verify alternative","verify for frontend developers","verify and react","verify skill for ai agents"],"zh":["React 代码验证","代码格式化","lint 检查","类型检查","功能测试","AI 工具","代码质量","代码稳定性","Verify Skill"],"ja":["React コード検証","コードフォーマット","lint チェック","型チェック","機能テスト","AI エージェント","コード品質","コード安定性","Verify Skill"],"ko":["React 코드 검증","코드 형식화","lint 확인","유형 검사","기능 테스트","AI 도구","코드 품질","코드 안정성","Verify Skill"],"es":["herramientas de verificación de React","verificación de cambios en React","yarn prettier","yarn linc","pruebas en paralelo","tipo de comprobación","pruebas de cambios","react testing","react verification"],"fr":["outils de vérification React","vérification de modifications React","yarn prettier","yarn linc","tests en parallèle","vérification de type","tests de modifications","react testing","react verification"],"de":["Überprüfungstools für React","Änderungsüberprüfung in React","yarn prettier","yarn linc","parallele Tests","Typüberprüfung","Änderungstests","react testing","react verification"],"pt":["Verify React","ferramenta de verificação","Prettier","Linc","Flow","testes em paralelo","commitar código","qualidade do código"],"ru":["ИИ Агент Verify","инструмент проверки","Prettier","Linc","Flow","параллельные тесты","коммит кода","качество кода"],"ar":["Verify React","أداة التحقق","Prettier","Linc","Flow","اختبارات متوازي","التزام الرمز","جودة الرمز"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring comprehensive code validation and formatting, particularly those working with React and utilizing tools like yarn, prettier, and linc.","zh":"适合需要全面代码验证和格式化的开发代理，特别是那些使用 React 并利用像 yarn、prettier 和 linc 等工具的代理。","ja":"React や yarn、prettier、linc などのツールを使用する開発エージェントが、包括的なコード検証とフォーマットを必要とする場合に最適です。","ko":"React 및 yarn, prettier, linc 등의 도구를 사용하는 개발 에이전트가 포괄적인 코드 유효성 검사 및 형식을 필요로 하는 경우에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una validación y formato de código comprehensivo, particularmente aquellos que trabajan con React y utilizan herramientas como yarn, prettier y linc.","fr":"Idéal pour les Agents de Développement nécessitant une validation et un formatage de code complet, en particulier ceux qui travaillent avec React et utilisent des outils comme yarn, prettier et linc.","de":"Ideal für Entwicklungsmittel benötigende umfassende Code-Validierung und -Formatierung, insbesondere für diejenigen, die mit React arbeiten und Tools wie yarn, prettier und linc verwenden.","pt":"Ideal para Agentes de Desenvolvimento que requerem validação e formatação de código abrangentes, particularmente aqueles que trabalham com React e utilizam ferramentas como yarn, prettier e linc.","ru":"Идеально подходит для агентов разработки, требующих всесторонней проверки и форматирования кода, особенно для тех, кто работает с React и использует инструменты seperti yarn, prettier и linc.","ar":"مثالي لعمال التطوير الذين يحتاجون إلى التحقق الشامل وتنسيق الشفرة، ولا سيما أولئك الذين يعملون مع React ويتفاعلون مع أدوات مثل yarn وprettier وlinc."},"recommendation":{"en":"Empowers agents to validate code changes through sequential and parallel execution of formatting, linting, type checking, and testing steps, utilizing yarn prettier, yarn linc, /flow, and /test commands to ensure code integrity and adherence to React contribution requirements.","zh":"赋予代理通过顺序和并行执行格式化、linting、类型检查和测试步骤来验证代码更改的能力，利用 yarn prettier、yarn linc、/flow 和 /test 命令来确保代码完整性和遵守 React 贡献要求。","ja":"エージェントがフォーマット、linting、型チェック、テストステップの順序的および並列実行を介してコード変更を検証する能力を付与し、yarn prettier、yarn linc、/flow、/test コマンドを使用してコードの整合性と React 貢献要件の遵守を確保します。","ko":"에이전트가 형식 지정, 린팅, 유형 확인 및 테스트 단계의 순차적 및 병렬 실행을 통해 코드 변경을 확인할 수 있는 능력을 부여하며, yarn prettier, yarn linc, /flow 및 /test 명령을 사용하여 코드의 무결성 및 React 기여 요구 사항을 준수합니다.","es":"Permite a los agentes validar los cambios de código a través de la ejecución secuencial y paralela de los pasos de formato, linting, verificación de tipos y pruebas, utilizando los comandos yarn prettier, yarn linc, /flow y /test para garantizar la integridad del código y el cumplimiento de los requisitos de contribución de React.","fr":"Permet aux agents de valider les modifications de code via l''exécution séquentielle et parallèle des étapes de formatage, de linting, de vérification de types et de tests, en utilisant les commandes yarn prettier, yarn linc, /flow et /test pour assurer l''intégrité du code et le respect des exigences de contribution de React.","de":"Ermöglicht es Agenten, Codeänderungen durch sequenzielle und parallele Ausführung von Formatierung-, Linting-, Typprüfungs- und Testschritten zu überprüfen, unter Verwendung der Befehle yarn prettier, yarn linc, /flow und /test, um die Codeintegrität und die Einhaltung der React-Beitrittsanforderungen sicherzustellen.","pt":"Habilita os agentes a validar alterações de código por meio da execução sequencial e paralela de etapas de formatação, linting, verificação de tipo e testes, utilizando comandos yarn prettier, yarn linc, /flow e /test para garantir a integridade do código e a aderência aos requisitos de contribuição do React.","ru":"Наделяет агентов возможностью проверять изменения кода посредством последовательного и параллельного выполнения этапов форматирования, linting, проверки типа и тестирования, используя команды yarn prettier, yarn linc, /flow и /test для обеспечения целостности кода и соблюдения требований к вкладу в React.","ar":"تمكن العمال من التحقق من تغييرات الشفرة من خلال التنفيذ المتسلسل والمتوازي لخطوات التنسيق وlinting وفتح النوع واختبار، باستخدام أوامر yarn prettier وyarn linc و/flow و/test لضمان سلامة الشفرة والامتثال لمتطلبات المساهمة في React."},"useCases":{"en":["Validating changes before committing to ensure code consistency and quality","Automating the testing of React contributions to verify compliance with requirements","Debugging code formatting and linting issues to improve overall code maintainability"],"zh":["在提交之前验证更改以确保代码的一致性和质量","自动测试 React 贡献以验证是否符合要求","调试代码格式化和 linting 问题以提高代码的可维护性"],"ja":["コードの一貫性と品質を確保するためにコミットする前に変更を検証する","React 貢献を自動テストして要件に従っていることを検証する","コードのメンテナンス性を向上させるためにコードのフォーマットと linting の問題をデバッグする"],"ko":["코드 일관성 및 품질을 보장하기 위해 커밋하기 전에 변경 사항을 확인하는 것","React 기여를 자동 테스트하여 요구 사항을 준수하는지 확인하는 것","코드 유지 보수성을 개선하기 위해 코드 형식 지정 및 린팅 문제를 디버깅하는 것"],"es":["Validar los cambios antes de confirmar para garantizar la coherencia y la calidad del código","Automatizar las pruebas de las contribuciones de React para verificar el cumplimiento de los requisitos","Depurar problemas de formato y linting de código para mejorar la mantenibilidad general del código"],"fr":["Valider les modifications avant de les valider pour assurer la cohérence et la qualité du code","Automatiser les tests des contributions de React pour vérifier le respect des exigences","Déboguer les problèmes de formatage et de linting de code pour améliorer la maintenabilité globale du code"],"de":["Änderungen vor dem Commit validieren, um die Konsistenz und Qualität des Codes sicherzustellen","Automatisieren der Tests von React-Beiträgen, um die Einhaltung der Anforderungen zu überprüfen","Beheben von Code-Formatierungs- und Linting-Problemen, um die allgemeine Wartbarkeit des Codes zu verbessern"],"pt":["Validar alterações antes de confirmar para garantir a consistência e a qualidade do código","Automatizar o teste de contribuições do React para verificar o cumprimento dos requisitos","Depurar problemas de formatação e linting do código para melhorar a manutenibilidade geral do código"],"ru":["Проверять изменения перед фиксацией для обеспечения согласованности и качества кода","Автоматизировать тестирование вкладов в React для проверки соблюдения требований","Отлаживать проблемы форматирования и linting кода для улучшения общей поддерживаемости кода"],"ar":["التحقق من التغييرات قبل الإلتزام لضمان الاتساق وجودة الشفرة","تأتميت اختبار مساهمات React للتحقق من الامتثال للمتطلبات","تصحيح مشاكل تنسيق الشفرة وlinting لتحسين صيانة الشفرة بشكل عام"]},"limitations":{"en":["Requires yarn and specific scripts (prettier, linc, /flow, /test) to be configured and available","Dependent on successful execution of sequential steps, with failure in any step halting the process"],"zh":["需要 yarn 和特定的脚本（prettier、linc、/flow、/test）被配置和可用","依赖于顺序步骤的成功执行，任何步骤的失败都会停止该过程"],"ja":["yarn と特定のスクリプト（prettier、linc、/flow、/test）が設定され利用可能である必要がある","順序ステップの成功実行に依存しており、どのステップでも失敗するとプロセスが停止する"],"ko":["yarn 및 특정 스크립트(prettier, linc, /flow, /test)가 구성되고 사용 가능해야 함","순차적 단계의 성공적 실행에 의존하며, 어떤 단계에서도 실패하면 프로세스가 중단됨"],"es":["Requiere que yarn y scripts específicos (prettier, linc, /flow, /test) estén configurados y disponibles","Depende de la ejecución exitosa de los pasos secuenciales, con un fallo en cualquier paso que detiene el proceso"],"fr":["Nécessite que yarn et des scripts spécifiques (prettier, linc, /flow, /test) soient configurés et disponibles","Dépend de l''exécution réussie des étapes séquentielles, avec une défaillance à n''importe quelle étape qui arrête le processus"],"de":["Erfordert, dass yarn und bestimmte Skripte (prettier, linc, /flow, /test) konfiguriert und verfügbar sind","Hängt von der erfolgreichen Ausführung der sequenziellen Schritte ab, wobei ein Fehler in einem beliebigen Schritt den Prozess stoppt"],"pt":["Requer yarn e scripts específicos (prettier, linc, /flow, /test) para serem configurados e disponíveis","Depende da execução bem-sucedida de etapas sequenciais, com falha em qualquer etapa interrompendo o processo"],"ru":["Требует наличия yarn и конкретных скриптов (prettier, linc, /flow, /test) для их конфигурации и доступности","Зависит от успешного выполнения последовательных этапов, при этом сбой на любом этапе останавливает процесс"],"ar":["يتطلب وجود yarn وبرامج نصية محددة (prettier وlinc و/flow و/test) لتكون مخططة ومتاحة","يعتمد على تنفيذ ناجح للخطوات المتسلسلة، مع فشل في أي خطوة يتوقف العملية"]},"version":4},"contentHash":"070d8a87c34b661d98c7b8d72b4443706c4f78386647b115476d34121e70d0be","repoEtag":"W/\"7e366b67cb3bf6b132fa9e4b13c8e3f5f4a0c4e37519cb121164846325962090\"","qualityScore":73}');
