INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/verify', 'verify', 'facebook', 'react', 'official', 'verify facebook react official declarative frontend javascript library react ui The verify skill validates changes before committing, checking React contribution requirements through a series of tests and checks, benefiting frontend developers. Verify Skill 用于验证 React 代码的格式、语法和功能，确保代码符合贡献要求 Verify Skill は React コードのフォーマット、文法、機能を検証し、コードが貢献要件を満たしていることを確認します Verify Skill은 React 코드의 형식, 문법 및 기능을 검증하여 코드가 기여 요구사항을 충족하는지 확인합니다 Verifica cambios en tu proyecto React con yarn prettier, yarn linc y pruebas en paralelo Vérifiez les modifications de votre projet React avec yarn prettier, yarn linc et des tests en parallèle Überprüfen Sie Änderungen in Ihrem React-Projekt mit yarn prettier, yarn linc und parallelen Tests O Verify é uma ferramenta que valida alterações no código React antes de commitar, utilizando tecnologias como Prettier, Linc e Flow ИИ Агент Verify - это инструмент, который проверяет изменения в коде React перед коммитом, используя технологии như Prettier, Linc и Flow Verify هو أداة تقوم بالتحقق من التغييرات في رمز React قبل الالتزام، باستخدام تقنيات مثل Prettier و Linc و Flow how to use verify verify setup guide react contribution requirements verify vs eslint verify install what is verify verify alternative verify for frontend developers verify and react verify skill for ai agents React 代码验证 代码格式化 lint 检查 类型检查 功能测试 AI 工具 代码质量 代码稳定性 Verify Skill Runs yarn prettier for code formatting Executes yarn linc for linting changed files Uses /flow for type checking Runs /test for testing changes in source Runs /test www for testing changes in www Shows success summary upon passing all checks Verify is a skill that runs all verification steps, including code formatting, linting, and type checking, to ensure code quality and compliance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/pptx', 'official', 'anthropics', 'skills', 'anthropics/skills', 'pptx', 85097, 8974, 71, '2026-03-06T03:11:21Z', '2026-03-06T03:20:58.722Z', 'e5b0df918cbe9d62508b3cf808d73899633f82fc19f6258a25ef9f0de7e62125', '{"id":"anthropics/skills/pptx","name":"pptx","description":{"en":"The PPTX skill enables AI agents to programmatically interact with PowerPoint (.pptx) files. It provides tools for developers to extract text, generate new presentations, and manipulate slide decks from the command line or via scripts.","pt":"A skill pptx permite automatizar a criação, edição e análise de apresentações .pptx. Use comandos CLI como `python -m markitdown` para extrair texto ou `pptxgenjs` para gerar decks do zero, integrando perfeitamente com seus agentes de IA.","ru":"Навык PPTX автоматизирует создание, редактирование и анализ презентаций .pptx. Используйте CLI команды, такие как `python -m markitdown` для извлечения текста или `pptxgenjs` для генерации презентаций с нуля, интегрируясь с ИИ Агентами.","ar":"تتيح مهارة pptx أتمتة إنشاء وتحرير وتحليل العروض التقديمية .pptx. استخدم أوامر CLI مثل `python -m markitdown` لاستخراج النص أو `pptxgenjs` لإنشاء العروض من الصفر، مع التكامل السلس مع أدوات الذكاء الاصطناعي."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"pptx","description":"Use this skill any time a .pptx file is involved in any way — as input, output, or both. This includes: creating slide decks, pitch decks, or presentations; reading, parsing, or extracting text from any .pptx file (even if the extracted content will be used elsewhere, like in an email or summary); editing, modifying, or updating existing presentations; combining or splitting slide files; working with templates, layouts, speaker notes, or comments. Trigger whenever the user mentions \\deck,\\ \\slides,\\ \\presentation,\\ or references a .pptx filename, regardless of what they plan to do with the content afterward. If a .pptx file needs to be opened, created, or touched, use this skill.","bodyPreview":"# PPTX Skill\n\n## Quick Reference\n\n| Task | Guide |\n|------|-------|\n| Read/analyze content | `python -m markitdown presentation.pptx` |\n| Edit or create from template | Read [editing.md](editing.md) |\n| Create from scratch | Read [pptxgenjs.md](pptxgenjs.md) |\n\n---\n\n## Reading Content\n\n```bash\n# Text extraction\npython -m markitdown presentation.pptx\n\n# Visual overview\npython scripts/thumbnail.py presentation.pptx\n\n# Raw XML\npython scripts/office/unpack.py presentation.pptx unpacked/\n```\n\n---\n\n##","body":"# PPTX Skill\n\n## Quick Reference\n\n| Task | Guide |\n|------|-------|\n| Read/analyze content | `python -m markitdown presentation.pptx` |\n| Edit or create from template | Read [editing.md](editing.md) |\n| Create from scratch | Read [pptxgenjs.md](pptxgenjs.md) |\n\n---\n\n## Reading Content\n\n```bash\n# Text extraction\npython -m markitdown presentation.pptx\n\n# Visual overview\npython scripts/thumbnail.py presentation.pptx\n\n# Raw XML\npython scripts/office/unpack.py presentation.pptx unpacked/\n```\n\n---\n\n## Editing Workflow\n\n**Read [editing.md](editing.md) for full details.**\n\n1. Analyze template with `thumbnail.py`\n2. Unpack → manipulate slides → edit content → clean → pack\n\n---\n\n## Creating from Scratch\n\n**Read [pptxgenjs.md](pptxgenjs.md) for full details.**\n\nUse when no template or reference presentation is available.\n\n---\n\n## Design Ideas\n\n**Don''t create boring slides.** Plain bullets on a white background won''t impress anyone. Consider ideas from this list for each slide.\n\n### Before Starting\n\n- **Pick a bold, content-informed color palette**: The palette should feel designed for THIS topic. If swapping your colors into a completely different presentation would still \"work,\" you haven''t made specific enough choices.\n- **Dominance over equality**: One color should dominate (60-70% visual weight), with 1-2 supporting tones and one sharp accent. Never give all colors equal weight.\n- **Dark/light contrast**: Dark backgrounds for title + conclusion slides, light for content (\"sandwich\" structure). Or commit to dark throughout for a premium feel.\n- **Commit to a visual motif**: Pick ONE distinctive element and repeat it — rounded image frames, icons in colored circles, thick single-side borders. Carry it across every slide.\n\n### Color Palettes\n\nChoose colors that match your topic — don''t default to generic blue. Use these palettes as inspiration:\n\n| Theme | Primary | Secondary | Accent |\n|-------|---------|-----------|--------|\n| **Midnight Executive** | `1E2761` (navy) | `CADCFC` (ice blue) | `FFFFFF` (white) |\n| **Forest & Moss** | `2C5F2D` (forest) | `97BC62` (moss) | `F5F5F5` (cream) |\n| **Coral Energy** | `F96167` (coral) | `F9E795` (gold) | `2F3C7E` (navy) |\n| **Warm Terracotta** | `B85042` (terracotta) | `E7E8D1` (sand) | `A7BEAE` (sage) |\n| **Ocean Gradient** | `065A82` (deep blue) | `1C7293` (teal) | `21295C` (midnight) |\n| **Charcoal Minimal** | `36454F` (charcoal) | `F2F2F2` (off-white) | `212121` (black) |\n| **Teal Trust** | `028090` (teal) | `00A896` (seafoam) | `02C39A` (mint) |\n| **Berry & Cream** | `6D2E46` (berry) | `A26769` (dusty rose) | `ECE2D0` (cream) |\n| **Sage Calm** | `84B59F` (sage) | `69A297` (eucalyptus) | `50808E` (slate) |\n| **Cherry Bold** | `990011` (cherry) | `FCF6F5` (off-white) | `2F3C7E` (navy) |\n\n### For Each Slide\n\n**Every slide needs a visual element** — image, chart, icon, or shape. Text-only slides are forgettable.\n\n**Layout options:**\n- Two-column (text left, illustration on right)\n- Icon + text rows (icon in colored circle, bold header, description below)\n- 2x2 or 2x3 grid (image on one side, grid of content blocks on other)\n- Half-bleed image (full left or right side) with content overlay\n\n**Data display:**\n- Large stat callouts (big numbers 60-72pt with small labels below)\n- Comparison columns (before/after, pros/cons, side-by-side options)\n- Timeline or process flow (numbered steps, arrows)\n\n**Visual polish:**\n- Icons in small colored circles next to section headers\n- Italic accent text for key stats or taglines\n\n### Typography\n\n**Choose an interesting font pairing** — don''t default to Arial. Pick a header font with personality and pair it with a clean body font.\n\n| Header Font | Body Font |\n|-------------|-----------|\n| Georgia | Calibri |\n| Arial Black | Arial |\n| Calibri | Calibri Light |\n| Cambria | Calibri |\n| Trebuchet MS | Calibri |\n| Impact | Arial |\n| Palatino | Garamond |\n| Consolas | Calibri |\n\n| Element | Size |\n|---------|------|\n| Slide title | 36-44pt bold |\n| Section header | 20-24pt bold |\n| Body text | 14-16pt |\n| Captions | 10-12pt muted |\n\n### Spacing\n\n- 0.5\" minimum margins\n- 0.3-0.5\" between content blocks\n- Leave breathing room—don''t fill every inch\n\n### Avoid (Common Mistakes)\n\n- **Don''t repeat the same layout** — vary columns, cards, and callouts across slides\n- **Don''t center body text** — left-align paragraphs and lists; center only titles\n- **Don''t skimp on size contrast** — titles need 36pt+ to stand out from 14-16pt body\n- **Don''t default to blue** — pick colors that reflect the specific topic\n- **Don''t mix spacing randomly** — choose 0.3\" or 0.5\" gaps and use consistently\n- **Don''t style one slide and leave the rest plain** — commit fully or keep it simple throughout\n- **Don''t create text-only slides** — add images, icons, charts, or visual elements; avoid plain title + bullets\n- **Don''t forget text box padding** — when aligning lines or shapes with text edges, set `margin: 0` on the text box or offset the shape to account for padding\n- **Don''t use low-contrast elements** — icons AND text need strong contrast against the background; avoid light text on light backgrounds or dark text on dark backgrounds\n- **NEVER use accent lines under titles** — these are a hallmark of AI-generated slides; use whitespace or background color instead\n\n---\n\n## QA (Required)\n\n**Assume there are problems. Your job is to find them.**\n\nYour first render is almost never correct. Approach QA as a bug hunt, not a confirmation step. If you found zero issues on first inspection, you weren''t looking hard enough.\n\n### Content QA\n\n```bash\npython -m markitdown output.pptx\n```\n\nCheck for missing content, typos, wrong order.\n\n**When using templates, check for leftover placeholder text:**\n\n```bash\npython -m markitdown output.pptx | grep -iE \"xxxx|lorem|ipsum|this.*(page|slide).*layout\"\n```\n\nIf grep returns results, fix them before declaring success.\n\n### Visual QA\n\n**⚠️ USE SUBAGENTS** — even for 2-3 slides. You''ve been staring at the code and will see what you expect, not what''s there. Subagents have fresh eyes.\n\nConvert slides to images (see [Converting to Images](#converting-to-images)), then use this prompt:\n\n```\nVisually inspect these slides. Assume there are issues — find them.\n\nLook for:\n- Overlapping elements (text through shapes, lines through words, stacked elements)\n- Text overflow or cut off at edges/box boundaries\n- Decorative lines positioned for single-line text but title wrapped to two lines\n- Source citations or footers colliding with content above\n- Elements too close (< 0.3\" gaps) or cards/sections nearly touching\n- Uneven gaps (large empty area in one place, cramped in another)\n- Insufficient margin from slide edges (< 0.5\")\n- Columns or similar elements not aligned consistently\n- Low-contrast text (e.g., light gray text on cream-colored background)\n- Low-contrast icons (e.g., dark icons on dark backgrounds without a contrasting circle)\n- Text boxes too narrow causing excessive wrapping\n- Leftover placeholder content\n\nFor each slide, list issues or areas of concern, even if minor.\n\nRead and analyze these images:\n1. /path/to/slide-01.jpg (Expected: [brief description])\n2. /path/to/slide-02.jpg (Expected: [brief description])\n\nReport ALL issues found, including minor ones.\n```\n\n### Verification Loop\n\n1. Generate slides → Convert to images → Inspect\n2. **List issues found** (if none found, look again more critically)\n3. Fix issues\n4. **Re-verify affected slides** — one fix often creates another problem\n5. Repeat until a full pass reveals no new issues\n\n**Do not declare success until you''ve completed at least one fix-and-verify cycle.**\n\n---\n\n## Converting to Images\n\nConvert presentations to individual slide images for visual inspection:\n\n```bash\npython scripts/office/soffice.py --headless --convert-to pdf output.pptx\npdftoppm -jpeg -r 150 output.pdf slide\n```\n\nThis creates `slide-01.jpg`, `slide-02.jpg`, etc.\n\nTo re-render specific slides after fixes:\n\n```bash\npdftoppm -jpeg -r 150 -f N -l N output.pdf slide-fixed\n```\n\n---\n\n## Dependencies\n\n- `pip install \"markitdown[pptx]\"` - text extraction\n- `pip install Pillow` - thumbnail grids\n- `npm install -g pptxgenjs` - creating from scratch\n- LibreOffice (`soffice`) - PDF conversion (auto-configured for sandboxed environments via `scripts/office/soffice.py`)\n- Poppler (`pdftoppm`) - PDF to images\n"},"category":"official","lastSynced":"2026-03-06T03:20:58.722Z","seo":{"title":{"en":"PPTX Skill: Parse & Generate Presentations | AI Agent Skill","pt":"pptx Skill: Guia Completo para Trabalhar com Apresentações","ru":"Навык PPTX: Полное руководство по работе с презентациями ...","ar":"مهارة pptx: دليل شامل للعمل مع العروض التقديمية في أدوات ..."},"description":{"en":"Master .pptx automation for AI agents. Extract text with markitdown, generate slides with pptxgenjs, and unpack XML. Learn specific commands for reading, edi...","pt":"Aprenda a usar a skill pptx para extrair texto com Python Markitdown, criar apresentações com pptxgenjs, editar templates e manipular arquivos .pptx em agent...","ru":"Используйте навык PPTX для извлечения текста с помощью Python Markitdown, создания презентаций с pptxgenjs, редактирования шаблонов и работы с файлами .pptx ...","ar":"استخدم مهارة pptx لاستخراج النص باستخدام Python Markitdown، وإنشاء العروض التقديمية باستخدام pptxgenjs، وتحرير القوالب والتعامل مع ملفات .pptx في أدوات الذكا..."},"definition":{"en":"pptx is an AI agent skill for programmatically handling PowerPoint .pptx files. It provides capabilities for reading content via markitdown, creating presentations from scratch with pptxgenjs, editing from templates, and unpacking the raw Office Open XML structure for low-level manipulation.","pt":"A skill pptx é uma ferramenta para agentes de IA que automatiza operações com arquivos .pptx. Ela lida com criação, edição, extração de texto, combinação de slides e trabalho com templates usando bibliotecas como pptxgenjs e Python Markitdown.","ru":"Навык PPTX — это инструмент для ИИ Агентов, автоматизирующий операции с файлами .pptx. Он обрабатывает создание, редактирование, извлечение текста, объединение слайдов и работу с шаблонами с использованием библиотек pptxgenjs и Python Markitdown.","ar":"مهارة pptx هي أداة لأدوات الذكاء الاصطناعي تؤتمت العمليات على ملفات .pptx. تتضمن الإنشاء والتحرير واستخراج النص ودمج الشرائح والعمل مع القوالب باستخدام مكتبات مثل pptxgenjs و Python Markitdown."},"features":{"en":["Extract text content from .pptx files using `python -m markitdown presentation.pptx`","Generate presentations from scratch using the pptxgenjs library","Edit or create presentations from predefined templates","Unpack .pptx files into raw Office Open XML components with `office/unpack.py`","Create visual overviews/thumbnails of presentations using `thumbnail.py`"],"pt":["Extrai texto de apresentações com `python -m markitdown presentation.pptx`","Cria decks do zero usando a biblioteca pptxgenjs","Edita e atualiza apresentações existentes a partir de templates","Combina ou divide arquivos de slides com scripts personalizados","Analisa o XML bruto de arquivos .pptx com `office/unpack.py`","Gera miniaturas visuais usando `python scripts/thumbnail.py`"],"ru":["Извлекает текст из презентаций с помощью `python -m markitdown presentation.pptx`","Создает презентации с нуля с использованием библиотеки pptxgenjs","Редактирует и обновляет существующие презентации из шаблонов","Объединяет или разделяет файлы слайдов с помощью пользовательских скриптов","Анализирует сырой XML файлов .pptx с помощью `office/unpack.py`","Создает визуальные миниатюры с использованием `python scripts/thumbnail.py`"],"ar":["استخراج النص من العروض التقديمية باستخدام `python -m markitdown presentation.pptx`","إنشاء عروض من الصفر باستخدام مكتبة pptxgenjs","تحرير وتحديث العروض التقديمية الحالية من القوالب","دمج أو تقسيم ملفات الشرائح باستخدام نصوص برمجية مخصصة","تحليل XML الخام لملفات .pptx باستخدام `office/unpack.py`","إنشاء صور مصغرة مرئية باستخدام `python scripts/thumbnail.py`"]},"keywords":{"en":["how to extract text from pptx","pptx vs ppt","pptxgenjs tutorial","pptx install markitdown","parse powerpoint xml","pptx skill setup guide","what is pptx ai agent","edit pptx from template","pptx alternative python"],"pt":["skill pptx agentes IA","extrair texto pptx python","criar apresentação pptxgenjs","editar template pptx","combinar slides pptx","cli unpack pptx xml","automatizar apresentações","python markitdown pptx"],"ru":["навык PPTX ИИ Агенты","извлечь текст pptx python","создать презентацию pptxgenjs","редактировать шаблон pptx","объединить слайды pptx","cli распаковать pptx xml","автоматизировать презентации","python markitdown pptx"],"ar":["مهارة pptx أدوات الذكاء الاصطناعي","استخراج نص pptx python","إنشاء عرض تقديمي pptxgenjs","تحرير قالب pptx","دمج شرائح pptx","أمر CLI فك pptx xml","أتمتة العروض التقديمية","python markitdown pptx"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Content Analysis and Automation Agents needing to programmatically interact with PowerPoint presentations.","zh":"非常适合需要以编程方式与 PowerPoint 演示文稿交互的内容分析和自动化智能体。","ja":"PowerPointプレゼンテーションとプログラム的に連携する必要があるコンテンツ分析および自動化エージェントに最適です。","ko":"PowerPoint 프레젠테이션과 프로그래밍 방식으로 상호 작용해야 하는 콘텐츠 분석 및 자동화 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Análisis de Contenido y Automatización que necesitan interactuar programáticamente con presentaciones de PowerPoint.","fr":"Idéal pour les Agents d''Analyse de Contenu et d''Automatisation nécessitant une interaction programmatique avec les présentations PowerPoint.","de":"Perfekt für Inhaltsanalyse- und Automatisierungs-Agenten, die programmgesteuert mit PowerPoint-Präsentationen interagieren müssen.","pt":"Ideal para Agentes de Análise de Conteúdo e Automação que precisam interagir programaticamente com apresentações do PowerPoint.","ru":"Идеально подходит для агентов анализа контента и автоматизации, которым требуется программное взаимодействие с презентациями PowerPoint.","ar":"مثالي لوكلاء تحليل المحتوى والأتمتة الذين يحتاجون إلى التفاعل برمجيًا مع عروض PowerPoint التقديمية."},"recommendation":{"en":"Empowers agents to extract, analyze, and manipulate .pptx content through Python-based tools like markitdown for text extraction, pptxgenjs for creation, and direct XML manipulation via office unpacking scripts. Provides comprehensive handling of slide decks, templates, speaker notes, and comments.","zh":"通过基于 Python 的工具（如用于文本提取的 markitdown、用于创建的 pptxgenjs，以及通过 office unpacking 脚本进行直接 XML 操作），使智能体能够提取、分析和操作 .pptx 内容。提供对幻灯片组、模板、演讲者备注和评论的全面处理。","ja":"テキスト抽出のための markitdown、作成のための pptxgenjs、office unpacking スクリプトによる直接的な XML 操作など、Python ベースのツールを通じて、エージェントが .pptx コンテンツを抽出、分析、操作することを可能にします。スライドデッキ、テンプレート、スピーカーノート、コメントの包括的な処理を提供します。","ko":"텍스트 추출을 위한 markitdown, 생성용 pptxgenjs, office unpacking 스크립트를 통한 직접 XML 조작과 같은 Python 기반 도구를 통해 에이전트가 .pptx 콘텐츠를 추출, 분석 및 조작할 수 있도록 합니다. 슬라이드 덱, 템플릿, 발표자 노트 및 주석에 대한 포괄적인 처리를 제공합니다.","es":"Permite a los agentes extraer, analizar y manipular contenido .pptx mediante herramientas basadas en Python como markitdown para extracción de texto, pptxgenjs para creación y manipulación directa de XML mediante scripts de desempaquetado de office. Proporciona manejo integral de decks de diapositivas, plantillas, notas del orador y comentarios.","fr":"Permet aux agents d''extraire, d''analyser et de manipuler le contenu .ppx via des outils Python comme markitdown pour l''extraction de texte, pptxgenjs pour la création et la manipulation directe de XML via des scripts de déballage office. Offre une gestion complète des decks de diapositives, modèles, notes d''orateur et commentaires.","de":"Ermöglicht Agenten das Extrahieren, Analysieren und Manipulieren von .ppx-Inhalten durch Python-basierte Tools wie markitdown für Textextraktion, pptxgenjs für die Erstellung und direkte XML-Manipulation via Office-Unpacking-Scripts. Bietet umfassende Handhabung von Slide-Decks, Vorlagen, Sprechernotizen und Kommentaren.","pt":"Capacita os agentes a extrair, analisar e manipular conteúdo .pptx por meio de ferramentas baseadas em Python, como markitdown para extração de texto, pptxgenjs para criação e manipulação direta de XML via scripts de descompactação do office. Fornece manipulação abrangente de decks de slides, modelos, notas do orador e comentários.","ru":"Позволяет агентам извлекать, анализировать и манипулировать содержимым .pptx с помощью инструментов на базе Python, таких как markitdown для извлечения текста, pptxgenjs для создания и прямого манипулирования XML с помощью скриптов распаковки office. Обеспечивает комплексную обработку колод слайдов, шаблонов, speaker notes и комментариев.","ar":"يمكّن الوكلاء من استخراج وتحليل ومعالجة محتوى .pptx من خلال أدوات تعمل بـ Python مثل markitdown لاستخراج النص، و pptxgenjs للإنشاء، ومعالجة XML مباشرة عبر نصوص فك حزمة office. يوفر التعامل الشامل مع مجموعات الشرائح والقوالب وملاحظات المتحدث والتعليقات."},"useCases":{"en":["Extracting text content from presentations for summarization","Generating new slide decks from templates or scratch","Modifying existing presentations by editing layouts or content"],"zh":["从演示文稿中提取文本内容以进行摘要","从模板或从头开始生成新的幻灯片组","通过编辑布局或内容来修改现有的演示文稿"],"ja":["要約のためのプレゼンテーションからのテキストコンテンツの抽出","テンプレートまたはスクラッチからの新しいスライドデッキの生成","レイアウトやコンテンツの編集による既存プレゼンテーションの変更"],"ko":["요약을 위한 프레젠테이션에서 텍스트 콘텐츠 추출","템플릿이나 처음부터 새 슬라이드 덱 생성","레이아웃 또는 콘텐츠 편집을 통한 기존 프레젠테이션 수정"],"es":["Extracción de contenido textual de presentaciones para resumen","Generación de nuevos decks de diapositivas desde plantillas o desde cero","Modificación de presentaciones existentes mediante edición de diseños o contenido"],"fr":["Extraction de contenu textuel des présentations pour synthèse","Génération de nouveaux decks de diapositives à partir de modèles ou de zéro","Modification de présentations existantes par édition de mises en page ou de contenu"],"de":["Extrahieren von Textinhalten aus Präsentationen zur Zusammenfassung","Erstellen neuer Slide-Decks aus Vorlagen oder von Grund auf","Bearbeiten bestehender Präsentationen durch Layout- oder Inhaltsänderungen"],"pt":["Extrair conteúdo textual de apresentações para resumo","Gerar novos decks de slides a partir de modelos ou do zero","Modificar apresentações existentes editando layouts ou conteúdo"],"ru":["Извлечение текстового содержимого из презентаций для summarization","Создание новых колод слайдов из шаблонов или с нуля","Изменение существующих презентаций путем редактирования макетов или содержимого"],"ar":["استخراج المحتوى النصي من العروض التقديمية للتلخيص","إنشاء مجموعات شرائح جديدة من قوالب أو من الصفر","تعديل العروض التقديمية الحالية عن طريق تحرير التخطيطات أو المحتوى"]},"limitations":{"en":["Requires Python environment with specific scripts","Needs markitdown module for text extraction","XML manipulation requires technical understanding of .pptx structure"],"zh":["需要具有特定脚本的 Python 环境","文本提取需要 markitdown 模块","XML 操作需要 .pptx 结构的技术理解"],"ja":["特定のスクリプトを備えた Python 環境が必要","テキスト抽出には markitdown モジュールが必要","XML 操作には .pptx 構造の技術的理解が必要"],"ko":["특정 스크립트가 포함된 Python 환경 필요","텍스트 추출을 위해 markitdown 모듈 필요","XML 조작에는 .pptx 구조에 대한 기술적 이해 필요"],"es":["Requiere entorno Python con scripts específicos","Necesita el módulo markitdown para extracción de texto","La manipulación de XML requiere comprensión técnica de la estructura .ppx"],"fr":["Nécessite un environnement Python avec des scripts spécifiques","Requiert le module markitdown pour l''extraction de texte","La manipulation XML exige une compréhension technique de la structure .ppx"],"de":["Erfordert Python-Umgebung mit spezifischen Scripts","Benötigt markitdown-Modul für Textextraktion","XML-Manipulation erfordert technisches Verständnis der .ppx-Struktur"],"pt":["Requer um ambiente Python com scripts específicos","Necessita do módulo markitdown para extração de texto","A manipulação de XML requer compreensão técnica da estrutura .pptx"],"ru":["Требуется среда Python со specific scripts","Необходим модуль markitdown для извлечения текста","Манипулирование XML требует технического понимания структуры .pptx"],"ar":["يتطلب بيئة Python مع نصوص محددة","يحتاج إلى وحدة markitdown لاستخراج النص","تتطلب معالجة XML فهماً تقنياً لبنية .pptx"]},"version":4},"contentHash":"e5b0df918cbe9d62508b3cf808d73899633f82fc19f6258a25ef9f0de7e62125","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":71}');
