INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/pptx', 'pptx', 'anthropics', 'skills', 'official', 'pptx anthropics skills official agent-skills The PPTX skill enables AI agents to programmatically interact with PowerPoint (.pptx) files. It provides tools for developers to extract text, generate new presentations, and manipulate slide decks from the command line or via scripts. A skill pptx permite automatizar a criação, edição e análise de apresentações .pptx. Use comandos CLI como `python -m markitdown` para extrair texto ou `pptxgenjs` para gerar decks do zero, integrando perfeitamente com seus agentes de IA. Навык PPTX автоматизирует создание, редактирование и анализ презентаций .pptx. Используйте CLI команды, такие как `python -m markitdown` для извлечения текста или `pptxgenjs` для генерации презентаций с нуля, интегрируясь с ИИ Агентами. تتيح مهارة pptx أتمتة إنشاء وتحرير وتحليل العروض التقديمية .pptx. استخدم أوامر CLI مثل `python -m markitdown` لاستخراج النص أو `pptxgenjs` لإنشاء العروض من الصفر، مع التكامل السلس مع أدوات الذكاء الاصطناعي. how to extract text from pptx pptx vs ppt pptxgenjs tutorial pptx install markitdown parse powerpoint xml pptx skill setup guide what is pptx ai agent edit pptx from template pptx alternative python Extract text content from .pptx files using `python -m markitdown presentation.pptx` Generate presentations from scratch using the pptxgenjs library Edit or create presentations from predefined templates Unpack .pptx files into raw Office Open XML components with `office/unpack.py` Create visual overviews/thumbnails of presentations using `thumbnail.py` pptx is an AI agent skill for programmatically handling PowerPoint .pptx files. It provides capabilities for reading content via markitdown, creating presentations from scratch with pptxgenjs, editing from templates, and unpacking the raw Office Open XML structure for low-level manipulation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/slack-gif-creator', 'official', 'anthropics', 'skills', 'anthropics/skills', 'slack-gif-creator', 85097, 8974, 71, '2026-03-06T03:11:21Z', '2026-03-06T03:22:54.174Z', '2efca615ce55a3edd8fc05c779068a8085816617991987e446606403cd3abb22', '{"id":"anthropics/skills/slack-gif-creator","name":"slack-gif-creator","description":{"en":"The slack-gif-creator skill provides developers and AI agents with the technical knowledge and utilities to generate animated GIFs specifically optimized for Slack. It includes Slack''s required dimensions, FPS parameters, and a core GIFBuilder workflow using Python and PIL.","zh":"Slack GIF Creator工具包提供创建优化的Slack GIF的知识和实用工具，包括尺寸、参数和核心工作流程","ja":"Slack GIF作成ツールキットは、最適化されたSlack GIFを作成するための知識とユーティリティを提供します","ko":"슬랙 GIF 생성기工具包은 최적화된 슬랙 GIF를 생성하기 위한 지식과 유틸리티를 제공합니다","es":"Un conjunto de herramientas y conocimientos técnicos para crear GIFs animados optimizados para Slack. Proporciona restricciones de dimensiones, parámetros de FPS y color, y utilidades de validación integradas con Python y PIL.","fr":"Une boîte à outils et des connaissances techniques pour créer des GIFs animés optimisés pour Slack. Fournit des contraintes de dimensions, paramètres FPS et couleur, et des utilitaires de validation intégrés avec Python et PIL.","de":"Ein Toolkit und technisches Wissen zur Erstellung von für Slack optimierten animierten GIFs. Bietet Dimensionsbeschränkungen, FPS- und Farbparameter sowie Validierungsprogramme, die in Python und PIL integriert sind.","pt":"O criador de GIFs do Slack é uma ferramenta que fornece utilitários e conhecimentos para criar GIFs animados otimizados para o Slack.","ru":"Создатель GIF для Slack - это инструмент, который предоставляет утилиты и знания для создания анимированных GIF, оптимизированных для Slack.","ar":"مصمم GIF لسك هو أداة توفر أدوات و معارف لإنشاء صور GIF المتحركة المُحسّنة لسك"},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"slack-gif-creator","description":"Knowledge and utilities for creating animated GIFs optimized for Slack. Provides constraints, validation tools, and animation concepts. Use when users request animated GIFs for Slack like make me a GIF of X doing Y for Slack.","bodyPreview":"# Slack GIF Creator\n\nA toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack.\n\n## Slack Requirements\n\n**Dimensions:**\n- Emoji GIFs: 128x128 (recommended)\n- Message GIFs: 480x480\n\n**Parameters:**\n- FPS: 10-30 (lower is smaller file size)\n- Colors: 48-128 (fewer = smaller file size)\n- Duration: Keep under 3 seconds for emoji GIFs\n\n## Core Workflow\n\n```python\nfrom core.gif_builder import GIFBuilder\nfrom PIL import Image, ImageDraw\n\n# 1. Create builder\nbuilder = GI","body":"# Slack GIF Creator\n\nA toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack.\n\n## Slack Requirements\n\n**Dimensions:**\n- Emoji GIFs: 128x128 (recommended)\n- Message GIFs: 480x480\n\n**Parameters:**\n- FPS: 10-30 (lower is smaller file size)\n- Colors: 48-128 (fewer = smaller file size)\n- Duration: Keep under 3 seconds for emoji GIFs\n\n## Core Workflow\n\n```python\nfrom core.gif_builder import GIFBuilder\nfrom PIL import Image, ImageDraw\n\n# 1. Create builder\nbuilder = GIFBuilder(width=128, height=128, fps=10)\n\n# 2. Generate frames\nfor i in range(12):\n    frame = Image.new(''RGB'', (128, 128), (240, 248, 255))\n    draw = ImageDraw.Draw(frame)\n\n    # Draw your animation using PIL primitives\n    # (circles, polygons, lines, etc.)\n\n    builder.add_frame(frame)\n\n# 3. Save with optimization\nbuilder.save(''output.gif'', num_colors=48, optimize_for_emoji=True)\n```\n\n## Drawing Graphics\n\n### Working with User-Uploaded Images\nIf a user uploads an image, consider whether they want to:\n- **Use it directly** (e.g., \"animate this\", \"split this into frames\")\n- **Use it as inspiration** (e.g., \"make something like this\")\n\nLoad and work with images using PIL:\n```python\nfrom PIL import Image\n\nuploaded = Image.open(''file.png'')\n# Use directly, or just as reference for colors/style\n```\n\n### Drawing from Scratch\nWhen drawing graphics from scratch, use PIL ImageDraw primitives:\n\n```python\nfrom PIL import ImageDraw\n\ndraw = ImageDraw.Draw(frame)\n\n# Circles/ovals\ndraw.ellipse([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Stars, triangles, any polygon\npoints = [(x1, y1), (x2, y2), (x3, y3), ...]\ndraw.polygon(points, fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Lines\ndraw.line([(x1, y1), (x2, y2)], fill=(r, g, b), width=5)\n\n# Rectangles\ndraw.rectangle([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n```\n\n**Don''t use:** Emoji fonts (unreliable across platforms) or assume pre-packaged graphics exist in this skill.\n\n### Making Graphics Look Good\n\nGraphics should look polished and creative, not basic. Here''s how:\n\n**Use thicker lines** - Always set `width=2` or higher for outlines and lines. Thin lines (width=1) look choppy and amateurish.\n\n**Add visual depth**:\n- Use gradients for backgrounds (`create_gradient_background`)\n- Layer multiple shapes for complexity (e.g., a star with a smaller star inside)\n\n**Make shapes more interesting**:\n- Don''t just draw a plain circle - add highlights, rings, or patterns\n- Stars can have glows (draw larger, semi-transparent versions behind)\n- Combine multiple shapes (stars + sparkles, circles + rings)\n\n**Pay attention to colors**:\n- Use vibrant, complementary colors\n- Add contrast (dark outlines on light shapes, light outlines on dark shapes)\n- Consider the overall composition\n\n**For complex shapes** (hearts, snowflakes, etc.):\n- Use combinations of polygons and ellipses\n- Calculate points carefully for symmetry\n- Add details (a heart can have a highlight curve, snowflakes have intricate branches)\n\nBe creative and detailed! A good Slack GIF should look polished, not like placeholder graphics.\n\n## Available Utilities\n\n### GIFBuilder (`core.gif_builder`)\nAssembles frames and optimizes for Slack:\n```python\nbuilder = GIFBuilder(width=128, height=128, fps=10)\nbuilder.add_frame(frame)  # Add PIL Image\nbuilder.add_frames(frames)  # Add list of frames\nbuilder.save(''out.gif'', num_colors=48, optimize_for_emoji=True, remove_duplicates=True)\n```\n\n### Validators (`core.validators`)\nCheck if GIF meets Slack requirements:\n```python\nfrom core.validators import validate_gif, is_slack_ready\n\n# Detailed validation\npasses, info = validate_gif(''my.gif'', is_emoji=True, verbose=True)\n\n# Quick check\nif is_slack_ready(''my.gif''):\n    print(\"Ready!\")\n```\n\n### Easing Functions (`core.easing`)\nSmooth motion instead of linear:\n```python\nfrom core.easing import interpolate\n\n# Progress from 0.0 to 1.0\nt = i / (num_frames - 1)\n\n# Apply easing\ny = interpolate(start=0, end=400, t=t, easing=''ease_out'')\n\n# Available: linear, ease_in, ease_out, ease_in_out,\n#           bounce_out, elastic_out, back_out\n```\n\n### Frame Helpers (`core.frame_composer`)\nConvenience functions for common needs:\n```python\nfrom core.frame_composer import (\n    create_blank_frame,         # Solid color background\n    create_gradient_background,  # Vertical gradient\n    draw_circle,                # Helper for circles\n    draw_text,                  # Simple text rendering\n    draw_star                   # 5-pointed star\n)\n```\n\n## Animation Concepts\n\n### Shake/Vibrate\nOffset object position with oscillation:\n- Use `math.sin()` or `math.cos()` with frame index\n- Add small random variations for natural feel\n- Apply to x and/or y position\n\n### Pulse/Heartbeat\nScale object size rhythmically:\n- Use `math.sin(t * frequency * 2 * math.pi)` for smooth pulse\n- For heartbeat: two quick pulses then pause (adjust sine wave)\n- Scale between 0.8 and 1.2 of base size\n\n### Bounce\nObject falls and bounces:\n- Use `interpolate()` with `easing=''bounce_out''` for landing\n- Use `easing=''ease_in''` for falling (accelerating)\n- Apply gravity by increasing y velocity each frame\n\n### Spin/Rotate\nRotate object around center:\n- PIL: `image.rotate(angle, resample=Image.BICUBIC)`\n- For wobble: use sine wave for angle instead of linear\n\n### Fade In/Out\nGradually appear or disappear:\n- Create RGBA image, adjust alpha channel\n- Or use `Image.blend(image1, image2, alpha)`\n- Fade in: alpha from 0 to 1\n- Fade out: alpha from 1 to 0\n\n### Slide\nMove object from off-screen to position:\n- Start position: outside frame bounds\n- End position: target location\n- Use `interpolate()` with `easing=''ease_out''` for smooth stop\n- For overshoot: use `easing=''back_out''`\n\n### Zoom\nScale and position for zoom effect:\n- Zoom in: scale from 0.1 to 2.0, crop center\n- Zoom out: scale from 2.0 to 1.0\n- Can add motion blur for drama (PIL filter)\n\n### Explode/Particle Burst\nCreate particles radiating outward:\n- Generate particles with random angles and velocities\n- Update each particle: `x += vx`, `y += vy`\n- Add gravity: `vy += gravity_constant`\n- Fade out particles over time (reduce alpha)\n\n## Optimization Strategies\n\nOnly when asked to make the file size smaller, implement a few of the following methods:\n\n1. **Fewer frames** - Lower FPS (10 instead of 20) or shorter duration\n2. **Fewer colors** - `num_colors=48` instead of 128\n3. **Smaller dimensions** - 128x128 instead of 480x480\n4. **Remove duplicates** - `remove_duplicates=True` in save()\n5. **Emoji mode** - `optimize_for_emoji=True` auto-optimizes\n\n```python\n# Maximum optimization for emoji\nbuilder.save(\n    ''emoji.gif'',\n    num_colors=48,\n    optimize_for_emoji=True,\n    remove_duplicates=True\n)\n```\n\n## Philosophy\n\nThis skill provides:\n- **Knowledge**: Slack''s requirements and animation concepts\n- **Utilities**: GIFBuilder, validators, easing functions\n- **Flexibility**: Create the animation logic using PIL primitives\n\nIt does NOT provide:\n- Rigid animation templates or pre-made functions\n- Emoji font rendering (unreliable across platforms)\n- A library of pre-packaged graphics built into the skill\n\n**Note on user uploads**: This skill doesn''t include pre-built graphics, but if a user uploads an image, use PIL to load and work with it - interpret based on their request whether they want it used directly or just as inspiration.\n\nBe creative! Combine concepts (bouncing + rotating, pulsing + sliding, etc.) and use PIL''s full capabilities.\n\n## Dependencies\n\n```bash\npip install pillow imageio numpy\n```\n"},"category":"official","lastSynced":"2026-03-06T03:22:54.174Z","seo":{"title":{"en":"Slack GIF Creator: Optimized GIF Setup Guide | AI Agent S...","zh":"Slack GIFCreator 工具包设置指南","ja":"Slack GIF作成ツールキットのベストプラクティス","ko":"슬랙 GIF 생성기 설정 가이드","es":"Slack GIF Creator: Guía de Configuración y Mejores Prácticas","fr":"Slack GIF Creator : Guide de Configuration et Bonnes Prat...","de":"Slack GIF Creator: Setup Guide und Best Practices","pt":"Guia de Configuração do Criador de GIFs do Slack","ru":"Настройка ИИ Агента: Создателя GIF для Slack","ar":"دليل إعداد مصمم GIF لسك"},"description":{"en":"Learn how to build Slack-optimized animated GIFs with the slack-gif-creator AI skill. This toolkit provides specific constraints, validation tools, and a GIF...","zh":"了解Slack GIF Creator工具包的技术细节，包括尺寸、参数和核心工作流程，用于创建优化的Slack GIF","ja":"Slack GIF作成ツールキットの技術的な詳細を確認し、最適化されたSlack GIFを作成する","ko":"슬랙 GIF 생성기工具包의 기술 세부 사항을 살펴보고 최적화된 슬랙 GIF를 생성하는 방법","es":"Herramienta para crear GIFs animados optimizados para Slack. Incluye dimensiones específicas (128x128, 480x480), control de FPS (10-30), paleta de colores (4...","fr":"Outil pour créer des GIFs animés optimisés pour Slack. Inclut des dimensions spécifiques (128x128, 480x480), contrôle FPS (10-30), palette de couleurs (48-12...","de":"Toolkit zur Erstellung von für Slack optimierten animierten GIFs. Enthält spezifische Abmessungen (128x128, 480x480), FPS-Kontrolle (10-30), Farbpalette (48-...","pt":"Aprenda a criar GIFs animados otimizados para o Slack com nosso guia de configuração do criador de GIFs","ru":"Узнайте, как создавать анимированные GIF для Slack с помощью нашего ИИ Агента","ar":"تعرف على كيفية إنشاء صور GIF المتحركة المُحسّنة لسك مع دليلنا لإعداد مصمم GIF"},"definition":{"en":"slack-gif-creator is an AI agent skill providing a toolkit with utilities and knowledge for creating animated GIFs optimized for Slack. It offers specific constraints, validation tools, and a core workflow using GIFBuilder and the Python Imaging Library (PIL).","zh":"Slack GIF Creator工具包是一套用于创建优化的Slack GIF的知识和实用工具集合","ja":"Slack GIF作成ツールキットは、最適化されたSlack GIFを作成するためのツールキットです","ko":"슬랙 GIF 생성기工具包은 최적화된 슬랙 GIF를 생성하기 위한 도구 모음입니다","es":"Slack GIF Creator es una skill de IA Agents que proporciona utilidades y especificaciones técnicas para generar GIFs animados optimizados para la plataforma Slack, incluyendo dimensiones, FPS, paleta de colores y duración recomendada.","fr":"Slack GIF Creator est une compétence d''IA Agents qui fournit des utilitaires et des spécifications techniques pour générer des GIFs animés optimisés pour Slack, incluant dimensions, FPS, palette de couleurs et durée recommandée.","de":"Slack GIF Creator ist eine KI-Agenten-Fähigkeit, die Werkzeuge und technische Spezifikationen zur Generierung von für Slack optimierten animierten GIFs bereitstellt, einschließlich Abmessungen, FPS, Farbpalette und empfohlener Dauer.","pt":"O que é um criador de GIFs do Slack? É uma ferramenta que ajuda a criar GIFs animados para o Slack.","ru":"Что такое Создатель GIF для Slack? Это инструмент, который помогает создавать анимированные GIF для Slack.","ar":"ما هو مصمم GIF لسك? هو أداة تساعد على إنشاء صور GIF المتحركة لسك"},"features":{"en":["Provides Slack-specific dimension requirements (128x128 for emoji GIFs, 480x480 for message GIFs)","Configures GIF parameters including FPS (10-30) and color palette (48-128 colors)","Enforces duration constraints (under 3 seconds for emoji GIFs) for optimal file size","Includes a core GIFBuilder utility for programmatic GIF creation","Integrates with Python''s PIL (Pillow) library for image manipulation"],"zh":["支持创建128x128和480x480尺寸的GIF","提供FPS、颜色和持续时间的参数设置","核心工作流程使用Python和PIL库","支持创建emoji GIF和message GIF","提供GIF文件大小优化的功能"],"ja":["128x128と480x480のGIFサイズをサポート","FPS、色、durationのパラメータ設定を提供","コアワークフローはPythonとPILライブラリを使用","emoji GIFとmessage GIFの作成をサポート","GIFファイルサイズの最適化機能を提供"],"ko":["128x128과 480x480 크기의 GIF를 지원","FPS, 색상, 지속 시간의 매개 변수 설정을 제공","코어 워크플로는 Python과 PIL 라이브러리를 사용","이모지 GIF와 메시지 GIF의 생성을 지원","GIF 파일 크기 최적화 기능을 제공"],"es":["Dimensiones predefinidas para emojis (128x128) y mensajes (480x480)","Control de FPS entre 10-30 para optimizar el tamaño del archivo","Limitación de paleta de colores de 48-128 para reducir peso","Recomendación de duración máxima de 3 segundos para GIFs de emoji","Integración con bibliotecas Python como PIL para la creación de GIFs","Herramientas de validación para cumplir con los requisitos de Slack"],"fr":["Dimensions prédéfinies pour emojis (128x128) et messages (480x480)","Contrôle FPS entre 10-30 pour optimiser la taille du fichier","Limitation de palette de couleurs de 48-128 pour réduire le poids","Recommandation de durée maximale de 3 secondes pour GIFs emoji","Intégration avec bibliothèques Python comme PIL pour création GIF","Outils de validation pour respecter les exigences Slack"],"de":["Vordefinierte Abmessungen für Emojis (128x128) und Nachrichten (480x480)","FPS-Kontrolle zwischen 10-30 zur Dateigrößenoptimierung","Farbpalettenbegrenzung auf 48-128 zur Gewichtsreduzierung","Empfohlene Maximallänge von 3 Sekunden für Emoji-GIFs","Integration mit Python-Bibliotheken wie PIL zur GIF-Erstellung","Validierungstools zur Einhaltung der Slack-Anforderungen"],"pt":["Dimensões de GIF recomendadas: 128x128 para emojis e 480x480 para mensagens","Parâmetros de FPS: 10-30 para controle de tamanho de arquivo","Limites de cores: 48-128 para tamanho de arquivo menor","Duração de GIF: mantenha abaixo de 3 segundos para emojis","Utilização da biblioteca PIL para criação de imagens","Utilização do Python para desenvolvimento de GIFs"],"ru":["Рекомендуемые размеры GIF: 128x128 для эмодзи и 480x480 для сообщений","Параметры FPS: 10-30 для контроля размера файла","Ограничения цвета: 48-128 для меньшего размера файла","Продолжительность GIF: поддерживайте ниже 3 секунд для эмодзи","Использование библиотеки PIL для создания изображений","Использование Python для разработки GIF"],"ar":["أحجام GIF الموصى بها: 128x128 لرموز التعبير و 480x480 لرسائل","معاييرFPS: 10-30 للتحكم في حجم الملف","قيود الألوان: 48-128 للحصول على حجم ملف أصغر","مدة GIF: احتفظ بها أقل من 3 ثوانٍ لرموز التعبير","استخدام مكتبة PIL لإنشاء الصور","استخدام Python لتطوير GIF"]},"keywords":{"en":["how to use slack-gif-creator","slack gif creator setup guide","slack gif builder python","slack-gif-creator vs giphy","slack optimized gif parameters","slack-gif-creator install","what is slack-gif-creator","slack-gif-creator alternative","PIL create slack gif"],"zh":["Slack GIF Creator","AI工具","GIF创建","Slack优化","Python开发","PIL库","GIF文件大小优化"],"ja":["Slack GIF作成ツールキット","AIエージェント","GIF作成","Slack最適化","Python開発","PILライブラリ","GIFファイルサイズ最適化"],"ko":["슬랙 GIF 생성기","AI도구","GIF 생성","슬랙 최적화","Python 개발","PIL 라이브러리","GIF 파일 크기 최적화"],"es":["slack gif creator","crear gifs para slack","optimizar gifs slack","dimensiones gif slack","python pil crear gif","fps optimo gif slack","toolkit gif animados slack","validacion gif slack","agentes ia crear gifs","slack gif builder python"],"fr":["slack gif creator","créer gifs pour slack","optimiser gifs slack","dimensions gif slack","python pil créer gif","fps optimal gif slack","boîte à outils gifs animés slack","validation gif slack","agents ia créer gifs","slack gif builder python"],"de":["slack gif creator","gifs für slack erstellen","gifs für slack optimieren","gif abmessungen slack","python pil gif erstellen","optimale fps slack gif","toolkit animierte gifs slack","gif validation slack","ki agenten gifs erstellen","slack gif builder python"],"pt":["criador de GIFs do Slack","GIFs animados para o Slack","otimização de GIFs","dimensões de GIF","parâmetros de FPS","limites de cores","duração de GIF","biblioteca PIL","Python para desenvolvimento de GIFs"],"ru":["Создатель GIF для Slack","Анимированные GIF для Slack","Оптимизация GIF","Размеры GIF","Параметры FPS","Ограничения цвета","Продолжительность GIF","Библиотека PIL","Python для разработки GIF"],"ar":["مصمم GIF لسك","صور GIF المتحركة لسك","تحسين صور GIF","أحجام GIF","معايير FPS","قيود الألوان","مدة GIF","مكتبة PIL","Python لتطوير GIF"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Python-based Content Creation Agents needing Slack-optimized animated GIF generation.","zh":"非常适合需要为 Slack 优化动画 GIF 生成的基于 Python 的内容创作智能体。","ja":"Slack 向けに最適化されたアニメーションGIF生成を必要とするPythonベースのコンテンツ作成エージェントに最適です。","ko":"Slack에 최적화된 애니메이션 GIF 생성을 필요로 하는 Python 기반 콘텐츠 생성 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Creación de Contenido basados en Python que necesitan generación de GIF animados optimizados para Slack.","fr":"Parfait pour les Agents de Création de Contenu basés sur Python ayant besoin d''une génération de GIF animés optimisée pour Slack.","de":"Perfekt für Python-basierte Content Creation Agents, die eine für Slack optimierte animierte GIF-Generierung benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo baseados em Python que necessitam de geração de GIF animados otimizados para o Slack.","ru":"Идеально подходит для агентов по созданию контента на базе Python, которым требуется создание анимированных GIF-изображений, оптимизированных для Slack.","ar":"مثالي لوكلاء إنشاء المحتوى القائم على Python الذين يحتاجون إلى إنشاء صور GIF متحركة مُحسنة لـ Slack."},"recommendation":{"en":"Empowers agents to create animated GIFs specifically optimized for Slack''s platform requirements using PIL (Pillow) and custom GIF building utilities. Provides dimension constraints (128x128 for emojis, 480x480 for messages), FPS optimization (10-30 range), and color reduction techniques (48-128 colors) for optimal file size and performance.","zh":"赋能智能体使用 PIL (Pillow) 和自定义 GIF 构建工具，创建专门针对 Slack 平台要求优化的动画 GIF。提供尺寸限制（表情符号为 128x128，消息为 480x480）、FPS 优化（10-30 范围）和颜色减少技术（48-128 种颜色），以实现最佳文件大小和性能。","ja":"PIL (Pillow) とカスタムGIFビルドユーティリティを使用して、Slackのプラットフォーム要件に特化して最適化されたアニメーションGIFを作成する機能をエージェントに提供します。最適なファイルサイズとパフォーマンスを実現するために、寸法制約（絵文字は128x128、メッセージは480x480）、FPS最適化（10-30範囲）、および色数削減技術（48-128色）を提供します。","ko":"PIL(Pillow) 및 사용자 정의 GIF 빌드 유틸리티를 사용하여 Slack 플랫폼 요구 사항에 특화되어 최적화된 애니메이션 GIF를 생성하는 기능을 에이전트에 부여합니다. 최적의 파일 크기와 성능을 위해 치수 제약(이모지는 128x128, 메시지는 480x480), FPS 최적화(10-30 범위) 및 색상 감소 기술(48-128색)을 제공합니다.","es":"Permite a los agentes crear GIF animados específicamente optimizados para los requisitos de la plataforma Slack utilizando PIL (Pillow) y utilidades personalizadas de construcción de GIF. Proporciona restricciones de dimensiones (128x128 para emojis, 480x480 para mensajes), optimización de FPS (rango de 10-30) y técnicas de reducción de color (48-128 colores) para un tamaño de archivo y rendimiento óptimos.","fr":"Permet aux agents de créer des GIF animés spécifiquement optimisés pour les exigences de la plateforme Slack en utilisant PIL (Pillow) et des utilitaires personnalisés de construction de GIF. Fournit des contraintes de dimensions (128x128 pour les emojis, 480x480 pour les messages), une optimisation des FPS (plage de 10-30) et des techniques de réduction de couleur (48-128 couleurs) pour une taille de fichier et des performances optimales.","de":"Ermöglicht es Agents, animierte GIFs zu erstellen, die speziell für die Plattformanforderungen von Slack optimiert sind, unter Verwendung von PIL (Pillow) und benutzerdefinierten GIF-Building-Utilities. Bietet Dimensionsbeschränkungen (128x128 für Emojis, 480x480 für Nachrichten), FPS-Optimierung (Bereich 10-30) und Farbreduktionstechniken (48-128 Farben) für optimale Dateigröße und Leistung.","pt":"Capacita os agentes a criar GIFs animados especificamente otimizados para os requisitos da plataforma Slack usando PIL (Pillow) e utilitários personalizados de construção de GIF. Fornece restrições de dimensão (128x128 para emojis, 480x480 para mensagens), otimização de FPS (faixa de 10-30) e técnicas de redução de cores (48-128 cores) para tamanho de arquivo e desempenho ideais.","ru":"Позволяет агентам создавать анимированные GIF-изображения, специально оптимизированные под требования платформы Slack, с использованием PIL (Pillow) и пользовательских утилит для создания GIF. Предоставляет ограничения по размерам (128x128 для эмодзи, 480x480 для сообщений), оптимизацию кадровой частоты (диапазон 10-30 FPS) и методы уменьшения количества цветов (48-128 цветов) для оптимального размера файла и производительности.","ar":"يمكن الوكلاء من إنشاء صور GIF متحركة مُحسنة خصيصًا لمتطلبات منصة Slack باستخدام PIL (Pillow) وأدوات إنشاء GIF المخصصة. يوفر قيود الأبعاد (128x128 للرموز التعبيرية، 480x480 للرسائل)، وتحسين معدل الإطارات (نطاق 10-30)، وتقنيات تقليل الألوان (48-128 لونًا) للحصول على حجم ملف وأداء مثاليين."},"useCases":{"en":["Generating Slack emoji GIFs with precise 128x128 dimensions","Creating message-embedded GIFs at 480x480 resolution","Optimizing animation parameters for minimal file size","Validating GIF specifications against Slack''s requirements"],"zh":["生成具有精确 128x128 尺寸的 Slack 表情符号 GIF","创建 480x480 分辨率的消息嵌入式 GIF","为最小文件大小优化动画参数","根据 Slack 的要求验证 GIF 规格"],"ja":["正確な128x128サイズのSlack絵文字GIFを生成する","480x480解像度のメッセージ埋め込みGIFを作成する","最小ファイルサイズのためにアニメーションパラメータを最適化する","Slackの要件に対してGIF仕様を検証する"],"ko":["정확한 128x128 크기의 Slack 이모지 GIF 생성","480x480 해상도의 메시지 임베디드 GIF 생성","최소 파일 크기를 위한 애니메이션 매개변수 최적화","Slack의 요구 사항에 대해 GIF 사양 검증"],"es":["Generación de GIFs para emojis de Slack con dimensiones precisas de 128x128","Creación de GIFs incrustados en mensajes con una resolución de 480x480","Optimización de parámetros de animación para un tamaño de archivo mínimo","Validación de especificaciones de GIF según los requisitos de Slack"],"fr":["Génération de GIF pour emojis Slack avec des dimensions précises de 128x128","Création de GIF intégrés aux messages avec une résolution de 480x480","Optimisation des paramètres d''animation pour une taille de fichier minimale","Validation des spécifications GIF par rapport aux exigences de Slack"],"de":["Generierung von Slack-Emoji-GIFs mit präzisen 128x128 Abmessungen","Erstellung von nachrichteneingebetteten GIFs mit 480x480 Auflösung","Optimierung von Animationsparametern für minimale Dateigröße","Validierung von GIF-Spezifikationen gegen die Anforderungen von Slack"],"pt":["Geração de GIFs de emoji do Slack com dimensões precisas de 128x128","Criação de GIFs incorporados em mensagens com resolução de 480x480","Otimização de parâmetros de animação para tamanho de arquivo mínimo","Validação de especificações de GIF em relação aos requisitos do Slack"],"ru":["Создание GIF-эмодзи для Slack с точными размерами 128x128","Создание GIF-изображений для встраивания в сообщения с разрешением 480x480","Оптимизация параметров анимации для минимального размера файла","Проверка спецификаций GIF на соответствие требованиям Slack"],"ar":["إنشاء رموز GIF تعبيرية لـ Slack بأبعاد دقيقة 128x128","إنشاء صور GIF مدمجة في الرسائل بدقة 480x480","تحسين معلمات الرسوم المتحركة لأصغر حجم ملف","التحقق من مواصفات GIF مقابل متطلبات Slack"]},"limitations":{"en":["Requires PIL (Pillow) library installation","Limited to Python-based GIF generation workflows","Focuses exclusively on Slack platform optimization","Requires manual animation concept implementation"],"zh":["需要安装 PIL (Pillow) 库","仅限于基于 Python 的 GIF 生成工作流程","仅专注于 Slack 平台优化","需要手动实现动画概念"],"ja":["PIL (Pillow) ライブラリのインストールが必要","PythonベースのGIF生成ワークフローに限定される","Slackプラットフォームの最適化にのみ焦点を当てている","アニメーションコンセプトの手動実装が必要"],"ko":["PIL(Pillow) 라이브러리 설치 필요","Python 기반 GIF 생성 워크플로우로 제한됨","Slack 플랫폼 최적화에만 집중함","수동 애니메이션 개념 구현 필요"],"es":["Requiere la instalación de la librería PIL (Pillow)","Limitado a flujos de trabajo de generación de GIF basados en Python","Se centra exclusivamente en la optimización para la plataforma Slack","Requiere la implementación manual del concepto de animación"],"fr":["Nécessite l''installation de la bibliothèque PIL (Pillow)","Limité aux workflows de génération de GIF basés sur Python","Se concentre exclusivement sur l''optimisation pour la plateforme Slack","Nécessite une implémentation manuelle du concept d''animation"],"de":["Erfordert die Installation der PIL (Pillow) Bibliothek","Beschränkt auf Python-basierte GIF-Generierungs-Workflows","Konzentriert sich ausschließlich auf die Optimierung für die Slack-Plattform","Erfordert die manuelle Implementierung des Animationskonzepts"],"pt":["Requer a instalação da biblioteca PIL (Pillow)","Limitado a fluxos de trabalho de geração de GIF baseados em Python","Foca exclusivamente na otimização da plataforma Slack","Requer a implementação manual do conceito de animação"],"ru":["Требует установки библиотеки PIL (Pillow)","Ограничено рабочими процессами создания GIF на основе Python","Сосредоточено исключительно на оптимизации для платформы Slack","Требует ручной реализации концепции анимации"],"ar":["يتطلب تثبيت مكتبة PIL (Pillow)","يقتصر على سير عمل إنشاء GIF القائم على Python","يركز حصريًا على تحسين منصة Slack","يتطلب التنفيذ اليدوي لفكرة الرسوم المتحركة"]},"version":4},"contentHash":"2efca615ce55a3edd8fc05c779068a8085816617991987e446606403cd3abb22","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":71}');
