INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/slack-gif-creator', 'slack-gif-creator', 'anthropics', 'skills', 'official', 'slack-gif-creator anthropics skills official agent-skills The slack-gif-creator skill provides developers and AI agents with the technical knowledge and utilities to generate animated GIFs specifically optimized for Slack. It includes Slack''s required dimensions, FPS parameters, and a core GIFBuilder workflow using Python and PIL. Slack GIF Creator工具包提供创建优化的Slack GIF的知识和实用工具，包括尺寸、参数和核心工作流程 Slack GIF作成ツールキットは、最適化されたSlack GIFを作成するための知識とユーティリティを提供します 슬랙 GIF 생성기工具包은 최적화된 슬랙 GIF를 생성하기 위한 지식과 유틸리티를 제공합니다 Un conjunto de herramientas y conocimientos técnicos para crear GIFs animados optimizados para Slack. Proporciona restricciones de dimensiones, parámetros de FPS y color, y utilidades de validación integradas con Python y PIL. Une boîte à outils et des connaissances techniques pour créer des GIFs animés optimisés pour Slack. Fournit des contraintes de dimensions, paramètres FPS et couleur, et des utilitaires de validation intégrés avec Python et PIL. Ein Toolkit und technisches Wissen zur Erstellung von für Slack optimierten animierten GIFs. Bietet Dimensionsbeschränkungen, FPS- und Farbparameter sowie Validierungsprogramme, die in Python und PIL integriert sind. O criador de GIFs do Slack é uma ferramenta que fornece utilitários e conhecimentos para criar GIFs animados otimizados para o Slack. Создатель GIF для Slack - это инструмент, который предоставляет утилиты и знания для создания анимированных GIF, оптимизированных для Slack. مصمم GIF لسك هو أداة توفر أدوات و معارف لإنشاء صور GIF المتحركة المُحسّنة لسك how to use slack-gif-creator slack gif creator setup guide slack gif builder python slack-gif-creator vs giphy slack optimized gif parameters slack-gif-creator install what is slack-gif-creator slack-gif-creator alternative PIL create slack gif Slack GIF Creator AI工具 GIF创建 Slack优化 Python开发 PIL库 GIF文件大小优化 Provides Slack-specific dimension requirements (128x128 for emoji GIFs, 480x480 for message GIFs) Configures GIF parameters including FPS (10-30) and color palette (48-128 colors) Enforces duration constraints (under 3 seconds for emoji GIFs) for optimal file size Includes a core GIFBuilder utility for programmatic GIF creation Integrates with Python''s PIL (Pillow) library for image manipulation slack-gif-creator is an AI agent skill providing a toolkit with utilities and knowledge for creating animated GIFs optimized for Slack. It offers specific constraints, validation tools, and a core workflow using GIFBuilder and the Python Imaging Library (PIL).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/web-artifacts-builder', 'official', 'anthropics', 'skills', 'anthropics/skills', 'web-artifacts-builder', 85097, 8974, 71, '2026-03-06T03:11:21Z', '2026-03-06T03:24:48.498Z', '81c5002c6643b0de7b8710b00e7a9038daa6fb9b68d59870ee6adb12da8d10f8', '{"id":"anthropics/skills/web-artifacts-builder","name":"web-artifacts-builder","description":{"en":"The web-artifacts-builder is a specialized AI agent skill that provides a suite of tools for developers to create sophisticated, multi-component HTML artifacts for claude.ai. It leverages a modern stack including React 18, TypeScript, Vite, and Parcel to bundle complex frontend applications into ...","zh":"Web Artifacts Builder 是一个用于创建复杂 AI 代理 HTML 构件的工具套件，使用 React、Tailwind CSS 和 shadcn/ui","ja":"Web Artifacts Builder は、AIエージェントのための複雑な HTML アーティファクトを作成するためのツールのセットです。React、Tailwind CSS、shadcn/ui を使用します","ko":"Web Artifacts Builder는 복잡한 AI 도구 HTML 아티팩트를 생성하기 위한 도구 세트입니다. React, Tailwind CSS, shadcn/ui를 사용합니다","es":"Suite de herramientas para desarrollar artefactos HTML complejos en claude.ai utilizando tecnologías web modernas como React 18, TypeScript, Vite y Tailwind CSS. Incluye scripts automatizados para inicializar proyectos y generar archivos HTML bundleados.","fr":"Suite d''outils pour développer des artefacts HTML complexes sur claude.ai en utilisant des technologies web modernes comme React 18, TypeScript, Vite et Tailwind CSS. Inclut des scripts automatisés pour initialiser des projets et générer des fichiers HTML bundle.","de":"Tool-Suite zur Entwicklung komplexer HTML-Artefakte in claude.ai mit modernen Web-Technologien wie React 18, TypeScript, Vite und Tailwind CSS. Enthält automatisierte Skripte zur Projektinitialisierung und Generierung gebündelter HTML-Dateien.","pt":"Suite de ferramentas para criar artefatos HTML complexos no claude.ai usando React 18, TypeScript, Vite, Tailwind CSS e shadcn/ui. Inclui scripts de inicialização e bundling para componentes multi-arquivo.","ru":"Набор инструментов для создания сложных HTML артефактов в claude.ai с использованием React 18, TypeScript, Vite, Tailwind CSS и shadcn/ui. Включает скрипты инициализации и сборки для многокомпонентных проектов.","ar":"مجموعة أدوات لإنشاء قطع HTML معقدة في claude.ai باستخدام React 18 وTypeScript وVite وTailwind CSS وshadcn/ui. تتضمن نصوص تهيئة وحزمة للمشاريع متعددة المكونات."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"web-artifacts-builder","description":"Suite of tools for creating elaborate, multi-component claude.ai HTML artifacts using modern frontend web technologies (React, Tailwind CSS, shadcn/ui). Use for complex artifacts requiring state management, routing, or shadcn/ui components - not for simple single-file HTML/JSX artifacts.","bodyPreview":"# Web Artifacts Builder\n\nTo build powerful frontend claude.ai artifacts, follow these steps:\n1. Initialize the frontend repo using `scripts/init-artifact.sh`\n2. Develop your artifact by editing the generated code\n3. Bundle all code into a single HTML file using `scripts/bundle-artifact.sh`\n4. Display artifact to user\n5. (Optional) Test the artifact\n\n**Stack**: React 18 + TypeScript + Vite + Parcel (bundling) + Tailwind CSS + shadcn/ui\n\n## Design & Style Guidelines\n\nVERY IMPORTANT: To avoid what","body":"# Web Artifacts Builder\n\nTo build powerful frontend claude.ai artifacts, follow these steps:\n1. Initialize the frontend repo using `scripts/init-artifact.sh`\n2. Develop your artifact by editing the generated code\n3. Bundle all code into a single HTML file using `scripts/bundle-artifact.sh`\n4. Display artifact to user\n5. (Optional) Test the artifact\n\n**Stack**: React 18 + TypeScript + Vite + Parcel (bundling) + Tailwind CSS + shadcn/ui\n\n## Design & Style Guidelines\n\nVERY IMPORTANT: To avoid what is often referred to as \"AI slop\", avoid using excessive centered layouts, purple gradients, uniform rounded corners, and Inter font.\n\n## Quick Start\n\n### Step 1: Initialize Project\n\nRun the initialization script to create a new React project:\n```bash\nbash scripts/init-artifact.sh <project-name>\ncd <project-name>\n```\n\nThis creates a fully configured project with:\n- ✅ React + TypeScript (via Vite)\n- ✅ Tailwind CSS 3.4.1 with shadcn/ui theming system\n- ✅ Path aliases (`@/`) configured\n- ✅ 40+ shadcn/ui components pre-installed\n- ✅ All Radix UI dependencies included\n- ✅ Parcel configured for bundling (via .parcelrc)\n- ✅ Node 18+ compatibility (auto-detects and pins Vite version)\n\n### Step 2: Develop Your Artifact\n\nTo build the artifact, edit the generated files. See **Common Development Tasks** below for guidance.\n\n### Step 3: Bundle to Single HTML File\n\nTo bundle the React app into a single HTML artifact:\n```bash\nbash scripts/bundle-artifact.sh\n```\n\nThis creates `bundle.html` - a self-contained artifact with all JavaScript, CSS, and dependencies inlined. This file can be directly shared in Claude conversations as an artifact.\n\n**Requirements**: Your project must have an `index.html` in the root directory.\n\n**What the script does**:\n- Installs bundling dependencies (parcel, @parcel/config-default, parcel-resolver-tspaths, html-inline)\n- Creates `.parcelrc` config with path alias support\n- Builds with Parcel (no source maps)\n- Inlines all assets into single HTML using html-inline\n\n### Step 4: Share Artifact with User\n\nFinally, share the bundled HTML file in conversation with the user so they can view it as an artifact.\n\n### Step 5: Testing/Visualizing the Artifact (Optional)\n\nNote: This is a completely optional step. Only perform if necessary or requested.\n\nTo test/visualize the artifact, use available tools (including other Skills or built-in tools like Playwright or Puppeteer). In general, avoid testing the artifact upfront as it adds latency between the request and when the finished artifact can be seen. Test later, after presenting the artifact, if requested or if issues arise.\n\n## Reference\n\n- **shadcn/ui components**: https://ui.shadcn.com/docs/components"},"category":"official","lastSynced":"2026-03-06T03:24:48.498Z","seo":{"title":{"en":"web-artifacts-builder: Build Complex Claude.ai HTML Artif...","zh":"Web Artifacts Builder.setup 指南 - 使用 React 和 Tailwind CSS","ja":"Web Artifacts Builder 導入ガイド - AIエージェントのための React と Tailwi...","ko":"Web Artifacts Builder 설정 가이드 - React, Tailwind CSS, AI 도구","es":"web-artifacts-builder: Guía de configuración para artefac...","fr":"web-artifacts-builder: Guide de configuration pour artefa...","de":"web-artifacts-builder: Setup-Anleitung für HTML-Artefakte...","pt":"web-artifacts-builder: Guia de Configuração para Artefato...","ru":"web-artifacts-builder: Руководство по настройке для сложн...","ar":"web-artifacts-builder: دليل الإعداد لإنشاء قطع HTML معقدة..."},"description":{"en":"Learn how to use the web-artifacts-builder AI agent skill to generate single HTML files from React, TypeScript, and shadcn/ui projects for Claude.ai. Include...","zh":"使用 Web Artifacts Builder 创建复杂的 AI 代理 HTML 构件，利用 React、Tailwind CSS 和 shadcn/ui","ja":"AIエージェントのための複雑な HTML アーティファクトを作成する、Web Artifacts Builder を使用して React と Tailwind CSS を活用する","ko":"Web Artifacts Builder로 복잡한 AI 도구 HTML 아티팩트를 생성하여 React, Tailwind CSS, shadcn/ui를 활용합니다","es":"Suite de herramientas para crear artefactos HTML complejos en claude.ai con React 18, TypeScript, Vite y shadcn/ui. Incluye scripts de inicialización y bundl...","fr":"Suite d''outils pour créer des artefacts HTML complexes sur claude.ai avec React 18, TypeScript, Vite et shadcn/ui. Inclut des scripts d''initialisation et de ...","de":"Tool-Suite zur Erstellung komplexer HTML-Artefakte in claude.ai mit React 18, TypeScript, Vite und shadcn/ui. Enth