INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/web-artifacts-builder', 'web-artifacts-builder', 'anthropics', 'skills', 'official', 'web-artifacts-builder anthropics skills official agent-skills The web-artifacts-builder is a specialized AI agent skill that provides a suite of tools for developers to create sophisticated, multi-component HTML artifacts for claude.ai. It leverages a modern stack including React 18, TypeScript, Vite, and Parcel to bundle complex frontend applications into ... Web Artifacts Builder 是一个用于创建复杂 AI 代理 HTML 构件的工具套件，使用 React、Tailwind CSS 和 shadcn/ui Web Artifacts Builder は、AIエージェントのための複雑な HTML アーティファクトを作成するためのツールのセットです。React、Tailwind CSS、shadcn/ui を使用します Web Artifacts Builder는 복잡한 AI 도구 HTML 아티팩트를 생성하기 위한 도구 세트입니다. React, Tailwind CSS, shadcn/ui를 사용합니다 Suite de herramientas para desarrollar artefactos HTML complejos en claude.ai utilizando tecnologías web modernas como React 18, TypeScript, Vite y Tailwind CSS. Incluye scripts automatizados para inicializar proyectos y generar archivos HTML bundleados. Suite d''outils pour développer des artefacts HTML complexes sur claude.ai en utilisant des technologies web modernes comme React 18, TypeScript, Vite et Tailwind CSS. Inclut des scripts automatisés pour initialiser des projets et générer des fichiers HTML bundle. Tool-Suite zur Entwicklung komplexer HTML-Artefakte in claude.ai mit modernen Web-Technologien wie React 18, TypeScript, Vite und Tailwind CSS. Enthält automatisierte Skripte zur Projektinitialisierung und Generierung gebündelter HTML-Dateien. Suite de ferramentas para criar artefatos HTML complexos no claude.ai usando React 18, TypeScript, Vite, Tailwind CSS e shadcn/ui. Inclui scripts de inicialização e bundling para componentes multi-arquivo. Набор инструментов для создания сложных HTML артефактов в claude.ai с использованием React 18, TypeScript, Vite, Tailwind CSS и shadcn/ui. Включает скрипты инициализации и сборки для многокомпонентных проектов. مجموعة أدوات لإنشاء قطع HTML معقدة في claude.ai باستخدام React 18 وTypeScript وVite وTailwind CSS وshadcn/ui. تتضمن نصوص تهيئة وحزمة للمشاريع متعددة المكونات. how to use web-artifacts-builder web-artifacts-builder vs simple html web-artifacts-builder install web-artifacts-builder setup guide what is web-artifacts-builder claude web-artifacts-builder react typescript web-artifacts-builder bundle artifact script web-artifacts-builder shadcn ui components Web Artifacts Builder AI 代理 React Tailwind CSS shadcn/ui Vite Parcel 状态管理 路由 Initializes frontend repositories using the `scripts/init-artifact.sh` shell script Bundles entire React application code into a single HTML file using `scripts/bundle-artifact.sh` and Parcel Leverages the modern Vite build tool for development and bundling Integrates the shadcn/ui component library for building sophisticated UIs Utilizes Tailwind CSS for utility-first styling within artifacts Supports complex artifacts requiring state management and routing with React 18 web-artifacts-builder is an AI agent skill providing a development suite for building complex claude.ai HTML artifacts. It uses a React 18, TypeScript, Vite, and Parcel stack with Tailwind CSS and shadcn/ui, bundling multi-component apps into a single HTML file via specific shell scripts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/receiving-code-review', 'official', 'obra', 'superpowers', 'obra/superpowers', 'receiving-code-review', 71924, 5546, 71, '2026-03-06T03:26:30Z', '2026-03-06T03:31:30.731Z', 'c9382e92b8f32363566068ecfed19d3b2651eaf40d3942b24840f839dedfc406', '{"id":"obra/superpowers/receiving-code-review","name":"receiving-code-review","description":{"en":"This AI agent skill provides a structured protocol for technically evaluating code review feedback before implementation. It benefits developers and AI agents by prioritizing verification and technical rigor over performative agreement, preventing the merging of unclear or incorrect suggestions.","zh":"代码审查接收需要技术上的严谨性和验证，而不是简单的同意或盲目实现。使用AIエージェント可以帮助您高效地接收和处理代码审查反馈","ja":"コードレビューの受信には技術的な厳格性と検証が必要であり、単なる同意や盲目的な実装ではありません。AIエージェントを使用すると、コードレビューのフィードバックを受け取って処理することができます","ko":"코드 리뷰 수신에는 기술적인 엄谨성과 검증이 필요하며, 단순한 동의나 무조건적인 구현은 아닙니다. AI 에이전트를 사용하면 코드 리뷰 피드백을 효과적으로 받고 처리할 수 있습니다","es":"Recibir revisiones de código de manera efectiva requiere rigor técnico y verificación","fr":"Recevoir des revues de code de manière efficace nécessite une rigueur technique et une vérification","de":"Die effektive Entgegennahme von Code-Reviews erfordert technische Strenge und Überprüfung","pt":"Uma habilidade técnica de IA que orienta desenvolvedores no processo de receber feedback de code review. Foca em verificação técnica rigorosa, compreensão clara dos requisitos e avaliação contra a realidade do codebase antes da implementação.","ru":"Технический навык ИИ, который направляет разработчиков в процессе получения фидбэка code review. Акцент на техническую проверку, четкое понимание требований и оценку против кодовой базы.","ar":"مهارة تقنية للذكاء الاصطناعي توجه المطورين في عملية استقبال ملاحظات مراجعة الكود. تركز على التحقق التقني الدقيق والفهم الواضح للمتطلبات والتقييم ضد قاعدة الكود."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"receiving-code-review","description":"Use when receiving code review feedback, before implementing suggestions, especially if feedback seems unclear or technically questionable - requires technical rigor and verification, not performative agreement or blind implementation","bodyPreview":"# Code Review Reception\n\n## Overview\n\nCode review requires technical evaluation, not emotional performance.\n\n**Core principle:** Verify before implementing. Ask before assuming. Technical correctness over social comfort.\n\n## The Response Pattern\n\n```\nWHEN receiving code review feedback:\n\n1. READ: Complete feedback without reacting\n2. UNDERSTAND: Restate requirement in own words (or ask)\n3. VERIFY: Check against codebase reality\n4. EVALUATE: Technically sound for THIS codebase?\n5. RESPOND: Techni","body":"# Code Review Reception\n\n## Overview\n\nCode review requires technical evaluation, not emotional performance.\n\n**Core principle:** Verify before implementing. Ask before assuming. Technical correctness over social comfort.\n\n## The Response Pattern\n\n```\nWHEN receiving code review feedback:\n\n1. READ: Complete feedback without reacting\n2. UNDERSTAND: Restate requirement in own words (or ask)\n3. VERIFY: Check against codebase reality\n4. EVALUATE: Technically sound for THIS codebase?\n5. RESPOND: Technical acknowledgment or reasoned pushback\n6. IMPLEMENT: One item at a time, test each\n```\n\n## Forbidden Responses\n\n**NEVER:**\n- \"You''re absolutely right!\" (explicit CLAUDE.md violation)\n- \"Great point!\" / \"Excellent feedback!\" (performative)\n- \"Let me implement that now\" (before verification)\n\n**INSTEAD:**\n- Restate the technical requirement\n- Ask clarifying questions\n- Push back with technical reasoning if wrong\n- Just start working (actions > words)\n\n## Handling Unclear Feedback\n\n```\nIF any item is unclear:\n  STOP - do not implement anything yet\n  ASK for clarification on unclear items\n\nWHY: Items may be related. Partial understanding = wrong implementation.\n```\n\n**Example:**\n```\nyour human partner: \"Fix 1-6\"\nYou understand 1,2,3,6. Unclear on 4,5.\n\n❌ WRONG: Implement 1,2,3,6 now, ask about 4,5 later\n✅ RIGHT: \"I understand items 1,2,3,6. Need clarification on 4 and 5 before proceeding.\"\n```\n\n## Source-Specific Handling\n\n### From your human partner\n- **Trusted** - implement after understanding\n- **Still ask** if scope unclear\n- **No performative agreement**\n- **Skip to action** or technical acknowledgment\n\n### From External Reviewers\n```\nBEFORE implementing:\n  1. Check: Technically correct for THIS codebase?\n  2. Check: Breaks existing functionality?\n  3. Check: Reason for current implementation?\n  4. Check: Works on all platforms/versions?\n  5. Check: Does reviewer understand full context?\n\nIF suggestion seems wrong:\n  Push back with technical reasoning\n\nIF can''t easily verify:\n  Say so: \"I can''t verify this without [X]. Should I [investigate/ask/proceed]?\"\n\nIF conflicts with your human partner''s prior decisions:\n  Stop and discuss with your human partner first\n```\n\n**your human partner''s rule:** \"External feedback - be skeptical, but check carefully\"\n\n## YAGNI Check for \"Professional\" Features\n\n```\nIF reviewer suggests \"implementing properly\":\n  grep codebase for actual usage\n\n  IF unused: \"This endpoint isn''t called. Remove it (YAGNI)?\"\n  IF used: Then implement properly\n```\n\n**your human partner''s rule:** \"You and reviewer both report to me. If we don''t need this feature, don''t add it.\"\n\n## Implementation Order\n\n```\nFOR multi-item feedback:\n  1. Clarify anything unclear FIRST\n  2. Then implement in this order:\n     - Blocking issues (breaks, security)\n     - Simple fixes (typos, imports)\n     - Complex fixes (refactoring, logic)\n  3. Test each fix individually\n  4. Verify no regressions\n```\n\n## When To Push Back\n\nPush back when:\n- Suggestion breaks existing functionality\n- Reviewer lacks full context\n- Violates YAGNI (unused feature)\n- Technically incorrect for this stack\n- Legacy/compatibility reasons exist\n- Conflicts with your human partner''s architectural decisions\n\n**How to push back:**\n- Use technical reasoning, not defensiveness\n- Ask specific questions\n- Reference working tests/code\n- Involve your human partner if architectural\n\n**Signal if uncomfortable pushing back out loud:** \"Strange things are afoot at the Circle K\"\n\n## Acknowledging Correct Feedback\n\nWhen feedback IS correct:\n```\n✅ \"Fixed. [Brief description of what changed]\"\n✅ \"Good catch - [specific issue]. Fixed in [location].\"\n✅ [Just fix it and show in the code]\n\n❌ \"You''re absolutely right!\"\n❌ \"Great point!\"\n❌ \"Thanks for catching that!\"\n❌ \"Thanks for [anything]\"\n❌ ANY gratitude expression\n```\n\n**Why no thanks:** Actions speak. Just fix it. The code itself shows you heard the feedback.\n\n**If you catch yourself about to write \"Thanks\":** DELETE IT. State the fix instead.\n\n## Gracefully Correcting Your Pushback\n\nIf you pushed back and were wrong:\n```\n✅ \"You were right - I checked [X] and it does [Y]. Implementing now.\"\n✅ \"Verified this and you''re correct. My initial understanding was wrong because [reason]. Fixing.\"\n\n❌ Long apology\n❌ Defending why you pushed back\n❌ Over-explaining\n```\n\nState the correction factually and move on.\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Performative agreement | State requirement or just act |\n| Blind implementation | Verify against codebase first |\n| Batch without testing | One at a time, test each |\n| Assuming reviewer is right | Check if breaks things |\n| Avoiding pushback | Technical correctness > comfort |\n| Partial implementation | Clarify all items first |\n| Can''t verify, proceed anyway | State limitation, ask for direction |\n\n## Real Examples\n\n**Performative Agreement (Bad):**\n```\nReviewer: \"Remove legacy code\"\n❌ \"You''re absolutely right! Let me remove that...\"\n```\n\n**Technical Verification (Good):**\n```\nReviewer: \"Remove legacy code\"\n✅ \"Checking... build target is 10.15+, this API needs 13+. Need legacy for backward compat. Current impl has wrong bundle ID - fix it or drop pre-13 support?\"\n```\n\n**YAGNI (Good):**\n```\nReviewer: \"Implement proper metrics tracking with database, date filters, CSV export\"\n✅ \"Grepped codebase - nothing calls this endpoint. Remove it (YAGNI)? Or is there usage I''m missing?\"\n```\n\n**Unclear Item (Good):**\n```\nyour human partner: \"Fix items 1-6\"\nYou understand 1,2,3,6. Unclear on 4,5.\n✅ \"Understand 1,2,3,6. Need clarification on 4 and 5 before implementing.\"\n```\n\n## GitHub Thread Replies\n\nWhen replying to inline review comments on GitHub, reply in the comment thread (`gh api repos/{owner}/{repo}/pulls/{pr}/comments/{id}/replies`), not as a top-level PR comment.\n\n## The Bottom Line\n\n**External feedback = suggestions to evaluate, not orders to follow.**\n\nVerify. Question. Then implement.\n\nNo performative agreement. Technical rigor always.\n"},"category":"official","lastSynced":"2026-03-06T03:31:30.731Z","seo":{"title":{"en":"receiving-code-review: Technical Verification Protocol fo...","zh":"代码审查接收指南 - AIエージェント最佳实践","ja":"コードレビュー受信ガイド - AIエージェントのベストプラクティス","ko":"코드 리뷰 수신 가이드 - AI 에이전트 사용법","es":"Guía de configuración para recibir revisión de código","fr":"Guide de mise en place pour la réception de revue de code","de":"Einrichtungsleitfaden für die Entgegennahme von Code-Reviews","pt":"Receiving Code Review: Guia Técnico para Agentes IA","ru":"Receiving Code Review: Техническое руководство для ИИ Аге...","ar":"Receiving Code Review: دليل تقني لأدوات الذكاء الاصطناعي"},"description":{"en":"Stop blindly implementing code review feedback. This AI agent skill enforces a technical verification protocol: READ, UNDERSTAND, VERIFY, EVALUATE, RESPOND. ...","zh":"了解如何高效接收代码审查反馈，并使用AIエージェント实现技术上的正确性","ja":"コードレビューのフィードバックを受け取る際のベストプラクティスを学び、AIエージェントを使用して技術的な正確性を実現する","ko":"코드 리뷰 피드백을 효과적으로 받고 처리하는 방법을 알아보고 AI 에이전트를 사용하여 기술적 정확성을 달성하십시오","es":"Aprende a recibir y responder a revisiones de código de manera efectiva con nuestro enfoque técnico","fr":"Découvrez comment recevoir et répondre aux revues de code de manière efficace avec notre approche technique","de":"Erfahren Sie, wie Sie Code-Reviews effektiv entgegennehmen und beantworten mit unserem technischen Ansatz","pt":"Habilidade de IA para desenvolvedores processarem revisões de código com rigor técnico. Aprenda a verificar feedback, evitar implementação cega e garantir co...","ru":"Навык ИИ для разработчиков по обработке code review с технической строгостью. Узнайте, как проверять фидбэк, избегать слепой реализации и обеспечивать технич...","ar":"مهارة الذكاء الاصطناعي للمطورين لمعالجة مراجعات الكود بدقة تقنية. تعلم كيفية التحقق من الملاحظات وتجنب التنفيذ الأعمى وضمان الصحة التقنية."},"definition":{"en":"receiving-code-review is an AI agent skill that provides a structured protocol for processing code review feedback. It emphasizes technical verification and understanding before implementation to prevent the merging of unclear or technically questionable suggestions.","zh":"代码审查接收是指在代码审查过程中，开发人员接收和处理代码审查反馈的过程","ja":"コードレビュー受信とは、コードレビューの際に開発者がフィードバックを受け取って処理するプロセス","ko":"코드 리뷰 수신은 코드 리뷰 과정에서 개발자가 코드 리뷰 피드백을 받고 처리하는 프로세스입니다","es":"La recepción de revisión de código es el proceso de evaluar y responder a comentarios técnicos sobre el código","fr":"La réception de revue de code est le processus d''évaluation et de réponse aux commentaires techniques sur le code","de":"Die Entgegennahme von Code-Reviews ist der Prozess der Bewertung und Beantwortung von technischen Kommentaren zum Code","pt":"Receiving Code Review é uma habilidade de IA para desenvolvedores que automatiza a recepção técnica de feedback. Enfatiza verificação rigorosa, compreensão de requisitos e avaliação técnica antes da implementação de sugestões, priorizando correção sobre conformidade social.","ru":"Receiving Code Review — это навык ИИ для разработчиков, автоматизирующий технический прием фидбэка. Акцент на строгую проверку, понимание требований и техническую оценку перед реализацией, приоритет технической корректности над социальным комфортом.","ar":"Receiving Code Review هي مهارة ذكاء اصطناعي للمطورين تُؤتمت الاستقبال التقني للملاحظات. تؤكد على التحقق الدقيق وفهم المتطلبات والتقييم التقني قبل التنفيذ، مع إعطاء الأولوية للصحة التقنية على الراحة الاجتماعية."},"features":{"en":["Executes READ step to consume feedback without immediate reaction","Performs UNDERSTAND step by restating requirements or asking clarifying questions","Conducts VERIFY step against the actual codebase reality","Runs EVALUATE step to assess technical soundness for the specific codebase","Initiates RESPOND step with technical justification for feedback acceptance or rejection"],"zh":["READ: 完整地阅读代码审查反馈","UNDERSTAND: 代码审查要求的重新表述","VERIFY: 代码审查反馈的技术验证","EVALUATE: 代码审查反馈的技术评估","RESPOND: 技术上的响应和处理"],"ja":["READ: コードレビューのフィードバックを完全に読む","UNDERSTAND: コードレビュー要求の再表現","VERIFY: コードレビューのフィードバックの技術的検証","EVALUATE: コードレビューのフィードバックの技術的評価","RESPOND: 技術的な対応と処理"],"ko":["READ: 코드 리뷰 피드백을 완전히 읽음","UNDERSTAND: 코드 리뷰 요구 사항의 재표현","VERIFY: 코드 리뷰 피드백의 기술적 검증","EVALUATE: 코드 리뷰 피드백의 기술적 평가","RESPOND: 기술적인 대응과 처리"],"es":["Verificación de comentarios técnicos","Evaluación de requisitos en propio lenguaje","Verificación contra la realidad del código","Evaluación de la corrección técnica para este código","Respuesta técnica a los comentarios"],"fr":["Vérification des commentaires techniques","Évaluation des exigences en propre langage","Vérification contre la réalité du code","Évaluation de la correction technique pour ce code","Réponse technique aux commentaires"],"de":["Überprüfung von technischen Kommentaren","Bewertung von Anforderungen in eigener Sprache","Überprüfung gegen die Realität des Codes","Bewertung der technischen Korrektheit für diesen Code","Technische Antwort auf Kommentare"],"pt":["Processo estruturado de 5 etapas: READ, UNDERSTAND, VERIFY, EVALUATE, RESPOND","Verificação técnica contra a realidade do codebase","Restatement de requisitos para confirmação de entendimento","Avaliação de sugestões para correção técnica específica","Prevenção de implementação cega de feedback","Foco em rigor técnico em vez de performatividade social"],"ru":["Структурированный 5-этапный процесс: READ, UNDERSTAND, VERIFY, EVALUATE, RESPOND","Техническая проверка против реальности кодовой базы","Переформулирование требований для подтверждения понимания","Оценка предложений на техническую корректность","Предотвращение слепой реализации фидбэка","Фокус на технической строгости вместо социального комфорта"],"ar":["عملية منظمة من 5 خطوات: READ, UNDERSTAND, VERIFY, EVALUATE, RESPOND","التحقق التقني ضد واقع قاعدة الكود","إعادة صياغة المتطلبات لتأكيد الفهم","تقييم الاقتراحات للصحة التقنية المحددة","منع التنفيذ الأعمى للملاحظات","التركيز على الدقة التقنية بدلاً من الأداء الاجتماعي"]},"keywords":{"en":["how to use receiving-code-review","what is receiving-code-review","receiving-code-review protocol","receiving-code-review vs manual review","receiving-code-review install","receiving-code-review setup guide","AI agent code review verification","technical code review evaluation"],"zh":["代码审查","代码审查接收","AIエージェント","代码审查反馈","技术上的正确性","代码审查最佳实践"],"ja":["コードレビュー","コードレビュー受信","AIエージェント","コードレビューのフィードバック","技術的な正確性","コードレビューのベストプラクティス"],"ko":["코드 리뷰","코드 리뷰 수신","AI 에이전트","코드 리뷰 피드백","기술적인 정확성","코드 리뷰 사용법"],"es":["recepción de revisión de código","revisión de código efectiva","rigor técnico en código","verificación de código","evaluación de requisitos","Herramientas de AI para revisión de código"],"fr":["réception de revue de code","revue de code efficace","rigueur technique dans le code","vérification de code","évaluation des exigences","Outils d''IA pour la revue de code"],"de":["Entgegennahme von Code-Reviews","effektive Code-Review","technische Strenge im Code","Überprüfung von Code","Bewertung von Anforderungen","AI-Tools für Code-Reviews"],"pt":["code review feedback técnico","verificação de code review IA","processar feedback desenvolvedor","implementar sugestões código","avaliação técnica codebase","habilidade IA para desenvolvedores","rigor técnico revisão código","automação recepção code review"],"ru":["технический фидбэк code review","проверка code review ИИ","обработка фидбэка разработчика","реализация предложений по коду","техническая оценка кодовой базы","навык ИИ для разработчиков","техническая строгость code review","автоматизация приема code review"],"ar":["ملاحظات تقنية لمراجعة الكود","تحقق مراجعة الكود بالذكاء الاصطناعي","معالجة ملاحظات المطور","تنفيذ اقتراحات الكود","تقييم تقني لقاعدة الكود","مهارة ذكاء اصطناعي للمطورين","دقة تقنية لمراجعة الكود","أتمتة استقبال مراجعة الكود"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Technical Agents requiring rigorous code review and verification capabilities, especially those working with codebases in languages like Python or JavaScript.","zh":"非常适合需要严格代码审查和验证能力的技术Agent，特别是那些处理Python或JavaScript等语言代码库的Agent。","ja":"PythonやJavaScriptなどのコードベースを扱う、厳格なコードレビューと検証機能を必要とするテクニカルAgentに最適です。","ko":"Python이나 JavaScript와 같은 언어의 코드베이스로 작업하는, 엄격한 코드 리뷰 및 검증 기능이 필요한 기술 에이전트에 이상적입니다.","es":"Ideal para agentes técnicos que requieren capacidades rigurosas de revisión y verificación de código, especialmente aquellos que trabajan con bases de código en lenguajes como Python o JavaScript.","fr":"Idéal pour les agents techniques nécessitant des capacités rigoureuses de révision et de vérification du code, en particulier ceux travaillant avec des bases de code dans des langages comme Python ou JavaScript.","de":"Ideal für technische Agenten, die strenge Code-Überprüfungs- und Verifizierungsfähigkeiten erfordern, insbesondere für diejenigen, die mit Codebasen in Sprachen wie Python oder JavaScript arbeiten.","pt":"Ideal para Agentes Técnicos que requerem capacidades rigorosas de revisão e verificação de código, especialmente aqueles que trabalham com codebases em linguagens como Python ou JavaScript.","ru":"Идеально подходит для технических агентов, требующих строгих возможностей проверки и анализа кода, особенно тех, кто работает с кодом на таких языках, как Python или JavaScript.","ar":"مثالي للوكلاء التقنيين الذين يتطلبون قدرات صارمة لمراجعة وتحقق من التعليمات البرمجية، خاصة أولئك الذين يعملون مع قواعد التعليمات البرمجية بلغات مثل Python أو JavaScript."},"recommendation":{"en":"Empowers agents to technically evaluate code review feedback, ensuring verification against codebase reality and promoting technical correctness over social comfort, leveraging principles like ''Verify before implementing'' and ''Ask before assuming'' to guarantee high-quality code.","zh":"使Agent能够从技术上评估代码审查反馈，确保根据代码库实际情况进行验证，并优先考虑技术正确性而非社交舒适度。它利用‘实施前验证’和‘假设前询问’等原则来保证高质量的代码。","ja":"コードレビューフィードバックを技術的に評価し、コードベースの現実に対して検証を確実に行い、社会的な快適さよりも技術的正確性を促進するようにAgentに権限を与えます。『実装前に検証する』や『仮定する前に尋ねる』といった原則を活用して、高品質なコードを保証します。","ko":"에이전트가 코드 리뷰 피드백을 기술적으로 평가하고, 코드베이스 현실에 대해 검증을 보장하며, 사회적 편안함보다 기술적 정확성을 증진시키도록 합니다. ''구현 전 검증'' 및 ''가정 전 질문''과 같은 원칙을 활용하여 고품질 코드를 보장합니다.","es":"Potencia a los agentes para evaluar técnicamente los comentarios de revisión de código, asegurando la verificación contra la realidad de la base de código y promoviendo la corrección técnica sobre la comodidad social, aprovechando principios como ''Verificar antes de implementar'' y ''Preguntar antes de asumir'' para garantizar código de alta calidad.","fr":"Permet aux agents d''évaluer techniquement les retours de revue de code, en assurant une vérification par rapport aux contraintes réelles de la base de code et en promouvant l''exactitude technique plutôt que le confort social, en s''appuyant sur des principes comme ''Vérifier avant de mettre en œuvre'' et ''Demander avant de supposer'' pour garantir un code de haute qualité.","de":"Ermächtigt Agenten, Code-Review-Feedback technisch zu bewerten, stellt die Verifizierung gegen die Realität der Codebasis sicher und fördert technische Korrektheit über sozialen Komfort, unter Nutzung von Prinzipien wie ''Vor der Implementierung überprüfen'' und ''Fragen, bevor angenommen wird'', um hochwertigen Code zu gewährleisten.","pt":"Capacita os agentes a avaliar tecnicamente o feedback da revisão de código, garantindo a verificação em relação à realidade do codebase e promovendo a correção técnica em vez do conforto social, aproveitando princípios como ''Verificar antes de implementar'' e ''Perguntar antes de assumir'' para garantir código de alta qualidade.","ru":"Позволяет агентам технически оценивать отзывы о проверке кода, обеспечивая проверку соответствия реальному состоянию кодовой базы и способствуя технической корректности, а не социальному комфорту, используя такие принципы, как «Сначала проверь, потом внедряй» и «Спроси, прежде чем предположить», чтобы гарантировать высокое качество кода.","ar":"يمكن الوكلاء من تقييم ملاحظات مراجعة التعليمات البرمجية تقنياً، مما يضمن التحقق من واقع قاعدة التعليمات البرمجية ويعزز الصحة التقنية على الراحة الاجتماعية، مستفيداً من مبادئ مثل ''تحقق قبل التنفيذ'' و''اسأل قبل الافتراض'' لضمان تعليمات برمجية عالية الجودة."},"useCases":{"en":["Evaluating code review feedback for technical soundness","Verifying suggested changes against existing codebase constraints","Responding to code reviews with technically accurate and informed decisions"],"zh":["评估代码审查反馈的技术合理性","根据现有代码库的约束条件验证建议的更改","以技术准确且明智的决策回应代码审查"],"ja":["コードレビューフィードバックの技術的健全性の評価","既存のコードベースの制約に対する提案された変更の検証","技術的に正確で情報に基づいた決定を用いたコードレビューへの対応"],"ko":["기술적 타당성을 위한 코드 리뷰 피드백 평가","기존 코드베이스 제약 조건에 대한 제안된 변경 사항 검증","기술적으로 정확하고 정보에 기반한 결정으로 코드 리뷰에 응답"],"es":["Evaluar los comentarios de revisión de código para solidez técnica","Verificar los cambios sugeridos contra las restricciones existentes de la base de código","Responder a las revisiones de código con decisiones técnicas precisas e informadas"],"fr":["Évaluer les retours de revue de code pour la solidité technique","Vérifier les modifications suggérées par rapport aux contraintes existantes de la base de code","Répondre aux revues de code avec des décisions techniques précises et éclairées"],"de":["Bewertung von Code-Review-Feedback auf technische Solidität","Überprüfung vorgeschlagener Änderungen gegen bestehende Einschränkungen der Codebasis","Reaktion auf Code-Reviews mit technisch genauen und fundierten Entscheidungen"],"pt":["Avaliar o feedback da revisão de código quanto à solidez técnica","Verificar as alterações sugeridas em relação às restrições existentes do codebase","Responder a revisões de código com decisões técnicas precisas e informadas"],"ru":["Оценка отзывов о проверке кода на предмет технической обоснованности","Проверка предлагаемых изменений на соответствие ограничениям существующей кодовой базы","Ответ на проверки кода с технически точными и обоснованными решениями"],"ar":["تقييم ملاحظات مراجعة التعليمات البرمجية من حيث السليمة التقنية","التحقق من التغييرات المقترحة مقابل قيود قاعدة التعليمات البرمجية الحالية","الرد على مراجعات التعليمات البرمجية بقرارات تقنية دقيقة ومستنيرة"]},"limitations":{"en":["Requires technical knowledge of the specific codebase and programming language","Assumes availability of clear and actionable code review feedback","May necessitate additional time for thorough verification and evaluation"],"zh":["需要具备特定代码库和编程语言的技术知识","假设可获得清晰且可操作的代码审查反馈","可能需要进行彻底验证和评估，从而需要额外的时间"],"ja":["特定のコードベースとプログラミング言語に関する技術知識が必要","明確で実行可能なコードレビューフィードバックの利用可能性を前提としている","徹底的な検証と評価のために追加の時間が必要となる可能性がある"],"ko":["특정 코드베이스 및 프로그래밍 언어에 대한 기술적 지식 필요","명확하고 실행 가능한 코드 리뷰 피드백의 가용성을 가정함","철저한 검증 및 평가를 위해 추가 시간이 필요할 수 있음"],"es":["Requiere conocimiento técnico de la base de código específica y del lenguaje de programación","Asume la disponibilidad de comentarios de revisión de código claros y accionables","Puede requerir tiempo adicional para una verificación y evaluación exhaustivas"],"fr":["Nécessite une connaissance technique de la base de code spécifique et du langage de programmation","Suppose la disponibilité de retours de revue de code clairs et exploitables","Peut nécessiter un temps supplémentaire pour une vérification et une évaluation approfondies"],"de":["Erfordert technisches Wissen der spezifischen Codebasis und der Programmiersprache","Setzt die Verfügbarkeit von klarem und umsetzbarem Code-Review-Feedback voraus","Kann zusätzliche Zeit für gründliche Verifizierung und Bewertung erfordern"],"pt":["Requer conhecimento técnico do codebase específico e da linguagem de programação","Assume a disponibilidade de feedback de revisão de código claro e acionável","Pode exigir tempo adicional para verificação e avaliação minuciosas"],"ru":["Требует технических знаний конкретной кодовой базы и языка программирования","Предполагает наличие четких и действенных отзывов о проверке кода","Может потребовать дополнительного времени для тщательной проверки и оценки"],"ar":["يتطلب معرفة تقنية بقاعدة التعليمات البرمجية المحددة ولغة البرمجة","تفترض توفر ملاحظات مراجعة تعليمات برمجية واضحة وقابلة للتنفيذ","قد تتطلب وقتاً إضافياً للتحقق والتقييم الشاملين"]},"version":4},"contentHash":"c9382e92b8f32363566068ecfed19d3b2651eaf40d3942b24840f839dedfc406","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":71}');
DELETE FROM skills_fts WHERE id = 'obra/superpowers/receiving-code-review';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/receiving-code-review', 'receiving-code-review', 'obra', 'superpowers', 'official', 'receiving-code-review obra superpowers official This AI agent skill provides a structured protocol for technically evaluating code review feedback before implementation. It benefits developers and AI agents by prioritizing verification and technical rigor over performative agreement, preventing the merging of unclear or incorrect suggestions. 代码审查接收需要技术上的严谨性和验证，而不是简单的同意或盲目实现。使用AIエージェント可以帮助您高效地接收和处理代码审查反馈 コードレビューの受信には技術的な厳格性と検証が必要であり、単なる同意や盲目的な実装ではありません。AIエージェントを使用すると、コードレビューのフィードバックを受け取って処理することができます 코드 리뷰 수신에는 기술적인 엄谨성과 검증이 필요하며, 단순한 동의나 무조건적인 구현은 아닙니다. AI 에이전트를 사용하면 코드 리뷰 피드백을 효과적으로 받고 처리할 수 있습니다 Recibir revisiones de código de manera efectiva requiere rigor técnico y verificación Recevoir des revues de code de manière efficace nécessite une rigueur technique et une vérification Die effektive Entgegennahme von Code-Reviews erfordert technische Strenge und Überprüfung Uma habilidade técnica de IA que orienta desenvolvedores no processo de receber feedback de code review. Foca em verificação técnica rigorosa, compreensão clara dos requisitos e avaliação contra a realidade do codebase antes da implementação. Технический навык ИИ, который направляет разработчиков в процессе получения фидбэка code review. Акцент на техническую проверку, четкое понимание требований и оценку против кодовой базы. مهارة تقنية للذكاء الاصطناعي توجه المطورين في عملية استقبال ملاحظات مراجعة الكود. تركز على التحقق التقني الدقيق والفهم الواضح للمتطلبات والتقييم ضد قاعدة الكود. how to use receiving-code-review what is receiving-code-review receiving-code-review protocol receiving-code-review vs manual review receiving-code-review install receiving-code-review setup guide AI agent code review verification technical code review evaluation 代码审查 代码审查接收 AIエージェント 代码审查反馈 技术上的正确性 代码审查最佳实践 Executes READ step to consume feedback without immediate reaction Performs UNDERSTAND step by restating requirements or asking clarifying questions Conducts VERIFY step against the actual codebase reality Runs EVALUATE step to assess technical soundness for the specific codebase Initiates RESPOND step with technical justification for feedback acceptance or rejection receiving-code-review is an AI agent skill that provides a structured protocol for processing code review feedback. It emphasizes technical verification and understanding before implementation to prevent the merging of unclear or technically questionable suggestions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/springboot-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'springboot-patterns', 61988, 7678, 71, '2026-03-06T03:39:20Z', '2026-03-06T04:35:23.104Z', '7ecbb9ce50282c9c1cf71e3e9245d077036c3f72bd589418d8dd573118faa0e5', '{"id":"affaan-m/everything-claude-code/springboot-patterns","name":"springboot-patterns","description":{"en":"This AI Agent Skill provides expert guidance on Spring Boot architecture patterns for building scalable REST APIs. It assists Java developers with structuring controller-service-repository layers, configuring data access, caching, and implementing production-ready patterns.","zh":"Spring Boot 设计模式提供了构建可扩展的生产级服务的解决方案，包括 REST API 设计、分层服务和数据访问","ja":"Spring Boot アーキテクチャ パターンは、拡張可能な生産性の高いサービスを構築するためのソリューションを提供し、REST API デザイン、レイヤード サービス、データ アクセスを含む","ko":"Spring Boot 개발 패턴은 확장 가능한 생산급 서비스를 구축하기 위한 솔루션을 제공하며, REST API 설계, 계층화된 서비스, 데이터 접근을 포함","es":"Patrones de arquitectura de Spring Boot para APIs escalables y de producción","fr":"Conception de Spring Boot pour des API évolutives et de production","de":"Spring-Boot-Muster für die Entwicklung skalierbarer REST-APIs","pt":"Spring Boot patterns para desenvolvimento de serviços escaláveis e de produção, incluindo REST API e acesso a dados","ru":"Шаблоны Spring Boot для создания масштабируемых и производственных сервисов, включая REST API и доступ к данным","ar":"أنماط Spring Boot لإنشاء خدمات قابلة للتوسعة، تشمل واجهة برمجة التطبيقات REST ووصول إلى البيانات"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"springboot-patterns","description":"Spring Boot architecture patterns, REST API design, layered services, data access, caching, async processing, and logging. Use for Java Spring Boot backend work.","bodyPreview":"# Spring Boot Development Patterns\n\nSpring Boot architecture and API patterns for scalable, production-grade services.\n\n## When to Activate\n\n- Building REST APIs with Spring MVC or WebFlux\n- Structuring controller → service → repository layers\n- Configuring Spring Data JPA, caching, or async processing\n- Adding validation, exception handling, or pagination\n- Setting up profiles for dev/staging/production environments\n- Implementing event-driven patterns with Spring Events or Kafka\n\n## REST API S","body":"# Spring Boot Development Patterns\n\nSpring Boot architecture and API patterns for scalable, production-grade services.\n\n## When to Activate\n\n- Building REST APIs with Spring MVC or WebFlux\n- Structuring controller → service → repository layers\n- Configuring Spring Data JPA, caching, or async processing\n- Adding validation, exception handling, or pagination\n- Setting up profiles for dev/staging/production environments\n- Implementing event-driven patterns with Spring Events or Kafka\n\n## REST API Structure\n\n```java\n@RestController\n@RequestMapping(\"/api/markets\")\n@Validated\nclass MarketController {\n  private final MarketService marketService;\n\n  MarketController(MarketService marketService) {\n    this.marketService = marketService;\n  }\n\n  @GetMapping\n  ResponseEntity<Page<MarketResponse>> list(\n      @RequestParam(defaultValue = \"0\") int page,\n      @RequestParam(defaultValue = \"20\") int size) {\n    Page<Market> markets = marketService.list(PageRequest.of(page, size));\n    return ResponseEntity.ok(markets.map(MarketResponse::from));\n  }\n\n  @PostMapping\n  ResponseEntity<MarketResponse> create(@Valid @RequestBody CreateMarketRequest request) {\n    Market market = marketService.create(request);\n    return ResponseEntity.status(HttpStatus.CREATED).body(MarketResponse.from(market));\n  }\n}\n```\n\n## Repository Pattern (Spring Data JPA)\n\n```java\npublic interface MarketRepository extends JpaRepository<MarketEntity, Long> {\n  @Query(\"select m from MarketEntity m where m.status = :status order by m.volume desc\")\n  List<MarketEntity> findActive(@Param(\"status\") MarketStatus status, Pageable pageable);\n}\n```\n\n## Service Layer with Transactions\n\n```java\n@Service\npublic class MarketService {\n  private final MarketRepository repo;\n\n  public MarketService(MarketRepository repo) {\n    this.repo = repo;\n  }\n\n  @Transactional\n  public Market create(CreateMarketRequest request) {\n    MarketEntity entity = MarketEntity.from(request);\n    MarketEntity saved = repo.save(entity);\n    return Market.from(saved);\n  }\n}\n```\n\n## DTOs and Validation\n\n```java\npublic record CreateMarketRequest(\n    @NotBlank @Size(max = 200) String name,\n    @NotBlank @Size(max = 2000) String description,\n    @NotNull @FutureOrPresent Instant endDate,\n    @NotEmpty List<@NotBlank String> categories) {}\n\npublic record MarketResponse(Long id, String name, MarketStatus status) {\n  static MarketResponse from(Market market) {\n    return new MarketResponse(market.id(), market.name(), market.status());\n  }\n}\n```\n\n## Exception Handling\n\n```java\n@ControllerAdvice\nclass GlobalExceptionHandler {\n  @ExceptionHandler(MethodArgumentNotValidException.class)\n  ResponseEntity<ApiError> handleValidation(MethodArgumentNotValidException ex) {\n    String message = ex.getBindingResult().getFieldErrors().stream()\n        .map(e -> e.getField() + \": \" + e.getDefaultMessage())\n        .collect(Collectors.joining(\", \"));\n    return ResponseEntity.badRequest().body(ApiError.validation(message));\n  }\n\n  @ExceptionHandler(AccessDeniedException.class)\n  ResponseEntity<ApiError> handleAccessDenied() {\n    return ResponseEntity.status(HttpStatus.FORBIDDEN).body(ApiError.of(\"Forbidden\"));\n  }\n\n  @ExceptionHandler(Exception.class)\n  ResponseEntity<ApiError> handleGeneric(Exception ex) {\n    // Log unexpected errors with stack traces\n    return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)\n        .body(ApiError.of(\"Internal server error\"));\n  }\n}\n```\n\n## Caching\n\nRequires `@EnableCaching` on a configuration class.\n\n```java\n@Service\npublic class MarketCacheService {\n  private final MarketRepository repo;\n\n  public MarketCacheService(MarketRepository repo) {\n    this.repo = repo;\n  }\n\n  @Cacheable(value = \"market\", key = \"#id\")\n  public Market getById(Long id) {\n    return repo.findById(id)\n        .map(Market::from)\n        .orElseThrow(() -> new EntityNotFoundException(\"Market not found\"));\n  }\n\n  @CacheEvict(value = \"market\", key = \"#id\")\n  public void evict(Long id) {}\n}\n```\n\n## Async Processing\n\nRequires `@EnableAsync` on a configuration class.\n\n```java\n@Service\npublic class NotificationService {\n  @Async\n  public CompletableFuture<Void> sendAsync(Notification notification) {\n    // send email/SMS\n    return CompletableFuture.completedFuture(null);\n  }\n}\n```\n\n## Logging (SLF4J)\n\n```java\n@Service\npublic class ReportService {\n  private static final Logger log = LoggerFactory.getLogger(ReportService.class);\n\n  public Report generate(Long marketId) {\n    log.info(\"generate_report marketId={}\", marketId);\n    try {\n      // logic\n    } catch (Exception ex) {\n      log.error(\"generate_report_failed marketId={}\", marketId, ex);\n      throw ex;\n    }\n    return new Report();\n  }\n}\n```\n\n## Middleware / Filters\n\n```java\n@Component\npublic class RequestLoggingFilter extends OncePerRequestFilter {\n  private static final Logger log = LoggerFactory.getLogger(RequestLoggingFilter.class);\n\n  @Override\n  protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,\n      FilterChain filterChain) throws ServletException, IOException {\n    long start = System.currentTimeMillis();\n    try {\n      filterChain.doFilter(request, response);\n    } finally {\n      long duration = System.currentTimeMillis() - start;\n      log.info(\"req method={} uri={} status={} durationMs={}\",\n          request.getMethod(), request.getRequestURI(), response.getStatus(), duration);\n    }\n  }\n}\n```\n\n## Pagination and Sorting\n\n```java\nPageRequest page = PageRequest.of(pageNumber, pageSize, Sort.by(\"createdAt\").descending());\nPage<Market> results = marketService.list(page);\n```\n\n## Error-Resilient External Calls\n\n```java\npublic <T> T withRetry(Supplier<T> supplier, int maxRetries) {\n  int attempts = 0;\n  while (true) {\n    try {\n      return supplier.get();\n    } catch (Exception ex) {\n      attempts++;\n      if (attempts >= maxRetries) {\n        throw ex;\n      }\n      try {\n        Thread.sleep((long) Math.pow(2, attempts) * 100L);\n      } catch (InterruptedException ie) {\n        Thread.currentThread().interrupt();\n        throw ex;\n      }\n    }\n  }\n}\n```\n\n## Rate Limiting (Filter + Bucket4j)\n\n**Security Note**: The `X-Forwarded-For` header is untrusted by default because clients can spoof it.\nOnly use forwarded headers when:\n1. Your app is behind a trusted reverse proxy (nginx, AWS ALB, etc.)\n2. You have registered `ForwardedHeaderFilter` as a bean\n3. You have configured `server.forward-headers-strategy=NATIVE` or `FRAMEWORK` in application properties\n4. Your proxy is configured to overwrite (not append to) the `X-Forwarded-For` header\n\nWhen `ForwardedHeaderFilter` is properly configured, `request.getRemoteAddr()` will automatically\nreturn the correct client IP from the forwarded headers. Without this configuration, use\n`request.getRemoteAddr()` directly—it returns the immediate connection IP, which is the only\ntrustworthy value.\n\n```java\n@Component\npublic class RateLimitFilter extends OncePerRequestFilter {\n  private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();\n\n  /*\n   * SECURITY: This filter uses request.getRemoteAddr() to identify clients for rate limiting.\n   *\n   * If your application is behind a reverse proxy (nginx, AWS ALB, etc.), you MUST configure\n   * Spring to handle forwarded headers properly for accurate client IP detection:\n   *\n   * 1. Set server.forward-headers-strategy=NATIVE (for cloud platforms) or FRAMEWORK in\n   *    application.properties/yaml\n   * 2. If using FRAMEWORK strategy, register ForwardedHeaderFilter:\n   *\n   *    @Bean\n   *    ForwardedHeaderFilter forwardedHeaderFilter() {\n   *        return new ForwardedHeaderFilter();\n   *    }\n   *\n   * 3. Ensure your proxy overwrites (not appends) the X-Forwarded-For header to prevent spoofing\n   * 4. Configure server.tomcat.remoteip.trusted-proxies or equivalent for your container\n   *\n   * Without this configuration, request.getRemoteAddr() returns the proxy IP, not the client IP.\n   * Do NOT read X-Forwarded-For directly—it is trivially spoofable without trusted proxy handling.\n   */\n  @Override\n  protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,\n      FilterChain filterChain) throws ServletException, IOException {\n    // Use getRemoteAddr() which returns the correct client IP when ForwardedHeaderFilter\n    // is configured, or the direct connection IP otherwise. Never trust X-Forwarded-For\n    // headers directly without proper proxy configuration.\n    String clientIp = request.getRemoteAddr();\n\n    Bucket bucket = buckets.computeIfAbsent(clientIp,\n        k -> Bucket.builder()\n            .addLimit(Bandwidth.classic(100, Refill.greedy(100, Duration.ofMinutes(1))))\n            .build());\n\n    if (bucket.tryConsume(1)) {\n      filterChain.doFilter(request, response);\n    } else {\n      response.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());\n    }\n  }\n}\n```\n\n## Background Jobs\n\nUse Spring’s `@Scheduled` or integrate with queues (e.g., Kafka, SQS, RabbitMQ). Keep handlers idempotent and observable.\n\n## Observability\n\n- Structured logging (JSON) via Logback encoder\n- Metrics: Micrometer + Prometheus/OTel\n- Tracing: Micrometer Tracing with OpenTelemetry or Brave backend\n\n## Production Defaults\n\n- Prefer constructor injection, avoid field injection\n- Enable `spring.mvc.problemdetails.enabled=true` for RFC 7807 errors (Spring Boot 3+)\n- Configure HikariCP pool sizes for workload, set timeouts\n- Use `@Transactional(readOnly = true)` for queries\n- Enforce null-safety via `@NonNull` and `Optional` where appropriate\n\n**Remember**: Keep controllers thin, services focused, repositories simple, and errors handled centrally. Optimize for maintainability and testability.\n"},"category":"official","lastSynced":"2026-03-06T04:35:23.104Z","seo":{"title":{"en":"springboot-patterns: REST API & Architecture Best Practic...","zh":"Spring Boot 设计模式 Setup Guide","ja":"Spring Boot アーキテクチャ パターン Best Practices","ko":"Spring Boot 개발 패턴 가이드","es":"Guía de Patrones de Spring Boot para Desarrollo de APIs","fr":"Meilleures Pratiques de Conception Spring Boot pour les APIs","de":"Spring Boot Muster-Setup für REST-API-Entwicklung","pt":"Guia de Configuração Spring Boot Patterns","ru":"Настройка шаблонов Spring Boot: ИИ Агенты","ar":"دليل إعداد أنماط Spring Boot"},"description":{"en":"Leverage Claude AI to implement Spring Boot layered services, configure Spring Data JPA, set up caching, and handle async processing. Get expert guidance on ...","zh":"学习 Spring Boot 架构模式和 REST API 设计，包括分层服务、数据访问、缓存和异步处理","ja":"Spring Boot アーキテクチャ パターンと REST API デザインを学び、レイヤード サービス、データ アクセス、キャッシュ、非同期処理を実現","ko":"Spring Boot 개발 패턴과 REST API 설계를 배우고, 계층화된 서비스, 데이터 접근, 캐싱, 비동기 처리를 구현","es":"Aprende a implementar patrones de arquitectura de Spring Boot para desarrollar APIs escalables y de producción","fr":"Découvrez les meilleures pratiques pour concevoir des API Spring Boot évolutives et de production","de":"Erfahren Sie, wie Sie Spring-Boot-Muster fü