INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/springboot-patterns', 'springboot-patterns', 'affaan-m', 'everything-claude-code', 'official', 'springboot-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This AI Agent Skill provides expert guidance on Spring Boot architecture patterns for building scalable REST APIs. It assists Java developers with structuring controller-service-repository layers, configuring data access, caching, and implementing production-ready patterns. Spring Boot 设计模式提供了构建可扩展的生产级服务的解决方案，包括 REST API 设计、分层服务和数据访问 Spring Boot アーキテクチャ パターンは、拡張可能な生産性の高いサービスを構築するためのソリューションを提供し、REST API デザイン、レイヤード サービス、データ アクセスを含む Spring Boot 개발 패턴은 확장 가능한 생산급 서비스를 구축하기 위한 솔루션을 제공하며, REST API 설계, 계층화된 서비스, 데이터 접근을 포함 Patrones de arquitectura de Spring Boot para APIs escalables y de producción Conception de Spring Boot pour des API évolutives et de production Spring-Boot-Muster für die Entwicklung skalierbarer REST-APIs Spring Boot patterns para desenvolvimento de serviços escaláveis e de produção, incluindo REST API e acesso a dados Шаблоны Spring Boot для создания масштабируемых и производственных сервисов, включая REST API и доступ к данным أنماط Spring Boot لإنشاء خدمات قابلة للتوسعة، تشمل واجهة برمجة التطبيقات REST ووصول إلى البيانات how to use springboot-patterns springboot-patterns setup guide springboot-patterns vs other Spring tools Spring Boot REST API patterns Spring Data JPA configuration Spring Boot caching implementation Spring MVC WebFlux architecture springboot-patterns install Spring Boot layered services Spring Events Kafka integration Spring Boot 设计模式 REST API 设计 分层服务 数据访问 缓存 异步处理 AIエージェント Java Spring Boot Structuring controller → service → repository layered architecture Configuring Spring Data JPA for data access operations Implementing caching strategies for performance optimization Setting up async processing for non-blocking operations Adding validation, exception handling, and pagination to REST APIs Implementing event-driven patterns with Spring Events or Kafka springboot-patterns is an AI Agent Skill that delivers specialized knowledge on Spring Boot development patterns, including REST API design with Spring MVC/WebFlux, layered architecture, Spring Data JPA configuration, caching, async processing, and event-driven implementation using Spring Events or Kafka.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/gh-review-requests', 'official', 'getsentry', 'skills', 'getsentry/skills', 'gh-review-requests', 360, 11, 71, '2026-03-06T00:20:36Z', '2026-03-06T05:09:05.976Z', '6ad2c7842dc19fb76c94564753981e87b0b1e848de0998477f29ccd18d6cf659', '{"id":"getsentry/skills/gh-review-requests","name":"gh-review-requests","description":{"en":"The gh-review-requests skill fetches unread GitHub notifications for open PRs where review is requested from a specified team or opened by a team member, benefiting developers and teams.","zh":"gh-review-requests skill 用于获取 GitHub 未读通知，用于打开的 PR 请求审查，支持 GitHub CLI 认证","ja":"gh-review-requests スキルは、GitHub の未読通知を取得するために使用され、GitHub CLI 認証をサポートします","ko":"gh-review-requests skill 은 GitHub 코드 리뷰 요청을 관리하기 위해 사용되며 GitHub CLI 인증을 지원합니다","es":"gh-review-requests fetch notificaciones de revisión de GitHub para PR abiertos filtradas por un equipo de GitHub. Requiere GitHub CLI autenticado.","fr":"gh-review-requests récupère les notifications de révision GitHub pour les PR ouverts filtrées par une équipe GitHub. Nécessite GitHub CLI authentifié.","de":"gh-review-requests ruft GitHub-Überprüfungsbenachrichtigungen für offene PRs ab, die von einem GitHub-Team gefiltert werden. Benötigt authentifizierten GitHub-CLI.","pt":"O gh-review-requests é um skill que fetch unread GitHub notifications para PRs abertas com solicitação de revisão de uma equipe específica, utilizando o GitHub CLI.","ru":"ИИ Агент gh-review-requests - это навык, который получает уведомления о запросах на просмотр из GitHub для открытых PR, используя GitHub CLI.","ar":"العميل الذكي gh-review-requests هو مهارة تقوم بFetching الإشعارات غير المقرؤة من GitHub للتقارير المفتوحة مع طلبات المراجعة من فريق معين، باستخدام واجهة سطر الأوامر GitHub."},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"gh-review-requests","description":"Fetch unread GitHub notifications for open PRs where review is requested from a specified team or opened by a team member. Use when asked to find PRs I need to review, show my review requests, what needs my review, fetch GitHub review requests, or check team review queue.","bodyPreview":"# GitHub Review Requests\n\nFetch unread `review_requested` notifications for open (unmerged) PRs, filtered by a GitHub team.\n\n**Requires**: GitHub CLI (`gh`) authenticated.\n\n## Step 1: Identify the Team\n\nIf the user has not specified a team, ask:\n\n> Which GitHub team should I filter by? (e.g. `streaming-platform`)\n\nAccept either a team slug (`streaming-platform`) or a display name (\"Streaming Platform\") — convert to lowercase-hyphenated slug before passing to the script.\n\n## Step 2: Run the Scrip","body":"# GitHub Review Requests\n\nFetch unread `review_requested` notifications for open (unmerged) PRs, filtered by a GitHub team.\n\n**Requires**: GitHub CLI (`gh`) authenticated.\n\n## Step 1: Identify the Team\n\nIf the user has not specified a team, ask:\n\n> Which GitHub team should I filter by? (e.g. `streaming-platform`)\n\nAccept either a team slug (`streaming-platform`) or a display name (\"Streaming Platform\") — convert to lowercase-hyphenated slug before passing to the script.\n\n## Step 2: Run the Script\n\n```bash\nuv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_review_requests.py --org getsentry --teams <team-slug>\n```\n\nTo filter by multiple teams, pass a comma-separated list:\n\n```bash\nuv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_review_requests.py --org getsentry --teams <team slugs>\n```\n\n### Script output\n\n```json\n{\n  \"total\": 3,\n  \"prs\": [\n    {\n      \"notification_id\": \"12345\",\n      \"title\": \"feat(kafka): add workflow to restart a broker\",\n      \"url\": \"https://github.com/getsentry/ops/pull/19144\",\n      \"repo\": \"getsentry/ops\",\n      \"pr_number\": 19144,\n      \"author\": \"bmckerry\",\n      \"reasons\": [\"opened by: bmckerry\"]\n    }\n  ]\n}\n```\n\n`reasons` will contain one or both of:\n- `\"review requested from: <Team Name>\"` — the team is a requested reviewer\n- `\"opened by: <login>\"` — the PR author is a team member\n\n## Step 3: Present Results\n\nDisplay results as a markdown table with full URLs:\n\n| # | Title | URL | Reason |\n|---|-------|-----|--------|\n| 1 | feat(kafka): add workflow to restart a broker | https://github.com/getsentry/ops/pull/19144 | opened by: evanh |\n\nIf `total` is 0, say: \"No unread review requests found for that team.\"\n\n## Fallback\n\nIf the script fails, run manually:\n\n```bash\ngh api notifications --paginate\n```\n\nThen for each `review_requested` notification, check:\n- `gh api repos/{repo}/pulls/{number}` — skip if `state == \"closed\"` or `merged_at` is set\n- `gh api repos/{repo}/pulls/{number}/requested_reviewers` — check `teams[].name`\n- `gh api orgs/{org}/teams/{slug}/members` — check if author is a member\n"},"category":"official","lastSynced":"2026-03-06T05:09:05.976Z","seo":{"title":{"en":"gh-review-requests: GitHub Review Request Setup Guide | A...","zh":"GitHub 代码审查请求设置指南 - gh-review-requests","ja":"GitHub レビューリクエストの設定方法 - gh-review-requests","ko":"GitHub 코드 리뷰 요청 가이드 - gh-review-requests","es":"Guía de configuración de gh-review-requests para desarrol...","fr":"Configurer les demandes d''examen GitHub avec gh-review-re...","de":"Einrichtungsanleitung für gh-review-requests für Entwickler","pt":"Guia de Configuração do gh-review-requests para Desenvolv...","ru":"ИИ Агент gh-review-requests: Руководство по Настройке","ar":"دليل إعداد العميل الذكي gh-review-requests لل مطورين"},"description":{"en":"Streamline your GitHub workflow by fetching unread review requests with gh-review-requests. Learn how to set up and use this AI agent skill today!","zh":"使用 gh-review-requests skill 获取 GitHub 未读通知，用于打开的 PR 请求审查，AIエージェント","ja":"GitHub の未読通知を取得するには、gh-review-requests スキルを使用してください - AIエージェント","ko":"GitHub 코드 리뷰 요청을 쉽게 관리하세요 - gh-review-requests, AI 도구","es":"Aprende a configurar gh-review-requests para fetch notificaciones de revisión de GitHub para PR abiertos y mejorar tu flujo de trabajo","fr":"Découvrez comment configurer gh-review-requests pour récupérer les notifications de révision GitHub pour les PR ouverts et améliorer votre flux de travail","de":"Erfahren Sie, wie Sie gh-review-requests konfigurieren, um GitHub-Überprüfungsbenachrichtigungen für offene PRs abzurufen und Ihren Arbeitsablauf zu verbessern","pt":"Aprenda a configurar o gh-review-requests para fetch unread GitHub notifications para PRs abertas com solicitação de revisão de uma equipe específica","ru":"Узнайте, как настроить ИИ Агент gh-review-requests для получения уведомлений о запросах на просмотр из GitHub для открытых PR","ar":"تعرف على كيفية إعداد العميل الذكي gh-review-requests لجلب الإشعارات غير المقرؤة من GitHub للتقارير المفتوحة مع طلبات المراجعة من فريق معين"},"definition":{"en":"gh-review-requests is a skill that fetches unread review_requested notifications for open GitHub PRs, filtered by a GitHub team, utilizing the GitHub CLI (gh) for authentication.","zh":"gh-review-requests 是一个用于获取 GitHub 未读通知的 skill，主要用于代码审查请求","ja":"gh-review-requests は、GitHub の未読通知を取得するために使用されるスキルです","ko":"gh-review-requests 는 GitHub 코드 리뷰 요청을 관리하기 위한 skill 입니다","es":"gh-review-requests es una herramienta de Agente de Inteligencia Artificial que fetch notificaciones de revisión de GitHub","fr":"gh-review-requests est un outil d''agent d''intelligence artificielle qui récupère les notifications de révision GitHub","de":"gh-review-requests ist ein Tool für künstliche Intelligenz-Agenten, das GitHub-Überprüfungsbenachrichtigungen abruft","pt":"O gh-review-requests é um skill que fetch unread GitHub notifications para PRs abertas com solicitação de revisão de uma equipe específica","ru":"ИИ Агент gh-review-requests - это навык, который получает уведомления о запросах на просмотр из GitHub","ar":"العميل الذكي gh-review-requests هو مهارة تقوم بFetching الإشعارات غير المقرؤة من GitHub للتقارير المفتوحة"},"features":{"en":["Fetches unread review_requested notifications for open GitHub PRs","Filters by a specified GitHub team using the team slug or display name","Utilizes the GitHub CLI (gh) for authentication","Supports conversion of team display names to lowercase-hyphenated slugs","Runs a script to fetch review requests based on the identified team"],"zh":["支持 GitHub CLI 认证","获取 GitHub 未读通知","用于打开的 PR 请求审查","支持团队过滤","支持团队 slug 或显示名称"],"ja":["GitHub CLI 認証をサポート","GitHub の未読通知を取得","オープンの PR 要求のレビュー","チームフィルタリングをサポート","チーム slug または表示名称をサポート"],"ko":["GitHub CLI 인증 지원","GitHub 코드 리뷰 요청 알림 가져오기","오픈된 PR 요청 리뷰","팀 필터링 지원","팀 슬러그 또는 표시 이름 지원"],"es":["Fetch notificaciones de revisión de GitHub para PR abiertos","Filtrado por un equipo de GitHub","Requiere GitHub CLI autenticado","Compatibilidad con team slug y display name","Soporte para PRs no fusionados"],"fr":["Récupère les notifications de révision GitHub pour les PR ouverts","Filtrage par une équipe GitHub","Nécessite GitHub CLI authentifié","Compatibilité avec team slug et display name","Prise en charge des PR non fusionnés"],"de":["Ruft GitHub-Überprüfungsbenachrichtigungen für offene PRs ab","Filterung durch ein GitHub-Team","Benötigt authentifizierten GitHub-CLI","Unterstützung für Team-Slug und Anzeigename","Unterstützung für nicht fusionierte PRs"],"pt":["Fetch unread GitHub notifications para PRs abertas com solicitação de revisão de uma equipe específica","Utiliza o GitHub CLI para autenticação","Filtro por equipe específica","Aceita equipe slug ou nome de exibição","Converte para slug em minúsculas com hífen antes de passar para o script"],"ru":["Получение уведомлений о запросах на просмотр из GitHub для открытых PR","Использование GitHub CLI для аутентификации","Фильтрация по конкретной команде","Принятие командного слага или имени отображения","Преобразование в слаг в нижнем регистре с дефисом перед передачей в скрипт"],"ar":["جلب الإشعارات غير المقرؤة من GitHub للتقارير المفتوحة مع طلبات المراجعة من فريق معين","استخدام واجهة سطر الأوامر GitHub للتحقق","تصفية بواسطة فريق معين","قبول سلاج الفريق أو اسم العرض","تحويل إلى سلاج بحروف صغيرة مع شرطة قبل تمريره إلى البرنامج النصي"]},"keywords":{"en":["how to use gh-review-requests","gh-review-requests setup guide","github review requests","gh-review-requests alternative","github cli tutorial","gh-review-requests install","github pr review workflow","gh-review-requests vs github notifications","github team management"],"zh":["GitHub 代码审查请求","gh-review-requests","AIエージェント","GitHub CLI","代码审查","PR 请求","团队过滤","GitHub 通知"],"ja":["GitHub レビューリクエスト","gh-review-requests","AIエージェント","GitHub CLI","コードレビュー","PR 要求","チームフィルタリング","GitHub 通知"],"ko":["GitHub 코드 리뷰 요청","gh-review-requests","AI 도구","GitHub CLI","코드 리뷰","PR 요청","팀 필터링","GitHub 알림"],"es":["gh-review-requests","Agente de Inteligencia Artificial","GitHub CLI","notificaciones de revisión","PR abiertos","equipo de GitHub","desarrollo de software","herramientas de desarrollo"],"fr":["gh-review-requests","agent d''intelligence artificielle","GitHub CLI","notifications de révision","PR ouverts","équipe GitHub","développement de logiciels","outils de développement"],"de":["gh-review-requests","künstliche Intelligenz-Agenten","GitHub-CLI","Überprüfungsbenachrichtigungen","offene PRs","GitHub-Team","Softwareentwicklung","Entwicklungstools"],"pt":["gh-review-requests","GitHub notifications","PRs abertas","solicitação de revisão","equipe específica","GitHub CLI","autenticação","ferramentas de desenvolvimento"],"ru":["ИИ Агент gh-review-requests","уведомления GitHub","открытые PR","запросы на просмотр","конкретная команда","GitHub CLI","аутентификация","инструменты разработки"],"ar":["العميل الذكي gh-review-requests","إشعارات GitHub","التقارير المفتوحة","طلبات المراجعة","فريق معين","واجهة سطر الأوامر GitHub","التحقق","أدوات التطوير"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined GitHub review request management.","zh":"适合需要简化 GitHub 审查请求管理的开发代理。","ja":"GitHub のレビュー依頼管理を効率化する必要がある開発エージェントに最適です。","ko":"GitHub 리뷰 요청 관리를 간소화해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión de solicitudes de revisión de GitHub optimizada.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de demande de revue GitHub rationalisée.","de":"Perfekt für Entwicklungsmittelstände, die eine optimierte GitHub-Überprüfungsanforderungsverwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gestão de solicitações de revisão do GitHub simplificada.","ru":"Идеально для агентов разработки, которым необходима упрощенная система управления запросами на обзор GitHub.","ar":"مثالي لعمليات تطوير العوامل التي تحتاج إلى إدارة طلبات استعراض GitHub مبسطة."},"recommendation":{"en":"Empowers agents to fetch unread GitHub notifications for open PRs where review is requested from a specified team or opened by a team member, utilizing the GitHub CLI and filtering by team slug or display name, and provides real-time updates on the team review queue using `gh` commands and GitHub APIs.","zh":"赋予代理人使用 GitHub CLI 和 GitHub APIs 来获取特定团队或团队成员打开的未读 GitHub 通知的能力，实时更新团队审查队列，并且可以通过 `gh` 命令和 GitHub APIs 过滤团队 slug 或显示名称。","ja":"エージェントが GitHub CLI と GitHub APIs を使用して、特定のチームまたはチームメンバーによって開かれた未読の GitHub 通知を取得し、チームのレビュー キューを `gh` コマンドと GitHub APIs を使用してリアルタイムに更新し、チームのスラッグまたは表示名でフィルタリングする機能を提供します。","ko":"에이전트가 GitHub CLI와 GitHub APIs를 사용하여 특정 팀 또는 팀 구성원에 의해 열린 읽지 않은 GitHub 알림을 가져오는 기능을 제공하고, `gh` 명령과 GitHub APIs를 사용하여 팀 리뷰 큐를 실시간으로 업데이트하며, 팀 슬러그 또는 표시 이름으로 필터링할 수 있습니다.","es":"Habilita a los agentes a recuperar notificaciones de GitHub no leídas para solicitudes de extracción abiertas donde se solicita una revisión de un equipo especificado o abierta por un miembro del equipo, utilizando la CLI de GitHub y filtrando por slug de equipo o nombre de pantalla, y proporciona actualizaciones en tiempo real sobre la cola de revisión del equipo utilizando comandos `gh` y API de GitHub.","fr":"Permet aux agents de récupérer des notifications GitHub non lues pour des demandes de tirage ouvertes où une revue est demandée à partir d''une équipe spécifiée ou ouverte par un membre de l''équipe, en utilisant la CLI GitHub et en filtrant par slug d''équipe ou nom d''affichage, et fournit des mises à jour en temps réel sur la file d''attente de revue de l''équipe en utilisant des commandes `gh` et des API GitHub.","de":"Ermächtigt Agenten, ungelesene GitHub-Benachrichtigungen für offene Pull-Requests abzurufen, für die eine Überprüfung durch ein bestimmtes Team oder durch ein Teammitglied angefordert wird, unter Verwendung der GitHub-CLI und Filterung nach Team-Slug oder Anzeigename, und bietet Echtzeit-Updates zur Team-Überprüfungswarteschlange mithilfe von `gh`-Befehlen und GitHub-APIs.","pt":"Habilita os agentes a buscar notificações não lidas do GitHub para PRs abertos onde a revisão é solicitada de uma equipe especificada ou aberta por um membro da equipe, utilizando o GitHub CLI e filtrando por slug da equipe ou nome de exibição, e fornece atualizações em tempo real na fila de revisão da equipe usando comandos `gh` e APIs do GitHub.","ru":"Наделяет агентов возможностью получать непрочитанные уведомления GitHub для открытых PR, где запрошен обзор от указанной команды или открыт членом команды, используя GitHub CLI и фильтрацию по слагу команды или имени отображения, и предоставляет обновления в реальном времени в очереди обзора команды с использованием команд `gh` и API GitHub.","ar":"تمكّن العوامل من استرجاع الإشعارات غير المقروءة من GitHub لطلبات Pull Request المفتوحة التي طُلبت منها المراجعة من فريق محدد أو مفتوحة من قبل عضو في الفريق، باستخدام واجهة سطر أوامر GitHub وتصفية النتائج حسب الاسم المختصر للفريق أو اسم العرض، وتقدم تحديثات في الوقت الفعلي لطابور مراجعة الفريق باستخدام أوامر `gh` وواجهات برمجة تطبيقات GitHub."},"useCases":{"en":["Fetching unread GitHub review requests for a specified team","Automating the retrieval of open PRs requiring review from a team member","Streamlining team review queues by filtering notifications"],"zh":["为特定团队获取未读的 GitHub 审查请求","自动检索需要团队成员审查的打开的 PR","通过筛选通知来简化团队审查队列"],"ja":["特定チームの未読の GitHub レビュー依頼を取得する","チームメンバーのレビューが必要なオープン PR を自動的に取得する","通知をフィルタリングしてチームのレビュー キューを効率化する"],"ko":["지정된 팀의 읽지 않은 GitHub 리뷰 요청을 가져오는 것","팀 구성원의 리뷰가 필요한 열린 PR를 자동으로 가져오는 것","알림을 필터링하여 팀 리뷰 큐를 간소화하는 것"],"es":["Recuperación de solicitudes de revisión de GitHub no leídas para un equipo especificado","Automatización de la recuperación de solicitudes de extracción abiertas que requieren revisión de un miembro del equipo","Optimización de las colas de revisión del equipo mediante el filtrado de notificaciones"],"fr":["Récupération de demandes de revue GitHub non lues pour une équipe spécifiée","Automatisation de la récupération de demandes de tirage ouvertes nécessitant une revue d''un membre de l''équipe","Optimisation des files d''attente de revue d''équipe en filtrant les notifications"],"de":["Abrufen ungelesener GitHub-Überprüfungsanfragen für ein bestimmtes Team","Automatisierung des Abrufens offener Pull-Requests, die eine Überprüfung durch ein Teammitglied erfordern","Optimierung der Team-Überprüfungswarteschlangen durch Filtern von Benachrichtigungen"],"pt":["Buscar solicitações de revisão não lidas do GitHub para uma equipe especificada","Automatizar a recuperação de PRs abertos que requerem revisão de um membro da equipe","Simplificar filas de revisão da equipe filtrando notificações"],"ru":["Получение непрочитанных запросов на обзор GitHub для указанной команды","Автоматизация получения открытых PR, требующих обзора от члена команды","Упрощение очередей обзора команды путем фильтрации уведомлений"],"ar":["استرجاع طلبات المراجعة غير المقروءة من GitHub لفريق محدد","تأتميم استرجاع طلبات Pull Request المفتوحة التي تتطلب مراجعة من عضو في الفريق","تبسيط طوابير مراجعة الفريق من خلال تصفية الإشعارات"]},"limitations":{"en":["Requires GitHub CLI (`gh`) authenticated","Limited to open (unmerged) PRs","Dependent on GitHub team configuration and permissions"],"zh":["需要通过身份验证的 GitHub CLI (`gh`)","仅限打开（未合并）的 PR","依赖于 GitHub 团队配置和权限"],"ja":["認証された GitHub CLI (`gh`) が必要","オープン (マージされていない) の PR に限られる","GitHub チームの設定と権限に依存する"],"ko":["인증된 GitHub CLI (`gh`)가 필요합니다.","열린 (병합되지 않은) PR에만 제한됩니다.","GitHub 팀 구성 및 권한에 종속됩니다."],"es":["Requiere GitHub CLI (`gh`) autenticada","Limitada a solicitudes de extracción abiertas (no fusionadas)","Dependiente de la configuración y permisos del equipo de GitHub"],"fr":["Nécessite une CLI GitHub (`gh`) authentifiée","Limitée aux demandes de tirage ouvertes (non fusionnées)","Dépendante de la configuration et des autorisations de l''équipe GitHub"],"de":["Erfordert authentifizierte GitHub-CLI (`gh`)","Begrenzt auf offene Pull-Requests (nicht zusammengeführt)","Abhängig von der Konfiguration und den Berechtigungen des GitHub-Teams"],"pt":["Requer autenticação do GitHub CLI (`gh`)","Limitado a PRs abertos (não mesclados)","Dependente da configuração e permissões da equipe do GitHub"],"ru":["Требует аутентификации GitHub CLI (`gh`)","Ограничен открытymi (неслитыми) PR","Зависит от конфигурации и разрешений команды GitHub"],"ar":["يتطلب مصادقة واجهة سطر أوامر GitHub (`gh`)","محدود لطلبات Pull Request المفتوحة (غير المدمجة)","يعتمد على تكوين الفريق وأذونات GitHub"]},"version":4},"contentHash":"6ad2c7842dc19fb76c94564753981e87b0b1e848de0998477f29ccd18d6cf659","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":71}');
