INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/gh-review-requests', 'gh-review-requests', 'getsentry', 'skills', 'official', 'gh-review-requests getsentry skills official tag-production The gh-review-requests skill fetches unread GitHub notifications for open PRs where review is requested from a specified team or opened by a team member, benefiting developers and teams. gh-review-requests skill 用于获取 GitHub 未读通知，用于打开的 PR 请求审查，支持 GitHub CLI 认证 gh-review-requests スキルは、GitHub の未読通知を取得するために使用され、GitHub CLI 認証をサポートします gh-review-requests skill 은 GitHub 코드 리뷰 요청을 관리하기 위해 사용되며 GitHub CLI 인증을 지원합니다 gh-review-requests fetch notificaciones de revisión de GitHub para PR abiertos filtradas por un equipo de GitHub. Requiere GitHub CLI autenticado. gh-review-requests récupère les notifications de révision GitHub pour les PR ouverts filtrées par une équipe GitHub. Nécessite GitHub CLI authentifié. gh-review-requests ruft GitHub-Überprüfungsbenachrichtigungen für offene PRs ab, die von einem GitHub-Team gefiltert werden. Benötigt authentifizierten GitHub-CLI. O gh-review-requests é um skill que fetch unread GitHub notifications para PRs abertas com solicitação de revisão de uma equipe específica, utilizando o GitHub CLI. ИИ Агент gh-review-requests - это навык, который получает уведомления о запросах на просмотр из GitHub для открытых PR, используя GitHub CLI. العميل الذكي gh-review-requests هو مهارة تقوم بFetching الإشعارات غير المقرؤة من GitHub للتقارير المفتوحة مع طلبات المراجعة من فريق معين، باستخدام واجهة سطر الأوامر GitHub. how to use gh-review-requests gh-review-requests setup guide github review requests gh-review-requests alternative github cli tutorial gh-review-requests install github pr review workflow gh-review-requests vs github notifications github team management GitHub 代码审查请求 gh-review-requests AIエージェント GitHub CLI 代码审查 PR 请求 团队过滤 GitHub 通知 Fetches unread review_requested notifications for open GitHub PRs Filters by a specified GitHub team using the team slug or display name Utilizes the GitHub CLI (gh) for authentication Supports conversion of team display names to lowercase-hyphenated slugs Runs a script to fetch review requests based on the identified team gh-review-requests is a skill that fetches unread review_requested notifications for open GitHub PRs, filtered by a GitHub team, utilizing the GitHub CLI (gh) for authentication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/expo-dev-client', 'official', 'expo', 'skills', 'expo/skills', 'expo-dev-client', 1349, 59, 71, '2026-03-06T04:04:30Z', '2026-03-06T05:22:43.005Z', 'aa79e42e9cd96ea92d4e691fb8222145055dec1b868b7defce224a41d8878a5f', '{"id":"expo/skills/expo-dev-client","name":"expo-dev-client","description":{"zh":"expo-dev-client 是用于创建和分发 Expo 开发客户端的工具，支持本地构建和 TestFlight 分发","ja":"expo-dev-client は、Expo 開発クライアントを作成および配布するためのツールで、ローカルビルドと TestFlight 配布をサポート","ko":"expo-dev-client는 Expo 개발 클라이언트를 생성 및 배포하기 위한 도구로 로컬 빌드 및 TestFlight 배포를 지원","es":"expo-dev-client permite a los desarrolladores crear y distribuir clientes de desarrollo de Expo de forma local o mediante TestFlight para probar cambios de código nativo","fr":"expo-dev-client permet aux développeurs de créer et de distribuer des clients de développement Expo localement ou via TestFlight pour tester les modifications de code natif","de":"Mit expo-dev-client können Entwickler Entwicklungsklienten für Expo lokal oder über TestFlight erstellen und verteilen, um native Code-Änderungen zu testen","pt":"O Expo Dev Client permite criar clientes de desenvolvimento locais ou via TestFlight para testar alterações de código nativo em dispositivos físicos","ru":"Expo Dev Client позволяет создавать клиенты разработки локально или через TestFlight для тестирования изменений родного кода на физических устройствах","ar":"أداة العميل التطويرية expo-dev-client تسمح بإنشاء عملاء التطوير المحلي أو عبر تطبيق TestFlight لاختبار التغييرات على الكود الأصلي على الأجهزة الفعلية","en":"Build and distribute Expo development clients locally or via TestFlight"},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"expo-dev-client","description":"Build and distribute Expo development clients locally or via TestFlight","version":"1.0.0","bodyPreview":"Use EAS Build to create development clients for testing native code changes on physical devices. Use this for creating custom Expo Go clients for testing branches of your app.\n\n## Important: When Development Clients Are Needed\n\n**Only create development clients when your app requires custom native code.** Most apps work fine in Expo Go.\n\nYou need a dev client ONLY when using:\n- Local Expo modules (custom native code)\n- Apple targets (widgets, app clips, extensions)\n- Third-party native modules n","body":"Use EAS Build to create development clients for testing native code changes on physical devices. Use this for creating custom Expo Go clients for testing branches of your app.\n\n## Important: When Development Clients Are Needed\n\n**Only create development clients when your app requires custom native code.** Most apps work fine in Expo Go.\n\nYou need a dev client ONLY when using:\n- Local Expo modules (custom native code)\n- Apple targets (widgets, app clips, extensions)\n- Third-party native modules not in Expo Go\n\n**Try Expo Go first** with `npx expo start`. If everything works, you don''t need a dev client.\n\n## EAS Configuration\n\nEnsure `eas.json` has a development profile:\n\n```json\n{\n  \"cli\": {\n    \"version\": \">= 16.0.1\",\n    \"appVersionSource\": \"remote\"\n  },\n  \"build\": {\n    \"production\": {\n      \"autoIncrement\": true\n    },\n    \"development\": {\n      \"autoIncrement\": true,\n      \"developmentClient\": true\n    }\n  },\n  \"submit\": {\n    \"production\": {},\n    \"development\": {}\n  }\n}\n```\n\nKey settings:\n- `developmentClient: true` - Bundles expo-dev-client for development builds\n- `autoIncrement: true` - Automatically increments build numbers\n- `appVersionSource: \"remote\"` - Uses EAS as the source of truth for version numbers\n\n## Building for TestFlight\n\nBuild iOS dev client and submit to TestFlight in one command:\n\n```bash\neas build -p ios --profile development --submit\n```\n\nThis will:\n1. Build the development client in the cloud\n2. Automatically submit to App Store Connect\n3. Send you an email when the build is ready in TestFlight\n\nAfter receiving the TestFlight email:\n1. Download the build from TestFlight on your device\n2. Launch the app to see the expo-dev-client UI\n3. Connect to your local Metro bundler or scan a QR code\n\n## Building Locally\n\nBuild a development client on your machine:\n\n```bash\n# iOS (requires Xcode)\neas build -p ios --profile development --local\n\n# Android\neas build -p android --profile development --local\n```\n\nLocal builds output:\n- iOS: `.ipa` file\n- Android: `.apk` or `.aab` file\n\n## Installing Local Builds\n\nInstall iOS build on simulator:\n\n```bash\n# Find the .app in the .tar.gz output\ntar -xzf build-*.tar.gz\nxcrun simctl install booted ./path/to/App.app\n```\n\nInstall iOS build on device (requires signing):\n\n```bash\n# Use Xcode Devices window or ideviceinstaller\nideviceinstaller -i build.ipa\n```\n\nInstall Android build:\n\n```bash\nadb install build.apk\n```\n\n## Building for Specific Platform\n\n```bash\n# iOS only\neas build -p ios --profile development\n\n# Android only\neas build -p android --profile development\n\n# Both platforms\neas build --profile development\n```\n\n## Checking Build Status\n\n```bash\n# List recent builds\neas build:list\n\n# View build details\neas build:view\n```\n\n## Using the Dev Client\n\nOnce installed, the dev client provides:\n- **Development server connection** - Enter your Metro bundler URL or scan QR\n- **Build information** - View native build details\n- **Launcher UI** - Switch between development servers\n\nConnect to local development:\n\n```bash\n# Start Metro bundler\nnpx expo start --dev-client\n\n# Scan QR code with dev client or enter URL manually\n```\n\n## Troubleshooting\n\n**Build fails with signing errors:**\n```bash\neas credentials\n```\n\n**Clear build cache:**\n```bash\neas build -p ios --profile development --clear-cache\n```\n\n**Check EAS CLI version:**\n```bash\neas --version\neas update\n```\n"},"category":"official","lastSynced":"2026-03-06T05:22:43.005Z","seo":{"title":{"zh":"expo-dev-client 设置指南：本地构建和分发 Expo 开发客户端","ja":"expo-dev-client のベストプラクティス：Expo 開発クライアントのローカルビルドと配布","ko":"expo-dev-client 설정 가이드: 로컬에서 Expo 개발 클라이언트 빌드 및 배포","es":"Guía de configuración de expo-dev-client para desarrollad...","fr":"Paramétrer expo-dev-client pour les développeurs - Meille...","de":"Einrichten von expo-dev-client für Entwickler: Lokale Ers...","pt":"Guia de Configuração do Expo Dev Client para Desenvolvedores","ru":"ИИ Агенты: Expo Dev Client - Руководство по Настройке","ar":"إعداد أداة العميل التطويرية expo-dev-client للعاملين بالت...","en":"expo-dev-client"},"description":{"zh":"expo-dev-client 是用于创建和分发 Expo 开发客户端的工具，支持本地构建和 TestFlight 分发","ja":"expo-dev-client は、Expo 開発クライアントを作成および配布するためのツールで、ローカルビルドと TestFlight 配布をサポート","ko":"expo-dev-client는 Expo 개발 클라이언트를 생성 및 배포하기 위한 도구로 로컬 빌드 및 TestFlight 배포를 지원","es":"expo-dev-client permite a los desarrolladores crear y distribuir clientes de desarrollo de Expo de forma local o mediante TestFlight para probar cambios de c...","fr":"expo-dev-client permet aux développeurs de créer et de distribuer des clients de développement Expo localement ou via TestFlight pour tester les modification...","de":"Mit expo-dev-client können Entwickler Entwicklungsklienten für Expo lokal oder über TestFlight erstellen und verteilen, um native Code-Änderungen zu testen","pt":"O Expo Dev Client permite criar clientes de desenvolvimento locais ou via TestFlight para testar alterações de código nativo em dispositivos físicos","ru":"Expo Dev Client позволяет создавать клиенты разработки локально или через TestFlight для тестирования изменений родного кода на физических устройствах","ar":"أداة العميل التطويرية expo-dev-client تسمح بإنشاء عملاء التطوير المحلي أو عبر تطبيق TestFlight لاختبار التغييرات على الكود الأصلي على الأجهزة الفعلية","en":"Build and distribute Expo development clients locally or via TestFlight"},"definition":{"en":"Build and distribute Expo development clients locally or via TestFlight"},"features":{"zh":["使用 EAS Build 创建开发客户端","支持本地构建和 TestFlight 分发","适用于自定义 Expo Go 客户端","支持本机代码更改的测试","支持 Apple 目标（widgets、app clips、extensions）","支持第三方本机模块"],"ja":["EAS Build を使用して開発クライアントを作成","ローカルビルドと TestFlight 配布をサポート","カスタム Expo Go クライアントに適しています","ネイティブコードの変更をテストするためのサポート","Apple ターゲット（widgets、app clips、extensions）をサポート","サードパーティのネイティブモジュールをサポート"],"ko":["EAS Build를 사용하여 개발 클라이언트 생성","로컬 빌드 및 TestFlight 배포 지원","커스텀 Expo Go 클라이언트에 적합","네이티브 코드 변경 테스트 지원","Apple 대상(위젯, 앱 클립, 확장 프로그램) 지원","제3자 네이티브 모듈 지원"],"es":["Creación de clientes de desarrollo de Expo para probar cambios de código nativo","Distribución local o mediante TestFlight","Compatibilidad con módulos de Expo personalizados","Soporte para objetivos de Apple como widgets, app clips y extensiones","Integración con módulos nativos de terceros"],"fr":["Création de clients de développement Expo pour tester les modifications de code natif","Distribution locale ou via TestFlight","Compatibilité avec des modules Expo personnalisés","Prise en charge d''objectifs Apple tels que les widgets, les app clips et les extensions","Intégration avec des modules natifs tiers"],"de":["Erstellung von Entwicklungsklienten für Expo zur Überprüfung von native Code-Änderungen","Lokale oder über TestFlight verteilte Verteilung","Unterstützung für benutzerdefinierte Expo-Module","Unterstützung für Apple-Ziele wie Widgets, App-Clips und Erweiterungen","Integration mit nativen Modulen von Drittanbietern"],"pt":["Criação de clientes de desenvolvimento locais para testar alterações de código nativo","Distribuição de clientes de desenvolvimento via TestFlight","Suporte a módulos Expo personalizados","Suporte a alvos Apple (widgets, app clips, extensions)","Suporte a módulos nativos de terceiros"],"ru":["Создание локальных клиентов разработки для тестирования изменений родного кода","Распространение клиентов разработки через TestFlight","Поддержка пользовательских модулей Expo","Поддержка целей Apple (виджеты, клипы приложений, расширения)","Поддержка родных модулей третьих сторон"],"ar":["إنشاء عملاء التطوير المحلي لاختبار التغييرات على الكود الأصلي","توزيع عملاء التطوير عبر تطبيق TestFlight","دعم الوحدات النمطية المخصصة لـ Expo","دعم أهداف شركة آبل (الوسائط، مقاطع التطبيقات، الامتدادات)","دعم الوحدات الأصلية لشركات الطرف الثالث"]},"keywords":{"zh":["expo-dev-client","Expo 开发客户端","本地构建","TestFlight 分发","EAS Build","自定义 Expo Go","本机代码更改","Apple 目标","第三方本机模块","AI工具","AIエージェント"],"ja":["expo-dev-client","Expo 開発クライアント","ローカルビルド","TestFlight 配布","EAS Build","カスタム Expo Go","ネイティブコードの変更","Apple ターゲット","サードパーティのネイティブモジュール","AIエージェント","AIツール"],"ko":["expo-dev-client","Expo 개발 클라이언트","로컬 빌드","TestFlight 배포","EAS Build","커스텀 Expo Go","네이티브 코드 변경","Apple 대상","제3자 네이티브 모듈","AI 에이전트","AI 도구"],"es":["expo-dev-client","clientes de desarrollo de Expo","código nativo","TestFlight","módulos de Expo personalizados","objetivos de Apple","módulos nativos de terceros","desarrollo de aplicaciones móviles","herramientas de desarrollo de Expo"],"fr":["expo-dev-client","clients de développement Expo","code natif","TestFlight","modules Expo personnalisés","objectifs Apple","modules natifs tiers","développement d''applications mobiles","outils de développement Expo"],"de":["expo-dev-client","Entwicklungsklienten für Expo","native Code","TestFlight","benutzerdefinierte Expo-Module","Apple-Ziele","native Module von Drittanbietern","Entwicklung von mobilen Anwendungen","Entwicklungstools für Expo"],"pt":["Expo Dev Client","criação de clientes de desenvolvimento","testar código nativo","TestFlight","módulos Expo personalizados","alvos Apple","módulos nativos de terceiros"],"ru":["Expo Dev Client","создание клиентов разработки","тестирование родного кода","TestFlight","пользовательские модули Expo","цели Apple","родные модули третьих сторон"],"ar":["أداة العميل التطويرية expo-dev-client","إنشاء عملاء التطوير","اختبار الكود الأصلي","تطبيق TestFlight","الوحدات النمطية المخصصة لـ Expo","أهداف شركة آبل","الوحدات الأصلية لشركات الطرف الثالث"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Mobile App Development Agents requiring native code testing on physical devices via Expo development clients","zh":"适合需要在物理设备上通过Expo开发客户端进行本机代码测试的移动应用开发代理","ja":"Expoの開発クライアントを介して物理デバイスでネイティブコードのテストを必要とするモバイルアプリ開発エージェントに最適","ko":"Expo 개발 클라이언트를 통해 물리적 장치에서 네이티브 코드 테스트가 필요한 모바일 앱 개발 에이전트에 적합","es":"Ideal para agentes de desarrollo de aplicaciones móviles que requieren pruebas de código nativo en dispositivos físicos a través de clientes de desarrollo de Expo","fr":"Idéal pour les agents de développement d''applications mobiles nécessitant des tests de code natif sur des appareils physiques via des clients de développement Expo","de":"Ideal für Mobile App Development Agents, die native Code-Tests auf physischen Geräten über Expo-Entwicklungsclients erfordern","pt":"Ideal para Agentes de Desenvolvimento de Aplicativos Móveis que exigem testes de código nativo em dispositivos físicos por meio de clientes de desenvolvimento Expo","ru":"Идеально подходит для агентов разработки мобильных приложений, требующих тестирования родного кода на физических устройствах через клиенты разработки Expo","ar":"مثالي لعميل تطبيق الهاتف المحمول الذي يتطلب اختبار الكود الأصلي على الأجهزة المادية من خلال عملاء تطوير Expo"},"recommendation":{"en":"Empowers agents to create custom Expo Go clients for testing branches of their app using EAS Build, facilitating the testing of local Expo modules, Apple targets, and third-party native modules over TestFlight","zh":"赋予代理创建自定义Expo Go客户端的能力，以使用EAS Build测试应用程序的分支，促进对本地Expo模块、Apple目标和第三方本机模块的TestFlight测试","ja":"EAS Buildを使用してアプリのブランチをテストするためのカスタムExpo Goクライアントを作成するエージェントを可能にし、ローカルExpoモジュール、Appleターゲット、およびサードパーティのネイティブモジュールのTestFlightテストを促進","ko":"EAS Build를 사용하여 애플리케이션의 분기를 테스트하기 위한 사용자 지정 Expo Go 클라이언트를 생성할 수 있는 에이전트를 가능하게 하며, 로컬 Expo 모듈, Apple 대상 및 제3자 네이티브 모듈의 TestFlight 테스트를 촉진","es":"Habilita a los agentes a crear clientes personalizados de Expo Go para probar ramas de su aplicación utilizando EAS Build, lo que facilita la prueba de módulos locales de Expo, objetivos de Apple y módulos nativos de terceros a través de TestFlight","fr":"Permet aux agents de créer des clients Expo Go personnalisés pour tester les branches de leur application en utilisant EAS Build, ce qui facilite le test des modules Expo locaux, des cibles Apple et des modules natifs tiers via TestFlight","de":"Ermächtigt Agenten, benutzerdefinierte Expo Go-Clients für das Testen von App-Zweigen mit EAS Build zu erstellen, wodurch das Testen lokaler Expo-Module, Apple-Ziele und native Module von Drittanbietern über TestFlight erleichtert wird","pt":"Habilita os agentes a criar clientes personalizados Expo Go para testar branches do aplicativo usando EAS Build, facilitando o teste de módulos Expo locais, alvos Apple e módulos nativos de terceiros via TestFlight","ru":"Позволяет агентам создавать пользовательские клиенты Expo Go для тестирования веток приложения с помощью EAS Build, что упрощает тестирование локальных модулей Expo, целей Apple и родных модулей третьих сторон через TestFlight","ar":"تمكن العملاء من إنشاء عملاء Expo Go المخصصين لاختبار فروع التطبيق باستخدام EAS Build، مما يسهل اختبار الوحدات المحلية Expo وأهداف Apple ووحدات الأصليين من الطرف الثالث عبر TestFlight"},"useCases":{"en":["Building and distributing development clients locally or via TestFlight","Creating custom Expo Go clients for testing native code changes on physical devices","Testing branches of an app with custom native code using EAS Build"],"zh":["在本地或通过TestFlight构建和分发开发客户端","为物理设备上的本机代码更改创建自定义Expo Go客户端","使用EAS Build和自定义本机代码测试应用程序的分支"],"ja":["ローカルまたはTestFlightを介して開発クライアントをビルドおよび配布","物理デバイスでのネイティブコードの変更のためのカスタムExpo Goクライアントを作成","EAS Buildおよびカスタムネイティブコードを使用してアプリのブランチをテスト"],"ko":["로컬 또는 TestFlight를 통해 개발 클라이언트를 빌드 및 배포","물리적 장치에서 네이티브 코드 변경에 대한 사용자 지정 Expo Go 클라이언트 생성","EAS Build 및 사용자 지정 네이티브 코드를 사용하여 애플리케이션의 분기를 테스트"],"es":["Crear y distribuir clientes de desarrollo localmente o a través de TestFlight","Crear clientes personalizados de Expo Go para probar cambios de código nativo en dispositivos físicos","Probar ramas de una aplicación con código nativo personalizado utilizando EAS Build"],"fr":["Créer et distribuer des clients de développement localement ou via TestFlight","Créer des clients Expo Go personnalisés pour tester les modifications de code natif sur des appareils physiques","Tester les branches d''une application avec du code natif personnalisé en utilisant EAS Build"],"de":["Erstellen und Verteilen von Entwicklungsclients lokal oder über TestFlight","Erstellen benutzerdefinierter Expo Go-Clients zum Testen von Änderungen des nativen Codes auf physischen Geräten","Testen von App-Zweigen mit benutzerdefiniertem nativem Code unter Verwendung von EAS Build"],"pt":["Construir e distribuir clientes de desenvolvimento localmente ou via TestFlight","Criar clientes Expo Go personalizados para testar alterações de código nativo em dispositivos físicos","Testar branches de um aplicativo com código nativo personalizado usando EAS Build"],"ru":["Построение и распространение клиентов разработки локально или через TestFlight","Создание пользовательских клиентов Expo Go для тестирования изменений родного кода на физических устройствах","Тестирование веток приложения с пользовательским родным кодом с помощью EAS Build"],"ar":["بناء وتوزيع عملاء التطوير محليا أو من خلال TestFlight","إنشاء عملاء Expo Go المخصصين لاختبار تغييرات الكود الأصلي على الأجهزة المادية","اختبار فروع التطبيق مع الكود الأصلي المخصص باستخدام EAS Build"]},"limitations":{"en":["Requires custom native code, local Expo modules, Apple targets, or third-party native modules to be necessary","Only needed when Expo Go is insufficient for app testing"],"zh":["需要自定义本机代码、 本地Expo模块、Apple目标或第三方本机模块","仅在Expo Go不足以用于应用程序测试时需要"],"ja":["カスタムネイティブコード、ローカルExpoモジュール、Appleターゲット、またはサードパーティのネイティブモジュールが必要","Expo Goがアプリのテストに不足している場合のみ必要"],"ko":["사용자 지정 네이티브 코드, 로컬 Expo 모듈, Apple 대상 또는 제3자 네이티브 모듈이 필요","Expo Go가 애플리케이션 테스트에 충분하지 않은 경우에만 필요"],"es":["Requiere código nativo personalizado, módulos locales de Expo, objetivos de Apple o módulos nativos de terceros para ser necesarios","Solo es necesario cuando Expo Go es insuficiente para la prueba de la aplicación"],"fr":["Nécessite un code natif personnalisé, des modules Expo locaux, des cibles Apple ou des modules natifs tiers pour être nécessaire","N''est nécessaire que lorsque Expo Go est insuffisant pour les tests d''application"],"de":["Benötigt benutzerdefinierten nativen Code, lokale Expo-Module, Apple-Ziele oder native Module von Drittanbietern, um notwendig zu sein","Wird nur benötigt, wenn Expo Go für die App-Testung unzureichend ist"],"pt":["Exige código nativo personalizado, módulos Expo locais, alvos Apple ou módulos nativos de terceiros para serem necessários","Só é necessário quando o Expo Go é insuficiente para o teste do aplicativo"],"ru":["Требует пользовательского родного кода, локальных модулей Expo, целей Apple или родных модулей третьих сторон для необходимости","Требуется только тогда, когда Expo Go недостаточен для тестирования приложения"],"ar":["يتطلب كود أصلي مخصص، وحدات Expo المحلية، وأهداف Apple، أو وحدات الأصليين من الطرف الثالث لتكون ضرورية","يتم الحاجة إليها فقط عند عدم كفاية Expo Go لاختبار التطبيق"]},"version":4},"contentHash":"aa79e42e9cd96ea92d4e691fb8222145055dec1b868b7defce224a41d8878a5f","repoEtag":"W/\"3d0b500324a01c512d7df52a068a135b350d8e49d3ce113161c97e6acbc0dfba\"","qualityScore":71}');
