INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/expo-dev-client', 'expo-dev-client', 'expo', 'skills', 'official', 'expo-dev-client expo skills official expo-dev-client 是用于创建和分发 Expo 开发客户端的工具，支持本地构建和 TestFlight 分发 expo-dev-client は、Expo 開発クライアントを作成および配布するためのツールで、ローカルビルドと TestFlight 配布をサポート expo-dev-client는 Expo 개발 클라이언트를 생성 및 배포하기 위한 도구로 로컬 빌드 및 TestFlight 배포를 지원 expo-dev-client permite a los desarrolladores crear y distribuir clientes de desarrollo de Expo de forma local o mediante TestFlight para probar cambios de código nativo expo-dev-client permet aux développeurs de créer et de distribuer des clients de développement Expo localement ou via TestFlight pour tester les modifications de code natif Mit expo-dev-client können Entwickler Entwicklungsklienten für Expo lokal oder über TestFlight erstellen und verteilen, um native Code-Änderungen zu testen O Expo Dev Client permite criar clientes de desenvolvimento locais ou via TestFlight para testar alterações de código nativo em dispositivos físicos Expo Dev Client позволяет создавать клиенты разработки локально или через TestFlight для тестирования изменений родного кода на физических устройствах أداة العميل التطويرية expo-dev-client تسمح بإنشاء عملاء التطوير المحلي أو عبر تطبيق TestFlight لاختبار التغييرات على الكود الأصلي على الأجهزة الفعلية Build and distribute Expo development clients locally or via TestFlight expo-dev-client Expo 开发客户端 本地构建 TestFlight 分发 EAS Build 自定义 Expo Go 本机代码更改 Apple 目标 第三方本机模块 AI工具 AIエージェント Build and distribute Expo development clients locally or via TestFlight');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-cli', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-cli', 8290, 490, 71, '2026-03-06T05:28:53Z', '2026-03-06T05:31:03.310Z', 'c011e33ff672d5b1ec80fd280f245ff0c15e8dac3b8a0d146c8973a596185878', '{"id":"huggingface/skills/hugging-face-cli","name":"hugging-face-cli","description":{"en":"The hugging-face-cli skill enables developers to execute Hugging Face Hub operations, including downloading models and datasets, uploading files, and managing repositories. It benefits AI agents and developers working with Hugging Face Hub.","zh":"Hugging Face CLI提供了直接的终端访问Hugging Face Hub的能力，用于下载、上传和管理仓库、缓存和计算资源","ja":"Hugging Face CLIは、Hugging Face Hubへの直接的なターミナルアクセスを提供します。ダウンロード、アップロード、リポジトリ、キャッシュ、コンピューティングリソースの管理が可能です","ko":"Hugging Face CLI는 Hugging Face Hub에 대한 직접적인 터미널 액세스를 제공합니다. 다운로드, 업로드, 리포지토리, 캐시 및 컴퓨팅 리소스 관리가 가능합니다","pt":"O Hugging Face CLI é uma ferramenta de linha de comando para interagir com o Hugging Face Hub, permitindo downloads de modelos e datasets, upload de arquivos e gerenciamento de repositórios","ru":"Hugging Face CLI — это инструмент командной строки для взаимодействия с Hugging Face Hub, позволяющий загружать модели и наборы данных,上传 файлов и управлять репозиториями","ar":"Hugging Face CLI هو أداة سطر أوامر للتفاعل مع Hugging Face Hub، مما يسمح بتحميل النماذج و مجموعات البيانات ورفع الملفات وإدارة المستودعات"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-cli","description":"Execute Hugging Face Hub operations using the `hf` CLI. Use when the user needs to download models/datasets/spaces, upload files to Hub repositories, create repos, manage local cache, or run compute jobs on HF infrastructure. Covers authentication, file transfers, repository creation, cache operations, and cloud compute.","bodyPreview":"# Hugging Face CLI\n\nThe `hf` CLI provides direct terminal access to the Hugging Face Hub for downloading, uploading, and managing repositories, cache, and compute resources.\n\n## Quick Command Reference\n\n| Task | Command |\n|------|---------|\n| Login | `hf auth login` |\n| Download model | `hf download <repo_id>` |\n| Download to folder | `hf download <repo_id> --local-dir ./path` |\n| Upload folder | `hf upload <repo_id> . .` |\n| Create repo | `hf repo create <name>` |\n| Create tag | `hf repo tag cr","body":"# Hugging Face CLI\n\nThe `hf` CLI provides direct terminal access to the Hugging Face Hub for downloading, uploading, and managing repositories, cache, and compute resources.\n\n## Quick Command Reference\n\n| Task | Command |\n|------|---------|\n| Login | `hf auth login` |\n| Download model | `hf download <repo_id>` |\n| Download to folder | `hf download <repo_id> --local-dir ./path` |\n| Upload folder | `hf upload <repo_id> . .` |\n| Create repo | `hf repo create <name>` |\n| Create tag | `hf repo tag create <repo_id> <tag>` |\n| Delete files | `hf repo-files delete <repo_id> <files>` |\n| List cache | `hf cache ls` |\n| Remove from cache | `hf cache rm <repo_or_revision>` |\n| List models | `hf models ls` |\n| Get model info | `hf models info <model_id>` |\n| List datasets | `hf datasets ls` |\n| Get dataset info | `hf datasets info <dataset_id>` |\n| List spaces | `hf spaces ls` |\n| Get space info | `hf spaces info <space_id>` |\n| List endpoints | `hf endpoints ls` |\n| Run GPU job | `hf jobs run --flavor a10g-small <image> <cmd>` |\n| Environment info | `hf env` |\n\n## Core Commands\n\n### Authentication\n```bash\nhf auth login                    # Interactive login\nhf auth login --token $HF_TOKEN  # Non-interactive\nhf auth whoami                   # Check current user\nhf auth list                     # List stored tokens\nhf auth switch                   # Switch between tokens\nhf auth logout                   # Log out\n```\n\n### Download\n```bash\nhf download <repo_id>                              # Full repo to cache\nhf download <repo_id> file.safetensors             # Specific file\nhf download <repo_id> --local-dir ./models         # To local directory\nhf download <repo_id> --include \"*.safetensors\"    # Filter by pattern\nhf download <repo_id> --repo-type dataset          # Dataset\nhf download <repo_id> --revision v1.0              # Specific version\n```\n\n### Upload\n```bash\nhf upload <repo_id> . .                            # Current dir to root\nhf upload <repo_id> ./models /weights              # Folder to path\nhf upload <repo_id> model.safetensors              # Single file\nhf upload <repo_id> . . --repo-type dataset        # Dataset\nhf upload <repo_id> . . --create-pr                # Create PR\nhf upload <repo_id> . . --commit-message=\"msg\"     # Custom message\n```\n\n### Repository Management\n```bash\nhf repo create <name>                              # Create model repo\nhf repo create <name> --repo-type dataset          # Create dataset\nhf repo create <name> --private                    # Private repo\nhf repo create <name> --repo-type space --space_sdk gradio  # Gradio space\nhf repo delete <repo_id>                           # Delete repo\nhf repo move <from_id> <to_id>                     # Move repo to new namespace\nhf repo settings <repo_id> --private true          # Update repo settings\nhf repo list --repo-type model                     # List repos\nhf repo branch create <repo_id> release-v1         # Create branch\nhf repo branch delete <repo_id> release-v1         # Delete branch\nhf repo tag create <repo_id> v1.0                  # Create tag\nhf repo tag list <repo_id>                         # List tags\nhf repo tag delete <repo_id> v1.0                  # Delete tag\n```\n\n### Delete Files from Repo\n```bash\nhf repo-files delete <repo_id> folder/             # Delete folder\nhf repo-files delete <repo_id> \"*.txt\"             # Delete with pattern\n```\n\n### Cache Management\n```bash\nhf cache ls                      # List cached repos\nhf cache ls --revisions          # Include individual revisions\nhf cache rm model/gpt2           # Remove cached repo\nhf cache rm <revision_hash>      # Remove cached revision\nhf cache prune                   # Remove detached revisions\nhf cache verify gpt2             # Verify checksums from cache\n```\n\n### Browse Hub\n```bash\n# Models\nhf models ls                                        # List top trending models\nhf models ls --search \"MiniMax\" --author MiniMaxAI  # Search models\nhf models ls --filter \"text-generation\" --limit 20  # Filter by task\nhf models info MiniMaxAI/MiniMax-M2.1               # Get model info\n\n# Datasets\nhf datasets ls                                      # List top trending datasets\nhf datasets ls --search \"finepdfs\" --sort downloads # Search datasets\nhf datasets info HuggingFaceFW/finepdfs             # Get dataset info\n\n# Spaces\nhf spaces ls                                        # List top trending spaces\nhf spaces ls --filter \"3d\" --limit 10               # Filter by 3D modeling spaces\nhf spaces info enzostvs/deepsite                    # Get space info\n```\n\n### Jobs (Cloud Compute)\n```bash\nhf jobs run python:3.12 python script.py           # Run on CPU\nhf jobs run --flavor a10g-small <image> <cmd>      # Run on GPU\nhf jobs run --secrets HF_TOKEN <image> <cmd>       # With HF token\nhf jobs ps                                         # List jobs\nhf jobs logs <job_id>                              # View logs\nhf jobs cancel <job_id>                            # Cancel job\n```\n\n### Inference Endpoints\n```bash\nhf endpoints ls                                     # List endpoints\nhf endpoints deploy my-endpoint \\\n  --repo openai/gpt-oss-120b \\\n  --framework vllm \\\n  --accelerator gpu \\\n  --instance-size x4 \\\n  --instance-type nvidia-a10g \\\n  --region us-east-1 \\\n  --vendor aws\nhf endpoints describe my-endpoint                   # Show endpoint details\nhf endpoints pause my-endpoint                      # Pause endpoint\nhf endpoints resume my-endpoint                     # Resume endpoint\nhf endpoints scale-to-zero my-endpoint              # Scale to zero\nhf endpoints delete my-endpoint --yes               # Delete endpoint\n```\n**GPU Flavors:** `cpu-basic`, `cpu-upgrade`, `cpu-xl`, `t4-small`, `t4-medium`, `l4x1`, `l4x4`, `l40sx1`, `l40sx4`, `l40sx8`, `a10g-small`, `a10g-large`, `a10g-largex2`, `a10g-largex4`, `a100-large`, `h100`, `h100x8`\n\n## Common Patterns\n\n### Download and Use Model Locally\n```bash\n# Download to local directory for deployment\nhf download meta-llama/Llama-3.2-1B-Instruct --local-dir ./model\n\n# Or use cache and get path\nMODEL_PATH=$(hf download meta-llama/Llama-3.2-1B-Instruct --quiet)\n```\n\n### Publish Model/Dataset\n```bash\nhf repo create my-username/my-model --private\nhf upload my-username/my-model ./output . --commit-message=\"Initial release\"\nhf repo tag create my-username/my-model v1.0\n```\n\n### Sync Space with Local\n```bash\nhf upload my-username/my-space . . --repo-type space \\\n  --exclude=\"logs/*\" --delete=\"*\" --commit-message=\"Sync\"\n```\n\n### Check Cache Usage\n```bash\nhf cache ls                      # See all cached repos and sizes\nhf cache rm model/gpt2           # Remove a repo from cache\n```\n\n## Key Options\n\n- `--repo-type`: `model` (default), `dataset`, `space`\n- `--revision`: Branch, tag, or commit hash\n- `--token`: Override authentication\n- `--quiet`: Output only essential info (paths/URLs)\n\n## References\n\n- **Complete command reference**: See [references/commands.md](references/commands.md)\n- **Workflow examples**: See [references/examples.md](references/examples.md)\n"},"category":"official","lastSynced":"2026-03-06T05:31:03.310Z","seo":{"title":{"en":"hugging-face-cli: Master Hub Operations | AI Agent Skill","zh":"Hugging Face CLI_SETUP GUIDE","ja":"Hugging Face CLIベストプラクティス","ko":"Hugging Face CLI설치 가이드","pt":"Guia de Configuração do Hugging Face CLI","ru":"Настройка Hugging Face CLI: ИИ Агенты для разработчиков","ar":"دليل إعداد Hugging Face CLI للأدوات الذكية"},"description":{"en":"Unlock the full potential of Hugging Face Hub with the hugging-face-cli. Learn how to download models, upload files, and manage repositories with ease. Get s...","zh":"使用Hugging Face CLI执行Hub操作，包括下载模型、上传文件和管理仓库","ja":"Hugging Face CLIを使用してHub操作を実行します。モデルをダウンロードしたり、ファイルをアップロードしたり、リポジトリを管理したりできます","ko":"Hugging Face CLI를 사용하여 Hub 작업을 수행하십시오. 모델 다운로드, 파일 업로드 및 리포지토리 관리를 포함합니다","pt":"Aprenda a usar o Hugging Face CLI para baixar modelos, fazer upload de arquivos e gerenciar repositórios com facilidade","ru":"Узнайте, как использовать Hugging Face CLI для загрузки моделей,上传 файлов и управления репозиториями с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام Hugging Face CLI لتحميل النماذج ورفع الملفات وإدارة المستودعات بسهولة"},"definition":{"en":"hugging-face-cli is a command-line interface for interacting with the Hugging Face Hub, providing features such as repository creation, file transfers, and compute job management.","zh":"Hugging Face CLI是用于执行Hugging Face Hub操作的命令行工具","ja":"Hugging Face CLIは、Hugging Face Hub操作を実行するためのコマンドラインツールです","ko":"Hugging Face CLI는 Hugging Face Hub 작업을 수행하는 명령줄 도구입니다","pt":"O Hugging Face CLI é uma ferramenta de linha de comando para interagir com o Hugging Face Hub","ru":"Hugging Face CLI — это инструмент командной строки для взаимодействия с Hugging Face Hub","ar":"Hugging Face CLI هو أداة سطر أوامر للتفاعل مع Hugging Face Hub"},"features":{"en":["Executes `hf auth login` for authentication","Downloads models and datasets using `hf download <repo_id>`","Uploads files to Hub repositories with `hf upload <repo_id>`","Creates repositories using `hf repo create <name>`","Manages local cache and runs compute jobs on HF infrastructure"],"zh":["下载模型和数据集","上传文件到Hub仓库","创建和管理仓库","管理本地缓存","在Hugging Face基础架构上运行计算作业"],"ja":["モデルとデータセットのダウンロード","ファイルをHubリポジトリにアップロード","リポジトリの作成と管理","ローカルキャッシュの管理","Hugging Faceインフラストラクチャ上でのコンピューティングジョブの実行"],"ko":["모델 및 데이터셋 다운로드","파일을 Hub 리포지토리에 업로드","리포지토리 생성 및 관리","로컬 캐시 관리","Hugging Face 인프라에서 컴퓨팅 작업 실행"],"pt":["Autenticação com `hf auth login`","Download de modelos e datasets com `hf download`","Upload de arquivos com `hf upload`","Criação de repositórios com `hf repo create`","Gerenciamento de cache com `hf cache`"],"ru":["Аутентификация с помощью `hf auth login`","Загрузка моделей и наборов данных с помощью `hf download`","Загрузка файлов с помощью `hf upload`","Создание репозиториев с помощью `hf repo create`","Управление кэшем с помощью `hf cache`"],"ar":["التحقق من الهوية باستخدام `hf auth login`","تحميل النماذج ومجموعات البيانات باستخدام `hf download`","رفع الملفات باستخدام `hf upload`","إنشاء مستودعات باستخدام `hf repo create`","إدارة الذاكرة المؤقتة باستخدام `hf cache`"]},"keywords":{"en":["hugging-face-cli tutorial","hugging face hub api","how to use hugging-face-cli","hugging-face-cli vs hub api","hugging-face-cli install guide","hugging face cli commands","hugging-face-cli repository management","hugging face hub repository creation","hugging-face-cli compute job management"],"zh":["Hugging Face CLI","AIエージェント工具","命令行工具","Hub操作","模型下载","文件上传","仓库管理","缓存管理","计算资源管理"],"ja":["Hugging Face CLI","AIエージェント","コマンドラインツール","Hub操作","モデルダウンロード","ファイルアップロード","リポジトリ管理","キャッシュ管理","コンピューティングリソース管理"],"ko":["Hugging Face CLI","AI 에이전트","명령줄 도구","Hub 작업","모델 다운로드","파일 업로드","리포지토리 관리","캐시 관리","컴퓨팅 리소스 관리"],"pt":["Hugging Face CLI","Hugging Face Hub","download de modelos","upload de arquivos","gerenciamento de repositórios","autenticação","cache","CLI para desenvolvedores"],"ru":["Hugging Face CLI","Hugging Face Hub","загрузка моделей","загрузка файлов","управление репозиториями","аутентификация","кэш","ИИ Агенты для разработчиков"],"ar":["Hugging Face CLI","Hugging Face Hub","تحميل النماذج","رفع الملفات","إدارة المستودعات","التحقق من الهوية","الذاكرة المؤقتة","أدوات ذكية للبرمجة"]}},"agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring seamless integration with the Hugging Face Hub for model and dataset management.","zh":"适用于需要与 Hugging Face Hub 无缝集成以进行模型和数据集管理的 AI Agents。","ja":"Hugging Face Hub とのシームレスな統合が必要な AI エージェントに適しています。","ko":"Hugging Face Hub와의 모델 및 데이터셋 관리를 위한无缝한 통합이 필요한 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA que requieren una integración perfecta con Hugging Face Hub para la gestión de modelos y conjuntos de datos.","fr":"Idéal pour les agents IA nécessitant une intégration transparente avec Hugging Face Hub pour la gestion de modèles et de jeux de données.","de":"Ideal für KI-Agents, die eine nahtlose Integration mit Hugging Face Hub für Modell- und Datensatzverwaltung erfordern.","pt":"Ideal para Agentes de IA que exigem integração sem problemas com o Hugging Face Hub para gerenciamento de modelos e conjuntos de dados.","ru":"Идеально для агентов ИИ, требующих бесшовной интеграции с Hugging Face Hub для управления моделями и наборами данных.","ar":"مثالية لعميل الذكاء الاصطناعي الذين يتطلبون التكامل السلس مع مركز هوجنغ فايس لإدارة النماذج و مجموعات البيانات."},"recommendation":{"en":"Empowers agents to execute Hugging Face Hub operations using the `hf` CLI, enabling direct access to model downloads, uploads, repository creation, and cloud compute jobs, all while handling authentication and cache management through protocols like HTTPS and SSH.","zh":"使得代理能够使用 `hf` CLI 执行 Hugging Face Hub 操作，实现对模型下载、上传、存储库创建和云计算作业的直接访问，同时通过 HTTPS 和 SSH 等协议处理身份验证和缓存管理。","ja":"`hf` CLI を使用して Hugging Face Hub 操作を実行できるようにエージェントを有効にし、モデルダウンロード、アップロード、リポジトリ作成、クラウドコンピューティングジョブへの直接アクセスを可能にし、HTTPS および SSH などのプロトコルを介して認証およびキャッシュ管理を処理します。","ko":"에이전트가 `hf` CLI를 사용하여 Hugging Face Hub 작업을 실행할 수 있도록 하여 모델 다운로드, 업로드, 저장소 생성 및 클라우드 컴퓨팅 작업에 직접 액세스할 수 있도록 하고 HTTPS 및 SSH와 같은 프로토콜을 통해 인증 및 캐시 관리를 처리합니다.","es":"Permite a los agentes ejecutar operaciones de Hugging Face Hub mediante la CLI `hf`, lo que permite el acceso directo a descargas de modelos, cargas, creación de repositorios y trabajos de proceso en la nube, todo mientras se manejan la autenticación y la gestión de caché a través de protocolos como HTTPS y SSH.","fr":"Permet aux agents d''exécuter des opérations Hugging Face Hub à l''aide de la CLI `hf`, permettant un accès direct aux téléchargements de modèles, aux téléversements, à la création de référentiels et aux travaux de calcul dans le cloud, le tout en gérant l''authentification et la gestion du cache via des protocoles tels que HTTPS et SSH.","de":"Ermöglicht es Agenten, Hugging Face Hub-Operationen über die `hf`-CLI auszuführen, wodurch direkter Zugriff auf Modell-Downloads, Uploads, Repository-Erstellung und Cloud-Compute-Jobs ermöglicht wird, während die Authentifizierung und Cache-Verwaltung über Protokolle wie HTTPS und SSH gehandhabt werden.","pt":"Habilita os agentes a executar operações do Hugging Face Hub usando o `hf` CLI, permitindo acesso direto a downloads de modelos, uploads, criação de repositórios e trabalhos de computação em nuvem, tudo isso enquanto lida com autenticação e gerenciamento de cache por meio de protocolos como HTTPS e SSH.","ru":"Наделяет агентов возможностью выполнять операции Hugging Face Hub с помощью `hf` CLI, обеспечивая прямой доступ к загрузке моделей, выгрузке, созданию репозиториев и облачным вычислительным задачам, при этом обрабатывая аутентификацию и управление кэшем через протоколы như HTTPS и SSH.","ar":"تمكين الوكلاء من تنفيذ عمليات مركز هوجنغ فايس باستخدام `hf` CLI، وتمكين الوصول المباشر إلى تنزيل النماذج و تحميلها وإنشاء المستودعات ووظائف الحوسبة السحابية، كل ذلك مع معالجة المصادقة وإدارة الذاكرة المخبأة من خلال بروتوكولات مثل HTTPS و SSH."},"useCases":{"en":["Downloading models and datasets from the Hugging Face Hub","Uploading custom models and datasets to private repositories","Managing local cache for efficient model versioning","Running compute jobs on Hugging Face infrastructure for scalable processing"],"zh":["从 Hugging Face Hub 下载模型和数据集","将自定义模型和数据集上传到私有存储库","管理本地缓存以实现模型版本控制","在 Hugging Face 基础设施上运行计算作业以实现可扩展的处理"],"ja":["Hugging Face Hub からモデルとデータセットをダウンロードする","カスタムモデルとデータセットをプライベートリポジトリにアップロードする","ローカルキャッシュを管理してモデルバージョニングを実現する","Hugging Face インフラストラクチャでコンピューティングジョブを実行してスケーラブルな処理を実現する"],"ko":["Hugging Face Hub에서 모델 및 데이터셋 다운로드","사용자 정의 모델 및 데이터셋을 개인 저장소에 업로드","로컬 캐시 관리를 통해 모델 버전 관리","Hugging Face 인프라에서 컴퓨팅 작업을 실행하여 확장 가능한 처리"],"es":["Descargar modelos y conjuntos de datos de Hugging Face Hub","Cargar modelos y conjuntos de datos personalizados en repositorios privados","Administrar la caché local para una versión eficiente de los modelos","Ejecutar trabajos de proceso en la infraestructura de Hugging Face para un procesamiento escalable"],"fr":["Télécharger des modèles et des jeux de données à partir de Hugging Face Hub","Téléverser des modèles et des jeux de données personnalisés dans des référentiels privés","Gérer la cache locale pour une version efficace des modèles","Exécuter des travaux de calcul sur l''infrastructure Hugging Face pour un traitement escalable"],"de":["Modelle und Datensätze von Hugging Face Hub herunterladen","Benutzerdefinierte Modelle und Datensätze in private Repositorys hochladen","Lokale Cache für eine effiziente Modellversionierung verwalten","Compute-Jobs auf der Hugging Face-Infrastruktur für ein skalierbares Verarbeiten ausführen"],"pt":["Baixar modelos e conjuntos de dados do Hugging Face Hub","Fazer upload de modelos e conjuntos de dados personalizados para repositórios privados","Gerenciar cache local para versionamento eficiente de modelos","Executar trabalhos de computação na infraestrutura do Hugging Face para processamento escalável"],"ru":["Загрузка моделей и наборов данных из Hugging Face Hub","Загрузка пользовательских моделей и наборов данных в приватные репозитории","Управление локальным кэшем для эффективной версионности моделей","Выполнение вычислительных задач на инфраструктуре Hugging Face для масштабируемой обработки"],"ar":["تنزيل النماذج ومجموعات البيانات من مركز هوجنغ فايس","تحميل النماذج ومجموعات البيانات المخصصة إلى مستودعات خاصة","إدارة الذاكرة المخبأة المحلية لنسخ النماذج بشكل فعال","تشغيل وظائف الحوسبة على بنية تحتية هوجنغ فايس لمعالجة قابلة للتوسعة"]},"limitations":{"en":["Requires Hugging Face account for authentication","Dependent on `hf` CLI version and compatibility","Limited to Hugging Face Hub services and models"],"zh":["需要 Hugging Face 账户进行身份验证","依赖于 `hf` CLI 版本和兼容性","仅限于 Hugging Face Hub 服务和模型"],"ja":["認証のために Hugging Face アカウントが必要","`hf` CLI のバージョンと互換性に依存","Hugging Face Hub サービスおよびモデルに限定"],"ko":["인증을 위해 Hugging Face 계정이 필요합니다.","`hf` CLI 버전 및 호환성에 종속됨","Hugging Face Hub 서비스 및 모델로 제한"],"es":["Requiere una cuenta de Hugging Face para la autenticación","Dependiente de la versión y la compatibilidad de la CLI `hf`","Limitado a los servicios y modelos de Hugging Face Hub"],"fr":["Nécessite un compte Hugging Face pour l''authentification","Dépendant de la version et de la compatibilité de la CLI `hf`","Limité aux services et modèles Hugging Face Hub"],"de":["Benötigt ein Hugging Face-Konto für die Authentifizierung","Abhängig von der Version und der Kompatibilität der `hf`-CLI","Begrenzt auf Hugging Face Hub-Dienste und -Modelle"],"pt":["Exige conta do Hugging Face para autenticação","Dependente da versão e compatibilidade do `hf` CLI","Limitado aos serviços e modelos do Hugging Face Hub"],"ru":["Требует учетной записи Hugging Face для аутентификации","Зависит от версии и совместимости `hf` CLI","Ограничен услугами и моделями Hugging Face Hub"],"ar":["يتطلب حساب هوجنغ فايس للمصادقة","يعتمد على إصدار ومتطلبات التوافق `hf` CLI","محدود بخدمات ونماذج مركز هوجنغ فايس"]},"version":4},"contentHash":"c011e33ff672d5b1ec80fd280f245ff0c15e8dac3b8a0d146c8973a596185878","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":71}');
