INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-cli', 'hugging-face-cli', 'huggingface', 'skills', 'official', 'hugging-face-cli huggingface skills official The hugging-face-cli skill enables developers to execute Hugging Face Hub operations, including downloading models and datasets, uploading files, and managing repositories. It benefits AI agents and developers working with Hugging Face Hub. Hugging Face CLI提供了直接的终端访问Hugging Face Hub的能力，用于下载、上传和管理仓库、缓存和计算资源 Hugging Face CLIは、Hugging Face Hubへの直接的なターミナルアクセスを提供します。ダウンロード、アップロード、リポジトリ、キャッシュ、コンピューティングリソースの管理が可能です Hugging Face CLI는 Hugging Face Hub에 대한 직접적인 터미널 액세스를 제공합니다. 다운로드, 업로드, 리포지토리, 캐시 및 컴퓨팅 리소스 관리가 가능합니다 O Hugging Face CLI é uma ferramenta de linha de comando para interagir com o Hugging Face Hub, permitindo downloads de modelos e datasets, upload de arquivos e gerenciamento de repositórios Hugging Face CLI — это инструмент командной строки для взаимодействия с Hugging Face Hub, позволяющий загружать модели и наборы данных,上传 файлов и управлять репозиториями Hugging Face CLI هو أداة سطر أوامر للتفاعل مع Hugging Face Hub، مما يسمح بتحميل النماذج و مجموعات البيانات ورفع الملفات وإدارة المستودعات hugging-face-cli tutorial hugging face hub api how to use hugging-face-cli hugging-face-cli vs hub api hugging-face-cli install guide hugging face cli commands hugging-face-cli repository management hugging face hub repository creation hugging-face-cli compute job management Hugging Face CLI AIエージェント工具 命令行工具 Hub操作 模型下载 文件上传 仓库管理 缓存管理 计算资源管理 Executes `hf auth login` for authentication Downloads models and datasets using `hf download <repo_id>` Uploads files to Hub repositories with `hf upload <repo_id>` Creates repositories using `hf repo create <name>` Manages local cache and runs compute jobs on HF infrastructure hugging-face-cli is a command-line interface for interacting with the Hugging Face Hub, providing features such as repository creation, file transfers, and compute job management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-dataset-viewer', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-dataset-viewer', 8290, 490, 71, '2026-03-06T05:28:53Z', '2026-03-06T05:32:56.001Z', '9d0598f5fd25118f83ea005aa7bf577f17b3b45c9ef7ec448ac4c2e6095a2b48', '{"id":"huggingface/skills/hugging-face-dataset-viewer","name":"hugging-face-dataset-viewer","description":{"en":"The hugging-face-dataset-viewer skill enables developers to execute read-only Dataset Viewer API calls for dataset exploration and extraction, supporting tasks like metadata fetching and data pagination.","pt":"O hugging-face-dataset-viewer é uma habilidade para executar chamadas de API de visualização de conjuntos de dados para exploração e extração de conjuntos de dados.","ru":"Hugging-face-dataset-viewer — это навык для выполнения запросов к API-просмотра наборов данных для изучения и извлечения наборов данных для ИИ Агентов","ar":"هوجنج فايس داتاسيت فيوور هو مهارة لتنفيذ مكالمات واجهة برمجة تطبيقات العرض لمجموعات البيانات لاستكشاف واستخراج مجموعات البيانات"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-dataset-viewer","description":"Use this skill for Hugging Face Dataset Viewer API workflows that fetch subset/split metadata, paginate rows, search text, apply filters, download parquet URLs, and read size or statistics.","bodyPreview":"# Hugging Face Dataset Viewer\r\n\r\nUse this skill to execute read-only Dataset Viewer API calls for dataset exploration and extraction.\r\n\r\n## Core workflow\r\n\r\n1. Optionally validate dataset availability with `/is-valid`.\r\n2. Resolve `config` + `split` with `/splits`.\r\n3. Preview with `/first-rows`.\r\n4. Paginate content with `/rows` using `offset` and `length` (max 100).\r\n5. Use `/search` for text matching and `/filter` for row predicates.\r\n6. Retrieve parquet links via `/parquet` and totals/metada","body":"# Hugging Face Dataset Viewer\r\n\r\nUse this skill to execute read-only Dataset Viewer API calls for dataset exploration and extraction.\r\n\r\n## Core workflow\r\n\r\n1. Optionally validate dataset availability with `/is-valid`.\r\n2. Resolve `config` + `split` with `/splits`.\r\n3. Preview with `/first-rows`.\r\n4. Paginate content with `/rows` using `offset` and `length` (max 100).\r\n5. Use `/search` for text matching and `/filter` for row predicates.\r\n6. Retrieve parquet links via `/parquet` and totals/metadata via `/size` and `/statistics`.\r\n\r\n## Defaults\r\n\r\n- Base URL: `https://datasets-server.huggingface.co`\r\n- Default API method: `GET`\r\n- Query params should be URL-encoded.\r\n- `offset` is 0-based.\r\n- `length` max is usually `100` for row-like endpoints.\r\n- Gated/private datasets require `Authorization: Bearer <HF_TOKEN>`.\r\n\r\n## Dataset Viewer\r\n\r\n- `Validate dataset`: `/is-valid?dataset=<namespace/repo>`\r\n- `List subsets and splits`: `/splits?dataset=<namespace/repo>`\r\n- `Preview first rows`: `/first-rows?dataset=<namespace/repo>&config=<config>&split=<split>`\r\n- `Paginate rows`: `/rows?dataset=<namespace/repo>&config=<config>&split=<split>&offset=<int>&length=<int>`\r\n- `Search text`: `/search?dataset=<namespace/repo>&config=<config>&split=<split>&query=<text>&offset=<int>&length=<int>`\r\n- `Filter with predicates`: `/filter?dataset=<namespace/repo>&config=<config>&split=<split>&where=<predicate>&orderby=<sort>&offset=<int>&length=<int>`\r\n- `List parquet shards`: `/parquet?dataset=<namespace/repo>`\r\n- `Get size totals`: `/size?dataset=<namespace/repo>`\r\n- `Get column statistics`: `/statistics?dataset=<namespace/repo>&config=<config>&split=<split>`\r\n- `Get Croissant metadata (if available)`: `/croissant?dataset=<namespace/repo>`\r\n\r\nPagination pattern:\r\n\r\n```bash\r\ncurl \"https://datasets-server.huggingface.co/rows?dataset=stanfordnlp/imdb&config=plain_text&split=train&offset=0&length=100\"\r\ncurl \"https://datasets-server.huggingface.co/rows?dataset=stanfordnlp/imdb&config=plain_text&split=train&offset=100&length=100\"\r\n```\r\n\r\nWhen pagination is partial, use response fields such as `num_rows_total`, `num_rows_per_page`, and `partial` to drive continuation logic.\r\n\r\nSearch/filter notes:\r\n\r\n- `/search` matches string columns (full-text style behavior is internal to the API).\r\n- `/filter` requires predicate syntax in `where` and optional sort in `orderby`.\r\n- Keep filtering and searches read-only and side-effect free.\r\n\r\n## Querying Datasets\r\n\r\nUse `npx parquetlens` with Hub parquet alias paths for SQL querying.\r\n\r\nParquet alias shape:\r\n\r\n```text\r\nhf://datasets/<namespace>/<repo>@~parquet/<config>/<split>/<shard>.parquet\r\n```\r\n\r\nDerive `<config>`, `<split>`, and `<shard>` from Dataset Viewer `/parquet`:\r\n\r\n```bash\r\ncurl -s \"https://datasets-server.huggingface.co/parquet?dataset=cfahlgren1/hub-stats\" \\\r\n  | jq -r ''.parquet_files[] | \"hf://datasets/\\(.dataset)@~parquet/\\(.config)/\\(.split)/\\(.filename)\"''\r\n```\r\n\r\nRun SQL query:\r\n\r\n```bash\r\nnpx -y -p parquetlens -p @parquetlens/sql parquetlens \\\r\n  \"hf://datasets/<namespace>/<repo>@~parquet/<config>/<split>/<shard>.parquet\" \\\r\n  --sql \"SELECT * FROM data LIMIT 20\"\r\n```\r\n\r\n### SQL export\r\n\r\n- CSV: `--sql \"COPY (SELECT * FROM data LIMIT 1000) TO ''export.csv'' (FORMAT CSV, HEADER, DELIMITER '','')\"`\r\n- JSON: `--sql \"COPY (SELECT * FROM data LIMIT 1000) TO ''export.json'' (FORMAT JSON)\"`\r\n- Parquet: `--sql \"COPY (SELECT * FROM data LIMIT 1000) TO ''export.parquet'' (FORMAT PARQUET)\"`\r\n\r\n## Creating and Uploading Datasets\r\n\r\nUse one of these flows depending on dependency constraints.\r\n\r\nZero local dependencies (Hub UI):\r\n\r\n- Create dataset repo in browser: `https://huggingface.co/new-dataset`\r\n- Upload parquet files in the repo \"Files and versions\" page.\r\n- Verify shards appear in Dataset Viewer:\r\n\r\n```bash\r\ncurl -s \"https://datasets-server.huggingface.co/parquet?dataset=<namespace>/<repo>\"\r\n```\r\n\r\nLow dependency CLI flow (`npx @huggingface/hub` / `hfjs`):\r\n\r\n- Set auth token:\r\n\r\n```bash\r\nexport HF_TOKEN=<your_hf_token>\r\n```\r\n\r\n- Upload parquet folder to a dataset repo (auto-creates repo if missing):\r\n\r\n```bash\r\nnpx -y @huggingface/hub upload datasets/<namespace>/<repo> ./local/parquet-folder data\r\n```\r\n\r\n- Upload as private repo on creation:\r\n\r\n```bash\r\nnpx -y @huggingface/hub upload datasets/<namespace>/<repo> ./local/parquet-folder data --private\r\n```\r\n\r\nAfter upload, call `/parquet` to discover `<config>/<split>/<shard>` values for querying with `@~parquet`.\r\n"},"category":"official","lastSynced":"2026-03-06T05:32:56.001Z","seo":{"title":{"en":"hugging-face-dataset-viewer: API Workflow Setup Guide | A...","pt":"Guia de Configuração do hugging-face-dataset-viewer","ru":"Руководство по настройке hugging-face-dataset-viewer для ...","ar":"دليل إعداد هوجنج فايس داتاسيت فيوور للآليات الذكية"},"description":{"en":"Unlock dataset exploration with hugging-face-dataset-viewer. Learn how to fetch metadata, paginate rows, and apply filters with our expert guide.","pt":"Aprenda a usar o hugging-face-dataset-viewer para explorar e extrair conjuntos de dados com API de visualização de conjuntos de dados","ru":"Узнайте, как использовать hugging-face-dataset-viewer для изучения и извлечения наборов данных с помощью API-просмотра наборов данных для ИИ Агентов","ar":"تعرف على كيفية استخدام هوجنج فايس داتاسيت فيوور لاستكشاف واستخراج مجموعات البيانات باستخدام واجهة برمجة تطبيقات العرض"},"definition":{"en":"hugging-face-dataset-viewer is a skill that provides read-only access to Hugging Face Dataset Viewer API for exploring and extracting dataset metadata and content.","pt":"O que é hugging-face-dataset-viewer? É uma habilidade para explorar e extrair conjuntos de dados usando a API de visualização de conjuntos de dados","ru":"Что такое hugging-face-dataset-viewer? Это навык для изучения и извлечения наборов данных с помощью API-просмотра наборов данных для ИИ Агентов","ar":"ما هو هوجنج فايس داتاسيت فيوور؟ هو مهارة لاستكشاف واستخراج مجموعات البيانات باستخدام واجهة برمجة تطبيقات العرض"},"features":{"en":["Fetch subset/split metadata using the `/splits` endpoint","Paginate rows with `/rows` using `offset` and `length` parameters","Search text with `/search` and apply filters with `/filter`","Retrieve parquet links via `/parquet` and access dataset statistics","Validate dataset availability with the `/is-valid` endpoint","Preview dataset content with `/first-rows`"],"pt":["Validação de disponibilidade de conjuntos de dados","Resolução de configuração e divisão de conjuntos de dados","Visualização de linhas iniciais de conjuntos de dados","Paginação de conteúdo de conjuntos de dados","Pesquisa de texto em conjuntos de dados","Filtragem de linhas de conjuntos de dados"],"ru":["Проверка наличия наборов данных","Разрешение конфигурации и разделения наборов данных","Просмотр начальных строк наборов данных","Страница содержимого наборов данных","Поиск текста в наборах данных","Фильтрация строк наборов данных для ИИ Агентов"],"ar":["التحقق من وجود مجموعات البيانات","تحليل التكوين واقسام مجموعات البيانات","عرض الصفوف الأولى لمجموعات البيانات","تنقّل المحتوى لمجموعات البيانات","البحث عن نص في مجموعات البيانات","تصفية الصفوف لمجموعات البيانات"]},"keywords":{"en":["hugging-face-dataset-viewer setup guide","how to use hugging-face-dataset-viewer","hugging-face-dataset-viewer api workflow","hugging-face-dataset-viewer vs dataset viewer","hugging-face-dataset-viewer install","what is hugging-face-dataset-viewer","hugging-face-dataset-viewer tutorial","hugging-face-dataset-viewer metadata fetching","hugging-face-dataset-viewer data pagination"],"pt":["hugging face dataset viewer","api de visualização de conjuntos de dados","exploração de conjuntos de dados","extração de conjuntos de dados","validação de conjuntos de dados","paginação de conjuntos de dados","pesquisa de texto em conjuntos de dados"],"ru":["hugging face dataset viewer","API-просмотра наборов данных","изучение наборов данных","извлечение наборов данных","проверка наличия наборов данных","страница содержимого наборов данных","поиск текста в наборах данных для ИИ Агентов"],"ar":["هوجنج فايس داتاسيت فيوور","واجهة برمجة تطبيقات العرض","استكشاف مجموعات البيانات","استخراج مجموعات البيانات","التحقق من وجود مجموعات البيانات","تنقّل المحتوى لمجموعات البيانات","البحث عن نص في مجموعات البيانات"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing programmatic access to Hugging Face datasets for exploration and extraction.","zh":"适用于需要以编程方式访问 Hugging Face 数据集进行探索和提取的数据分析代理。","ja":"Hugging Face のデータセットにプログラムによるアクセスを必要とするデータ分析エージェントに最適です。","ko":"Hugging Face 데이터セット에 프로그래밍 방식으로 액세스하여 탐색 및 추출이 필요한 데이터 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de Análisis de Datos que necesitan acceso programático a los conjuntos de datos de Hugging Face para exploración y extracción.","fr":"Parfait pour les agents d''Analyse de Données ayant besoin d''un accès programmatique aux jeux de données Hugging Face pour exploration et extraction.","de":"Perfekt für Data-Analytics-Agents, die programmatischen Zugriff auf Hugging Face-Datensätze für Exploration und Extraktion benötigen.","pt":"Perfeito para Agentes de Análise de Dados que precisam de acesso programático aos conjuntos de dados do Hugging Face para exploração e extração.","ru":"Идеально подходит для агентов анализа данных, которым требуется программный доступ к наборам данных Hugging Face для изучения и извлечения.","ar":"مثالي للوكلاء تحليل البيانات الذين يحتاجون إلى الوصول البرمجي إلى مجموعات البيانات من Hugging Face للتجول والاستخراج."},"recommendation":{"en":"Empowers agents to fetch dataset subset/split metadata, paginate rows with offset and length parameters (max 100), perform text search, apply row predicates via filters, and retrieve parquet URLs for direct download. Provides comprehensive dataset exploration through the Dataset Viewer API workflow.","zh":"赋予代理获取数据集子集/拆分元数据、使用偏移量和长度参数分页行（最大 100 行）、执行文本搜索、通过过滤器应用行谓词以及检索 parquet URL 以进行直接下载的能力。通过 Dataset Viewer API 工作流提供全面数据集探索。","ja":"エージェントがデータセットサブセット/スプリットのメタデータを取得し、オフセットと長さパラメータで行をページ化する（最大 100 行）、テキスト検索を行い、フィルターを介して行述語を適用し、直接ダウンロードするために parquet URL を取得することを可能にします。Dataset Viewer API ワークフローを介した包括的なデータセットの探索を提供します。","ko":"에이전트가 데이터셋 하위 집합/분할 메타데이터를 가져오고 오프셋 및 길이 매개 변수로 행을 페이지화하는 기능을 제공합니다(최대 100행). 또한 텍스트 검색을 수행하고 필터를 통해 행 술어를 적용하며 직접 다운로드할 수 있는 parquet URL을 가져올 수 있습니다. Dataset Viewer API 워크플로우를 통해 데이터셋의 종합적인 탐색을 제공합니다.","es":"Habilita a los agentes a recuperar metadatos de subconjuntos/divisiones de conjuntos de datos, paginar filas con parámetros de desplazamiento y longitud (máximo 100), realizar búsquedas de texto, aplicar predicados de fila a través de filtros y recuperar URLs de parquet para descarga directa. Proporciona una exploración exhaustiva de conjuntos de datos a través del flujo de trabajo de la API del Visor de conjuntos de datos.","fr":"Permet aux agents de récupérer des métadonnées de sous-ensembles/divisions de jeux de données, de paginer des lignes avec des paramètres d''offset et de longueur (max 100), d''effectuer des recherches de texte, d''appliquer des prédicats de ligne via des filtres et de récupérer des URL de parquet pour téléchargement direct. Fournit une exploration exhaustive de jeux de données à travers le flux de travail de l''API du Visualiseur de jeux de données.","de":"Ermächtigt Agenten, Metadaten von Datensatz-Untermengen/Aufteilungen abzurufen, Zeilen mit Offset- und Längenparametern (max. 100) zu paginieren, Textsuchen durchzuführen, Zeilenprädikate über Filter anzuwenden und Parquet-URLs für direkten Download abzurufen. Bietet umfassende Datensatz-Exploration durch den API-Workflow des Dataset-Viewers.","pt":"Habilita os agentes a buscar metadados de subconjunto/divisão de conjunto de dados, paginar linhas com parâmetros de deslocamento e comprimento (máx. 100), realizar busca de texto, aplicar predicados de linha via filtros e recuperar URLs de parquet para download direto. Fornece uma exploração abrangente do conjunto de dados por meio do fluxo de trabalho da API do Visualizador de Conjunto de Dados.","ru":"Наделяет агентов возможностью получать метаданные подмножества/разбиения набора данных, постранично выводить строки с параметрами смещения и длины (макс. 100), выполнять текстовый поиск, применять предикаты строки через фильтры и получать URLs паркета для прямой загрузки. Предоставляет всестороннее изучение набора данных через рабочий процесс API-просмотрщика набора данных.","ar":"تمكّن الوكلاء من استرجاع بيانات تعريف جزء/تقسيم مجموعة البيانات، وتقديم صفحات من الصفوف مع معلمات الإزاحة والطول (أقصى 100)، وإجراء بحث نصي، وتطبيق أحكام الصفوف عبر المرشحات، واسترجاع عناوين URL للتحميل المباشر. يوفر استكشافًا شاملاً لمجموعة البيانات من خلال تدفق عمل API لمشاهدة مجموعة البيانات."},"useCases":{"en":["Paginating large datasets using offset and length parameters","Applying text search filters to locate specific data rows","Retrieving parquet file URLs for bulk dataset downloads","Resolving dataset config and split metadata for structured access"],"zh":["使用偏移量和长度参数对大型数据集进行分页","应用文本搜索过滤器来定位特定的数据行","检索 parquet 文件 URL 以进行批量数据集下载","解决数据集配置和分割元数据以进行结构化访问"],"ja":["オフセットと長さパラメータで大規模なデータセットをページ化する","テキスト検索フィルターを適用して特定のデータ行を検索する","バルクデータセットのダウンロードのために parquet ファイルの URL を取得する","データセットの構成とスプリットのメタデータを解決して構造化されたアクセスを提供する"],"ko":["오프셋 및 길이 매개 변수로 대형 데이터셋을 페이지화하는 것","특정 데이터 행을 찾기 위해 텍스트 검색 필터를 적용하는 것","대량 데이터셋 다운로드를 위해 parquet 파일 URL을 가져오는 것","구조화된 액세스를 제공하기 위해 데이터셋 구성 및 분할 메타데이터를 해결하는 것"],"es":["Paginación de grandes conjuntos de datos utilizando parámetros de desplazamiento y longitud","Aplicación de filtros de búsqueda de texto para localizar filas de datos específicas","Recuperación de URLs de archivos parquet para descargas de conjuntos de datos a granel","Resolución de configuración y metadatos de división de conjuntos de datos para acceso estructurado"],"fr":["Pagination de grands jeux de données en utilisant des paramètres d''offset et de longueur","Application de filtres de recherche de texte pour localiser des lignes de données spécifiques","Récupération d''URL de fichiers parquet pour des téléchargements de jeux de données en vrac","Résolution de la configuration et des métadonnées de division de jeux de données pour un accès structuré"],"de":["Paginierung großer Datensätze unter Verwendung von Offset- und Längenparametern","Anwendung von Textsuchfiltern, um spezifische Datensatzzeilen zu lokalisieren","Abruf von Parquet-Datei-URLs für Massendownloads von Datensätzen","Auflösung von Datensatz-Konfiguration und -Metadaten für strukturierten Zugriff"],"pt":["Paginar grandes conjuntos de dados usando parâmetros de deslocamento e comprimento","Aplicar filtros de busca de texto para localizar linhas de dados específicas","Recuperar URLs de arquivos parquet para downloads de conjunto de dados em massa","Resolver configuração de conjunto de dados e metadados de divisão para acesso estruturado"],"ru":["Постраничный вывод крупных наборов данных с использованием параметров смещения и длины","Применение фильтров текстового поиска для локализации определенных строк данных","Получение URLs-паркета для массовой загрузки наборов данных","Разрешение конфигурации набора данных и метаданных разбиения для структурированного доступа"],"ar":["تقديم صفحات لمجموعات البيانات الكبيرة باستخدام معلمات الإزاحة والطول","تطبيق مرشحات البحث النصي لتحديد صفوف البيانات المحددة","استرجاع عناوين URL لملفات باركيت لتحميل مجموعات البيانات بالجملة","تحديد cấutureة مجموعة البيانات وبيانات تعريف التقسيم للوصول المنظم"]},"limitations":{"en":["Read-only API access (no write operations)","Maximum 100 rows per pagination request","Requires valid Hugging Face dataset identifier","Dependent on Hugging Face API availability"],"zh":["仅限读取 API 访问（不支持写入操作）","每次分页请求的最大行数为 100","需要有效的 Hugging Face 数据集标识符","依赖于 Hugging Face API 的可用性"],"ja":["読み取りのみの API アクセス（書き込み操作はサポートされていません）","ページ化要求ごとの最大行数は 100","有効な Hugging Face データセット識別子が必要","Hugging Face API の可用性に依存"],"ko":["읽기 전용 API 액세스(쓰기 작업은 지원되지 않음)","페이지 매김 요청당 최대 행 수는 100","유효한 Hugging Face 데이터셋 식별자가 필요","Hugging Face API 가용성에 의존"],"es":["Acceso de solo lectura a la API (sin operaciones de escritura)","Máximo 100 filas por solicitud de paginación","Requiere un identificador de conjunto de datos de Hugging Face válido","Dependiente de la disponibilidad de la API de Hugging Face"],"fr":["Accès en lecture seule à l''API (pas d''opérations d''écriture)","Maximum 100 lignes par requête de pagination","Nécessite un identifiant de jeu de données Hugging Face valide","Dépend de la disponibilité de l''API Hugging Face"],"de":["Nur Lesezugriff auf die API (keine Schreiboperationen)","Maximal 100 Zeilen pro Paginierungsanfrage","Erfordert einen gültigen Hugging Face-Datensatz-Identifikator","Abhängig von der Verfügbarkeit der Hugging Face-API"],"pt":["Acesso à API somente leitura (sem operações de gravação)","Máximo 100 linhas por solicitação de paginação","Exige um identificador de conjunto de dados do Hugging Face válido","Dependente da disponibilidade da API do Hugging Face"],"ru":["Только чтение доступа к API (без операций записи)","Максимум 100 строк на запрос постраничного вывода","Требуется действительный идентификатор набора данных Hugging Face","Зависит от доступности API Hugging Face"],"ar":["دخول وصول القراءة فقط (بدون عمليات الكتابة)","الحد الأقصى 100 صفوف لكل طلب تقديم صفحات","يتطلب معرّف مجموعة بيانات Hugging Face صالح","يعتمد على إمكانية وصول API من Hugging Face"]},"version":4},"contentHash":"9d0598f5fd25118f83ea005aa7bf577f17b3b45c9ef7ec448ac4c2e6095a2b48","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":71}');
