INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-dataset-viewer', 'hugging-face-dataset-viewer', 'huggingface', 'skills', 'official', 'hugging-face-dataset-viewer huggingface skills official The hugging-face-dataset-viewer skill enables developers to execute read-only Dataset Viewer API calls for dataset exploration and extraction, supporting tasks like metadata fetching and data pagination. O hugging-face-dataset-viewer é uma habilidade para executar chamadas de API de visualização de conjuntos de dados para exploração e extração de conjuntos de dados. Hugging-face-dataset-viewer — это навык для выполнения запросов к API-просмотра наборов данных для изучения и извлечения наборов данных для ИИ Агентов هوجنج فايس داتاسيت فيوور هو مهارة لتنفيذ مكالمات واجهة برمجة تطبيقات العرض لمجموعات البيانات لاستكشاف واستخراج مجموعات البيانات hugging-face-dataset-viewer setup guide how to use hugging-face-dataset-viewer hugging-face-dataset-viewer api workflow hugging-face-dataset-viewer vs dataset viewer hugging-face-dataset-viewer install what is hugging-face-dataset-viewer hugging-face-dataset-viewer tutorial hugging-face-dataset-viewer metadata fetching hugging-face-dataset-viewer data pagination Fetch subset/split metadata using the `/splits` endpoint Paginate rows with `/rows` using `offset` and `length` parameters Search text with `/search` and apply filters with `/filter` Retrieve parquet links via `/parquet` and access dataset statistics Validate dataset availability with the `/is-valid` endpoint Preview dataset content with `/first-rows` hugging-face-dataset-viewer is a skill that provides read-only access to Hugging Face Dataset Viewer API for exploring and extracting dataset metadata and content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/feature-flags', 'official', 'facebook', 'react', 'facebook/react', 'feature-flags', 243646, 50653, 71, '2026-03-06T05:37:42Z', '2026-03-06T06:11:05.872Z', 'b82f8ab67ebed3a34d71cb9f4ed7a0f94ab6129d23c171443ba10fef3f92adc1', '{"id":"facebook/react/feature-flags","name":"feature-flags","description":{"en":"The feature-flags skill helps React developers manage and debug feature flags, including understanding @gate pragmas and updating flags for different channels.","zh":"Feature Flags是React中用于管理功能开发的技术，包括@gate pragma和React Feature Flags文件","ja":"Feature FlagsはReactの機能開発を管理するための技術です","ko":"Feature Flags는 React에서 기능 개발을 관리하는 기술입니다","es":"Los feature-flags permiten a los desarrolladores probar y implementar nuevas características en React de manera controlada. Aprende a utilizarlos de manera efectiva.","fr":"Les feature-flags permettent aux développeurs de tester et de mettre en œuvre de nouvelles fonctionnalités dans React de manière contrôlée. Apprenez à les utiliser de manière efficace.","de":"Feature-Flags ermöglichen es Entwicklern, neue Funktionen in React kontrolliert zu testen und zu implementieren. Lernen Sie, sie effektiv zu nutzen.","pt":"Configuração e depuração de feature flags no React, incluindo @gate pragmas e canais específicos","ru":"Настройка и отладка фич-флагов в React, включая @gate прагмы и канал-зависимые тесты","ar":"إعداد وتصحيح أخطاء مرشحات الميزات في React، بما في ذلك @gate برAGMA وتحديد القنوات"},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"feature-flags","description":"Use when feature flag tests fail, flags need updating, understanding @gate pragmas, debugging channel-specific test failures, or adding new flags to React.","bodyPreview":"# React Feature Flags\n\n## Flag Files\n\n| File | Purpose |\n|------|---------|\n| `packages/shared/ReactFeatureFlags.js` | Default flags (canary), `__EXPERIMENTAL__` overrides |\n| `packages/shared/forks/ReactFeatureFlags.www.js` | www channel, `__VARIANT__` overrides |\n| `packages/shared/forks/ReactFeatureFlags.native-fb.js` | React Native, `__VARIANT__` overrides |\n| `packages/shared/forks/ReactFeatureFlags.test-renderer.js` | Test renderer |\n\n## Gating Tests\n\n### `@gate` pragma (test-level)\n\nUse w","body":"# React Feature Flags\n\n## Flag Files\n\n| File | Purpose |\n|------|---------|\n| `packages/shared/ReactFeatureFlags.js` | Default flags (canary), `__EXPERIMENTAL__` overrides |\n| `packages/shared/forks/ReactFeatureFlags.www.js` | www channel, `__VARIANT__` overrides |\n| `packages/shared/forks/ReactFeatureFlags.native-fb.js` | React Native, `__VARIANT__` overrides |\n| `packages/shared/forks/ReactFeatureFlags.test-renderer.js` | Test renderer |\n\n## Gating Tests\n\n### `@gate` pragma (test-level)\n\nUse when the feature is completely unavailable without the flag:\n\n```javascript\n// @gate enableViewTransition\nit(''supports view transitions'', () => {\n  // This test only runs when enableViewTransition is true\n  // and is SKIPPED (not failed) when false\n});\n```\n\n### `gate()` inline (assertion-level)\n\nUse when the feature exists but behavior differs based on flag:\n\n```javascript\nit(''renders component'', async () => {\n  await act(() => root.render(<App />));\n\n  if (gate(flags => flags.enableNewBehavior)) {\n    expect(container.textContent).toBe(''new output'');\n  } else {\n    expect(container.textContent).toBe(''legacy output'');\n  }\n});\n```\n\n## Adding a New Flag\n\n1. Add to `ReactFeatureFlags.js` with default value\n2. Add to each fork file (`*.www.js`, `*.native-fb.js`, etc.)\n3. If it should vary in www/RN, set to `__VARIANT__` in the fork file\n4. Gate tests with `@gate flagName` or inline `gate()`\n\n## Checking Flag States\n\nUse `/flags` to view states across channels. See the `flags` skill for full command options.\n\n## `__VARIANT__` Flags (GKs)\n\nFlags set to `__VARIANT__` simulate gatekeepers - tested twice (true and false):\n\n```bash\n/test www <pattern>              # __VARIANT__ = true\n/test www variant false <pattern> # __VARIANT__ = false\n```\n\n## Debugging Channel-Specific Failures\n\n1. Run `/flags --diff <channel1> <channel2>` to compare values\n2. Check `@gate` conditions - test may be gated to specific channels\n3. Run `/test <channel> <pattern>` to isolate the failure\n4. Verify flag exists in all fork files if newly added\n\n## Common Mistakes\n\n- **Forgetting both variants** - Always test `www` AND `www variant false` for `__VARIANT__` flags\n- **Using @gate for behavior differences** - Use inline `gate()` if both paths should run\n- **Missing fork files** - New flags must be added to ALL fork files, not just the main one\n- **Wrong gate syntax** - It''s `gate(flags => flags.name)`, not `gate(''name'')`\n"},"category":"official","lastSynced":"2026-03-06T06:11:05.872Z","seo":{"title":{"en":"feature-flags: Setup Guide for React Developers | AI Agen...","zh":"Feature Flags Setup Guide for React","ja":"ReactのFeature Flagsベストプラクティス","ko":"React Feature Flags 구현 가이드","es":"Guía de configuración de feature-flags para React","fr":"Guide de mise en place des feature-flags pour React","de":"Einrichtungsleitfaden für Feature-Flags in React","pt":"Guia de Configuração de Feature Flags para React","ru":"ИИ Агенты: Настройка Фич-Флагов для React","ar":"إعداد مرشحات الميزات ل React"},"description":{"en":"Master feature flag management in React with our expert guide. Learn to debug test failures, update flags, and optimize your workflow now!","zh":"了解Feature Flags的技术细节，包括@gate pragma、React Feature Flags文件和调试频道特定测试失败","ja":"AIエージェントのFeature Flagsを使用してReactアプリケーションの機能開発を最適化","ko":"React Native와 React에서 Feature Flags를 사용하여 기능 개발을 최적화하는 방법","es":"Aprende a depurar fallas de tests de feature-flags y a agregar nuevos indicadores en React con nuestra guía paso a paso","fr":"Découvrez comment déboguer les échecs de tests de feature-flags et ajouter de nouveaux indicateurs dans React avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Fehler bei Feature-Flag-Tests debuggen und neue Flaggen in React hinzufügen können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar e depurar feature flags no React com nossa guia passo a passo","ru":"ИИ Агенты: Узнайте, как настроить и отладить фич-флаги в React","ar":"تعلم كيفية إعداد وتصحيح أخطاء مرشحات الميزات في React"},"definition":{"en":"feature-flags is a set of techniques and tools for managing and testing feature flags in React applications, including declarative frontend development and JavaScript libraries.","zh":"Feature Flags是一种技术，用于管理React应用程序的功能开发和测试","ja":"Feature Flagsは、Reactアプリケーションの機能開発とテストを管理するための技術です","ko":"Feature Flags는 React 애플리케이션의 기능 개발과 테스트를 관리하는 기술입니다","es":"Feature-flags son indicadores que permiten activar o desactivar características en una aplicación React","fr":"Les feature-flags sont des indicateurs qui permettent d''activer ou de désactiver des fonctionnalités dans une application React","de":"Feature-Flags sind Flaggen, die es ermöglichen, Funktionen in einer React-Anwendung zu aktivieren oder zu deaktivieren","pt":"Feature flags são recursos que permitem ativar ou desativar funcionalidades no React","ru":"Фич-флаги - это функции, которые позволяют включать или выключать функциональность в React","ar":"مرشحات الميزات هي ميزات تمكن من تفعيل أو تعطيل الوظائف في React"},"features":{"en":["Manages default flags and __EXPERIMENTAL__ overrides in ReactFeatureFlags.js","Supports channel-specific flag updates, including www, React Native, and test renderer","Uses @gate pragmas for test-level gating and debugging","Enables updating of flags for different channels, including __VARIANT__ overrides","Debugs channel-specific test failures and flag-related issues","Integrates with React for seamless feature flag management"],"zh":["使用@gate pragma进行测试级别的功能开发","管理React Feature Flags文件，包括默认标志和变体覆盖","调试频道特定测试失败","添加新标志到React应用程序","使用React Native和React进行功能开发"],"ja":["テストレベルの機能開発に@gate pragmaを使用","React Feature Flagsファイルを管理する，デフォルトのフラグとバリアントのオーバーライドを含む","チャネル特定のテスト失敗をデバッグ","新しいフラグをReactアプリケーションに追加","React NativeとReactを使用した機能開発"],"ko":["테스트 레벨의 기능 개발에 @gate pragma 사용","React Feature Flags 파일 관리, 기본 플래그 및 변형 오버라이드 포함","채널 특정 테스트 실패 디버깅","새로운 플래그를 React 애플리케이션에 추가","React Native와 React를 사용한 기능 개발"],"es":["Depuración de fallas de tests de feature-flags","Actualización de indicadores de características","Uso de @gate pragmas para tests","Gestión de indicadores de características para canales específicos","Implementación de nuevos indicadores en React"],"fr":["Débogage des échecs de tests de feature-flags","Mise à jour des indicateurs de fonctionnalités","Utilisation de @gate pragmas pour les tests","Gestion des indicateurs de fonctionnalités pour les canaux spécifiques","Mise en œuvre de nouveaux indicateurs dans React"],"de":["Fehlerbehebung bei Feature-Flag-Tests","Aktualisierung von Feature-Flaggen","Verwendung von @gate-Pragmas für Tests","Verwaltung von Feature-Flaggen für spezifische Kanäle","Implementierung neuer Flaggen in React"],"pt":["Configuração de feature flags com @gate pragmas","Depuração de testes de canais específicos","Uso de arquivos de flags padrão e personalizados","Integração com React Native e test renderer","Suporte a canais específicos, como www e native-fb"],"ru":["Настройка фич-флагов с помощью @gate прагм","Отладка канал-зависимых тестов","Использование файлов флагов по умолчанию и пользовательских","Интеграция с React Native и тест рендерером","Поддержка канал-зависимых, таких как www и native-fb"],"ar":["إعداد مرشحات الميزات باستخدام @gate برAGMA","تصحيح أخطاء اختبارات القنوات المحددة","استخدام ملفات المرشحات الافتراضية والمخصصة","التكامل مع React Native ومتحكم العرض","دعم القنوات المحددة، مثل www وnative-fb"]},"keywords":{"en":["how to use feature flags in React","feature flags setup guide","debugging feature flag test failures","feature flags vs environment variables","installing feature flags in React","feature flags best practices for React developers","what is feature flags in React","feature flags alternative for React","feature flags and @gate pragmas"],"zh":["Feature Flags","React","JavaScript","前端开发","功能开发","测试开发","AIエージェント","React Native"],"ja":["Feature Flags","React","JavaScript","フロントエンド開発","機能開発","テスト開発","AIエージェント","React Native"],"ko":["Feature Flags","React","JavaScript","프론트엔드 개발","기능 개발","테스트 개발","AI 에이전트","React Native"],"es":["feature-flags","react","depuración de tests","indicadores de características","@gate pragmas","canal específico","nuevas características en React","herramientas de desarrollo de React","AI Agentes para desarrollo de software"],"fr":["feature-flags","react","débogage de tests","indicateurs de fonctionnalités","@gate pragmas","canal spécifique","nouvelles fonctionnalités dans React","outils de développement de React","Outils d''intelligence artificielle pour le développement de logiciels"],"de":["Feature-Flags","React","Fehlerbehebung bei Tests","Feature-Flaggen","@gate-Pragmas","spezifischer Kanal","neue Funktionen in React","Entwicklungstools für React","Künstliche Intelligenz-Tools für Software-Entwicklung"],"pt":["feature flags react","configuração de feature flags","depuração de feature flags","react native feature flags","testes de canais específicos","gate pragmas","arquivos de flags padrão"],"ru":["фич-флаги react","настройка фич-флагов","отладка фич-флагов","react native фич-флаги","канал-зависимые тесты","gate прагмы","файлы флагов по умолчанию"],"ar":["مرشحات الميزات react","إعداد مرشحات الميزات","تصحيح أخطاء مرشحات الميزات","react native مرشحات الميزات","اختبارات القنوات المحددة","gate برAGMA","ملفات المرشحات الافتراضية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for React Development Agents needing efficient feature flag management and debugging capabilities.","zh":"适用于需要高效的功能标志管理和调试功能的React开发代理。","ja":"React開発エージェントが効率的な機能フラグ管理とデバッグ機能を必要とする場合に最適です。","ko":"효율적인 기능 플래그 관리 및 디버깅 기능이 필요한 React 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo de React que necesitan una gestión eficiente de indicadores de función y capacidades de depuración.","fr":"Parfait pour les Agents de Développement React nécessitant une gestion efficace des indicateurs de fonctionnalité et des capacités de débogage.","de":"Perfekt für React-Entwicklungsagenten, die eine effiziente Verwaltung von Funktionsflags und Debugging-Funktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento React que necessitam de gerenciamento eficiente de recursos de feature flag e capacidades de depuração.","ru":"Идеально подходит для агентов разработки React, которым необходим эффективный менеджмент фич-флагов и возможности отладки.","ar":"مثالي لعمليات تطوير الوكلاء React التي تحتاج إلى إدارة فعالة لإشارات الميزة وقدرات فحص الأخطاء."},"recommendation":{"en":"Empowers agents to manage and debug feature flags using @gate pragmas, understanding __EXPERIMENTAL__ and __VARIANT__ overrides, and updating flags in React, leveraging files like ReactFeatureFlags.js and ReactFeatureFlags.www.js.","zh":"赋予代理管理和调试功能标志的能力，使用@gate语义，理解__EXPERIMENTAL__和__VARIANT__覆盖，并在React中更新标志，利用诸如ReactFeatureFlags.js和ReactFeatureFlags.www.js的文件。","ja":"@gateプラグマを使用して機能フラグを管理およびデバッグするエージェントを可能にし、__EXPERIMENTAL__および__VARIANT__のオーバーライドを理解し、Reactでフラグを更新します。ReactFeatureFlags.jsおよびReactFeatureFlags.www.jsなどのファイルを利用します。","ko":"에이전트가 @gate 프ラ그마를 사용하여 기능 플래그를 관리 및 디버깅할 수 있도록 하며, __EXPERIMENTAL__ 및 __VARIANT__ 오버라이드를 이해하고, React에서 플래그를 업데이트합니다. ReactFeatureFlags.js 및 ReactFeatureFlags.www.js와 같은 파일을 활용합니다.","es":"Habilita a los agentes a gestionar y depurar indicadores de función utilizando @gate pragmas, comprendiendo __EXPERIMENTAL__ y __VARIANT__ anulaciones, y actualizando indicadores en React, aprovechando archivos como ReactFeatureFlags.js y ReactFeatureFlags.www.js.","fr":"Permet aux agents de gérer et de déboguer les indicateurs de fonctionnalité à l''aide de @gate pragmas, en comprenant __EXPERIMENTAL__ et __VARIANT__ substitutions, et en mettant à jour les indicateurs dans React, en exploitant des fichiers tels que ReactFeatureFlags.js et ReactFeatureFlags.www.js.","de":"Ermöglicht es Agenten, Funktionsflags zu verwalten und zu debuggen, indem sie @gate-Pragmas verwenden, __EXPERIMENTAL__- und __VARIANT__-Überschreibungen verstehen und Flags in React aktualisieren, indem sie Dateien wie ReactFeatureFlags.js und ReactFeatureFlags.www.js nutzen.","pt":"Habilita os agentes a gerenciar e depurar bandeiras de recursos usando @gate pragmas, compreendendo __EXPERIMENTAL__ e __VARIANT__ substituições, e atualizando bandeiras no React, aproveitando arquivos como ReactFeatureFlags.js e ReactFeatureFlags.www.js.","ru":"Наделяет агентов возможностью управлять и отлаживать фич-флаги с помощью @gate прагм, понимая __EXPERIMENTAL__ и __VARIANT__ переопределения, и обновляя флаги в React, используя файлы типа ReactFeatureFlags.js и ReactFeatureFlags.www.js.","ar":"تمكين الوكلاء من إدارة وتصحيح علامات الميزة باستخدام @gate البراغمات، وفهم __EXPERIMENTAL__ و __VARIANT__ التعديلات، وتحديث العلامات في React، واستخدام الملفات مثل ReactFeatureFlags.js و ReactFeatureFlags.www.js."},"useCases":{"en":["Debugging channel-specific test failures","Updating feature flags for canary releases","Adding new flags to React applications"],"zh":["调试特定频道的测试失败","为金丝雀发布更新功能标志","向React应用程序添加新标志"],"ja":["チャネル固有のテスト失敗をデバッグする","カナリアリリースの機能フラグを更新する","Reactアプリケーションに新しいフラグを追加する"],"ko":["특정 채널의 테스트 실패를 디버깅하는 것","카나리아 릴리스를 위한 기능 플래그 업데이트","React 애플리케이션에 새로운 플래그 추가"],"es":["Depuración de errores de prueba específicos del canal","Actualización de indicadores de función para lanzamientos de canario","Adición de nuevos indicadores a aplicaciones React"],"fr":["Débogage des échecs de test spécifiques au canal","Mise à jour des indicateurs de fonctionnalité pour les versions de canari","Ajout de nouveaux indicateurs aux applications React"],"de":["Debugging von kanalspezifischen Testfehlern","Aktualisierung von Funktionsflags für Canary-Veröffentlichungen","Hinzufügen neuer Flags zu React-Anwendungen"],"pt":["Depuração de falhas de testes específicas de canal","Atualização de bandeiras de recursos para lançamentos canary","Adição de novas bandeiras a aplicações React"],"ru":["Отладка неудач тестирования конкретных каналов","Обновление фич-флагов для канареечных релизов","Добавление новых флагов в приложения React"],"ar":["تصحيح أخطاء فحص القنوات المحددة","تحديث علامات الميزة لإصدارات الكناري","إضافة علامات جديدة إلى تطبيقات React"]},"limitations":{"en":["Requires React environment","Specific to React feature flag management"],"zh":["需要React环境","特定于React功能标志管理"],"ja":["React環境が必要","Reactの機能フラグ管理に特有"],"ko":["React 환경이 필요","React 기능 플래그 관리에 특정"],"es":["Requiere entorno React","Específico para la gestión de indicadores de función de React"],"fr":["Nécessite un environnement React","Spécifique à la gestion des indicateurs de fonctionnalité React"],"de":["Benötigt React-Umgebung","Spezifisch für die Verwaltung von React-Funktionsflags"],"pt":["Requer ambiente React","Específico para gerenciamento de bandeiras de recursos React"],"ru":["Требуется среда React","Конкретно для управления фич-флагами React"],"ar":["يتطلب بيئة React","محدد لإدارة علامات الميزة React"]},"version":4},"contentHash":"b82f8ab67ebed3a34d71cb9f4ed7a0f94ab6129d23c171443ba10fef3f92adc1","repoEtag":"W/\"7e366b67cb3bf6b132fa9e4b13c8e3f5f4a0c4e37519cb121164846325962090\"","qualityScore":71}');
