INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/feature-flags', 'feature-flags', 'facebook', 'react', 'official', 'feature-flags facebook react official declarative frontend javascript library react ui The feature-flags skill helps React developers manage and debug feature flags, including understanding @gate pragmas and updating flags for different channels. Feature Flags是React中用于管理功能开发的技术，包括@gate pragma和React Feature Flags文件 Feature FlagsはReactの機能開発を管理するための技術です Feature Flags는 React에서 기능 개발을 관리하는 기술입니다 Los feature-flags permiten a los desarrolladores probar y implementar nuevas características en React de manera controlada. Aprende a utilizarlos de manera efectiva. Les feature-flags permettent aux développeurs de tester et de mettre en œuvre de nouvelles fonctionnalités dans React de manière contrôlée. Apprenez à les utiliser de manière efficace. Feature-Flags ermöglichen es Entwicklern, neue Funktionen in React kontrolliert zu testen und zu implementieren. Lernen Sie, sie effektiv zu nutzen. Configuração e depuração de feature flags no React, incluindo @gate pragmas e canais específicos Настройка и отладка фич-флагов в React, включая @gate прагмы и канал-зависимые тесты إعداد وتصحيح أخطاء مرشحات الميزات في React، بما في ذلك @gate برAGMA وتحديد القنوات how to use feature flags in React feature flags setup guide debugging feature flag test failures feature flags vs environment variables installing feature flags in React feature flags best practices for React developers what is feature flags in React feature flags alternative for React feature flags and @gate pragmas Feature Flags React JavaScript 前端开发 功能开发 测试开发 AIエージェント React Native Manages default flags and __EXPERIMENTAL__ overrides in ReactFeatureFlags.js Supports channel-specific flag updates, including www, React Native, and test renderer Uses @gate pragmas for test-level gating and debugging Enables updating of flags for different channels, including __VARIANT__ overrides Debugs channel-specific test failures and flag-related issues Integrates with React for seamless feature flag management feature-flags is a set of techniques and tools for managing and testing feature flags in React applications, including declarative frontend development and JavaScript libraries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openai/codex/babysit-pr', 'community', 'openai', 'codex', 'openai/codex', 'babysit-pr', 61978, 8225, 70, '2026-02-26T07:41:12Z', '2026-03-06T02:32:13.037Z', '165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5', '{"id":"openai/codex/babysit-pr","name":"babysit-pr","description":{"en":"A lightweight terminal-based agent that persistently monitors a GitHub Pull Request until it is merged, closed, or becomes mergeable. It automates the observation of CI status, unaddressed review comments, and potential merge conflicts, alerting developers only when necessary.","zh":"babysit-pr是一款轻量级编码代理，在终端中持续监控PR状态，直到合并、关闭或CI成功且无未处理评论。它自动处理CI基础设施问题和权限错误，帮助开发者自动化代码审查流程。","ja":"babysit-prは軽量コーディングエージェントで、ターミナル内でPRのマージ、クローズ、またはCI成功と未対応コメントなしを条件に持続監視します。CIインフラ問題や権限エラーを自動処理し、開発者のコードレビュープロセスを自動化します。","ko":"babysit-pr는 경량 코딩 에이전트로, 터미널에서 PR의 병합, 종료 또는 CI 성공 및 미처리 코멘트 없음을 조건으로 지속 모니터링합니다. CI 인프라 문제와 권한 오류를 자동 처리하여 개발자의 코드 검토 프로세스를 자동화합니다.","es":"babysit-pr es un agente de IA ligero que se ejecuta en tu terminal para monitorizar persistentemente pull requests. Verifica el estado de CI, comentarios de revisión sin abordar, aprobaciones requeridas y conflictos de fusión potenciales hasta que el PR se resuelva o requiera intervención.","fr":"babysit-pr est un agent IA léger exécuté dans votre terminal pour surveiller persistamment les pull requests. Il vérifie le statut CI, les commentaires de revue non traités, les approbations requises et les conflits de fusion potentiels jusqu''à résolution du PR ou besoin d''intervention.","de":"babysit-pr ist ein schlanker KI-Agent, der persistent Pull Requests im Terminal überwacht. Er prüft CI-Status, nicht behandelte Review-Kommentare, erforderliche Freigaben und potenzielle Merge-Konflikte, bis der PR gelöst ist oder Intervention benötigt.","pt":"O babysit-pr é um agente de codificação leve que executa persistentemente no seu terminal para monitorar Pull Requests. Ele automatiza a observação de resultados de CI, comentários de revisão não resolvidos, aprovações necessárias e status de conflitos de merge até que o PR seja mesclado, fechado...","ru":"babysit-pr — это легковесный кодирующий ИИ агент, постоянно работающий в вашем терминале для наблюдения за Pull Requests. Он автоматизирует мониторинг статуса CI, необработанных комментариев ревью, необходимых одобрений и риска конфликтов слияния, пока PR не будет мерджен, закрыт или не потребует...","ar":"babysit-pr هو أداة ذكاء اصطناعي خفيفة للترميز تعمل بشكل مستمر في الطرفية لمراقبة طلبات السحب. تُؤتمت مراقبة حالة CI، التعليقات غير المعالجة، الموافقات المطلوبة ومخاطر تعارض الدمج حتى اندماج الطلب، إغلاقه أو الحاجة لتدخل المطور."},"seo":{"title":{"en":"babysit-pr: Automate PR Monitoring & CI Checks | AI Agent...","zh":"babysit-pr AI代理设置指南：自动化PR监控与CI管理","ja":"babysit-pr AIエージェントの導入ガイド：自動PR監視とCI管理","ko":"babysit-pr AI 에이전트 설정 가이드: 자동화된 PR 모니터링 및 CI 관리","es":"babysit-pr: Guía de configuración para automatizar revisi...","fr":"babysit-pr: Guide de configuration pour automatiser la su...","de":"babysit-pr: Setup-Anleitung zur Automatisierung der PR-Üb...","pt":"babysit-pr: Guia de Configuração para Agentes de IA em CLI","ru":"babysit-pr: Руководство по настройке ИИ Агента для управл...","ar":"babysit-pr: دليل الإعداد لأداة الذكاء الاصطناعي لإدارة طل..."},"description":{"en":"Persistent CLI agent for PR monitoring. Automatically checks CI status, review comments, and merge conflicts. Free up developer time by automating PR babysit...","zh":"babysit-pr是一款终端运行的轻量级AI代理，持续监控PR状态直到合并/关闭、CI成功或无未处理评论。处理CI基础设施问题和权限错误，适合开发者自动化工作流。","ja":"babysit-prはターミナルで動作する軽量AIエージェントで、PRがマージ/クローズされるかCI成功まで監視。CIインフラ問題や権限エラーに対応し、開発者の自動化ワークフローに最適。","ko":"babysit-pr는 터미널에서 실행되는 경량 AI 에이전트로, PR이 병합/종료되거나 CI 성공 시까지 지속 모니터링합니다. CI 인프라 문제와 권한 오류를 처리하여 개발자 워크플로우 자동화에 적합합니다.","es":"Agente de IA babysit-pr que ejecuta en terminal para monitorear PRs hasta su resolución: fusión, cierre o bloqueo. Automatiza la vigilancia de CI, comentario...","fr":"Agent IA babysit-pr exécuté en terminal pour surveiller les PR jusqu''à résolution: fusion, fermeture ou blocage. Automatise le suivi CI, commentaires de revu...","de":"KI-Agent babysit-pr läuft im Terminal und überwacht PRs bis zur Auflösung: Merge, Schließung oder Blockierung. Automatisiert CI-Überwachung, Review-Kommentar...","pt":"Agente de IA leve em terminal para monitorar PRs até a mesclagem. Verifica CI, comentários de revisão, conflitos de merge e alerta sobre problemas. Automatiz...","ru":"Легковесный ИИ агент в терминале для наблюдения за PR до мерджа. Проверяет CI, комментарии ревью, конфликты слияния и предупреждает о проблемах. Автоматизиру...","ar":"أداة ذكاء اصطناعي خفيفة في الطرفية لمراقبة طلبات الدمج حتى الاندماج. تتحقق من CI، تعليقات المراجعة، تعارضات الدمج وتنبه للمشاكل. تُؤتمت سير عمل المطورين."},"definition":{"en":"babysit-pr is a CLI-based AI agent that automates the monitoring of a GitHub Pull Request. It runs persistently in your terminal, tracking CI success, review comment status, and merge conflicts, and only exits upon PR merge/close or when user intervention is required.","zh":"babysit-pr是一款终端运行的AI代理，持续监控Pull Request直到合并/关闭、CI成功、无未处理评论且无合并冲突。它处理CI基础设施问题和权限错误，自动化代码审查流程。","ja":"babysit-prはターミナルで動作するAIエージェントで、PRのマージ/クローズ、CI成功、未対応コメントなし、マージコンフリクトなしを条件に持続監視します。CIインフラ問題や権限エラーを処理し、コードレビューを自動化します。","ko":"babysit-pr는 터미널에서 실행되는 AI 에이전트로, PR의 병합/종료, CI 성공, 미처리 코멘트 없음, 병합 충돌 없음을 조건으로 지속 모니터링합니다. CI 인프라 문제와 권한 오류를 처리하여 코드 리뷰를 자동화합니다.","es":"babysit-pr es un agente de codificación ligero que ejecuta en terminal para monitorizar pull requests de forma persistente. Supervisa automáticamente el CI, los comentarios de revisión, las aprobaciones requeridas y los conflictos de fusión hasta que el PR se fusiona, se cierra o requiere ayuda del usuario.","fr":"babysit-pr est un agent de codification léger exécuté en terminal pour surveiller les pull requests de manière persistante. Il supervise automatiquement le CI, les commentaires de revue, les approbations requises et les conflits de fusion jusqu''à fusion, fermeture du PR ou besoin d''aide utilisateur.","de":"babysit-pr ist ein schlanker Coding-Agent, der persistent Pull Requests im Terminal überwacht. Er überwacht automatisch CI, Review-Kommentare, erforderliche Freigaben und Merge-Konflikte, bis der PR gemerged, geschlossen wird oder Benutzerhilfe benötigt.","pt":"babysit-pr é um agente de IA em CLI que monitora Pull Requests de forma persistente no terminal. Ele verifica automaticamente o status do CI, comentários de revisão, aprovações e conflitos de merge, terminando apenas quando o PR é mesclado, fechado ou precisa de ajuda do usuário.","ru":"babysit-pr — это ИИ агент для CLI, который постоянно наблюдает за Pull Requests в терминале. Он автоматически проверяет статус CI, комментарии ревью, одобрения и конфликты слияния, завершая работу только при мердже, закрытии PR или необходимости помощи пользователя.","ar":"babysit-pr هي أداة ذكاء اصطناعي في سطر الأوامر تراقب طلبات السحب باستمرار. تتحقق تلقائيًا من حالة CI، تعليقات المراجعة، الموافقات وتعارضات الدمج، وتتوقف فقط عند اندماج الطلب، إغلاقه أو الحاجة لمساعدة المستخدم."},"features":{"en":["Persistently monitors a PR until terminal outcomes (merged, closed, or mergeable) are met","Surfaces unaddressed review comments that block the merge process","Checks for CI success and handles repeated flaky test failures with a retry budget","Verifies that required review approval is not blocking the PR from being merged","Identifies potential merge conflicts by checking if the PR is reported as mergeable","Exits and alerts the user for help with infrastructure issues or permission problems"],"zh":["持续监控PR直到合并/关闭或CI成功","检查未处理的代码审查评论","验证必需的审查批准状态","检测潜在的合并冲突风险","处理CI基础设施问题和权限错误","在需要用户干预时发出警报"],"ja":["PRのマージ/クローズまたはCI成功まで持続監視","未対応のコードレビューコメントをチェック","必須レビュー承認状態の検証","潜在的なマージコンフリクトリスクの検出","CIインフラ問題や権限エラーの処理","ユーザー介入が必要な場合のアラート発行"],"ko":["PR 병합/종료 또는 CI 성공 시까지 지속 모니터링","미처리 코드 리뷰 코멘트 확인","필요 리뷰 승인 상태 검증","잠재적 병합 충돌 위험 감지","CI 인프라 문제 및 권한 오류 처리","사용자 개입 필요 시 알림 발송"],"es":["Monitorización persistente de PRs hasta fusión, cierre o bloqueo","Verificación automática del estado de CI y reintentos ante fallos flaky","Detección de comentarios de revisión sin abordar","Validación de aprobaciones de revisión requeridas para merge","Detección de conflictos de fusión potenciales (merge conflicts)","Notificación cuando se requiere intervención humana (problemas de infraestructura, permisos)"],"fr":["Surveillance persistante des PRs jusqu''à fusion, fermeture ou blocage","Vérification automatique du statut CI et réessais sur échecs flaky","Détection des commentaires de revue non traités","Validation des approbations de revue requises pour le merge","Détection des conflits de fusion potentiels (merge conflicts)","Notification lorsque l''intervention humaine est requise (problèmes d''infrastructure, permissions)"],"de":["Persistente Überwachung von PRs bis Merge, Schließung oder Blockierung","Automatische CI-Statusprüfung und Retries bei flaky Failures","Erkennung nicht behandelter Review-Kommentare","Validierung erforderlicher Review-Freigaben für Merge","Erkennung potenzieller Merge-Konflikte (merge conflicts)","Benachrichtigung bei benötigter menschlicher Intervention (Infrastrukturprobleme, Berechtigungen)"],"pt":["Monitoramento persistente de PR até mesclagem, fechamento ou necessidade de intervenção","Verificação automática do status de CI e suporte a retry para falhas intermitentes","Detecção de comentários de revisão não resolvidos que bloqueiam a mesclagem","Validação de aprovações de revisão necessárias para merge","Análise de risco de conflitos de merge (mergeable status)","Execução como agente leve diretamente no terminal do desenvolvedor"],"ru":["Постоянное наблюдение за PR до мерджа, закрытия или необходимости вмешательства","Автоматическая проверка статуса CI и поддержка повторных запусков при флаковых сбоях","Обнаружение необработанных комментариев ревью, блокирующих мердж","Проверка необходимых одобрений ревью для слияния","Анализ риска конфликтов слияния (mergeable status)","Запуск как легковесный агент непосредственно в терминале разработчика"],"ar":["مراقبة مستمرة لطلب الدمج حتى الاندماج، الإغلاق أو الحاجة للتدخل","فحص تلقائي لحالة CI ودعم إعادة المحاولة للأعطال المتقطعة","كشف التعليقات غير المعالجة من المراجعة التي تمنع الاندماج","التحقق من الموافقات المطلوبة للمراجعة قبل الدمج","تحليل مخاطر تعارض الدمج (حالة إمكانية الدمج - mergeable)","التشغيل كأداة خفيفة مباشرة في طرفية المطور"]},"keywords":{"en":["what is babysit-pr","how to use babysit-pr","babysit-pr vs traditional CI","babysit-pr alternative","babysit-pr install guide","babysit-pr setup","automate PR monitoring CLI","GitHub PR merge conflict checker","CI status monitoring agent","persistent PR watcher tool"],"zh":["babysit-pr AI代理","PR自动化监控","CI持续集成管理","终端编码工具","代码审查自动化","合并冲突检测","GitHub PR管理","开发者工作流自动化"],"ja":["babysit-pr AIエージェント","PR自動監視","CI継続的インテグレーション管理","ターミナルコーディングツール","コードレビュー自動化","マージコンフリクト検出","GitHub PR管理","開発者ワークフロー自動化"],"ko":["babysit-pr AI 에이전트","PR 자동화 모니터링","CI 지속적 통합 관리","터미널 코딩 도구","코드 리뷰 자동화","병합 충돌 감지","GitHub PR 관리","개발자 워크플로우 자동화"],"es":["babysit-pr agente IA","automatizar revisiones PR","monitorizar pull requests terminal","CI checks automáticos","detectar conflictos merge","gestión de comentarios revisión","herramienta CLI desarrollo","automatización flujos trabajo GitHub"],"fr":["babysit-pr agent IA","automatiser surveillance PR","surveiller pull requests terminal","vérifications CI automatiques","détecter conflits merge","gestion commentaires revue","outil CLI développement","automatisation workflows GitHub"],"de":["babysit-pr KI-Agent","PR-Überwachung automatisieren","Pull Requests Terminal überwachen","automatische CI-Checks","Merge-Konflikte erkennen","Review-Kommentare verwalten","CLI-Tool Entwicklung","GitHub Workflows Automatisierung"],"pt":["agente IA CLI babysit-pr","monitorar pull requests terminal","automatizar revisão PR","verificar status CI PR","detectar conflitos merge","comentários revisão não resolvidos","lightweight coding agent","ferramenta desenvolvedor PR"],"ru":["ИИ агент CLI babysit-pr","наблюдать за pull requests терминал","автоматизировать ревью PR","проверить статус CI PR","обнаружить конфликты слияния","необработанные комментарии ревью","легковесный кодирующий агент","инструмент разработчика PR"],"ar":["أداة ذكاء اصطناعي babysit-pr سطر أوامر","مراقبة طلبات السحب في الطرفية","أتمتة مراجعة طلبات الدمج","التحقق من حالة CI للطلب","كشف تعارضات الدمج","تعليقات مراجعة غير معالجة","أداة ترميز خفيفة","إدارة طلبات الدمج للمطورين"]}},"owner":"openai","repo":"codex","repoPath":"openai/codex","stars":61978,"forks":8225,"updatedAt":"2026-02-26T07:41:12Z","topics":[],"category":"community","skillMd":{"name":"babysit-pr","description":"Babysit a GitHub pull request after creation by continuously polling CI checks/workflow runs, new review comments, and mergeability state until the PR is ready to merge (or merged/closed). Diagnose failures, retry likely flaky failures up to 3 times, auto-fix/push branch-related issues when appropriate, and stop only when user help is required (for example CI infrastructure issues, exhausted flaky retries, or ambiguous/blocking situations). Use when the user asks Codex to monitor a PR, watch CI, handle review comments, or keep an eye on failures and feedback on an open PR.","bodyPreview":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission pr","body":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission problems, or ambiguity that cannot be resolved safely).\n\nDo not stop merely because a single snapshot returns `idle` while checks are still pending.\n\n## Inputs\nAccept any of the following:\n\n- No PR argument: infer the PR from the current branch (`--pr auto`)\n- PR number\n- PR URL\n\n## Core Workflow\n\n1. When the user asks to \"monitor\"/\"watch\"/\"babysit\" a PR, start with the watcher''s continuous mode (`--watch`) unless you are intentionally doing a one-shot diagnostic snapshot.\n2. Run the watcher script to snapshot PR/CI/review state (or consume each streamed snapshot from `--watch`).\n3. Inspect the `actions` list in the JSON response.\n4. If `diagnose_ci_failure` is present, inspect failed run logs and classify the failure.\n5. If the failure is likely caused by the current branch, patch code locally, commit, and push.\n6. If `process_review_comment` is present, inspect surfaced review items and decide whether to address them.\n7. If a review item is actionable and correct, patch code locally, commit, and push.\n8. If the failure is likely flaky/unrelated and `retry_failed_checks` is present, rerun failed jobs with `--retry-failed-now`.\n9. If both actionable review feedback and `retry_failed_checks` are present, prioritize review feedback first; a new commit will retrigger CI, so avoid rerunning flaky checks on the old SHA unless you intentionally defer the review change.\n10. On every loop, verify mergeability / merge-conflict status (for example via `gh pr view`) in addition to CI and review state.\n11. After any push or rerun action, immediately return to step 1 and continue polling on the updated SHA/state.\n12. If you had been using `--watch` before pausing to patch/commit/push, relaunch `--watch` yourself in the same turn immediately after the push (do not wait for the user to re-invoke the skill).\n13. Repeat polling until the PR is green + review-clean + mergeable, `stop_pr_closed` appears, or a user-help-required blocker is reached.\n14. Maintain terminal/session ownership: while babysitting is active, keep consuming watcher output in the same turn; do not leave a detached `--watch` process running and then end the turn as if monitoring were complete.\n\n## Commands\n\n### One-shot snapshot\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --once\n```\n\n### Continuous watch (JSONL)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --watch\n```\n\n### Trigger flaky retry cycle (only when watcher indicates)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --retry-failed-now\n```\n\n### Explicit PR target\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr <number-or-url> --once\n```\n\n## CI Failure Classification\nUse `gh` commands to inspect failed runs before deciding to rerun.\n\n- `gh run view <run-id> --json jobs,name,workflowName,conclusion,status,url,headSha`\n- `gh run view <run-id> --log-failed`\n\nPrefer treating failures as branch-related when logs point to changed code (compile/test/lint/typecheck/snapshots/static analysis in touched areas).\n\nPrefer treating failures as flaky/unrelated when logs show transient infra/external issues (timeouts, runner provisioning failures, registry/network outages, GitHub Actions infra errors).\n\nIf classification is ambiguous, perform one manual diagnosis attempt before choosing rerun.\n\nRead `.codex/skills/babysit-pr/references/heuristics.md` for a concise checklist.\n\n## Review Comment Handling\nThe watcher surfaces review items from:\n\n- PR issue comments\n- Inline review comments\n- Review submissions (COMMENT / APPROVED / CHANGES_REQUESTED)\n\nIt intentionally surfaces Codex reviewer bot feedback (for example comments/reviews from `chatgpt-codex-connector[bot]`) in addition to human reviewer feedback. Most unrelated bot noise should still be ignored.\nFor safety, the watcher only auto-surfaces trusted human review authors (for example repo OWNER/MEMBER/COLLABORATOR, plus the authenticated operator) and approved review bots such as Codex.\nOn a fresh watcher state file, existing pending review feedback may be surfaced immediately (not only comments that arrive after monitoring starts). This is intentional so already-open review comments are not missed.\n\nWhen you agree with a comment and it is actionable:\n\n1. Patch code locally.\n2. Commit with `codex: address PR review feedback (#<n>)`.\n3. Push to the PR head branch.\n4. Resume watching on the new SHA immediately (do not stop after reporting the push).\n5. If monitoring was running in `--watch` mode, restart `--watch` immediately after the push in the same turn; do not wait for the user to ask again.\n\nIf you disagree or the comment is non-actionable/already addressed, record it as handled by continuing the watcher loop (the script de-duplicates surfaced items via state after surfacing them).\nIf a code review comment/thread is already marked as resolved in GitHub, treat it as non-actionable and safely ignore it unless new unresolved follow-up feedback appears.\n\n## Git Safety Rules\n\n- Work only on the PR head branch.\n- Avoid destructive git commands.\n- Do not switch branches unless necessary to recover context.\n- Before editing, check for unrelated uncommitted changes. If present, stop and ask the user.\n- After each successful fix, commit and `git push`, then re-run the watcher.\n- If you interrupted a live `--watch` session to make the fix, restart `--watch` immediately after the push in the same turn.\n- Do not run multiple concurrent `--watch` processes for the same PR/state file; keep one watcher session active and reuse it until it stops or you intentionally restart it.\n- A push is not a terminal outcome; continue the monitoring loop unless a strict stop condition is met.\n\nCommit message defaults:\n\n- `codex: fix CI failure on PR #<n>`\n- `codex: address PR review feedback (#<n>)`\n\n## Monitoring Loop Pattern\nUse this loop in a live Codex session:\n\n1. Run `--once`.\n2. Read `actions`.\n3. First check whether the PR is now merged or otherwise closed; if so, report that terminal state and stop polling immediately.\n4. Check CI summary, new review items, and mergeability/conflict status.\n5. Diagnose CI failures and classify branch-related vs flaky/unrelated.\n6. Process actionable review comments before flaky reruns when both are present; if a review fix requires a commit, push it and skip rerunning failed checks on the old SHA.\n7. Retry failed checks only when `retry_failed_checks` is present and you are not about to replace the current SHA with a review/CI fix commit.\n8. If you pushed a commit or triggered a rerun, report the action briefly and continue polling (do not stop).\n9. After a review-fix push, proactively restart continuous monitoring (`--watch`) in the same turn unless a strict stop condition has already been reached.\n10. If everything is passing, mergeable, not blocked on required review approval, and there are no unaddressed review items, report success and stop.\n11. If blocked on a user-help-required issue (infra outage, exhausted flaky retries, unclear reviewer request, permissions), report the blocker and stop.\n12. Otherwise sleep according to the polling cadence below and repeat.\n\nWhen the user explicitly asks to monitor/watch/babysit a PR, prefer `--watch` so polling continues autonomously in one command. Use repeated `--once` snapshots only for debugging, local testing, or when the user explicitly asks for a one-shot check.\nDo not stop to ask the user whether to continue polling; continue autonomously until a strict stop condition is met or the user explicitly interrupts.\nDo not hand control back to the user after a review-fix push just because a new SHA was created; restarting the watcher and re-entering the poll loop is part of the same babysitting task.\nIf a `--watch` process is still running and no strict stop condition has been reached, the babysitting task is still in progress; keep streaming/consuming watcher output instead of ending the turn.\n\n## Polling Cadence\nUse adaptive polling and continue monitoring even after CI turns green:\n\n- While CI is not green (pending/running/queued or failing): poll every 1 minute.\n- After CI turns green: start at every 1 minute, then back off exponentially when there is no change (for example 1m, 2m, 4m, 8m, 16m, 32m), capping at every 1 hour.\n- Reset the green-state polling interval back to 1 minute whenever anything changes (new commit/SHA, check status changes, new review comments, mergeability changes, review decision changes).\n- If CI stops being green again (new commit, rerun, or regression): return to 1-minute polling.\n- If any poll shows the PR is merged or otherwise closed: stop polling immediately and report the terminal state.\n\n## Stop Conditions (Strict)\nStop only when one of the following is true:\n\n- PR merged or closed (stop as soon as a poll/snapshot confirms this).\n- PR is ready to merge: CI succeeded, no surfaced unaddressed review comments, not blocked on required review approval, and no merge conflict risk.\n- User intervention is required and Codex cannot safely proceed alone.\n\nKeep polling when:\n\n- `actions` contains only `idle` but checks are still pending.\n- CI is still running/queued.\n- Review state is quiet but CI is not terminal.\n- CI is green but mergeability is unknown/pending.\n- CI is green and mergeable, but the PR is still open and you are waiting for possible new review comments or merge-conflict changes per the green-state cadence.\n- The PR is green but blocked on review approval (`REVIEW_REQUIRED` / similar); continue polling on the green-state cadence and surface any new review comments without asking for confirmation to keep watching.\n\n## Output Expectations\nProvide concise progress updates while monitoring and a final summary that includes:\n\n- During long unchanged monitoring periods, avoid emitting a full update on every poll; summarize only status changes plus occasional heartbeat updates.\n- Treat push confirmations, intermediate CI snapshots, and review-action updates as progress updates only; do not emit the final summary or end the babysitting session unless a strict stop condition is met.\n- A user request to \"monitor\" is not satisfied by a couple of sample polls; remain in the loop until a strict stop condition or an explicit user interruption.\n- A review-fix commit + push is not a completion event; immediately resume live monitoring (`--watch`) in the same turn and continue reporting progress updates.\n- When CI first transitions to all green for the current SHA, emit a one-time celebratory progress update (do not repeat it on every green poll). Preferred style: `🚀 CI is all green! 33/33 passed. Still on watch for review approval.`\n- Do not send the final summary while a watcher terminal is still running unless the watcher has emitted/confirmed a strict stop condition; otherwise continue with progress updates.\n\n- Final PR SHA\n- CI status summary\n- Mergeability / conflict status\n- Fixes pushed\n- Flaky retry cycles used\n- Remaining unresolved failures or review comments\n\n## References\n\n- Heuristics and decision tree: `.codex/skills/babysit-pr/references/heuristics.md`\n- GitHub CLI/API details used by the watcher: `.codex/skills/babysit-pr/references/github-api-notes.md`\n"},"lastSynced":"2026-03-06T02:32:13.037Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps and CI/CD Automation Agents requiring persistent GitHub repository monitoring.","zh":"非常适合需要持续监控 GitHub 仓库的 DevOps 和 CI/CD Automation Agents。","ja":"GitHub リポジトリの持続的な監視を必要とする DevOps および CI/CD Automation Agents に最適です。","ko":"지속적인 GitHub 리포지토리 모니터링이 필요한 DevOps 및 CI/CD Automation Agents에 이상적입니다.","es":"Ideal para DevOps y Agentes de Automatización de CI/CD que requieren monitorización persistente de repositorios de GitHub.","fr":"Idéal pour les DevOps et les Agents d''Automatisation CI/CD nécessitant une surveillance persistante des dépôts GitHub.","de":"Ideal für DevOps und CI/CD-Automatisierungs-Agents, die eine persistente Überwachung von GitHub-Repositories erfordern.","pt":"Ideal para Agentes de Automação DevOps e CI/CD que requerem monitorização persistente de repositórios GitHub.","ru":"Идеально подходит для агентов автоматизации DevOps и CI/CD, требующих постоянного мониторинга репозиториев GitHub.","ar":"مثالي لوكلاء DevOps وأتمتة CI/CD التي تتطلب مراقبة مستمرة لمستودعات GitHub."},"recommendation":{"en":"Enables continuous monitoring of GitHub Pull Requests for terminal states including merge completion, CI success, unaddressed review comments, and merge conflicts. Provides automated alerts only when developer intervention is required.","zh":"支持对 GitHub Pull Requests 的持续监控，包括合并完成、CI 成功、未处理的审阅评论和合并冲突等最终状态。仅在需要开发人员干预时提供自动化警报。","ja":"マージ完了、CI 成功、未対応のレビューコメント、マージコンフリクトなどの終端状態に対する GitHub Pull Requests の継続的な監視を可能にします。開発者の介入が必要な場合にのみ自動アラートを提供します。","ko":"병합 완료, CI 성공, 처리되지 않은 리뷰 코멘트, 병합 충돌을 포함한 터미널 상태에 대한 GitHub Pull Requests의 지속적인 모니터링을 가능하게 합니다. 개발자의 개입이 필요할 때만 자동화된 알림을 제공합니다.","es":"Permite la monitorización continua de Pull Requests de GitHub para estados terminales que incluyen la finalización de la fusión, el éxito del CI, los comentarios de revisión no abordados y los conflictos de fusión. Proporciona alertas automatizadas solo cuando se requiere la intervención del desarrollador.","fr":"Permet une surveillance continue des Pull Requests GitHub pour les états terminaux, y compris l''achèvement de la fusion, la réussite du CI, les commentaires de revue non traités et les conflits de fusion. Fournit des alertes automatisées uniquement lorsque l''intervention du développeur est nécessaire.","de":"Ermöglicht die kontinuierliche Überwachung von GitHub-Pull-Requests auf Endzustände, einschließlich Abschluss des Merges, CI-Erfolg, nicht behobene Review-Kommentare und Merge-Konflikte. Stellt automatisierte Benachrichtigungen nur dann bereit, wenn ein Eingreifen des Entwicklers erforderlich ist.","pt":"Permite a monitorização contínua de Pull Requests do GitHub para estados terminais, incluindo conclusão de merge, sucesso de CI, comentários de revisão não resolvidos e conflitos de merge. Fornece alertas automatizados apenas quando a intervenção do desenvolvedor é necessária.","ru":"Обеспечивает непрерывный мониторинг Pull Requests в GitHub на предмет конечных состояний, включая завершение слияния, успешное прохождение CI, нерешенные комментарии рецензентов и конфликты слияния. Предоставляет автоматические оповещения только тогда, когда требуется вмешательство разработчика.","ar":"يتيح المراقبة المستمرة لطلبات السحب (Pull Requests) في GitHub للوصول إلى الحالات النهائية بما في ذلك اكتمال الدمج، ونجاح CI، وتعليقات المراجعة غير المعالجة، وتعارضات الدمج. يوفر تنبيهات آلية فقط عندما تكون هناك حاجة إلى تدخل المطور."},"useCases":{"en":["Monitoring CI pipeline status until successful completion","Tracking unresolved PR review comments from team members","Detecting merge conflicts in real-time","Automating PR status notifications for development teams"],"zh":["监控 CI pipeline 状态直至成功完成","跟踪团队成员未解决的 PR 审阅评论","实时检测合并冲突","为开发团队自动化 PR 状态通知"],"ja":["CI pipeline のステータスを成功完了まで監視","チームメンバーからの未解決の PR レビューコメントの追跡","マージコンフリクトのリアルタイム検出","開発チーム向けの PR ステータス通知の自動化"],"ko":["성공적으로 완료될 때까지 CI pipeline 상태 모니터링","팀 구성원의 해결되지 않은 PR 리뷰 코멘트 추적","실시간으로 병합 충돌 감지","개발 팀을 위한 PR 상태 알림 자동화"],"es":["Monitorización del estado de la pipeline de CI hasta su finalización exitosa","Seguimiento de comentarios de revisión de PR no resueltos por parte de los miembros del equipo","Detección de conflictos de fusión en tiempo real","Automatización de notificaciones de estado de PR para equipos de desarrollo"],"fr":["Surveillance de l''état de la pipeline CI jusqu''à son achèvement réussi","Suivi des commentaires de revue de PR non résolus par les membres de l''équipe","Détection des conflits de fusion en temps réel","Automatisation des notifications d''état des PR pour les équipes de développement"],"de":["Überwachung des CI-Pipeline-Status bis zum erfolgreichen Abschluss","Verfolgung von ungelösten PR-Review-Kommentaren von Teammitgliedern","Echtzeiterkennung von Merge-Konflikten","Automatisierung von PR-Statusbenachrichtigungen für Entwicklungsteams"],"pt":["Monitorização do estado do pipeline de CI até à conclusão bem-sucedida","Acompanhamento de comentários de revisão de PR não resolvidos por parte dos membros da equipa","Deteção de conflitos de merge em tempo real","Automatização de notificações de estado de PR para equipas de desenvolvimento"],"ru":["Мониторинг статуса CI-конвейера до успешного завершения","Отслеживание нерешенных комментариев рецензирования PR от членов команды","Обнаружение конфликтов слияния в реальном времени","Автоматизация уведомлений о статусе PR для команд разработки"],"ar":["مراقبة حالة خط أنابيب CI حتى اكتماله بنجاح","تتبع تعليقات مراجعة طلبات السحب غير المحلولة من أعضاء الفريق","الكشف عن تعارضات الدمج في الوقت الفعلي","أتمتة إشعارات حالة طلبات السحب لفرق التطوير"]},"limitations":{"en":["Requires GitHub repository access","Depends on GitHub API stability","Limited to terminal-based operation"],"zh":["需要 GitHub 仓库访问权限","依赖于 GitHub API 的稳定性","仅限于基于终端的操作"],"ja":["GitHub リポジトリへのアクセスが必要","GitHub API の安定性に依存","ターミナルベースの操作に限定"],"ko":["GitHub 리포지토리 액세스 권한 필요","GitHub API 안정성에 의존","터미널 기반 운영으로 제한됨"],"es":["Requiere acceso al repositorio de GitHub","Depende de la estabilidad de la API de GitHub","Limitado a operación basada en terminal"],"fr":["Nécessite un accès au dépôt GitHub","Dépend de la stabilité de l''API GitHub","Limité à une opération basée sur le terminal"],"de":["Erfordert Zugriff auf das GitHub-Repository","Hängt von der Stabilität der GitHub-API ab","Beschränkt auf terminalbasierte Operation"],"pt":["Requer acesso ao repositório GitHub","Depende da estabilidade da API do GitHub","Limitado à operação baseada em terminal"],"ru":["Требуется доступ к репозиторию GitHub","Зависит от стабильности GitHub API","Ограничено работой через терминал"],"ar":["يتطلب الوصول إلى مستودع GitHub","يعتمد على استقرار واجهة برمجة التطبيقات (API) الخاصة بـ GitHub","مقتصر على التشغيل القائم على الطرفية"]},"version":4},"contentHash":"165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5","qualityScore":70}');
